let _rbacUser = null;       // {email, role, name}
let _rbacPerms = new Set(); // set of allowed view-ids for current user
let _rbacAllPerms = {};     // {role: {viewId: bool}} — for admin panel

// ── Inicialización ────────────────────────────────────────────
(async function _rbacInit(){
  // Cargar logo en el overlay
  const logoEl = document.getElementById('rbacLogo');
  const appLogo = document.querySelector('.brand-logo');
  if(logoEl && appLogo) logoEl.src = appLogo.src;

  // Restaurar sesión desde localStorage
  const saved = localStorage.getItem('_rbacSession');
  if(saved){
    try{
      const s = JSON.parse(saved);
      if(s.email && s.role){
        _rbacUser = s;
        await _rbacLoadPerms(s.role);
        _rbacApplySession();
        return;
      }
    }catch(e){}
  }
  // Mostrar overlay de login
  const ov = document.getElementById('rbacOverlay');
  if(ov) ov.classList.remove('hidden');
  // Enter key en el input
  const inp = document.getElementById('rbacEmailInput');
  if(inp) inp.addEventListener('keydown', e=>{ if(e.key==='Enter') _rbacLogin(); });
})();

async function _rbacLogin(){
  const inp    = document.getElementById('rbacEmailInput');
  const pinInp = document.getElementById('rbacPinInput');
  const err    = document.getElementById('rbacErrorMsg');
  const btn    = document.getElementById('rbacLoginBtn');
  if(!inp) return;
  const email = inp.value.trim().toLowerCase();
  const pin   = pinInp ? pinInp.value.trim() : '';
  if(!email){ if(err) err.textContent='Introduce un correo válido.'; return; }
  if(!pin || pin.length !== 4){ if(err) err.textContent='El PIN debe tener 4 dígitos.'; return; }
  if(btn){ btn.disabled=true; btn.textContent='Verificando...'; }
  if(err) err.textContent='';
  if(!_sb){
    if(err) err.textContent='Sin conexión a la base de datos.';
    if(btn){btn.disabled=false;btn.textContent='Entrar →';}
    return;
  }
  const {data, error} = await _sb.from('app_users').select('*').eq('email', email).eq('active', true).single();
  if(error || !data){
    if(err) err.textContent='Este correo no está autorizado. Contacta con el administrador.';
    if(btn){ btn.disabled=false; btn.textContent='Entrar →'; }
    return;
  }
  // Validate PIN
  if(data.pin && data.pin !== pin){
    if(err) err.textContent='PIN incorrecto. Inténtalo de nuevo.';
    if(btn){ btn.disabled=false; btn.textContent='Entrar →'; }
    if(pinInp){ pinInp.value=''; pinInp.focus(); }
    return;
  }
  // PIN not set yet (legacy users) — accept any PIN and save it
  if(!data.pin){
    await _sb.from('app_users').update({pin}).eq('id', data.id);
  }
  _rbacUser = {email: data.email, role: data.role, name: data.name||data.email};
  localStorage.setItem('_rbacSession', JSON.stringify(_rbacUser));
  // Si la BD tiene la columna my_team, restauramos el equipo de este director.
  // localStorage ya tiene "myTeam" persistido, pero la BD prevalece si hay valor.
  try{
    if(data.my_team && typeof setMyTeam==='function'){
      setMyTeam(data.my_team);
    }
    // Restaurar también filtros globales por usuario (cat/modality/gender) si existen
    if(data.my_cat !== undefined && data.my_cat !== null){
      _globalFilters.cat = data.my_cat || '';
      try{ localStorage.setItem('gf_cat', _globalFilters.cat); }catch(_){}
    }
    if(data.my_modality !== undefined && data.my_modality !== null){
      _globalFilters.modality = data.my_modality || '';
      try{ localStorage.setItem('gf_modality', _globalFilters.modality); }catch(_){}
    }
    if(data.my_gender !== undefined && data.my_gender !== null){
      _globalFilters.gender = data.my_gender || '';
      try{ localStorage.setItem('gf_gender', _globalFilters.gender); }catch(_){}
    }
  }catch(_){}
  await _rbacLoadPerms(data.role);
  _rbacApplySession();
}

async function _rbacLoadPerms(role){
  _rbacPerms = new Set();
  // SUPERADMIN y ADMIN tienen acceso a todo siempre (sin consultar BD)
  if(role === 'SUPERADMIN' || role === 'ADMIN'){
    ALL_VIEWS.forEach(v => _rbacPerms.add(v.id));
    return;
  }
  if(!_sb) return;
  const {data} = await _sb.from('app_permissions').select('view_id, allowed').eq('role', role);
  // Si la tabla no existe o está vacía, dar permisos básicos por defecto según rol
  if(!data || data.length === 0){
    const defaults = {
      DIRECTOR: ['view-historial','view-carga','view-tabla','view-analisis','view-comparativo','view-equipos','view-tactica','view-simulador','view-graficos','view-top10','view-evolucion','view-powerranking','view-tendencias','view-seleccion','view-validacion','view-equipos-ccaa','view-ciclistas-cat'],
      CICLISTA: ['view-carga','view-tabla','view-analisis','view-equipos'],
      LECTOR:   ['view-carga','view-tabla']
    };
    (defaults[role]||[]).forEach(id => _rbacPerms.add(id));
    return;
  }
  data.forEach(p=>{ if(p.allowed) _rbacPerms.add(p.view_id); });
}

function _rbacApplySession(){
  // Ocultar overlay
  const ov = document.getElementById('rbacOverlay');
  if(ov) ov.classList.add('hidden');
  // Mostrar user bar
  const bar = document.getElementById('rbacUserBar');
  const emailEl = document.getElementById('rbacUserEmail');
  const roleEl  = document.getElementById('rbacUserRoleLabel');
  if(bar) bar.style.display='';
  if(emailEl) emailEl.textContent = _rbacUser.email;
  if(roleEl)  roleEl.textContent  = _rbacUser.role;
  // Renderizar menú según permisos
  _rbacRenderMenu();
  // Navegar a primera vista permitida
  const first = ALL_VIEWS.find(v=>_rbacPerms.has(v.id));
  if(first) showView(first.id);
}

function _rbacRenderMenu(){
  const nav = document.getElementById('sideNav');
  if(!nav) return;
  // Mostrar/ocultar cada botón según permisos
  ALL_VIEWS.forEach(v=>{
    const btn = nav.querySelector(`[data-view="${v.id}"]`);
    if(btn) btn.style.display = _rbacPerms.has(v.id) ? '' : 'none';
  });
  // Ocultar secciones cuyos items estén todos ocultos
  nav.querySelectorAll('.nav-section').forEach(sec=>{
    const visibleBtns = [...sec.querySelectorAll('.nav-btn')].filter(b=>b.style.display!=='none');
    sec.style.display = visibleBtns.length ? '' : 'none';
  });
}

function _rbacLogout(){
  localStorage.removeItem('_rbacSession');
  _rbacUser = null;
  _rbacPerms = new Set();
  // Ocultar todo y mostrar overlay
  const bar = document.getElementById('rbacUserBar');
  if(bar) bar.style.display='none';
  ALL_VIEWS.forEach(v=>{
    const btn = document.querySelector(`[data-view="${v.id}"]`);
    if(btn) btn.style.display='none';
  });
  document.querySelectorAll('.spa-view').forEach(v=>v.classList.remove('active'));
  const ov = document.getElementById('rbacOverlay');
  if(ov){ ov.classList.remove('hidden'); const inp=document.getElementById('rbacEmailInput'); if(inp) inp.value=''; }
}

// ─────────────────────────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════
// RESUMEN DE TEMPORADA
// ═══════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════
// CALENDARIO DE TEMPORADA
// ═══════════════════════════════════════════════════════════════
let _calYear    = new Date().getFullYear();
let _calMonth   = new Date().getMonth(); // 0-based
let _calView    = 'monthly'; // 'monthly' | 'annual'
let _calPast    = []; // carreras disputadas cargadas
let _calPlanned = []; // carreras planificadas de Supabase
let _calInited  = false;

const _CAL_MONTHS_ES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const _CAL_DAYS_ES   = ['L','M','X','J','V','S','D'];

async function _calInit(){
  if(!_calInited){
    _calInited = true;
    await _calLoadData();
  }
  _calRender();
  // Inicializar selector de año del lector FCCV (solo la primera vez)
  if(typeof _fccvInitYears === 'function') _fccvInitYears();
}

async function _calLoadData(){
  // Carreras disputadas del historial
  const history = await _ensureHistory();
  _calPast = history.map(r=>{
    const ds = _parseSpanishDate(r.raceDate);
    return {
      id:   r.id || null,             // ← para abrir detalle al hacer click
      date: ds ? new Date(ds+'T12:00:00') : null,
      dateStr: r.raceDate,
      name: r.raceName,
      localidad: r.localidad||'',
      km:   r.km||'',
      avg:  r.avg||'',
      ridersCount: (r.riders||[]).length,
      type: 'past'
    };
  }).filter(r=>r.date);

  // Carreras planificadas de Supabase
  if(_sb){
    const {data} = await _sb.from('races').select('id,name,date,notes').eq('race_type','planificada').order('date');
    if(data) _calPlanned = data.map(r=>{
      let extra={};
      try{ extra=JSON.parse(r.notes||'{}'); }catch(e){}
      return { id:r.id, date: new Date(r.date+'T12:00:00'), dateStr:r.date, name:r.name, localidad:extra.localidad||'', cat:extra.cat||'', modality:extra.modality||'', fccvId:extra.fccvId||'', fccvDetailUrl:extra.fccvDetailUrl||'', notes:extra.notes||'', type:'planned' };
    });
  }
}

function _calPrev(){
  if(_calView==='annual'){ _calYear--; }
  else { _calMonth--; if(_calMonth<0){_calMonth=11;_calYear--;} }
  _calRender();
}
function _calNext(){
  if(_calView==='annual'){ _calYear++; }
  else { _calMonth++; if(_calMonth>11){_calMonth=0;_calYear++;} }
  _calRender();
}
function _calToday(){
  const now = new Date();
  _calYear = now.getFullYear(); _calMonth = now.getMonth();
  _calRender();
}
function _calSetView(v){
  _calView = v;
  const btnM = document.getElementById('calBtnMonthly');
  const btnA = document.getElementById('calBtnAnnual');
  if(btnM){ btnM.style.background=v==='monthly'?'#1a56db':'#fff'; btnM.style.color=v==='monthly'?'#fff':'#374151'; btnM.style.borderColor=v==='monthly'?'#1a56db':'#d0d5dd'; }
  if(btnA){ btnA.style.background=v==='annual'?'#1a56db':'#fff'; btnA.style.color=v==='annual'?'#fff':'#374151'; btnA.style.borderColor=v==='annual'?'#1a56db':'#d0d5dd'; }
  _calRender();
}

function _calRender(){
  const body  = document.getElementById('calBody');
  const title = document.getElementById('calTitle');
  if(!body) return;
  if(_calView==='annual'){
    if(title) title.textContent = 'Año '+_calYear;
    body.innerHTML = _calBuildAnnual();
  } else {
    if(title) title.textContent = _CAL_MONTHS_ES[_calMonth]+' '+_calYear;
    body.innerHTML = _calBuildMonth(_calYear, _calMonth);
  }
}

function _calGetRacesForDay(y, m, d){
  const all = [..._calPast, ..._calPlanned];
  return all.filter(r=>{
    if(!r.date) return false;
    return r.date.getFullYear()===y && r.date.getMonth()===m && r.date.getDate()===d;
  });
}

function _calBuildMonth(y, m){
  const today = new Date();
  const firstDay = new Date(y, m, 1);
  // Lunes=0 ... Domingo=6
  let startDow = firstDay.getDay()-1; if(startDow<0) startDow=6;
  const daysInMonth = new Date(y, m+1, 0).getDate();

  let html = `<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-bottom:6px">`;
  _CAL_DAYS_ES.forEach(d=>{ html+=`<div style="text-align:center;font-size:12px;font-weight:800;color:#6b7280;padding:6px 0">${d}</div>`; });
  html += '</div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px">';

  // Celdas vacías al inicio
  for(let i=0;i<startDow;i++) html+=`<div></div>`;

  for(let day=1;day<=daysInMonth;day++){
    const isToday = today.getFullYear()===y && today.getMonth()===m && today.getDate()===day;
    const isPast  = new Date(y,m,day) < new Date(today.getFullYear(),today.getMonth(),today.getDate());
    const races   = _calGetRacesForDay(y,m,day);
    const hasPast = races.some(r=>r.type==='past');
    const hasPlan = races.some(r=>r.type==='planned');
    const raceInfo = races.map(r=>`${escapeHtml(r.name)}${r.localidad?' · '+escapeHtml(r.localidad):''}`).join('\n');

    const bgColor = isToday ? '#fef2f2' : races.length>0 ? (hasPast&&!hasPlan?'#eff6ff':hasPlan&&!hasPast?'#f0fdf4':'#fefce8') : isPast?'#f9fafb':'#fff';
    const border  = isToday ? '2px solid #ef4444' : races.length>0 ? '1.5px solid #e0e7ff' : '1px solid #f3f4f6';
    const dayColor= isToday ? '#ef4444' : isPast&&races.length===0 ? '#9ca3af' : '#111827';
    const cursor  = !isPast || races.length>0 ? 'pointer' : 'default';

    html += `<div title="${escapeHtml(raceInfo)}" onclick="_calDayClick(${y},${m},${day})"
      style="min-height:72px;border-radius:10px;border:${border};background:${bgColor};padding:6px 8px;cursor:${cursor};transition:box-shadow .15s"
      onmouseenter="this.style.boxShadow='0 2px 8px rgba(0,0,0,.1)'" onmouseleave="this.style.boxShadow=''">
      <div style="font-size:13px;font-weight:${isToday?'900':'700'};color:${dayColor};margin-bottom:4px">${day}</div>
      ${races.map(r=>{
        const isPastClickable = r.type==='past' && r.id;
        const onClickAttr = isPastClickable
          ? `onclick="event.stopPropagation();_calOpenRaceDetails('${escapeAttr(String(r.id))}')"`
          : '';
        return `<div ${onClickAttr} style="font-size:10px;font-weight:700;background:${r.type==='past'?'#3b82f6':'#10b981'};color:#fff;border-radius:4px;padding:2px 5px;margin-bottom:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;cursor:${isPastClickable?'pointer':'default'};${isPastClickable?'box-shadow:inset 0 -2px 0 rgba(0,0,0,.15)':''}" title="${escapeHtml(r.name)}${isPastClickable?' — Click para ver participantes':''}">
          ${r.type==='planned'?'📋 ':''}${escapeHtml(r.name)}
        </div>`;
      }).join('')}
    </div>`;
  }
  html += '</div>';

  // Lista de carreras del mes
  const monthRaces = [..._calPast, ..._calPlanned].filter(r=>{
    return r.date && r.date.getFullYear()===y && r.date.getMonth()===m;
  }).sort((a,b)=>a.date-b.date);

  if(monthRaces.length>0){
    html += `<div style="margin-top:20px;font-weight:800;font-size:14px;color:#0b2f6b;margin-bottom:10px">📋 Carreras de ${_CAL_MONTHS_ES[m]}</div>
    <div style="display:flex;flex-direction:column;gap:8px">`;
    monthRaces.forEach(r=>{
      const isPlan = r.type==='planned';
      const canClickPast = !isPlan && r.id;
      const rowClick = canClickPast ? `onclick="_calOpenRaceDetails('${escapeAttr(String(r.id))}')"` : '';
      const rowHover = canClickPast ? 'transition:background .15s' : '';
      // Botón Info: SIEMPRE visible. Al hacer clic buscamos la ficha FCCV;
      // si no se encuentra, avisamos y ofrecemos sincronizar.
      const safeName = escapeAttr(r.name||'');
      const safeDate = r.date ? `${r.date.getFullYear()}-${String(r.date.getMonth()+1).padStart(2,'0')}-${String(r.date.getDate()).padStart(2,'0')}` : '';
      const safeCat = escapeAttr(r.cat||'');
      const safeMod = escapeAttr(r.modality||'');
      const safeFccvId = escapeAttr(r.fccvId||'');
      const infoBtn = `<button onclick="event.stopPropagation();_calOpenFccvInfo('${safeName}','${safeDate}','${safeCat}','${safeMod}','${safeFccvId}')" style="background:#1e40af;color:#fff;border:none;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:11px;font-weight:700;margin-right:4px" title="Ficha oficial FCCV (reglamento, planos, clasificación...)">ℹ️ Info</button>`;
      html += `<div ${rowClick} style="display:flex;align-items:center;gap:12px;background:${isPlan?'#f0fdf4':'#eff6ff'};border:1px solid ${isPlan?'#a7f3d0':'#bfdbfe'};border-radius:10px;padding:10px 14px;${canClickPast?'cursor:pointer;':''}${rowHover}"
        ${canClickPast?`onmouseenter="this.style.background='#dbeafe'" onmouseleave="this.style.background='#eff6ff'"`:''}>
        <div style="width:10px;height:10px;border-radius:50%;background:${isPlan?'#10b981':'#3b82f6'};flex-shrink:0"></div>
        <div style="flex:1">
          <div style="font-weight:700;font-size:13px">${isPlan?'📋 ':''} ${escapeHtml(r.name)}</div>
          ${r.localidad?`<div style="font-size:11px;color:#6b7280">${escapeHtml(r.localidad)}</div>`:''}
          ${canClickPast?`<div style="font-size:11px;color:#1d4ed8;font-weight:600;margin-top:2px">👥 ${r.ridersCount||0} corredores · Click para ver detalle</div>`:''}
        </div>
        <div style="font-size:12px;color:#6b7280;flex-shrink:0">${r.date.getDate()} ${_CAL_MONTHS_ES[r.date.getMonth()]}</div>
        ${infoBtn}
        ${isPlan?`<button onclick="event.stopPropagation();_calEditPlanned('${r.id}')" style="background:#eff6ff;color:#1d4ed8;border:none;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:12px;font-weight:700;margin-right:4px" title="Editar">✏️</button><button onclick="event.stopPropagation();_calDeletePlanned('${r.id}')" style="background:#fee2e2;color:#dc2626;border:none;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:11px;font-weight:700" title="Eliminar">✕</button>`:''}
      </div>`;
    });
    html += '</div>';
  }

  // Botón añadir en días futuros del mes
  const now2 = new Date(); now2.setHours(0,0,0,0);
  const hasCurrentOrFuture = new Date(y,m+1,0) >= now2;
  if(hasCurrentOrFuture){
    html += `<div style="margin-top:16px;text-align:center">
      <button onclick="_calOpenModal(null)" style="background:#10b981;color:#fff;border:none;border-radius:10px;padding:10px 20px;font-weight:700;font-size:13px;cursor:pointer">➕ Añadir carrera planificada</button>
    </div>`;
  }
  return html;
}

function _calBuildAnnual(){
  let html = `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px">`;
  for(let m=0;m<12;m++){
    const races = [..._calPast,..._calPlanned].filter(r=>r.date&&r.date.getFullYear()===_calYear&&r.date.getMonth()===m);
    html += `<div style="border:1px solid #e5e7eb;border-radius:12px;overflow:hidden">
      <div style="background:${races.length>0?'#0b2f6b':'#f3f4f6'};color:${races.length>0?'#fff':'#6b7280'};padding:8px 12px;font-weight:800;font-size:13px;display:flex;justify-content:space-between;align-items:center;cursor:pointer" onclick="_calGoMonth(${m})">
        <span>${_CAL_MONTHS_ES[m]}</span>
        ${races.length>0?`<span style="background:rgba(255,255,255,.2);border-radius:20px;padding:2px 8px;font-size:11px">${races.length} carrera${races.length!==1?'s':''}</span>`:''}
      </div>
      <div style="padding:8px 12px;font-size:12px">
        ${races.length===0?'<span style="color:#9ca3af">Sin carreras</span>':
          races.sort((a,b)=>a.date-b.date).map(r=>`
          <div style="display:flex;align-items:center;gap:6px;padding:3px 0;border-bottom:1px solid #f9fafb">
            <span style="width:8px;height:8px;border-radius:50%;background:${r.type==='past'?'#3b82f6':'#10b981'};flex-shrink:0;display:inline-block"></span>
            <span style="font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1" title="${escapeHtml(r.name)}">${escapeHtml(r.name)}</span>
            <span style="color:#9ca3af;flex-shrink:0">${r.date.getDate()}</span>
          </div>`).join('')}
      </div>
    </div>`;
  }
  html += '</div>';
  return html;
}

function _calGoMonth(m){
  _calMonth = m;
  _calSetView('monthly');
}

function _calPrint(){
  const title    = document.getElementById('calTitle');
  const body     = document.getElementById('calBody');
  if(!body || !title) return;

  const titleText = title.textContent || 'Calendario';
  const isAnnual  = _calView === 'annual';
  const teamName  = (typeof myTeam !== 'undefined' && myTeam) ? myTeam : 'Equipo';

  // Leyenda HTML (igual a la de la app)
  const legendHtml = `
    <div style="display:flex;gap:18px;flex-wrap:wrap;margin-bottom:18px;font-size:12px;font-weight:700;align-items:center">
      <span><span style="display:inline-block;width:12px;height:12px;background:#3b82f6;border-radius:3px;margin-right:5px;vertical-align:middle"></span>Carrera disputada</span>
      <span><span style="display:inline-block;width:12px;height:12px;background:#10b981;border-radius:3px;margin-right:5px;vertical-align:middle"></span>Carrera planificada</span>
      <span><span style="display:inline-block;width:12px;height:12px;background:#ef4444;border-radius:3px;margin-right:5px;vertical-align:middle"></span>Hoy</span>
    </div>`;

  const printWin = window.open('', '_blank', 'width=1100,height=800');
  if(!printWin){ alert('El navegador bloqueó la ventana emergente. Permite ventanas emergentes para esta página e inténtalo de nuevo.'); return; }

  printWin.document.write(`<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>${teamName} · ${titleText}</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
      background: #fff;
      color: #111827;
      padding: 24px 28px;
    }

    /* ── Cabecera ── */
    .cal-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      border-bottom: 3px solid #0b2f6b;
      padding-bottom: 12px;
      margin-bottom: 18px;
    }
    .cal-header-left { display: flex; align-items: center; gap: 14px; }
    .cal-logo { width: 70px; height: 70px; flex-shrink: 0; }
    .cal-team  { font-size: 14px; font-weight: 800; color: #0b2f6b; }
    .cal-title { font-size: 22px; font-weight: 900; color: #0b2f6b; }
    .cal-date-print { font-size: 11px; color: #9ca3af; margin-top: 2px; }

    /* ── Celdas del grid mensual ── */
    div[style*="min-height:72px"] {
      page-break-inside: avoid;
    }

    /* ── Vista anual: grid responsivo en papel ── */
    div[style*="minmax(240px"] {
      display: grid !important;
      grid-template-columns: repeat(4, 1fr) !important;
      gap: 12px !important;
    }

    /* ── Pie ── */
    .cal-footer {
      margin-top: 22px;
      border-top: 1px solid #e5e7eb;
      padding-top: 10px;
      font-size: 10px;
      color: #9ca3af;
      text-align: center;
    }

    /* ── Impresión: ajustar a UNA sola página A4 horizontal ── */
    @media print {
      @page {
        size: A4 landscape;
        margin: 6mm 8mm;
      }
      html, body { width: 100%; height: 100%; overflow: hidden; }
      body { padding: 0 !important; margin: 0 !important; }
      .no-print, button { display: none !important; }
      * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }

      /* Cabecera más compacta */
      .cal-header { padding-bottom: 6px !important; margin-bottom: 8px !important; border-bottom-width: 2px !important; }
      .cal-logo { width: 48px !important; height: 48px !important; }
      .cal-logo svg { width: 48px !important; height: 48px !important; }
      .cal-title { font-size: 17px !important; }
      .cal-team  { font-size: 11px !important; }
      .cal-date-print { font-size: 9px !important; margin-top: 0 !important; }

      /* Leyenda compacta */
      #calPrintBody { width: 100%; }
      body > div[style*="display:flex"][style*="gap:18px"] {
        margin-bottom: 8px !important;
        font-size: 10px !important;
      }

      /* ── Vista MENSUAL ──
         Celdas del calendario más altas para llenar la página */
      div[style*="min-height:72px"] {
        min-height: 90px !important;
        padding: 5px 7px !important;
        page-break-inside: avoid;
      }
      /* Ocultar la lista de carreras debajo del calendario y el botón añadir */
      #calPrintBody > div:nth-child(n+3) { display: none !important; }

      /* ── Vista ANUAL ──
         12 meses en 4 columnas x 3 filas, compacto */
      div[style*="minmax(240px"] {
        display: grid !important;
        grid-template-columns: repeat(4, 1fr) !important;
        grid-template-rows: repeat(3, 1fr) !important;
        gap: 5px !important;
        height: calc(100vh - 80px) !important;
      }
      div[style*="minmax(240px"] > div {
        font-size: 10px !important;
        border-radius: 8px !important;
        overflow: hidden !important;
      }
      div[style*="minmax(240px"] > div > div:first-child {
        padding: 4px 8px !important;
        font-size: 11px !important;
      }
      div[style*="minmax(240px"] > div > div:last-child {
        padding: 4px 8px !important;
        font-size: 9px !important;
      }

      /* Pie pequeño */
      .cal-footer { margin-top: 6px !important; padding-top: 4px !important; font-size: 8px !important; }
    }
  </style>
</head>
<body>

  <!-- Botón imprimir (sólo en pantalla) -->
  <div class="no-print" style="text-align:right;margin-bottom:14px">
    <button onclick="window.print()" style="background:#6366f1;color:#fff;border:none;border-radius:9px;padding:9px 18px;font-size:13px;font-weight:700;cursor:pointer;margin-right:8px">🖨️ Imprimir / Guardar PDF</button>
    <button onclick="window.close()" style="background:#f3f4f6;color:#374151;border:1px solid #d0d5dd;border-radius:9px;padding:9px 18px;font-size:13px;font-weight:700;cursor:pointer">✕ Cerrar</button>
  </div>

  <!-- Cabecera -->
  <div class="cal-header">
    <div class="cal-header-left">
      <div class="cal-logo">
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 310 310" width="70" height="70">
          <!-- Fondo circular gris con borde negro -->
          <circle cx="155" cy="155" r="148" fill="#c8c8c8" stroke="#111111" stroke-width="8"/>
          <!-- Sombra/profundidad de las letras TBG -->
          <text x="159" y="120" font-family="'Arial Black',Impact,'Franklin Gothic Heavy',sans-serif"
            font-size="82" font-weight="900" text-anchor="middle" fill="#0e4d73" opacity="0.55">TBG</text>
          <!-- Letras TBG principales en azul -->
          <text x="155" y="116" font-family="'Arial Black',Impact,'Franklin Gothic Heavy',sans-serif"
            font-size="82" font-weight="900" text-anchor="middle" fill="#2B91C8">TBG</text>
          <!-- Reflejo/iluminación superior -->
          <text x="153" y="113" font-family="'Arial Black',Impact,'Franklin Gothic Heavy',sans-serif"
            font-size="82" font-weight="900" text-anchor="middle" fill="#6BBFE0" opacity="0.25">TBG</text>

          <!-- Símbolo infinito ciclismo -->
          <g transform="translate(155,192)">
            <!-- Infinito relleno base azul -->
            <path d="M0,0 C8,-30 56,-34 72,-14 C88,6 80,36 56,40 C32,44 6,24 0,0 C-6,24 -32,44 -56,40 C-80,36 -88,6 -72,-14 C-56,-34 -8,-30 0,0 Z"
              fill="#2B91C8" stroke="#1a5c8a" stroke-width="1.5"/>
            <!-- Hueco interior izquierdo -->
            <path d="M0,0 C-5,18 -27,32 -46,28 C-65,24 -70,8 -60,-6 C-50,-20 -8,-22 0,0 Z"
              fill="#c8c8c8"/>
            <!-- Hueco interior derecho -->
            <path d="M0,0 C5,18 27,32 46,28 C65,24 70,8 60,-6 C50,-20 8,-22 0,0 Z"
              fill="#c8c8c8"/>

            <!-- Ciclista simplificado sobre el lóbulo izquierdo -->
            <g stroke="#2B91C8" stroke-linecap="round" fill="none">
              <!-- Rueda trasera -->
              <circle cx="-62" cy="18" r="11" stroke-width="3.5"/>
              <!-- Rueda delantera -->
              <circle cx="-32" cy="18" r="11" stroke-width="3.5"/>
              <!-- Cuadro: tubo inferior -->
              <line x1="-62" y1="18" x2="-32" y2="18" stroke-width="2.5"/>
              <!-- Cuadro: vaina -->
              <line x1="-47" y1="-2" x2="-62" y2="18" stroke-width="2.5"/>
              <!-- Cuadro: tubo diagonal -->
              <line x1="-47" y1="-2" x2="-32" y2="18" stroke-width="2.5"/>
              <!-- Horquilla / manillar -->
              <line x1="-32" y1="18" x2="-28" y2="4" stroke-width="2.5"/>
              <line x1="-28" y1="4" x2="-20" y2="3" stroke-width="2.5"/>
              <!-- Tija sillín -->
              <line x1="-47" y1="-2" x2="-48" y2="-12" stroke-width="2.5"/>
              <!-- Cuerpo ciclista (en posición aerodinámica) -->
              <line x1="-48" y1="-12" x2="-30" y2="-18" stroke-width="3" stroke="#2B91C8"/>
              <!-- Brazos hacia manillar -->
              <line x1="-30" y1="-18" x2="-20" y2="3" stroke-width="2.5"/>
            </g>
            <!-- Cabeza ciclista -->
            <circle cx="-27" cy="-22" r="7" fill="#2B91C8"/>
          </g>

          <!-- SECCION DEPORTIVA -->
          <text x="155" y="270" font-family="Arial,Helvetica,sans-serif"
            font-size="13" font-weight="700" text-anchor="middle"
            fill="#1a1a1a" letter-spacing="2.5">SECCION DEPORTIVA</text>
        </svg>
      </div>
      <div>
        <div class="cal-team">${escapeHtml(teamName)}</div>
        <div class="cal-title">${escapeHtml(titleText)}</div>
        <div class="cal-date-print">Generado el ${new Date().toLocaleDateString('es-ES',{day:'2-digit',month:'long',year:'numeric'})}</div>
      </div>
    </div>
  </div>

  <!-- Leyenda -->
  ${legendHtml}

  <!-- Contenido del calendario -->
  <div id="calPrintBody">
    ${body.innerHTML}
  </div>

  <div class="cal-footer">
    ${escapeHtml(teamName)} · Calendario de Temporada · ${escapeHtml(titleText)}
  </div>

  <script>
    // Ocultar botones de edición (eliminar carrera planificada) en el impreso
    document.querySelectorAll('button').forEach(b => {
      if(b.textContent.trim() === '✕' || b.getAttribute('onclick') && b.getAttribute('onclick').includes('_calDelete')){
        b.style.display = 'none';
      }
    });
    // Ocultar botón "Añadir carrera planificada"
    document.querySelectorAll('button').forEach(b => {
      if(b.textContent.includes('Añadir')) b.style.display = 'none';
    });
  <\/script>
</body>
</html>`);

  printWin.document.close();
  // Pequeño delay para que el navegador termine de parsear antes de enfocar
  setTimeout(() => { try{ printWin.focus(); } catch(e){} }, 300);
}

function _calDayClick(y,m,d){
  const now = new Date(); now.setHours(0,0,0,0);
  const clicked = new Date(y,m,d);
  const races = _calGetRacesForDay(y,m,d);
  // Si tiene carreras ya y es pasado → mostrar detalle (ya está en la lista de abajo)
  // Si es futuro o no tiene carreras → abrir modal
  if(clicked >= now){
    const dateStr = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    _calOpenModal(dateStr);
  }
}

// ID de la carrera que se está editando (null = modo añadir)
let _calEditingId = null;

function _calOpenModal(dateStr){
  _calEditingId = null;
  const modal = document.getElementById('calModal');
  const dateInp = document.getElementById('calPlanDate');
  const msg = document.getElementById('calModalMsg');
  const title = document.getElementById('calModalTitle');
  if(!modal) return;
  if(title) title.textContent = '➕ Añadir carrera planificada';
  if(dateInp) dateInp.value = dateStr || '';
  document.getElementById('calPlanName').value='';
  document.getElementById('calPlanCat').value='';
  document.getElementById('calPlanLoc').value='';
  document.getElementById('calPlanNotes').value='';
  if(msg) msg.textContent='';
  modal.style.display='flex';
  document.body.style.overflow='hidden';
  setTimeout(()=>{ const n=document.getElementById('calPlanName'); if(n) n.focus(); },100);
}

function _calEditPlanned(id){
  const race = _calPlanned.find(r=>r.id===id);
  if(!race) return;
  _calEditingId = id;
  const modal = document.getElementById('calModal');
  const msg = document.getElementById('calModalMsg');
  const title = document.getElementById('calModalTitle');
  if(!modal) return;
  if(title) title.textContent = '✏️ Editar carrera planificada';
  document.getElementById('calPlanName').value = race.name || '';
  document.getElementById('calPlanDate').value = race.dateStr || '';
  document.getElementById('calPlanCat').value  = race.cat || '';
  document.getElementById('calPlanLoc').value  = race.localidad || '';
  document.getElementById('calPlanNotes').value= race.notes || '';
  if(msg) msg.textContent='';
  modal.style.display='flex';
  document.body.style.overflow='hidden';
  setTimeout(()=>{ const n=document.getElementById('calPlanName'); if(n){ n.focus(); n.select(); } },100);
}

function _calCloseModal(){
  const modal = document.getElementById('calModal');
  if(modal) modal.style.display='none';
  document.body.style.overflow='';
  _calEditingId = null;
}

// ═════════════════════════════════════════════════════════════════════
// MODAL DETALLE DE CARRERA FINALIZADA (calendario → click sobre carrera azul)
// Soporta 2 vistas: 'all' = todos los participantes / 'mine' = solo mi equipo
// ═════════════════════════════════════════════════════════════════════
let _calRaceModalCurrentId = null;
let _calRaceModalView = 'all'; // 'all' | 'mine'
let _calRaceModalRaceCache = null;

async function _calOpenRaceDetails(raceId){
  if(!raceId) return;
  const history = (typeof _cachedHistory!=='undefined' && Array.isArray(_cachedHistory)) ? _cachedHistory : await _ensureHistory();
  const race = history.find(r => String(r.id) === String(raceId));
  if(!race){ alert('No se encontró la carrera en el historial.'); return; }

  _calRaceModalCurrentId = raceId;
  _calRaceModalRaceCache = race;
  _calRaceModalView = 'all'; // siempre arranca en "Todos"

  const modal = document.getElementById('calRaceModal');
  if(!modal) return;

  // ── HEADER (fijo, no cambia con la vista) ──
  const title = document.getElementById('calRaceModalTitle');
  const sub   = document.getElementById('calRaceModalSub');
  if(title) title.textContent = race.raceName || 'Carrera sin nombre';
  const subParts = [];
  if(race.raceDate)  subParts.push(`📅 ${race.raceDate}`);
  if(race.localidad) subParts.push(`📍 ${race.localidad}`);
  if(race.km)        subParts.push(`📏 ${race.km}`);
  if(race.avg)       subParts.push(`💨 ${race.avg}`);
  if(sub) sub.innerHTML = subParts.join(' · ');

  _calRaceModalRenderCurrent();

  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';
}

function _calRaceModalSetView(v){
  _calRaceModalView = v;
  _calRaceModalRenderCurrent();
}

// Renderiza KPIs + body según _calRaceModalView (usando la carrera en caché)
function _calRaceModalRenderCurrent(){
  const race = _calRaceModalRaceCache;
  if(!race) return;

  const ridersAll = (race.riders || []).slice().sort((a,b)=>(a.pos||999)-(b.pos||999));
  const totalRiders = ridersAll.length;
  const teamsAll = new Set(ridersAll.map(r=>r.team).filter(Boolean));
  const winner = ridersAll.find(r=>r.pos===1) || ridersAll[0];
  const myTeamKey = (typeof myTeam!=='undefined' && myTeam) ? (typeof teamKey==='function'?teamKey(myTeam):myTeam.toLowerCase().trim()) : '';
  const isMine = (r)=>{
    if(!myTeamKey) return false;
    const tk = typeof teamKey==='function'?teamKey(r.team||''):(r.team||'').toLowerCase().trim();
    return tk === myTeamKey;
  };
  const myRiders = myTeamKey ? ridersAll.filter(isMine) : [];
  const myBest = myRiders.length ? myRiders.slice().sort((a,b)=>(a.pos||999)-(b.pos||999))[0] : null;

  // Lista a mostrar según la vista
  const showMine = _calRaceModalView === 'mine';
  const list = showMine ? myRiders : ridersAll;

  // ── TABS (Todos / Mi equipo) ──
  const tabsHtml = `
    <div style="display:flex;gap:6px;margin:6px 0 14px 0;border-bottom:2px solid #e5e7eb">
      <button onclick="_calRaceModalSetView('all')" style="padding:9px 16px;border:none;background:transparent;font-weight:800;font-size:13px;cursor:pointer;border-bottom:3px solid ${_calRaceModalView==='all'?'#1a56db':'transparent'};margin-bottom:-2px;color:${_calRaceModalView==='all'?'#1a56db':'#6b7280'}">👥 Todos los participantes <span style="font-weight:600;opacity:.7">(${totalRiders})</span></button>
      ${myTeamKey ? `<button onclick="_calRaceModalSetView('mine')" style="padding:9px 16px;border:none;background:transparent;font-weight:800;font-size:13px;cursor:pointer;border-bottom:3px solid ${_calRaceModalView==='mine'?'#1a56db':'transparent'};margin-bottom:-2px;color:${_calRaceModalView==='mine'?'#1a56db':'#6b7280'}">⭐ Solo mi equipo <span style="font-weight:600;opacity:.7">(${myRiders.length})</span></button>` : ''}
    </div>`;

  // ── KPIs (cambian según vista) ──
  const kpis = document.getElementById('calRaceModalKpis');
  if(kpis){
    if(showMine){
      // KPIs centrados en MI equipo
      const myPodiums = myRiders.filter(r=>r.pos<=3).length;
      const myTop10   = myRiders.filter(r=>r.pos<=10).length;
      const myWins    = myRiders.filter(r=>r.pos===1).length;
      const avgPos    = myRiders.length ? (myRiders.reduce((s,r)=>s+(r.pos||0),0)/myRiders.length).toFixed(1) : '—';
      kpis.innerHTML = `
        <div style="background:#dbeafe;border:1px solid #3b82f6;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:#1d4ed8">${myRiders.length}</div><div style="font-size:10px;text-transform:uppercase;color:#1e40af;letter-spacing:.4px;margin-top:2px">Mis Corredores</div></div>
        <div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${myBest?myBest.pos+'º':'—'}</div><div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:.4px;margin-top:2px">Mejor Pos.</div></div>
        <div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${avgPos}</div><div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:.4px;margin-top:2px">Media Pos.</div></div>
        <div style="background:${myWins?'#fef3c7':'#fff'};border:1px solid ${myWins?'#fcd34d':'#e2e8f0'};border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:${myWins?'#b45309':'#94a3b8'}">${myWins}</div><div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:.4px;margin-top:2px">🥇 Victorias</div></div>
        <div style="background:${myPodiums?'#fef3c7':'#fff'};border:1px solid ${myPodiums?'#fcd34d':'#e2e8f0'};border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:${myPodiums?'#b45309':'#94a3b8'}">${myPodiums}</div><div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:.4px;margin-top:2px">🥉 Podios</div></div>
        <div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${myTop10}</div><div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:.4px;margin-top:2px">Top 10</div></div>`;
    } else {
      const cats = new Set(ridersAll.map(r=>r.cat).filter(Boolean));
      kpis.innerHTML = `
        <div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${totalRiders}</div><div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:.4px;margin-top:2px">Corredores</div></div>
        <div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${teamsAll.size}</div><div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:.4px;margin-top:2px">Equipos</div></div>
        <div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${cats.size}</div><div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:.4px;margin-top:2px">Categorías</div></div>
        <div style="background:${winner?'#fef3c7':'#fff'};border:1px solid ${winner?'#fcd34d':'#e2e8f0'};border-radius:10px;padding:12px;text-align:center"><div style="font-size:13px;font-weight:900;color:#b45309;line-height:1.1">🥇 ${winner?escapeHtml((winner.name||'').slice(0,28)):'—'}</div><div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:.4px;margin-top:4px">Ganador</div></div>
        ${myBest ? `<div style="background:#dbeafe;border:1px solid #3b82f6;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:900;color:#1d4ed8">${myBest.pos}º</div><div style="font-size:10px;text-transform:uppercase;color:#1e40af;letter-spacing:.4px;margin-top:2px">Mi mejor</div></div>` : ''}`;
    }
  }

  // ── BODY (tabs + lista) ──
  const body = document.getElementById('calRaceModalBody');
  if(!body) return;
  if(!totalRiders){
    body.innerHTML = tabsHtml + `<div style="padding:30px;text-align:center;color:#9ca3af">No hay corredores registrados en esta prueba.</div>`;
    return;
  }
  if(showMine && !list.length){
    body.innerHTML = tabsHtml + `<div style="padding:30px;text-align:center;color:#9ca3af">
      <div style="font-size:32px;margin-bottom:6px">⭐</div>
      <div style="font-weight:700;color:#374151">Ningún corredor de "${escapeHtml(myTeam||'')}" en esta prueba</div>
    </div>`;
    return;
  }

  const subtitle = showMine
    ? `⭐ Mis corredores en "${escapeHtml(race.raceName||'')}" (${list.length})`
    : `👥 Lista completa de participantes (${totalRiders})${myRiders.length?` · ⭐ ${myRiders.length} de mi equipo`:''}`;

  body.innerHTML = tabsHtml + `
    <div style="margin:6px 0 10px 0;font-size:12px;color:#6b7280;font-weight:600">${subtitle}</div>
    <div style="display:flex;flex-direction:column;gap:4px">
      ${list.map(r=>{
        const mine = isMine(r);
        const medal = r.pos===1?'🥇':r.pos===2?'🥈':r.pos===3?'🥉':'';
        return `<div onclick="_calRaceModalGotoRider('${escapeAttr(r.name||'')}')" style="display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;background:${mine?'#dbeafe':'#fff'};border:1px solid ${mine?'#3b82f6':'#f3f4f6'};cursor:pointer;transition:background .15s" onmouseenter="this.style.background='${mine?'#bfdbfe':'#f9fafb'}'" onmouseleave="this.style.background='${mine?'#dbeafe':'#fff'}'">
          <div style="font-weight:900;color:${r.pos<=3?'#b45309':'#0b2f6b'};min-width:38px;text-align:center;font-size:14px">${medal||(r.pos+'º')}</div>
          <div style="flex:1;min-width:0">
            <div style="font-weight:700;color:#111827;font-size:13px">${escapeHtml(r.name||'—')}${mine?' <span style=\"font-size:10px;color:#1d4ed8\">⭐</span>':''}</div>
            <div style="font-size:11px;color:#6b7280">${escapeHtml(r.team||'—')}${r.cat?` · ${escapeHtml(r.cat)}`:''}${r.region?` · 🗺️ ${escapeHtml(r.region)}`:''}</div>
          </div>
          <div style="font-family:monospace;font-size:12px;color:#475569;flex-shrink:0">${r.time||''}</div>
        </div>`;
      }).join('')}
    </div>`;
}

function _calRaceModalClose(){
  const modal = document.getElementById('calRaceModal');
  if(modal) modal.style.display = 'none';
  document.body.style.overflow = '';
  _calRaceModalCurrentId = null;
}

async function _calRaceModalExport(){
  if(!_calRaceModalCurrentId) return;
  const history = (typeof _cachedHistory!=='undefined' && Array.isArray(_cachedHistory)) ? _cachedHistory : await _ensureHistory();
  const race = history.find(r => String(r.id) === String(_calRaceModalCurrentId));
  if(!race) return;

  const ridersAll = (race.riders||[]).slice().sort((a,b)=>(a.pos||999)-(b.pos||999));
  const myTeamKey = (typeof myTeam!=='undefined' && myTeam) ? (typeof teamKey==='function'?teamKey(myTeam):myTeam.toLowerCase().trim()) : '';
  const myRiders = myTeamKey ? ridersAll.filter(r=>{
    const tk = typeof teamKey==='function'?teamKey(r.team||''):(r.team||'').toLowerCase().trim();
    return tk === myTeamKey;
  }) : [];

  const showMine = _calRaceModalView === 'mine';
  const exportList = showMine ? myRiders : ridersAll;
  if(!exportList.length){ alert('No hay corredores en la vista actual para exportar.'); return; }

  const dateStr = new Date().toLocaleDateString('es-ES',{day:'2-digit',month:'long',year:'numeric'});
  const winner = ridersAll.find(r=>r.pos===1) || ridersAll[0];
  const teams = new Set(ridersAll.map(r=>r.team).filter(Boolean));

  const titlePrefix = showMine ? `⭐ ${escapeHtml(myTeam||'Mi Equipo')} en` : '🏁';
  const subtitle = showMine ? `Solo corredores de mi equipo · Total participantes en la prueba: ${ridersAll.length}` : '';

  // KPIs en la cabecera del PDF según vista
  let kpisHtml = '';
  if(showMine){
    const myWins = myRiders.filter(r=>r.pos===1).length;
    const myPodiums = myRiders.filter(r=>r.pos<=3).length;
    const myTop10 = myRiders.filter(r=>r.pos<=10).length;
    const myBest = myRiders.length ? myRiders[0].pos : '—';
    const avgPos = myRiders.length ? (myRiders.reduce((s,r)=>s+(r.pos||0),0)/myRiders.length).toFixed(1) : '—';
    kpisHtml = `
      <div class="kpi"><div class="kpi-v">${myRiders.length}</div><div class="kpi-l">Mis corredores</div></div>
      <div class="kpi"><div class="kpi-v">${myBest}${myBest!=='—'?'º':''}</div><div class="kpi-l">Mejor pos.</div></div>
      <div class="kpi"><div class="kpi-v">${avgPos}</div><div class="kpi-l">Media pos.</div></div>
      <div class="kpi"><div class="kpi-v">${myWins}</div><div class="kpi-l">🥇 Victorias</div></div>
      <div class="kpi"><div class="kpi-v">${myPodiums}</div><div class="kpi-l">🥉 Podios</div></div>
      <div class="kpi"><div class="kpi-v">${myTop10}</div><div class="kpi-l">Top 10</div></div>`;
  } else {
    kpisHtml = `
      <div class="kpi"><div class="kpi-v">${ridersAll.length}</div><div class="kpi-l">Corredores</div></div>
      <div class="kpi"><div class="kpi-v">${teams.size}</div><div class="kpi-l">Equipos</div></div>
      <div class="kpi"><div class="kpi-v">${escapeHtml((winner?.name||'').slice(0,24))}</div><div class="kpi-l">🥇 Ganador</div></div>`;
  }

  const rowsHtml = exportList.map(r=>{
    const medal = r.pos===1?'🥇':r.pos===2?'🥈':r.pos===3?'🥉':'';
    return `<tr>
      <td style="text-align:center;font-weight:900">${medal||r.pos+'º'}</td>
      <td style="font-weight:700">${escapeHtml(r.name||'—')}</td>
      ${showMine ? '' : `<td>${escapeHtml(r.team||'—')}</td>`}
      <td>${escapeHtml(r.cat||'—')}</td>
      ${showMine ? '' : `<td>${escapeHtml(r.region||'—')}</td>`}
      <td style="font-family:monospace">${escapeHtml(r.time||'')}</td>
    </tr>`;
  }).join('');

  const tableHead = showMine
    ? `<tr><th>Pos.</th><th>Ciclista</th><th>Cat.</th><th>Tiempo</th></tr>`
    : `<tr><th>Pos.</th><th>Ciclista</th><th>Equipo</th><th>Cat.</th><th>CCAA</th><th>Tiempo</th></tr>`;

  const _pdfLogoSrc = document.querySelector('.brand-logo')?.src || '';
  const filenameSuffix = showMine ? `-${(myTeam||'mi-equipo').toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,20)}` : '';
  const w = window.open('','_blank');
  w.document.write(`<!DOCTYPE html><html><head><title>${escapeHtml(race.raceName||'Carrera')}${filenameSuffix}</title>
  <style>
  @page{size:A4 portrait;margin:14mm}
  *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}
  body{font-family:Arial,sans-serif;padding:24px;color:#111;max-width:1100px;margin:0 auto}
  .hdr{background:linear-gradient(135deg,#0b2f6b,#1286c7)!important;color:#fff!important;padding:20px 24px;border-radius:12px;margin-bottom:20px;display:flex;justify-content:space-between;align-items:flex-start;gap:16px}
  .hdr *{color:#fff!important}
  .hdr-title{font-size:22px;font-weight:900;margin:0 0 4px}
  .hdr-sub{font-size:12px;opacity:.85}
  .hdr-logo{height:80px;max-width:180px;object-fit:contain;background:#fff!important;border-radius:10px;padding:6px}
  .kpis{display:flex;gap:12px;margin-top:12px;flex-wrap:wrap}
  .kpi{background:rgba(255,255,255,.2)!important;border-radius:8px;padding:6px 14px;text-align:center}
  .kpi-v{font-size:18px;font-weight:900}.kpi-l{font-size:9px;opacity:.7;text-transform:uppercase}
  table{width:100%;border-collapse:collapse;font-size:11px}
  th{background:#f0f4f8!important;padding:7px 9px;text-align:left;font-size:10px;font-weight:800;text-transform:uppercase;color:#475467}
  td{padding:6px 9px;border-bottom:1px solid #f3f4f6}
  tr:nth-child(even) td{background:#f9fbff!important}
  .footer{margin-top:16px;font-size:10px;color:#9ca3af;text-align:center}
  </style></head><body>
  <div class="hdr">
    <div style="flex:1">
      <div class="hdr-title">${titlePrefix} ${escapeHtml(race.raceName||'Carrera')}</div>
      <div class="hdr-sub">${race.raceDate||''}${race.localidad?' · 📍 '+escapeHtml(race.localidad):''}${race.km?' · 📏 '+escapeHtml(race.km):''} · Generado el ${dateStr}</div>
      ${subtitle?`<div style="font-size:11px;opacity:.85;margin-top:4px;font-style:italic">${subtitle}</div>`:''}
      <div class="kpis">${kpisHtml}</div>
    </div>
    ${_pdfLogoSrc ? `<img class="hdr-logo" src="${_pdfLogoSrc}" alt="MFPP">` : ''}
  </div>
  <table>
    <thead>${tableHead}</thead>
    <tbody>${rowsHtml}</tbody>
  </table>
  <div class="footer">Director Ciclismo MFPP · ${escapeHtml(race.raceName||'')}${showMine?' · '+escapeHtml(myTeam||''):''} · ${dateStr}</div>
  <script>window.onload=()=>window.print();<\/script>
  </body></html>`);
  w.document.close();
}

function _calRaceModalLoadAsCurrent(){
  if(!_calRaceModalCurrentId) return;
  const id = _calRaceModalCurrentId;
  _calRaceModalClose();
  if(typeof loadHistoryEntry==='function'){
    loadHistoryEntry(id);
  } else {
    alert('No se puede cargar la prueba (función no disponible).');
  }
}

function _calRaceModalGotoRider(riderName){
  if(!riderName) return;
  _calRaceModalClose();
  // Ir al Informe de Plantilla del rider (si tenemos myTeam) o al Análisis individual
  // Como necesitamos cargar primero la prueba para Análisis individual, mejor llevamos
  // a la vista de Evolución que funciona desde el historial
  if(typeof showView==='function') showView('view-evolucion');
  setTimeout(()=>{
    const sel = document.getElementById('evolRiderSelect');
    if(sel){
      // Buscar opción que coincida con el nombre
      const norm = (s)=>(s||'').toLowerCase().trim();
      const target = norm(riderName);
      const found = [...sel.options].find(o=>norm(o.textContent).includes(target) || norm(o.value).includes(target));
      if(found){
        sel.value = found.value;
        if(typeof evolSelectRider==='function') evolSelectRider(found.value);
      }
    }
  }, 300);
}

// ═════════════════════════════════════════════════════════════════════
// LECTOR DINÁMICO FCCV (Federación Ciclismo Comunidad Valenciana)
// Scraping en tiempo real del calendario oficial vía proxy CORS
// ═════════════════════════════════════════════════════════════════════

// Lista de proxies CORS — se prueban en orden hasta que uno funcione.
// IMPORTANTE: codetabs es el único que actualmente devuelve el HTML COMPLETO
// del calendario FCCV con TODAS las pruebas del año. Los otros dos están
// devolviendo respuestas vacías/rate-limited en muchos sitios. Por eso va el
// primero. También exigimos un mínimo razonable de tamaño para detectar
// respuestas truncadas.
const _FCCV_PROXIES = [
  url => `https://api.codetabs.com/v1/proxy/?quest=${encodeURIComponent(url)}`,
  url => `https://corsproxy.io/?${encodeURIComponent(url)}`,
  url => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,
];

let _fccvLastResults = [];
let _fccvLastAllRaces = [];
let _fccvPanelOpen = true;
// Mapa { '12345': '<div>...modal HTML...</div>' } con los modales originales
// de la FCCV (que contienen reglamento, info completa, contactos...).
let _fccvDetailsById = {};

// ── Persistencia local del último scrape FCCV ──
// Guardamos en localStorage el listado de carreras y los modales para que el
// botón Info funcione tras recargar la página sin tener que volver a sincronizar.
const _FCCV_STORAGE_KEY = 'fccvScrapeV1';
function _fccvPersistScrape(){
  try{
    const payload = {
      ts: Date.now(),
      races: _fccvLastAllRaces||[],
      details: _fccvDetailsById||{}
    };
    const str = JSON.stringify(payload);
    // Evitar superar el cupo (5-10MB) — si pesa mucho, descartamos los modales
    if(str.length > 3_500_000){
      payload.details = {};
      localStorage.setItem(_FCCV_STORAGE_KEY, JSON.stringify(payload));
    } else {
      localStorage.setItem(_FCCV_STORAGE_KEY, str);
    }
  }catch(_){}
}
function _fccvLoadScrape(){
  try{
    const str = localStorage.getItem(_FCCV_STORAGE_KEY);
    if(!str) return;
    const data = JSON.parse(str);
    if(data && Array.isArray(data.races)){
      _fccvLastAllRaces = data.races;
      _fccvDetailsById = data.details || {};
    }
  }catch(_){}
}
// Cargar al arrancar el script
_fccvLoadScrape();

function _fccvToggle(){
  _fccvPanelOpen = !_fccvPanelOpen;
  const body = document.getElementById('fccvBody');
  const chev = document.getElementById('fccvChevron');
  if(body) body.style.display = _fccvPanelOpen ? '' : 'none';
  if(chev) chev.style.transform = _fccvPanelOpen ? '' : 'rotate(-90deg)';
}

function _fccvInitYears(){
  const sel = document.getElementById('fccvYear');
  if(!sel || sel.options.length>1) return;
  const cur = new Date().getFullYear();
  const years = [cur-1, cur, cur+1];
  sel.innerHTML = years.map(y=>`<option value="${y}" ${y===cur?'selected':''}>${y}</option>`).join('');
}

async function _fccvFetch(url, opts){
  const minBytes = (opts && opts.minBytes) || 200000; // 200KB por defecto:
  // el HTML del calendario FCCV pesa ~1.6MB, así que cualquier respuesta
  // pequeña significa que el proxy devolvió error o respuesta vacía.
  // Para fichas individuales se puede bajar el mínimo con opts.minBytes.
  let lastErr = null;
  for(const proxify of _FCCV_PROXIES){
    try{
      const proxyUrl = proxify(url);
      const r = await fetch(proxyUrl, {signal: AbortSignal.timeout ? AbortSignal.timeout(20000) : undefined});
      if(r.ok){
        const text = await r.text();
        if(text && text.length >= minBytes){
          console.log(`[FCCV] proxy OK: ${proxyUrl.slice(0,60)}… (${(text.length/1024).toFixed(0)} KB)`);
          return text;
        }
        console.warn(`[FCCV] proxy devolvió respuesta corta (${text.length} bytes, mínimo ${minBytes}):`, proxyUrl.slice(0,60));
      }
      lastErr = new Error(`Proxy responded ${r.status}`);
    } catch(e){
      lastErr = e;
      console.warn('[FCCV] proxy falló:', e.message);
    }
  }
  throw lastErr || new Error('Todos los proxies CORS fallaron');
}

// Parser FCCV-específico: la FCCV usa Unix timestamps + códigos DDMES
let _fccvLastRawHtml = '';

const FCCV_MON_ABBR = {ENE:1,FEB:2,MAR:3,ABR:4,MAY:5,JUN:6,JUL:7,AGO:8,SEP:9,SET:9,OCT:10,NOV:11,DIC:12};
const FCCV_MON_FULL = {enero:1,febrero:2,marzo:3,abril:4,mayo:5,junio:6,julio:7,agosto:8,septiembre:9,setiembre:9,octubre:10,noviembre:11,diciembre:12,gener:1,febrer:2,març:3,marc:3,maig:5,juny:6,juliol:7,agost:8,setembre:9,novembre:11,desembre:12};

// Patrones de fecha en orden de prioridad
const _FCCV_TS_RE = /\b(1[5-9]\d{8}|20\d{8})\b/;
// Acepta 23MAY · 23 MAY · 23\nMAY (la FCCV los muestra en celdas con salto de línea)
const _FCCV_DDMON_RE = /\b(\d{1,2})\s{0,5}(ENE|FEB|MAR|ABR|MAY|JUN|JUL|AGO|SEP|SET|OCT|NOV|DIC)\b/i;
const _FCCV_DATENUM_RE = /\b(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})\b/;
const _FCCV_DATEISO_RE = /\b(20[2-3]\d)-(\d{1,2})-(\d{1,2})\b/;
const _FCCV_DATEWORD_RE = new RegExp(`\\b(\\d{1,2})\\s*(?:de\\s+)?(${Object.keys(FCCV_MON_FULL).join('|')})(?:\\s+(?:de|del)\\s+)?(\\d{4})?\\b`, 'i');

function _fccvParseDate(text, defaultYear){
  if(!text) return null;
  const fallbackYear = defaultYear ? String(defaultYear) : String(new Date().getFullYear());
  // 1) Unix timestamp (más fiable en FCCV). Sumamos 12h para evitar bugs de
  // zona horaria entre Madrid (UTC+1/+2) y UTC (FCCV guarda midnight Madrid).
  const mts = text.match(_FCCV_TS_RE);
  if(mts){
    const ts = parseInt(mts[1]);
    const d = new Date((ts + 12*3600) * 1000);
    const y = d.getUTCFullYear();
    if(y >= 2020 && y <= 2033){
      const mm = String(d.getUTCMonth()+1).padStart(2,'0');
      const dd = String(d.getUTCDate()).padStart(2,'0');
      return {iso:`${y}-${mm}-${dd}`, raw: mts[0], src:'timestamp'};
    }
  }
  // 2) ISO YYYY-MM-DD
  const mi = text.match(_FCCV_DATEISO_RE);
  if(mi){
    const yy = mi[1], mm = mi[2].padStart(2,'0'), dd = mi[3].padStart(2,'0');
    if(+mm>=1&&+mm<=12&&+dd>=1&&+dd<=31) return {iso:`${yy}-${mm}-${dd}`, raw: mi[0], src:'iso'};
  }
  // 3) DDMES (13JUN, 01ABR) — formato FCCV (sin año, usar el del filtro)
  const mddmon = text.match(_FCCV_DDMON_RE);
  if(mddmon){
    const dd = mddmon[1].padStart(2,'0');
    const monKey = mddmon[2].toUpperCase();
    const mm = String(FCCV_MON_ABBR[monKey]).padStart(2,'0');
    if(+dd>=1&&+dd<=31){
      // Año: el explícito si está · si no, el del desplegable
      const ymatch = text.match(/\b(20[2-3]\d)\b/);
      const yy = ymatch ? ymatch[1] : fallbackYear;
      return {iso:`${yy}-${mm}-${dd}`, raw: mddmon[0], src:'ddmon'};
    }
  }
  // 4) DD/MM/YYYY
  const mn = text.match(_FCCV_DATENUM_RE);
  if(mn){
    const dd = mn[1].padStart(2,'0');
    const mm = mn[2].padStart(2,'0');
    let yy = mn[3]; if(yy.length===2) yy='20'+yy;
    const y = +yy;
    if(y>=2020&&y<=2033&&+mm>=1&&+mm<=12&&+dd>=1&&+dd<=31){
      return {iso:`${yy}-${mm}-${dd}`, raw: mn[0], src:'datenum'};
    }
  }
  // 5) "12 de mayo de 2026"
  const mw = text.match(_FCCV_DATEWORD_RE);
  if(mw){
    const dd = mw[1].padStart(2,'0');
    const mm = String(FCCV_MON_FULL[mw[2].toLowerCase()]).padStart(2,'0');
    const yy = mw[3] || fallbackYear;
    return {iso:`${yy}-${mm}-${dd}`, raw: mw[0], src:'word'};
  }
  return null;
}

// Valida que un nombre de carrera no sea un email, URL, etiqueta de cat/modalidad, etc.
function _fccvIsValidRaceName(n){
  if(!n) return false;
  n = String(n).trim();
  if(n.length < 5 || n.length > 200) return false;
  if(/@/.test(n)) return false;
  if(/^\d+$/.test(n)) return false;
  if(/^https?:\/\//i.test(n)) return false;
  if(/^(tel\.?|email|web|fax|administra|auxiliar|secretar|calendario|normativa|seguro|federarse|tramitaci|accid|palau\b|c\/|c\.\/?)\s/i.test(n)) return false;
  if(!/[a-záéíóúñ]/i.test(n)) return false;
  // Rechaza ETIQUETAS de modalidad puras
  if(/^(carretera|btt|btt\s*rally|mtb|ciclo.?cross|cx|pista|trial|cicloturismo|ciclismo\s+para\s+todos|escuelas?\s+ciclismo|ciclisme|escolar)$/i.test(n)) return false;
  // Rechaza ETIQUETAS de categoría puras (o listas de categorías)
  if(/^(cadete[s]?|cadet[s]?|cadete\s+fem\.?|cadete\s+femenino|junior[s]?|junior\s+fem\.?|sub.?23|elite|elite\s+fem\.?|master[s]?|alev[ií]n(?:\s+femenino(?:\s+\d)?)?|infantil[es]?|principiantes|promesa[s]?|a\s+partir\s+de\s+\d+\s+a[ñn]os)$/i.test(n)) return false;
  // Rechaza listas de categorías estilo "Cadete, Cadete Fem., Juni..." o "Elite, Sub-23"
  if(/^[a-záéíóúñ\s,.]+\.\.\.\s*$/i.test(n) && /,/.test(n)) return false;
  // Rechaza códigos UCI (1.12.5, 40.B, 16.C, etc)
  if(/^\d+\.\d+(\.[A-Z0-9+]+)?$/i.test(n)) return false;
  // Rechaza nombres que sean SOLO modalidad+categoría
  if(/^(carretera|btt|cx|pista|trial|cicloturismo)\s+(cadet|junior|sub|elite|master|fem)/i.test(n) && n.length < 35) return false;
  return true;
}

// Limpia el nombre de carrera quitando códigos, timestamps, datos sobrantes
function _fccvCleanRaceName(rawName){
  if(!rawName) return '';
  let s = String(rawName).replace(/\s+/g,' ').trim();
  // Quitar timestamp inicial
  s = s.replace(/^\s*1[5-9]\d{8}\s+/,'').replace(/^\s*20\d{8}\s+/,'');
  // Quitar código DDMES inicial
  s = s.replace(/^\s*\d{1,2}(ENE|FEB|MAR|ABR|MAY|JUN|JUL|AGO|SEP|SET|OCT|NOV|DIC)\s+/i,'');
  return s.trim();
}

// Dispatcher para el botón "ℹ️ Info" de la lista de carreras del calendario.
// Recibe nombre, fecha, categoría, modalidad y, si está disponible, el ID FCCV
// ya guardado al añadir la prueba desde la federación (match inequívoco).
async function _calOpenFccvInfo(name, dateIso, cat, modality, fccvId){
  // Path rápido: tenemos el ID exacto → abrir directamente
  if(fccvId && _fccvDetailsById && _fccvDetailsById[fccvId]){
    _fccvShowRaceDetails(fccvId); return;
  }
  // Si la prueba planificada no trae categoría/modalidad propias, usamos los
  // filtros globales de la FCCV como pistas (por defecto Cadete + Carretera +
  // Masculino para nuestro equipo) — así se desambigua bien cuando hay varias
  // versiones de la misma prueba el mismo día (Junior vs Cadete, etc.).
  const fccvCatSel = (document.getElementById('fccvCat')?.value || '').trim();
  const fccvModSel = (document.getElementById('fccvMod')?.value || '').trim();
  if(!cat && fccvCatSel) cat = fccvCatSel;
  if(!modality && fccvModSel) modality = fccvModSel;
  // Construir un objeto compatible con _calFindFccvForRace
  const fakeRace = {name, date: dateIso ? new Date(dateIso) : null, cat: cat||'', modality: modality||'', fccvId: fccvId||''};
  let m = _calFindFccvForRace(fakeRace);
  if(m){ _fccvShowRaceDetails(m.fccvId); return; }
  // No hay match. Si el scrape está vacío, ofrecer sincronizar.
  if(!(_fccvLastAllRaces||[]).length){
    if(confirm('No hay datos de la FCCV cargados.\n¿Sincronizar ahora con la Federación?')){
      try{
        // Ir a la vista calendario si no está
        if(typeof showView==='function' && document.getElementById('view-calendario')){
          showView('view-calendario');
        }
        await _fccvSync();
        m = _calFindFccvForRace(fakeRace);
        if(m){ _fccvShowRaceDetails(m.fccvId); return; }
      }catch(e){ console.error(e); }
    }
    alert('No se encontró esta prueba en el calendario actual de la FCCV.\n• La prueba puede haber sido retirada del calendario.\n• O el nombre difiere demasiado del oficial.');
    return;
  }
  // Diagnóstico: mostrar las carreras FCCV de la misma fecha (o ±3 días), y si
  // tenemos categoría/modalidad las usamos para acotar.
  const ref = dateIso ? new Date(dateIso+'T12:00:00') : null;
  let sameDay = (_fccvLastAllRaces||[]).filter(c=>{
    if(!c.fccvId || !c.date) return false;
    if(!ref) return false;
    const cd = new Date(c.date+'T12:00:00');
    return Math.abs((cd-ref)/86400000) <= 3;
  });
  // Fallback: si no hay nada en ±3 días pero el nombre del usuario coincide
  // razonablemente con alguna prueba, devolvemos esas candidatas igualmente.
  if(!sameDay.length && name){
    const norm = s=>(s||'').toLowerCase()
      .normalize('NFD').replace(/[̀-ͯ]/g,'')
      .replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
    const nK = norm(name);
    const userTokens = nK.split(' ').filter(t=>t.length>=4);
    sameDay = (_fccvLastAllRaces||[]).filter(c=>{
      if(!c.fccvId) return false;
      const cK = norm(c.name);
      if(cK===nK || cK.includes(nK) || nK.includes(cK)) return true;
      const ctok = cK.split(' ').filter(t=>t.length>=4);
      const shared = userTokens.filter(t=>ctok.includes(t)).length;
      return shared>=2; // al menos 2 tokens compartidos
    }).slice(0,10);
  }
  // Filtrar por categoría y modalidad si las tenemos
  const userCatLow = (cat||'').toLowerCase();
  const userModLow = (modality||'').toLowerCase();
  if(sameDay.length>1 && userCatLow){
    const tok = /cadet/.test(userCatLow)?'cadet':/j[uú]nior/.test(userCatLow)?'junior':/sub.?23/.test(userCatLow)?'sub23':/elite|[eé]lite/.test(userCatLow)?'elite':/master/.test(userCatLow)?'master':'';
    if(tok){
      const filt = sameDay.filter(c=>(c.category||'').toLowerCase().includes(tok.slice(0,5)));
      if(filt.length) sameDay = filt;
    }
  }
  if(sameDay.length>1 && userModLow){
    const filt = sameDay.filter(c=>(c.modality||'').toLowerCase().includes(userModLow.slice(0,4)));
    if(filt.length) sameDay = filt;
  }
  if(sameDay.length===1){ _fccvShowRaceDetails(sameDay[0].fccvId); return; }
  if(sameDay.length){
    // Abrir un selector
    _fccvShowPickerForDate(name, dateIso, sameDay);
    return;
  }
  // No hay match en el scrape actual. Mostramos un loader y lanzamos sync
  // (con cache: si ya hay URL ganadora guardada para este año, el sync es rápido).
  const targetYear = dateIso ? dateIso.slice(0,4) : String(new Date().getFullYear());
  const loaderId = '_fccvAutosyncDialog';
  const old = document.getElementById(loaderId);
  if(old) old.remove();
  const ldr = document.createElement('div');
  ldr.id = loaderId;
  ldr.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99998;display:flex;align-items:center;justify-content:center';
  ldr.innerHTML = `<div style="background:#fff;border-radius:14px;padding:24px 32px;text-align:center;font-family:system-ui;box-shadow:0 20px 60px rgba(0,0,0,.4);max-width:380px">
    <div style="font-size:28px;margin-bottom:10px">⏳</div>
    <div style="font-weight:800;color:#0b2f6b;font-size:14px;margin-bottom:4px" id="_fccvAutoMsg">Buscando la prueba en la FCCV…</div>
    <div style="font-size:11px;color:#6b7280" id="_fccvAutoSub">Año ${targetYear}</div>
    <button id="_fccvAutoCancel" style="margin-top:14px;background:#fee2e2;color:#dc2626;border:none;border-radius:8px;padding:6px 14px;font-weight:700;font-size:12px;cursor:pointer">Cancelar</button>
  </div>`;
  document.body.appendChild(ldr);
  let cancelled = false;
  document.getElementById('_fccvAutoCancel').onclick = ()=>{ cancelled = true; ldr.remove(); };
  try{
    const yearSel = document.getElementById('fccvYear');
    if(yearSel){
      if(![...yearSel.options].some(o=>o.value===targetYear)){
        const opt = document.createElement('option');
        opt.value = targetYear; opt.textContent = targetYear;
        yearSel.appendChild(opt);
      }
      yearSel.value = targetYear;
    }
    await _fccvSync();
    if(cancelled) return;
    const m2 = _calFindFccvForRace(fakeRace);
    if(m2){ ldr.remove(); _fccvShowRaceDetails(m2.fccvId); return; }

    // ─ BRUTE FORCE AUTOMÁTICO ─
    // El scrape sigue sin tener la prueba. La FCCV recorta su HTML público a
    // "hoy en adelante" y no hemos encontrado un parámetro de filtro que abra
    // el archivo. Barrido inteligente: cogemos el ID más bajo conocido del año
    // y bajamos descargando fichas individuales hasta dar con la nuestra.
    const yearRaces = (_fccvLastAllRaces||[]).filter(c=>c.fccvId && c.date && c.date.startsWith(targetYear)).sort((a,b)=>a.date.localeCompare(b.date));
    if(!yearRaces.length){
      ldr.remove();
      alert(`No hay datos del año ${targetYear} en el scrape. Sincroniza desde el panel FCCV primero.`);
      return;
    }
    // Encontrar el ID conocido cuya fecha está MÁS cerca (por arriba) de la pedida
    const targetMs = new Date(dateIso+'T12:00:00').getTime();
    let anchorId = parseInt(yearRaces[0].fccvId, 10);
    let anchorDate = yearRaces[0].date;
    for(const c of yearRaces){
      const cMs = new Date(c.date+'T12:00:00').getTime();
      if(cMs >= targetMs){ anchorId = parseInt(c.fccvId,10); anchorDate = c.date; break; }
    }
    // Estimar cuántos IDs hay que retroceder: ~5-10 IDs por día de diferencia
    const daysBetween = Math.max(0, Math.round((new Date(anchorDate+'T12:00:00').getTime() - targetMs)/86400000));
    const estimatedSpan = Math.max(40, daysBetween*8 + 40);
    // Iterar IDs hacia abajo. Si se quedan en negativo paramos.
    let scanned = 0, found = null;
    const sub = document.getElementById('_fccvAutoSub');
    const msg = document.getElementById('_fccvAutoMsg');
    if(msg) msg.textContent = `Buscando ficha en archivo FCCV…`;
    const tryId = async (id)=>{
      if(cancelled || found) return null;
      try{
        const raw = await _fccvFetchDetailById(String(id));
        if(!raw) return null;
        // Parsear: buscar fecha y nombre dentro del HTML descargado
        const tmp = document.createElement('div');
        tmp.innerHTML = raw;
        const text = (tmp.textContent||'').replace(/\s+/g,' ');
        // ¿Aparece la fecha pedida (DD/MM/YYYY o YYYY-MM-DD)?
        const [yy,mm,dd] = dateIso.split('-');
        const dateRegex = new RegExp(`\\b${dd}[/\\-\\. ]${mm}[/\\-\\. ]${yy}\\b|\\b${yy}[/\\-]${mm}[/\\-]${dd}\\b`, 'i');
        const hasDate = dateRegex.test(text);
        if(!hasDate) return null;
        // Compara nombre con tokens del nombre pedido
        const userNameTokens = name.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'')
          .replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(t=>t.length>=4);
        const textLow = text.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
        const matchTokens = userNameTokens.filter(t=>textLow.includes(t)).length;
        if(matchTokens>=2 || matchTokens===userNameTokens.length){
          return String(id);
        }
        return null;
      }catch(_){ return null; }
    };
    // Escaneo en paralelo en bloques de 4 IDs descendentes
    const PARALLEL = 4;
    for(let offset=1; offset<=estimatedSpan && !cancelled && !found; offset+=PARALLEL){
      const batch = [];
      for(let k=0;k<PARALLEL;k++){
        const id = anchorId - offset - k;
        if(id<1000) continue;
        batch.push(tryId(id));
      }
      if(msg) msg.textContent = `Buscando ficha en archivo FCCV…`;
      if(sub) sub.textContent = `Año ${targetYear} · revisadas ${scanned} fichas`;
      const results = await Promise.all(batch);
      scanned += batch.length;
      for(const r of results){ if(r){ found = r; break; } }
    }
    if(cancelled){ return; }
    if(found){
      // Vincular el fccvId a la carrera planificada para futuras consultas
      try{
        const planned = (_calPlanned||[]).find(p=>p.name===name && (p.dateStr||'').slice(0,10)===dateIso);
        if(planned && _sb && !String(planned.id).startsWith('local-')){
          const {data} = await _sb.from('races').select('notes').eq('id', planned.id).maybeSingle();
          let extra = {};
          if(data?.notes){ try{ extra = JSON.parse(data.notes); }catch(_){} }
          extra.fccvId = found;
          await _sb.from('races').update({notes: JSON.stringify(extra)}).eq('id', planned.id);
          planned.fccvId = found;
        }
      }catch(_){}
      ldr.remove();
      _fccvShowRaceDetails(found);
      return;
    }
    ldr.remove();
  }catch(e){
    console.error(e);
    ldr.remove();
  }

  // Diagnóstico avanzado: muestra fechas reales del scrape cercanas a la pedida
  const allDates = (_fccvLastAllRaces||[]).filter(c=>c.date).map(c=>c.date).sort();
  const datesNear = [];
  if(ref){
    for(const c of (_fccvLastAllRaces||[])){
      if(!c.date) continue;
      const cd = new Date(c.date+'T12:00:00');
      const diff = (cd-ref)/86400000;
      if(Math.abs(diff)<=7) datesNear.push({date:c.date, name:c.name, cat:c.category||'', mod:c.modality||'', fccvId:c.fccvId});
    }
  }
  const diag = datesNear.length
    ? '\n\nCarreras del scrape en ±7 días:\n' + datesNear.slice(0,8).map(d=>`  • ${d.date} — ${(d.name||'').slice(0,40)} [${(d.mod||'').slice(0,10)} / ${(d.cat||'').slice(0,18)}]`).join('\n')
    : (allDates.length ? `\n\nRango de fechas en el scrape: ${allDates[0]} … ${allDates[allDates.length-1]}` : '');
  alert(`No se encontró match el ${dateIso||'(sin fecha)'} ni por nombre similar.\nScrape actual: ${(_fccvLastAllRaces||[]).length} carreras.${diag}\n\nPosibles causas:\n• La prueba no pertenece a la FCCV.\n• El año filtrado al sincronizar fue distinto.\n• Aún no la han publicado o la han retirado.`);
}

// Selector cuando no encontramos match exacto pero hay candidatas el mismo día.
function _fccvShowPickerForDate(name, dateIso, candidates){
  const old = document.getElementById('_fccvPickerDialog');
  if(old) old.remove();
  const overlay = document.createElement('div');
  overlay.id = '_fccvPickerDialog';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.onclick = e=>{ if(e.target===overlay) overlay.remove(); };
  overlay.innerHTML = `
    <div style="background:#fff;border-radius:14px;max-width:580px;width:100%;max-height:80vh;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.4)">
      <div style="background:linear-gradient(135deg,#1e40af,#0b2f6b);color:#fff;padding:16px 20px;display:flex;justify-content:space-between;align-items:center">
        <div style="flex:1;min-width:0">
          <div style="font-size:11px;opacity:.85;letter-spacing:.6px;text-transform:uppercase">Selecciona la prueba FCCV correspondiente</div>
          <div style="font-size:14px;font-weight:700;margin-top:2px">${escapeHtml(name)} · ${dateIso}</div>
        </div>
        <button onclick="document.getElementById('_fccvPickerDialog').remove()" style="background:rgba(255,255,255,.18);color:#fff;border:none;border-radius:8px;width:32px;height:32px;font-size:18px;font-weight:800;cursor:pointer">✕</button>
      </div>
      <div style="padding:14px 18px;overflow-y:auto;flex:1">
        <div style="font-size:12px;color:#6b7280;margin-bottom:10px">No pude identificar automáticamente cuál es. Elige tú la prueba en la FCCV que corresponde:</div>
        ${candidates.map(c=>`
          <button onclick="document.getElementById('_fccvPickerDialog').remove();_fccvShowRaceDetails('${c.fccvId}')" style="display:block;width:100%;text-align:left;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:10px 14px;margin-bottom:8px;cursor:pointer;transition:background .15s" onmouseenter="this.style.background='#eff6ff'" onmouseleave="this.style.background='#f9fafb'">
            <div style="font-weight:700;color:#0b2f6b;font-size:13px">${escapeHtml(c.name)}</div>
            <div style="font-size:11px;color:#6b7280;margin-top:3px">📅 ${c.date} · 📍 ${escapeHtml(c.location||'')} · 🏷️ ${escapeHtml(c.category||'')}</div>
            <div style="font-size:10px;color:#94a3b8;margin-top:2px">FCCV id: ${c.fccvId}</div>
          </button>
        `).join('')}
      </div>
    </div>`;
  document.body.appendChild(overlay);
}

// Busca, en el último scrape FCCV, una carrera que coincida con la fila del
// calendario por nombre+fecha (matching laxo). Devuelve {fccvId,...} o null.
function _calFindFccvForRace(r){
  if(!r || !r.name) return null;
  const all = (_fccvLastAllRaces||[]);
  if(!all.length) return null;
  const norm = s=>(s||'').toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g,'')
    .replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
  const nK = norm(r.name);
  if(nK.length<3) return null;
  const dateIso = r.date ? `${r.date.getFullYear()}-${String(r.date.getMonth()+1).padStart(2,'0')}-${String(r.date.getDate()).padStart(2,'0')}` : '';

  // Pre-filtrar candidatos por fecha exacta (ventana de ±1 día por si hay
  // desfases de zona horaria entre el scrape y los datos en Supabase).
  const onSameDate = [];
  if(dateIso){
    const ref = new Date(dateIso+'T12:00:00');
    for(const c of all){
      if(!c.fccvId || !c.date) continue;
      const cDate = new Date(c.date+'T12:00:00');
      const diffDays = Math.abs((cDate - ref)/86400000);
      if(diffDays<=1) onSameDate.push(c);
    }
  }
  const pool = onSameDate.length ? onSameDate : all.filter(c=>c.fccvId);

  // Match inequívoco si la carrera planificada guarda su fccvId
  if(r.fccvId){
    const hit = pool.find(c=>c.fccvId===r.fccvId);
    if(hit) return hit;
  }

  // Token de categoría del usuario (e.g. "cadete", "junior", "elite") y modalidad
  const userCatTok = (()=>{
    const c = (r.cat||'').toLowerCase();
    if(/cadet/.test(c)) return 'cadet';
    if(/j[uú]nior/.test(c)) return 'junior';
    if(/sub.?23/.test(c)) return 'sub23';
    if(/elite|[eé]lite/.test(c)) return 'elite';
    if(/master/.test(c)) return 'master';
    if(/infantil/.test(c)) return 'infantil';
    if(/alev[ií]n/.test(c)) return 'alevin';
    if(/escola|escuela/.test(c)) return 'escuela';
    if(/promesa/.test(c)) return 'promesa';
    if(/principiant/.test(c)) return 'principiant';
    return '';
  })();
  const userIsFem = /\bfem(en[ií]n)?(o|a)?\b|\bf\.?\b|\bmujer/.test((r.cat||'').toLowerCase());
  const userMod = (r.modality||'').toLowerCase();

  // Helper: detecta si una categoría FCCV contiene un token MASCULINO de la
  // categoría del usuario (e.g. "Cadete" sin marca fem).
  const fccvHasUserCat = (fccvCat)=>{
    if(!userCatTok || !fccvCat) return false;
    const tokens = fccvCat.toLowerCase().split(/[,;]/).map(s=>s.replace(/\.\.\.$/,'').trim());
    return tokens.some(t=>{
      if(!t.includes(userCatTok.slice(0,5))) return false;
      const isTokFem = /\bfem\b|fem\.|femen|mujer|dones/.test(t);
      return userIsFem ? isTokFem : !isTokFem;
    });
  };

  // Score por nombre + categoría + modalidad
  let best = null, bestScore = -1;
  for(const c of pool){
    const cK = norm(c.name);
    if(!cK) continue;
    let score = 0;
    if(cK===nK) score += 100;
    else if(cK.includes(nK) || nK.includes(cK)) score += 70;
    else {
      const tok = nK.split(' ').filter(t=>t.length>=4);
      const ctok = cK.split(' ').filter(t=>t.length>=4);
      const shared = tok.filter(t=>ctok.includes(t)).length;
      score += shared*12;
    }
    // BONUS / PENALIZACIÓN por categoría
    if(userCatTok){
      const match = fccvHasUserCat(c.category||'');
      if(match) score += 80;
      else score -= 40; // descarta fuerte si la categoría del usuario NO aparece
    }
    // BONUS por modalidad
    if(userMod){
      const cMod = (c.modality||'').toLowerCase();
      if(cMod && (cMod.includes(userMod.slice(0,4)) || userMod.includes(cMod.slice(0,4)))) score += 30;
      // Penaliza modalidades opuestas
      const isCarretera = /carretera|ruta/.test(userMod);
      const isBtt = /btt|mtb|monta/.test(userMod);
      if(isCarretera && /btt|mtb/.test(cMod)) score -= 50;
      if(isBtt && /carretera|ruta/.test(cMod)) score -= 50;
    }
    if(score>bestScore){ bestScore = score; best = c; }
  }
  // Si la única candidata del día tiene score positivo, igualmente la devolvemos
  if(onSameDate.length===1 && bestScore>=-20) return onSameDate[0];
  return bestScore>=24 ? best : null;
}

function _fccvParseHtml(html, defaultYear){
  _fccvLastRawHtml = html;
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const races = [];
  const seen = new Set();
  // Indexar todos los modales <div id="pruebaXXXXX"> con la info completa de
  // cada prueba (categorías sin truncar, reglamento, contactos...). NO
  // reseteamos el cache: la FCCV solo publica futuras y queremos conservar
  // los modales de pruebas pasadas para poder seguir consultándolas.
  doc.querySelectorAll('div[id^="prueba"]').forEach(el=>{
    const m = el.id.match(/^prueba(\d+)$/);
    if(m) _fccvDetailsById[m[1]] = el.innerHTML || '';
  });
  const yearStr = defaultYear ? String(defaultYear) : String(new Date().getFullYear());

  const push = (date, name, location, rawText, modality, category, fccvId, fccvDetailUrl) => {
    name = _fccvCleanRaceName(name);
    if(!date || !_fccvIsValidRaceName(name)) return;
    // Filtrar por año seleccionado (descarta restos de otros años en la página)
    if(date.slice(0,4) !== yearStr) return;
    // Incluir categoría en la clave de dedup: la FCCV publica varias filas con el
    // mismo nombre y fecha pero distintas categorías (ej. una para Junior y otra
    // para Cadete). Si dedup solo usa nombre+fecha se descarta la segunda.
    const catKey = (category||'').toLowerCase().replace(/\s+/g,' ').slice(0,60);
    const modKey = (modality||'').toLowerCase().replace(/\s+/g,' ').slice(0,30);
    const key = date + '|' + name.toLowerCase().slice(0,50) + '|' + catKey + '|' + modKey;
    if(seen.has(key)) return;
    seen.add(key);
    races.push({date, dateText:date, name, location:(location||'').trim(), rawText:(rawText||name), modality:modality||'', category:category||'', fccvId: fccvId||'', fccvDetailUrl: fccvDetailUrl||''});
  };

  // Diagnóstico: contadores de estadísticas del parser
  const _stats = {
    tablesFound: doc.querySelectorAll('table').length,
    rowsTotal: doc.querySelectorAll('tr').length,
    rowsWithTd: 0,
    rowsWith3plus: 0,
    rowsWithDate: 0,
    rowsWithValidName: 0,
    rowsAccepted: 0,
    samples: []
  };

  // Helpers de clasificación de celdas
  const isCatListCell = (c)=>{
    if(!c || c.length<3 || c.length>200) return false;
    // Lista de categorías: empieza con un token de categoría conocido
    if(/^\s*(cadet|junior|sub.?23|elite|master|escola|infantil|alev|feme?ni|cicloturism|promesa|a\s+partir|principiant)/i.test(c)){
      // Y contiene marcas: coma, "fem.", "..." o solo una palabra de cat
      if(/,|\bfem\.?\b|\.\.\.|\s+\d/i.test(c) || /^(cadete[s]?|junior[s]?|elite|master|sub.?23|cadet)$/i.test(c.trim())) return true;
    }
    return false;
  };
  const isLocationCell = (c)=>{
    if(!c) return false;
    // PUEBLO (PROVINCIA), PROVINCIA NOMBRE (PROVINCIA), VILA-REAL I MORELLA (CASTELLON)
    return /^[A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ0-9\s'`´·\-\/]{2,60}\s*\([A-ZÁÉÍÓÚÑ\s]+\)\s*$/i.test(c.trim());
  };
  const isModalityCell = (c)=>{
    if(!c) return false;
    return /^(carretera|btt(\s*rally)?|mtb|ciclo.?cross|cx|pista|trial|cicloturismo|ciclismo\s+para\s+todos|escuelas?\s+ciclismo|ciclisme|escolar)$/i.test(c.trim());
  };
  const isUCICodeCell = (c)=>{
    if(!c) return false;
    return /^\d+\.\d+(\.[A-Z0-9+]+)?(\.\+?[A-Z]+)?$/i.test(c.trim());
  };
  const isDDMESCell = (c)=>{
    if(!c) return false;
    return /^\s*\d{1,2}\s{0,5}(ENE|FEB|MAR|ABR|MAY|JUN|JUL|AGO|SEP|SET|OCT|NOV|DIC)\s*$/i.test(c);
  };
  const racePat = /\b(trofeo|trofeu|memorial|copa|challenge|cri\b|vuelta|criterium|critèrium|premi|premio|campeonato|cpto|cronoescalada|cronometro|gran\s+premi|gp\s|circuit|liga|marcha|desafio|reto|clasica|classica|open\b|trial)\b/i;

  // ── ESTRATEGIA PRINCIPAL FCCV: cada <tr> con celdas <td> es una carrera ──
  doc.querySelectorAll('tr').forEach(row=>{
    const cells = [...row.querySelectorAll('td')];
    if(cells.length){ _stats.rowsWithTd++; }
    if(cells.length < 2) return;
    _stats.rowsWith3plus++;

    const tdTexts = cells.map(td=>(td.textContent||'').replace(/\s+/g,' ').trim());

    // Buscar fecha: TODOS los attrs + textContent + outerHTML (extra: timestamps en JS embebido)
    const allAttrs = cells.flatMap(td=>{
      const vals = [];
      for(const attr of td.attributes) vals.push(attr.value);
      td.querySelectorAll('*').forEach(c=>{
        for(const attr of c.attributes) vals.push(attr.value);
      });
      return vals;
    }).join(' ');
    // También revisar la propia <tr>
    const trAttrs = [...row.attributes].map(a=>a.value).join(' ');
    const dateSource = trAttrs + ' ' + allAttrs + ' ' + tdTexts.join(' ');

    const d = _fccvParseDate(dateSource, yearStr);
    if(!d){
      // Guardar muestra para debug
      if(_stats.samples.length < 8){
        _stats.samples.push({reason:'sin_fecha', tdTexts: tdTexts.slice(0,8), attrs: trAttrs.slice(0,300)});
      }
      return;
    }
    _stats.rowsWithDate++;

    // Clasificar cada celda por su FORMATO (no por su posición)
    let location = tdTexts.find(isLocationCell) || '';
    let modality = tdTexts.find(isModalityCell) || '';
    let category = tdTexts.find(isCatListCell) || tdTexts.find(c=>/^(cadet[es]?|junior[s]?|sub.?23|elite|master|escola[rs]?|infantil[es]?|alev[ií]n|principiant|promesa[s]?|cicloturism\w*)$/i.test(c.trim())) || '';

    // Candidatos a NOMBRE: las que no sean ninguna de las clasificadas
    const used = new Set([location, modality, category].filter(Boolean));
    const nameCandidates = tdTexts.filter(c=>{
      if(used.has(c)) return false;
      if(isDDMESCell(c) || isUCICodeCell(c)) return false;
      return _fccvIsValidRaceName(c);
    });

    // Priorizar nombres con palabras-clave de carrera
    const named = nameCandidates.sort((a,b)=>{
      const ar = racePat.test(a) ? 0 : 1;
      const br = racePat.test(b) ? 0 : 1;
      if(ar!==br) return ar-br;
      return b.length - a.length;
    });
    const name = named[0] || nameCandidates[0] || '';
    if(!name){
      if(_stats.samples.length < 8){
        _stats.samples.push({reason:'sin_nombre', date:d.iso, tdTexts: tdTexts.slice(0,8), category, modality, location});
      }
      return;
    }
    _stats.rowsWithValidName++;

    // Extraer ID de prueba FCCV del HTML de la fila (data-target="#prueba12345"
    // o href="#prueba12345"); permite enlazar a la documentación oficial.
    let fccvId = '';
    const idMatch = (row.outerHTML||'').match(/prueba(\d{3,7})\b/);
    if(idMatch) fccvId = idMatch[1];

    // Extraer URL de la página de detalle de la prueba (el botón "Más" del
    // calendario apunta ahí, y desde ese URL la FCCV expone los tabs:
    // Información, Documentos, Deportistas, Técnicos/Otros, Clasificación).
    let fccvDetailUrl = '';
    const anchors = [...row.querySelectorAll('a[href]')];
    for(const a of anchors){
      const href = a.getAttribute('href') || '';
      const txt = (a.textContent||'').trim().toLowerCase();
      // Prioridad 1: href que contiene "prueba" o "smartweb" y NO es un ancla a modal
      if(href && !href.startsWith('#') && !/javascript:/i.test(href) &&
         (/prueba|smartweb/i.test(href) || /^m[aá]s$|info|detalle/i.test(txt))){
        fccvDetailUrl = href;
        if(/prueba/i.test(href)) break; // mejor candidato
      }
    }
    // Convertir a URL absoluta si era relativa
    if(fccvDetailUrl && !/^https?:/i.test(fccvDetailUrl)){
      fccvDetailUrl = fccvDetailUrl.startsWith('/')
        ? 'https://fccv.es' + fccvDetailUrl
        : 'https://fccv.es/' + fccvDetailUrl;
    }

    const before = races.length;
    push(d.iso, name, location, tdTexts.join(' | '), modality, category, fccvId, fccvDetailUrl);
    if(races.length > before){
      _stats.rowsAccepted++;
    } else {
      // No se aceptó (filtro de año o duplicado)
      if(_stats.samples.length < 8){
        _stats.samples.push({reason:'push_rechazo', date:d.iso, name, yearExpected: yearStr});
      }
    }
  });

  // Almacenar stats en variable global para que el debug los muestre
  window._fccvLastStats = _stats;

  // ── ESTRATEGIA FALLBACK: filas tr con cualquier fecha (sin timestamp) ──
  if(races.length < 5){
    doc.querySelectorAll('tr').forEach(row=>{
      const text = (row.textContent||'').replace(/\s+/g,' ').trim();
      if(!text || text.length < 10 || text.length > 800) return;
      if(_FCCV_TS_RE.test(text)) return; // ya procesada
      const d = _fccvParseDate(text, yearStr);
      if(!d) return;
      const cells = [...row.querySelectorAll('td')].map(td=>(td.textContent||'').replace(/\s+/g,' ').trim()).filter(Boolean);
      const validCells = cells.filter(c=>_fccvIsValidRaceName(c));
      const name = validCells.sort((a,b)=>b.length-a.length)[0] || '';
      const location = validCells.find(c=>c!==name && c.length>2 && c.length<60) || '';
      push(d.iso, name, location, text);
    });
  }

  // ── ESTRATEGIA FALLBACK: bloques div/li con título + fecha ──
  if(races.length < 5){
    doc.querySelectorAll('div, li, article, section').forEach(el=>{
      if(!el.querySelector('a, h2, h3, h4, h5, strong, b')) return;
      const text = (el.textContent||'').replace(/\s+/g,' ').trim();
      if(text.length < 10 || text.length > 800) return;
      if(_FCCV_TS_RE.test(text)) return;
      const d = _fccvParseDate(text, yearStr);
      if(!d) return;
      const nameEl = el.querySelector('a, h2, h3, h4, h5, strong, b');
      const name = (nameEl?.textContent||'').replace(/\s+/g,' ').trim();
      if(!_fccvIsValidRaceName(name)) return;
      const restText = text.replace(name,'').replace(d.raw,'').replace(/\s+/g,' ').trim();
      const location = restText.split(/[·•|,\-—()/]/).map(s=>s.trim()).find(s=>s.length>2&&s.length<60) || '';
      push(d.iso, name, location, text);
    });
  }

  // Ordenar por fecha
  races.sort((a,b)=>a.date.localeCompare(b.date));
  return races;
}

// Extrae texto de categoría del rawText (mejor esfuerzo) — para mostrar en
// la columna Categoría de la tabla de resultados FCCV.
function _fccvExtractCategoryFromText(txt){
  if(!txt) return '';
  const s = String(txt);
  // Buscar tokens de categoría conocidos, intentar capturar la lista completa
  // Ej: "Cadete, Cadete Fem., Junior" o "Elite, Sub-23"
  const catTokens = /\b(?:cadet[es]?(?:\s+fem\.?)?|junior[s]?(?:\s+fem\.?)?|sub.?23(?:\s+fem\.?)?|elite(?:\s+fem\.?)?|master[s]?|alev[ií]n(?:\s+femenino)?(?:\s+\d)?|infantil[es]?|escola[rs]?\s*ciclismo|cicloturismo|principiantes|promesa[s]?)/ig;
  const matches = s.match(catTokens);
  if(!matches || !matches.length) return '';
  // Eliminar duplicados conservando orden, máximo 4 categorías
  const seen = new Set();
  const unique = [];
  matches.forEach(m=>{
    const k = m.toLowerCase().replace(/\s+/g,' ').trim();
    if(seen.has(k)) return;
    seen.add(k);
    unique.push(m.replace(/\s+/g,' ').trim());
  });
  let result = unique.slice(0,4).join(', ');
  if(unique.length > 4) result += '...';
  return result;
}

// Detecta si una prueba es FEMENINO-ONLY (solo mujeres)
// Estrategia: 2 pruebas (más fuerte si la columna "Categorías" está disponible)
function _fccvIsFemaleOnly(txt, categoryField){
  const lower = (txt||'').toLowerCase();

  // PRUEBA 1 — La más fiable: columna Categorías celda a celda.
  // Si TODAS las categorías listadas contienen "fem", "femenin" o "mujer",
  // es 100% femenina.
  if(categoryField && categoryField.trim()){
    const tokens = categoryField.toLowerCase()
      .split(/[,;]/)
      .map(s=>s.replace(/\.\.\.$/,'').trim())
      .filter(s=>s.length>=3);
    if(tokens.length){
      const allFem = tokens.every(t=>/\bfem\b|fem\.|femen|mujer|dones/i.test(t));
      if(allFem) return true;
    }
  }

  // PRUEBA 2 — Indicadores fuertes en el TÍTULO o rawText
  const titlePatterns = /(\bfemen[ií]n[oa]?\b|\bfemen[ií]s?\b|\bmujeres\b|\bfeminas\b|\bdones\b|gran\s+premi\s+femen|trofeo\s+femen|copa\s+femen|carrera\s+ciclista\s+femen|trofeo\s+f[eé]minas|\bf[eé]mina[s]?\b|challenge\s+mujeres|copa\s+mujeres|reto\s+mujeres)/i;
  return titlePatterns.test(lower);
}

// Detecta si tiene categoría masculina (no fem) entre sus categorías
function _fccvHasMaleCategory(txt, categoryField){
  // 1) Si tenemos columna Categorías, decidimos por celdas
  if(categoryField && categoryField.trim()){
    const tokens = categoryField.toLowerCase()
      .split(/[,;]/)
      .map(s=>s.replace(/\.\.\.$/,'').trim())
      .filter(s=>s.length>=3);
    if(tokens.length){
      // Una categoría MASCULINA es una que tiene "cadete/junior/sub23/elite/master"
      // y NO tiene "fem"/"femen"/"mujer"
      const hasMale = tokens.some(t=>
        /\b(cadet|junior|sub.?23|elite|master)/i.test(t) &&
        !/\bfem\b|fem\.|femen|mujer|dones/i.test(t)
      );
      return hasMale;
    }
  }
  // 2) Fallback general
  const lower = (txt||'').toLowerCase();
  const malePatterns = [
    /\bcadet[es]?\b(?!\s*(?:fem|femen|f\.|f,))/,
    /\bjunior[es]?\b(?!\s*(?:fem|femen|f\.|f,))/,
    /\bsub.?23\b(?!\s*(?:fem|femen|f\.))/,
    /\belite\b(?!\s*(?:fem|femen|f\.))/,
    /\bmaster[s]?\b(?!\s*(?:fem|femen|f\.))/,
  ];
  return malePatterns.some(re=>re.test(lower));
}

// Aplica filtros con la lógica de exclusión (no mezclar Cadetes con Escuela/Infantil)
function _fccvApplyFilters(races, cat, mod, gen){
  return races.filter(r=>{
    // Buscar en rawText + name + modality + category (cada uno aporta señal)
    const txt = [(r.rawText||''), (r.name||''), (r.modality||''), (r.category||'')].join(' ').toLowerCase();

    // ── MODALIDAD ──
    if(mod){
      const modPatterns = {
        'carretera': /(carretera|ruta|\bcri\b|cronometro|circuito|critérium|criterium|copa.*carretera)/i,
        'btt':       /(\bbtt\b|\bmtb\b|monta[ñn]a|descenso|enduro|maratón|xc\b)/i,
        'cx':        /(\bcx\b|ciclo.?cross|ciclocross)/i,
        'pista':     /pista/i,
        'trial':     /trial/i,
      };
      const p = modPatterns[mod];
      if(p && !p.test(txt)) return false;
      // Exclusiones cruzadas: si pides CARRETERA, no debe ser explícitamente BTT/CX
      if(mod==='carretera' && /(\bbtt\b|\bmtb\b|ciclo.?cross|\bcx\b|monta[ñn]a)/i.test(txt)) return false;
      if(mod==='btt' && /carretera|ruta/i.test(txt) && !/btt|mtb/i.test(txt)) return false;
    }

    // ── CATEGORÍA ──
    // Acepta variantes ES + CA/VA (valenciano) + abreviaciones.
    if(cat){
      const catPatterns = {
        // cadete (ES) · cadet (CA/VA) · cadetes · cadets · CAD · CAD-1 · CAD-2 · CDT
        'cadete':    /(\bcadet(?:e|es|s)?\b|\bcad(?:[-_ ]?[12])?\b|\bcdt\b)/i,
        // junior (ES) · júnior · juniors · jun · JUN-1/2 · sub-17 / sub-19 (RFEC)
        'junior':    /(\bj[uú]nior(?:s|es)?\b|\bjun(?:[-_ ]?[12])?\b|\bsub.?(?:17|19)\b)/i,
        // sub-23 / sub23
        'sub23':     /(\bsub.?23\b)/i,
        // elite / élite
        'elite':     /(\b[éeÉE]lite\b)/i,
        // master / masters / M30 / M40 ...
        'master':    /(\bmaster[s]?\b|\bm[-_ ]?\d{2,3}\b)/i,
        // femenino / femení (CA/VA) / fem / F-CAD / F-JUN
        'femenino':  /(femenin[oa]?\b|femen[ií]\b|\bfem\b|\bf[-_ ]?(?:cad|jun|elite|master))/i,
      };
      const p = catPatterns[cat];
      if(p && !p.test(txt)) return false;

      // EXCLUSIÓN CRÍTICA: cuando pides cadete/junior/sub23/elite/master no queremos
      // pruebas mezcladas con ESCUELA/INFANTIL/ALEVÍN/PRINCIPIANTES/PROMESAS/BENJAMÍN
      // (idiomas ES + CA/VA)
      const adultCategories = ['cadete','junior','sub23','elite','master'];
      if(adultCategories.includes(cat)){
        const exclusionRe = /(\bescuela[s]?\b|\bescolar(?:es)?\b|\bescola[rs]?\b|\binfantil[es]?\b|\binfantí?l[s]?\b|\balev[ií]n(?:es)?\b|\balev[ií]?[ns]?\b|\bprincipiant\w*\b|\bpre[-_ ]?infantil\w*\b|\bpromesa[s]?\b|\bbenjam[ií]n(?:es)?\b|\bbenjamí?[ns]?\b)/i;
        if(exclusionRe.test(txt)) return false;
      }
    }

    // ── GÉNERO ──
    // Lógica estricta usando la columna Categorías cuando está disponible:
    //  - "masculino": excluye pruebas FEMENINO-ONLY (todas sus categorías son fem).
    //                 Además, si se ha pedido también una categoría concreta
    //                 (cadete/junior/...), exige que esa categoría aparezca SIN
    //                 marca fem en al menos un token (p.ej. "Cadete" sí, "Cadete Fem." no).
    //  - "femenino":  solo pruebas con al menos una categoría femenina
    //  - "mixto":     debe tener al menos 1 categoría masculina Y 1 femenina
    //  - "" (Todos):  no filtra por género
    if(gen){
      // Si el campo category está vacío, intentamos extraerlo del rawText
      const catField = r.category || _fccvExtractCategoryFromText(r.rawText) || '';
      const isFem = _fccvIsFemaleOnly(txt, catField);
      const hasMale = _fccvHasMaleCategory(txt, catField);
      if(gen==='masculino'){
        if(isFem && !hasMale) return false;
        // Si además filtra por categoría concreta (cadete/junior/sub23/elite/master),
        // exige que esa categoría exista SIN marca fem en al menos un token.
        const adultCats = {
          'cadete':/cadet/i, 'junior':/j[uú]nior|\bjun\b/i, 'sub23':/sub.?23/i,
          'elite':/[éeÉE]lite/i, 'master':/master/i
        };
        if(cat && adultCats[cat] && catField){
          const tokens = catField.toLowerCase()
            .split(/[,;]/).map(s=>s.replace(/\.\.\.$/,'').trim()).filter(s=>s.length>=2);
          const hasMaleVariant = tokens.some(t=>
            adultCats[cat].test(t) && !/\bfem\b|fem\.|femen|mujer|dones/i.test(t)
          );
          if(tokens.length && !hasMaleVariant) return false;
        }
      } else if(gen==='femenino'){
        if(!isFem && !/\b(fem\b|fem\.|femen|femina|mujer|dones)/i.test(txt)) return false;
      } else if(gen==='mixto'){
        const hasFemMark = /\bfem\b|fem\.|femen|femina|mujer|dones/i.test(catField || txt);
        if(!(hasMale && hasFemMark)) return false;
      }
    }

    return true;
  });
}

// Borra todo el scrape acumulado y los modales en caché. Útil cuando los
// datos en localStorage están corruptos o desfasados.
function _fccvResetCache(){
  if(!confirm('¿Borrar todo el scrape FCCV acumulado y los modales cacheados?\n\nTras esto, la próxima sincronización empezará desde cero descargando el calendario completo.')) return;
  _fccvLastAllRaces = [];
  _fccvLastResults = [];
  _fccvDetailsById = {};
  try{
    localStorage.removeItem(_FCCV_STORAGE_KEY);
    // También borrar URLs ganadoras cacheadas por año
    for(let i=localStorage.length-1;i>=0;i--){
      const k = localStorage.key(i);
      if(k && k.startsWith('fccvWorkingUrl_')) localStorage.removeItem(k);
    }
  }catch(_){}
  const status = document.getElementById('fccvStatus');
  if(status){
    status.textContent = '🗑️ Caché borrada. Pulsa Sincronizar para descargar el calendario actualizado.';
    status.style.color = '#dc2626';
  }
  const results = document.getElementById('fccvResults');
  if(results) results.innerHTML = '';
  if(typeof _calRender==='function') _calRender();
}

// ── Importador de Excel exportado desde la FCCV ──
// La FCCV permite exportar a Excel todo el calendario del año (incluyendo
// pruebas ya disputadas que no aparecen en el HTML público). El usuario
// arrastra ese fichero aquí y nosotros lo parseamos con SheetJS.
function _fccvHandleExcelInput(ev){
  const file = ev.target.files && ev.target.files[0];
  if(file) _fccvParseExcelFile(file);
  ev.target.value = ''; // reset para permitir re-seleccionar el mismo fichero
}
function _fccvHandleExcelDrop(ev){
  const file = ev.dataTransfer.files && ev.dataTransfer.files[0];
  if(file) _fccvParseExcelFile(file);
}
async function _fccvParseExcelFile(file){
  const status = document.getElementById('fccvStatus');
  if(status){ status.textContent = `📥 Leyendo ${file.name}…`; status.style.color = '#92400e'; }
  try{
    const buf = await file.arrayBuffer();
    const wb = XLSX.read(buf, {type:'array', cellHTML:true, cellDates:true});
    const sheet = wb.Sheets[wb.SheetNames[0]];
    if(!sheet){ throw new Error('Excel sin hojas'); }
    const rows = XLSX.utils.sheet_to_json(sheet, {header:1, defval:'', raw:false});
    if(rows.length < 2){ throw new Error('Excel vacío o sin filas de datos'); }

    // Detectar encabezados (primera fila con varias celdas que parecen títulos)
    let headerIdx = 0;
    for(let i=0;i<Math.min(rows.length,5);i++){
      const r = rows[i].map(c=>String(c||'').toLowerCase());
      if(r.some(c=>/fecha/.test(c)) && r.some(c=>/prueba|nombre/.test(c))){
        headerIdx = i; break;
      }
    }
    const header = rows[headerIdx].map(c=>String(c||'').toLowerCase().trim());
    const idx = {
      fecha:    header.findIndex(c=>/fecha/.test(c)),
      modalidad:header.findIndex(c=>/modalidad/.test(c)),
      cat:      header.findIndex(c=>/categor/.test(c)),
      clase:    header.findIndex(c=>/clase|uci/.test(c)),
      prueba:   header.findIndex(c=>/prueba|nombre/.test(c)),
      lugar:    header.findIndex(c=>/lugar|localidad|poblaci/.test(c)),
      club:     header.findIndex(c=>/club|organiz/.test(c)),
    };
    if(idx.fecha<0 || idx.prueba<0){
      throw new Error('No se detectaron las columnas Fecha y Prueba. Cabeceras: '+header.join(' | '));
    }

    // Parsear fechas en formato español DD/MM/YYYY o Date
    const parseFecha = (val)=>{
      if(!val) return '';
      if(val instanceof Date && !isNaN(val)){
        const y = val.getFullYear(), m = String(val.getMonth()+1).padStart(2,'0'), d = String(val.getDate()).padStart(2,'0');
        return `${y}-${m}-${d}`;
      }
      const s = String(val).trim();
      let m = s.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})$/);
      if(m){
        let yy = m[3]; if(yy.length===2) yy = (parseInt(yy,10)>50?'19':'20')+yy;
        return `${yy}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;
      }
      m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
      if(m) return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
      return '';
    };

    const newRaces = [];
    for(let i=headerIdx+1; i<rows.length; i++){
      const r = rows[i];
      if(!r || !r.length) continue;
      const fecha = parseFecha(r[idx.fecha]);
      const name = String(r[idx.prueba]||'').trim();
      if(!fecha || !name) continue;
      newRaces.push({
        date: fecha,
        dateText: fecha,
        name,
        location: idx.lugar>=0 ? String(r[idx.lugar]||'').trim() : '',
        rawText: r.join(' | '),
        modality: idx.modalidad>=0 ? String(r[idx.modalidad]||'').trim() : '',
        category: idx.cat>=0 ? String(r[idx.cat]||'').trim() : '',
        club: idx.club>=0 ? String(r[idx.club]||'').trim() : '',
        clase: idx.clase>=0 ? String(r[idx.clase]||'').trim() : '',
        fccvId: '',         // el Excel no incluye ID interno
        fccvDetailUrl: '',
        source: 'excel'
      });
    }

    // Merge con scrape acumulado: indexamos por (fecha + nombre normalizado + cat)
    // para no duplicar. Las entradas del Excel pueden no tener fccvId — no las
    // tocamos pero las usamos para matching/info básica.
    const norm = s=>(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
    const key = c=>`${c.date||''}|${norm(c.name).slice(0,50)}|${norm(c.category).slice(0,30)}`;
    const merged = new Map();
    for(const c of (_fccvLastAllRaces||[])) merged.set(key(c), c);
    let added = 0, updated = 0;
    for(const c of newRaces){
      const k = key(c);
      const prev = merged.get(k);
      if(prev){
        // Si el previo no tenía algunos campos, los rellena con los del Excel
        if(!prev.modality && c.modality) prev.modality = c.modality;
        if(!prev.category && c.category) prev.category = c.category;
        if(!prev.location && c.location) prev.location = c.location;
        updated++;
      } else {
        merged.set(k, c);
        added++;
      }
    }
    _fccvLastAllRaces = [...merged.values()].sort((a,b)=>(a.date||'').localeCompare(b.date||''));
    _fccvPersistScrape();
    if(status){
      status.textContent = `✅ Excel importado · ${added} pruebas nuevas, ${updated} actualizadas · total en caché: ${_fccvLastAllRaces.length}`;
      status.style.color = '#15803d';
    }
    // Refrescar la vista del calendario (los botones Info reaccionarán al nuevo cache)
    if(typeof _calRender==='function') _calRender();
  }catch(e){
    console.error(e);
    if(status){
      status.textContent = `❌ Error procesando Excel: ${e.message}`;
      status.style.color = '#dc2626';
    }
    alert('No pude leer el Excel.\n\n' + e.message + '\n\nAsegúrate de descargarlo desde el botón Excel del calendario FCCV.');
  }
}

async function _fccvSync(){
  _fccvInitYears();
  const year = document.getElementById('fccvYear')?.value || new Date().getFullYear();
  const cat  = document.getElementById('fccvCat')?.value || '';
  const mod  = document.getElementById('fccvMod')?.value || '';
  const gen  = document.getElementById('fccvGen')?.value || '';

  const btn = document.getElementById('fccvSyncBtn');
  const status = document.getElementById('fccvStatus');
  const results = document.getElementById('fccvResults');
  if(results) results.innerHTML = '';
  if(btn){ btn.disabled = true; btn.textContent = '⏳ Consultando FCCV...'; btn.style.opacity = '.7'; }
  if(status) status.textContent = `Conectando con fccv.es (vía proxy CORS)...`;

  const baseUrl = `https://fccv.es/index.php/es/smartweb/seccion/calendario/valenciana/${year}`;
  const yyyy = String(year);
  // Timestamps Unix para 1-enero y 31-diciembre del año seleccionado en hora
  // local Madrid (UTC+1). Estos son los nombres REALES de parámetro que usa
  // el slider de fechas de la FCCV: fecha_inicio_b / fecha_fin_b.
  const tsFrom = Math.floor(new Date(`${yyyy}-01-01T00:00:00+01:00`).getTime()/1000);
  const tsTo   = Math.floor(new Date(`${yyyy}-12-31T23:59:00+01:00`).getTime()/1000);
  const REAL_FILTER = `${baseUrl}?fecha_inicio_b=${tsFrom}&fecha_fin_b=${tsTo}`;
  const dateFrom = `${yyyy}-01-01`;
  const dateTo   = `${yyyy}-12-31`;
  const dateFromES = `01/01/${yyyy}`;
  const dateToES   = `31/12/${yyyy}`;
  // Probamos varios nombres de parámetros de filtro de fechas. El primero es
  // el que confirmamos que funciona (revisando el HTML del slider).
  const candidateUrls = [
    REAL_FILTER, // ✅ funciona: devuelve TODO el año (descubierto inspeccionando el HTML real)
    // Variantes con fechas ISO YYYY-MM-DD
    `${baseUrl}?fechaDesde=${dateFrom}&fechaHasta=${dateTo}`,
    `${baseUrl}?desde=${dateFrom}&hasta=${dateTo}`,
    `${baseUrl}?from=${dateFrom}&to=${dateTo}`,
    `${baseUrl}?fecha_inicio=${dateFrom}&fecha_fin=${dateTo}`,
    `${baseUrl}?inicio=${dateFrom}&fin=${dateTo}`,
    `${baseUrl}?fechaInicio=${dateFrom}&fechaFin=${dateTo}`,
    `${baseUrl}?d1=${dateFrom}&d2=${dateTo}`,
    `${baseUrl}?start=${dateFrom}&end=${dateTo}`,
    `${baseUrl}?fechaIni=${dateFrom}&fechaFin=${dateTo}`,
    // Variantes con fechas DD/MM/YYYY (más típico en formularios españoles)
    `${baseUrl}?fechaDesde=${encodeURIComponent(dateFromES)}&fechaHasta=${encodeURIComponent(dateToES)}`,
    `${baseUrl}?desde=${encodeURIComponent(dateFromES)}&hasta=${encodeURIComponent(dateToES)}`,
    `${baseUrl}?fecha_inicio=${encodeURIComponent(dateFromES)}&fecha_fin=${encodeURIComponent(dateToES)}`,
    // Variante con parámetros típicos de Joomla SmartWeb
    `${baseUrl}?filter_fechaInicio=${dateFrom}&filter_fechaFin=${dateTo}`,
    `${baseUrl}?filter[fechaInicio]=${dateFrom}&filter[fechaFin]=${dateTo}`,
    // Forzar vista "todas" / archivo
    `${baseUrl}?all=1`,
    `${baseUrl}?past=1`,
    `${baseUrl}?archivo=1`,
    `${baseUrl}?ver=todas`,
    `${baseUrl}/archivo`,
    `${baseUrl}/todas`,
    `${baseUrl}/historico`,
    baseUrl // fallback sin filtro (solo futuros)
  ];
  const fccvUrl = baseUrl; // para mensajes/UI
  try{
    let html = '', all = [], chosenUrl = '';
    // Cache de la URL que funcionó la vez anterior — la probamos primero para
    // resincronizar rápido. Solo hace falta probar todas las variantes la 1ª vez.
    const cachedUrl = (()=>{ try{ return localStorage.getItem('fccvWorkingUrl_'+yyyy)||''; }catch(_){ return ''; } })();
    if(cachedUrl){
      try{
        if(status) status.textContent = `Conectando (filtro guardado)...`;
        const h = await _fccvFetch(cachedUrl);
        if(h && h.length>=500){
          const parsed = _fccvParseHtml(h, year);
          if(parsed.length>=50){
            all = parsed; html = h; chosenUrl = cachedUrl;
          }
        }
      }catch(_){}
    }
    // Si la cacheada no dio resultados, probamos las candidatas en PARALELO
    // (3 a la vez) y nos quedamos con la que devuelva más pruebas.
    if(!all.length || all.length<200){
      if(status) status.textContent = `Buscando filtro óptimo de la FCCV...`;
      const tryOne = async (url)=>{
        try{
          const h = await _fccvFetch(url);
          if(!h || h.length<500) return null;
          const parsed = _fccvParseHtml(h, year);
          return {url, h, parsed};
        }catch(_){ return null; }
      };
      // Procesar en chunks de 3 paralelos
      const CHUNK = 3;
      for(let i=0;i<candidateUrls.length;i+=CHUNK){
        const chunk = candidateUrls.slice(i, i+CHUNK);
        const results = await Promise.all(chunk.map(tryOne));
        for(const res of results){
          if(!res) continue;
          if(res.parsed.length > all.length){
            all = res.parsed; html = res.h; chosenUrl = res.url;
          }
        }
        // Si ya tenemos buen resultado, paramos
        if(all.length>=200 || all.some(r=>r.date && r.date.startsWith(yyyy+'-01'))) break;
      }
      // Guardar la URL ganadora si supera al fallback "solo futuros"
      if(chosenUrl && chosenUrl!==baseUrl){
        try{ localStorage.setItem('fccvWorkingUrl_'+yyyy, chosenUrl); }catch(_){}
      }
    }
    if(status) status.textContent = `📄 HTML recibido (${(html.length/1024).toFixed(1)} KB) · ${chosenUrl===baseUrl?'sin filtro de fechas':'con filtro de fechas'} · ${all.length} carreras detectadas`;
    if(!all.length){
      if(results) results.innerHTML = `<div style="background:#fef2f2;border:1px solid #fca5a5;border-radius:10px;padding:14px;color:#991b1b;font-size:13px">
        ⚠️ Se recibió el HTML pero no se detectó ninguna carrera con el formato esperado.<br>
        Puede que la estructura de la web haya cambiado. <a href="${fccvUrl}" target="_blank" style="color:#dc2626;font-weight:700">Abrir calendario FCCV en nueva pestaña</a> para inspeccionar.
      </div>`;
      if(status) status.textContent = '';
      return;
    }
    const filtered = _fccvApplyFilters(all, cat, mod, gen);
    _fccvLastResults = filtered;
    // Fusionar el scrape nuevo con el histórico acumulado: la FCCV solo
    // publica pruebas futuras en su calendario, así que las que ya se han
    // disputado desaparecen del HTML — pero nosotros queremos seguir pudiendo
    // consultar su info / reglamento / clasificación. Solución: nunca borrar,
    // siempre acumular indexando por fccvId.
    const prevById = new Map();
    for(const c of (_fccvLastAllRaces||[])){
      if(c && c.fccvId) prevById.set(c.fccvId, c);
    }
    for(const c of all){
      if(c && c.fccvId) prevById.set(c.fccvId, c); // sobreescribe con datos más recientes
    }
    _fccvLastAllRaces = [...prevById.values()].sort((a,b)=>(a.date||'').localeCompare(b.date||''));
    // _fccvDetailsById ya se acumula de forma natural en _fccvParseHtml (no se
    // resetea aquí). Si una prueba pasada ya no aparece en el scrape nuevo,
    // su modal HTML guardado seguirá disponible en localStorage.
    _fccvPersistScrape();
    if(status){
      const debugBtn = ` <button onclick="_fccvShowDebug()" style="background:#fff;color:#92400e;border:1px solid #fcd34d;border-radius:6px;padding:2px 8px;font-size:11px;font-weight:700;cursor:pointer;margin-left:6px">🔍 Debug</button>`;
      status.innerHTML = `✅ ${all.length} carreras detectadas en el HTML · ${filtered.length} pasan los filtros · ${new Date().toLocaleTimeString('es-ES')}${debugBtn}`;
    }
    _fccvRenderResults(filtered);
  } catch(e){
    if(results) results.innerHTML = `<div style="background:#fef2f2;border:1px solid #fca5a5;border-radius:10px;padding:14px;color:#991b1b;font-size:13px">
      ❌ <strong>No se pudo conectar con la FCCV:</strong> ${escapeHtml(e.message||String(e))}<br>
      <span style="font-size:11px">Los proxies CORS pueden estar caídos. Reintenta en unos segundos o abre directamente <a href="${fccvUrl}" target="_blank" style="color:#dc2626;font-weight:700">${fccvUrl}</a></span>
    </div>`;
    if(status) status.textContent = '';
    console.error('[FCCV] Error:', e);
  } finally{
    if(btn){ btn.disabled = false; btn.textContent = '🔄 Sincronizar con Federación'; btn.style.opacity = '1'; }
  }
}

function _fccvRenderResults(races){
  const box = document.getElementById('fccvResults');
  if(!box) return;
  if(!races.length){
    box.innerHTML = `<div style="background:#fff;border:1px dashed #fcd34d;border-radius:10px;padding:18px;text-align:center;color:#92400e">
      <div style="font-size:28px;margin-bottom:6px">🤷</div>
      Ninguna carrera coincide con los filtros aplicados. Prueba a ampliar los criterios.
    </div>`;
    return;
  }

  // Identificar cuáles ya están en tu calendario (planned o past)
  const existingPlanned = (typeof _calPlanned!=='undefined'?_calPlanned:[]) || [];
  const existingPast    = (typeof _calPast   !=='undefined'?_calPast   :[]) || [];

  const normalize = (s)=>(s||'').toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g,'')
    .replace(/[^a-z0-9 ]/g,'')
    .replace(/\s+/g,' ').trim();

  const findMatch = (race)=>{
    const nKey = normalize(race.name);
    if(!nKey || nKey.length<5) return null;
    // Matching por nombre normalizado (substring de 8+ caracteres)
    const snippet = nKey.slice(0,Math.min(20, nKey.length));
    const matchInList = (list, type)=>{
      for(const it of list){
        const itKey = normalize(it.name);
        if(!itKey) continue;
        if(itKey === nKey || itKey.includes(snippet) || nKey.includes(itKey.slice(0,Math.min(20,itKey.length)))){
          return {item:it, type};
        }
      }
      return null;
    };
    return matchInList(existingPlanned, 'planned') || matchInList(existingPast, 'past');
  };

  box.innerHTML = `<div style="background:#fff;border-radius:10px;overflow:hidden;border:1px solid #fcd34d">
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead style="background:#fef3c7">
        <tr>
          <th style="padding:9px 12px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#78350f;width:110px">Fecha</th>
          <th style="padding:9px 12px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#78350f">Nombre de la prueba</th>
          <th style="padding:9px 12px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#78350f;width:170px">Categoría</th>
          <th style="padding:9px 12px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#78350f;width:140px">Localidad</th>
          <th style="padding:9px 12px;text-align:center;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#78350f;width:90px">Estado</th>
          <th style="padding:9px 12px;text-align:center;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#78350f;width:60px" title="Abre la ficha oficial de la FCCV con reglamento e info">FCCV</th>
          <th style="padding:9px 12px;text-align:center;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#78350f;width:70px">Acción</th>
        </tr>
      </thead>
      <tbody>
        ${races.map((r,i)=>{
          const match = findMatch(r);
          let estado='', accion='';
          if(!match){
            estado = `<span style="background:#dcfce7;color:#15803d;padding:3px 8px;border-radius:99px;font-size:11px;font-weight:700">🆕 Nueva</span>`;
            accion = `<button onclick="_fccvAddRace(${i})" style="background:#10b981;color:#fff;border:none;border-radius:7px;padding:5px 10px;font-weight:800;font-size:12px;cursor:pointer">＋ Añadir</button>`;
          } else if(match.type==='planned'){
            const sameDate = (match.item.dateStr||'').slice(0,10) === r.date;
            if(sameDate){
              estado = `<span style="background:#dbeafe;color:#1d4ed8;padding:3px 8px;border-radius:99px;font-size:11px;font-weight:700">✓ Planificada</span>`;
              accion = `<span style="font-size:11px;color:#94a3b8">—</span>`;
            } else {
              estado = `<span style="background:#fef3c7;color:#92400e;padding:3px 8px;border-radius:99px;font-size:11px;font-weight:700">📅 Cambio fecha</span>`;
              accion = `<button onclick="_fccvAddRace(${i})" style="background:#d97706;color:#fff;border:none;border-radius:7px;padding:5px 10px;font-weight:800;font-size:12px;cursor:pointer" title="Actualizar fecha sin perder datos">↻ Actualizar</button>`;
            }
          } else { // past
            estado = `<span style="background:#e0e7ff;color:#4338ca;padding:3px 8px;border-radius:99px;font-size:11px;font-weight:700">🏁 Disputada</span>`;
            accion = `<span style="font-size:11px;color:#94a3b8">—</span>`;
          }
          const [y,m,d] = r.date.split('-');
          const dateDisplay = `${d}/${m}/${y}`;
          const catLabel = r.category || _fccvExtractCategoryFromText(r.rawText) || '—';
          // Botón "Info": abre la ficha oficial FCCV (reglamento, categorías
          // completas, contactos) en una ventana propia, leída del modal que
          // ya descargamos junto al calendario — instantáneo, sin volver a
          // filtrar en fccv.es.
          const fccvYear = (r.date||'').slice(0,4) || new Date().getFullYear();
          const fccvBase = `https://fccv.es/index.php/es/smartweb/seccion/calendario/valenciana/${fccvYear}`;
          const hasDetails = r.fccvId && _fccvDetailsById[r.fccvId];
          const linkBtn = hasDetails
            ? `<button onclick="_fccvShowRaceDetails('${r.fccvId}')" title="Ver ficha oficial FCCV (reglamento, info)" style="display:inline-flex;align-items:center;gap:4px;background:#1e40af;color:#fff;border:none;border-radius:7px;padding:5px 9px;font-weight:800;font-size:12px;cursor:pointer">ℹ️ Info</button>`
            : `<a href="${fccvBase}" target="_blank" rel="noopener" title="Abrir calendario FCCV (no se detectaron datos de esta prueba)" style="display:inline-flex;align-items:center;gap:4px;background:#94a3b8;color:#fff;text-decoration:none;border-radius:7px;padding:5px 9px;font-weight:700;font-size:11px;cursor:pointer">🔗</a>`;
          return `<tr style="border-top:1px solid #fef3c7">
            <td style="padding:9px 12px;font-family:monospace;font-weight:700;color:#0b2f6b">${dateDisplay}</td>
            <td style="padding:9px 12px;font-weight:700">${escapeHtml(r.name)}</td>
            <td style="padding:9px 12px;color:#475569;font-size:12px;font-weight:600">${escapeHtml(catLabel)}</td>
            <td style="padding:9px 12px;color:#6b7280;font-size:12px">${escapeHtml(r.location||'—')}</td>
            <td style="padding:9px 12px;text-align:center">${estado}</td>
            <td style="padding:9px 12px;text-align:center">${linkBtn}</td>
            <td style="padding:9px 12px;text-align:center">${accion}</td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>
  </div>`;
}

// Modal de debug: muestra TODAS las carreras detectadas (sin filtrar) y
// los primeros 6000 caracteres del HTML crudo recibido. Para diagnosticar
// problemas de parsing.
function _fccvShowDebug(){
  const all = _fccvLastAllRaces || [];
  const stats = window._fccvLastStats || {tablesFound:0,rowsTotal:0,rowsWithTd:0,rowsWith3plus:0,rowsWithDate:0,rowsWithValidName:0,rowsAccepted:0,samples:[]};
  const rawFirst = (_fccvLastRawHtml||'').slice(0, 6000);
  const rawLast = (_fccvLastRawHtml||'').length > 8000
    ? (_fccvLastRawHtml||'').slice(-6000)
    : '';
  const totalKb = ((_fccvLastRawHtml||'').length/1024).toFixed(1);

  const statsHtml = `
    <table style="width:100%;border-collapse:collapse;font-size:12px;font-family:monospace">
      <tr><td style="padding:4px 8px;border:1px solid #e5e7eb;background:#f9fafb">Tablas encontradas</td><td style="padding:4px 8px;border:1px solid #e5e7eb;text-align:right;font-weight:700">${stats.tablesFound}</td></tr>
      <tr><td style="padding:4px 8px;border:1px solid #e5e7eb;background:#f9fafb">&lt;tr&gt; totales</td><td style="padding:4px 8px;border:1px solid #e5e7eb;text-align:right;font-weight:700">${stats.rowsTotal}</td></tr>
      <tr><td style="padding:4px 8px;border:1px solid #e5e7eb;background:#f9fafb">&lt;tr&gt; con &lt;td&gt;</td><td style="padding:4px 8px;border:1px solid #e5e7eb;text-align:right;font-weight:700">${stats.rowsWithTd}</td></tr>
      <tr><td style="padding:4px 8px;border:1px solid #e5e7eb;background:#f9fafb">&lt;tr&gt; con ≥2 celdas</td><td style="padding:4px 8px;border:1px solid #e5e7eb;text-align:right;font-weight:700">${stats.rowsWith3plus}</td></tr>
      <tr><td style="padding:4px 8px;border:1px solid #e5e7eb;background:#fef3c7">&lt;tr&gt; con FECHA detectada</td><td style="padding:4px 8px;border:1px solid #e5e7eb;text-align:right;font-weight:700;background:#fef3c7">${stats.rowsWithDate}</td></tr>
      <tr><td style="padding:4px 8px;border:1px solid #e5e7eb;background:#fef3c7">&lt;tr&gt; con NOMBRE válido</td><td style="padding:4px 8px;border:1px solid #e5e7eb;text-align:right;font-weight:700;background:#fef3c7">${stats.rowsWithValidName}</td></tr>
      <tr><td style="padding:4px 8px;border:1px solid #e5e7eb;background:#dcfce7">&lt;tr&gt; aceptadas finalmente</td><td style="padding:4px 8px;border:1px solid #e5e7eb;text-align:right;font-weight:700;background:#dcfce7">${stats.rowsAccepted}</td></tr>
    </table>
  `;

  const samplesHtml = stats.samples.length
    ? `<ol style="font-size:11px;font-family:monospace;padding-left:18px;margin:0">
        ${stats.samples.map(s=>`<li style="margin-bottom:6px;padding:6px;background:#fff;border:1px solid #e5e7eb;border-radius:6px">
          <strong style="color:#dc2626">[${s.reason}]</strong>
          ${s.date?` fecha: <code>${s.date}</code>`:''}
          ${s.name?` nombre: <strong>${escapeHtml(s.name)}</strong>`:''}
          ${s.tdTexts?`<br><span style="color:#64748b">td: ${s.tdTexts.map(t=>escapeHtml((t||'').slice(0,40))).join(' | ')}</span>`:''}
        </li>`).join('')}
      </ol>`
    : `<div style="color:#94a3b8;padding:10px">Sin muestras de descarte.</div>`;

  const allHtml = all.length
    ? `<ol style="font-size:12px;font-family:monospace;padding-left:20px;margin:0">
        ${all.map(r=>`<li style="margin-bottom:4px"><strong>${r.date}</strong> — ${escapeHtml(r.name)} <span style="color:#94a3b8">${escapeHtml(r.location||'')}</span></li>`).join('')}
      </ol>`
    : `<div style="color:#dc2626;padding:14px;background:#fef2f2;border-radius:8px">⚠️ El parser no detectó ninguna carrera.</div>`;

  const old = document.getElementById('_fccvDebugDialog');
  if(old) old.remove();
  const overlay = document.createElement('div');
  overlay.id = '_fccvDebugDialog';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.onclick = e => { if(e.target===overlay) overlay.remove(); };
  overlay.innerHTML = `<div style="background:#fff;border-radius:14px;max-width:1000px;width:100%;max-height:92vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.3);padding:22px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">
      <h3 style="margin:0;color:#0b2f6b">🔍 Debug del parser FCCV</h3>
      <button onclick="document.getElementById('_fccvDebugDialog')?.remove()" style="background:#f3f4f6;border:none;border-radius:8px;padding:6px 12px;font-weight:700;cursor:pointer">✕ Cerrar</button>
    </div>
    <p style="font-size:13px;color:#374151;margin:0 0 10px"><strong>${all.length}</strong> carreras detectadas · HTML recibido: <strong>${totalKb} KB</strong></p>

    <details open style="margin-bottom:14px">
      <summary style="cursor:pointer;font-weight:800;color:#0b2f6b;padding:8px;background:#f0f9ff;border-radius:8px">📊 Estadísticas del parser</summary>
      <div style="padding:10px;background:#f9fafb;border-radius:8px;margin-top:6px">${statsHtml}</div>
    </details>

    <details style="margin-bottom:14px">
      <summary style="cursor:pointer;font-weight:800;color:#0b2f6b;padding:8px;background:#fef2f2;border-radius:8px">⚠️ Filas descartadas (primeras 8 muestras)</summary>
      <div style="padding:10px;background:#fef9f9;border-radius:8px;margin-top:6px;max-height:280px;overflow-y:auto">${samplesHtml}</div>
    </details>

    <details style="margin-bottom:14px">
      <summary style="cursor:pointer;font-weight:800;color:#0b2f6b;padding:8px;background:#f0f9ff;border-radius:8px">📋 Carreras detectadas (sin filtrar)</summary>
      <div style="padding:12px;background:#f9fafb;border-radius:8px;margin-top:6px;max-height:300px;overflow-y:auto">${allHtml}</div>
    </details>

    <details style="margin-bottom:14px">
      <summary style="cursor:pointer;font-weight:800;color:#0b2f6b;padding:8px;background:#f0f9ff;border-radius:8px">🌐 HTML primeros 6 KB</summary>
      <pre style="padding:12px;background:#1f2937;color:#86efac;border-radius:8px;font-size:11px;overflow-x:auto;max-height:280px;margin-top:6px;white-space:pre-wrap;word-break:break-all">${escapeHtml(rawFirst)}</pre>
    </details>

    ${rawLast ? `<details style="margin-bottom:14px">
      <summary style="cursor:pointer;font-weight:800;color:#0b2f6b;padding:8px;background:#f0f9ff;border-radius:8px">🌐 HTML últimos 6 KB</summary>
      <pre style="padding:12px;background:#1f2937;color:#86efac;border-radius:8px;font-size:11px;overflow-x:auto;max-height:280px;margin-top:6px;white-space:pre-wrap;word-break:break-all">${escapeHtml(rawLast)}</pre>
    </details>`:''}

    <div style="display:flex;gap:8px;margin-top:10px">
      <button onclick="navigator.clipboard.writeText(_fccvLastRawHtml||'').then(()=>alert('✓ HTML completo copiado al portapapeles ('+((_fccvLastRawHtml||'').length/1024).toFixed(1)+' KB)'))" style="background:#0b2f6b;color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">📋 Copiar HTML completo</button>
      <button onclick="navigator.clipboard.writeText(JSON.stringify({stats: window._fccvLastStats, races: _fccvLastAllRaces}, null, 2)).then(()=>alert('✓ Stats y carreras copiadas al portapapeles'))" style="background:#fff;color:#0b2f6b;border:1.5px solid #0b2f6b;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">📋 Copiar stats + carreras</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);
}

// Descarga bajo demanda la ficha individual de una prueba que no esté en
// cache. La FCCV expone cada prueba bajo URLs con patrones consistentes; se
// prueban varios hasta encontrar uno que responda. El HTML resultante se
// guarda en _fccvDetailsById[id] para que futuras consultas sean instantáneas.
async function _fccvFetchDetailById(fccvId, knownUrl){
  if(!fccvId) return null;
  if(_fccvDetailsById[fccvId]) return _fccvDetailsById[fccvId];
  // Si tenemos un detailUrl conocido (extraído del scrape) lo usamos primero;
  // luego variantes habituales en Joomla SmartWeb de la FCCV.
  const candidates = [];
  if(knownUrl) candidates.push(knownUrl);
  candidates.push(
    `https://fccv.es/index.php/es/smartweb/prueba/${fccvId}`,
    `https://fccv.es/index.php/es/smartweb/seccion/prueba/${fccvId}`,
    `https://fccv.es/index.php/component/smartweb/?view=prueba&id=${fccvId}`,
    `https://fccv.es/index.php?option=com_smartweb&view=prueba&id=${fccvId}`
  );

  for(const url of candidates){
    try{
      const html = await _fccvFetch(url, {minBytes: 2000}); // fichas son pequeñas
      if(!html || html.length<500) continue;
      const doc = new DOMParser().parseFromString(html, 'text/html');
      // Estrategia 1: existe el modal embebido (mismo patrón que el calendario)
      const modal = doc.querySelector(`#prueba${fccvId}`) ||
                    doc.querySelector('[id^="prueba"]');
      let content = '';
      if(modal){
        content = modal.innerHTML || '';
      } else {
        // Estrategia 2: extraer el contenedor principal de la página
        const main = doc.querySelector('article, main, #content, .item-page, .smartweb-prueba, .moduletable') ||
                     doc.querySelector('body');
        if(main){
          // Quitar nav/header/footer obvios
          main.querySelectorAll('nav, header, footer, script, style, .breadcrumb, #aside').forEach(el=>el.remove());
          content = main.innerHTML || '';
        }
      }
      if(content && content.length>200){
        _fccvDetailsById[fccvId] = content;
        try{ _fccvPersistScrape(); }catch(_){}
        return content;
      }
    }catch(e){
      console.warn(`[FCCV] fetch directo ${url} falló:`, e.message);
    }
  }
  return null;
}

// Muestra los detalles oficiales de una prueba FCCV (categorías completas,
// reglamento, contactos) en un modal propio. Reescribe los enlaces relativos
// del HTML original para que apunten a fccv.es y se abran en pestaña nueva.
async function _fccvShowRaceDetails(pruebaId){
  let raw = _fccvDetailsById[pruebaId];
  if(!raw){
    // No tenemos el modal en cache. Mostrar loader y descargar individualmente
    // desde la FCCV (proxy CORS). Útil para pruebas pasadas que la FCCV ha
    // sacado del calendario público pero cuya ficha individual sigue accesible.
    const loaderId = '_fccvLoadingDialog';
    const old = document.getElementById(loaderId);
    if(old) old.remove();
    const ldr = document.createElement('div');
    ldr.id = loaderId;
    ldr.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99998;display:flex;align-items:center;justify-content:center';
    ldr.innerHTML = `<div style="background:#fff;border-radius:14px;padding:24px 32px;text-align:center;font-family:system-ui;box-shadow:0 20px 60px rgba(0,0,0,.4)">
      <div style="font-size:28px;margin-bottom:10px">⏳</div>
      <div style="font-weight:800;color:#0b2f6b;font-size:14px">Descargando ficha FCCV...</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px">prueba ${pruebaId}</div>
    </div>`;
    document.body.appendChild(ldr);
    // Buscar URL conocida en el scrape acumulado (si existe)
    const known = (_fccvLastAllRaces||[]).find(r=>r.fccvId===pruebaId);
    raw = await _fccvFetchDetailById(pruebaId, known?.fccvDetailUrl);
    ldr.remove();
    if(!raw){
      alert(`No se pudo descargar la ficha de la prueba ${pruebaId} desde la FCCV.\nReintenta más tarde — los proxies CORS pueden estar saturados.`);
      return;
    }
  }
  // Reescribir URLs relativas → absolutas hacia fccv.es y forzar target="_blank"
  let html = raw
    .replace(/(href|src)=(["'])\/(?!\/)/g, '$1=$2https://fccv.es/')
    .replace(/(href|src)=(["'])(?!https?:|mailto:|tel:|#)([^"']+)\2/g, '$1=$2https://fccv.es/$3$2')
    .replace(/<a\b(?![^>]*\btarget=)/g, '<a target="_blank" rel="noopener"');

  // Localizar nombre y fecha desde _fccvLastResults para mostrarlos como título
  const race = (_fccvLastResults||[]).find(r=>r.fccvId===pruebaId)
            || (_fccvLastAllRaces||[]).find(r=>r.fccvId===pruebaId);
  const titleName = race ? race.name : `Prueba ${pruebaId}`;
  const titleDate = race ? (()=>{ const [y,m,d]=race.date.split('-'); return `${d}/${m}/${y}`; })() : '';

  // Extraer TODOS los ficheros adjuntos (reglamento, planos, tracks GPX/KMZ,
  // imágenes del recorrido, cartel...). Incluye enlaces con texto ("REGLAMENTO
  // PÚBLICO") y enlaces que solo contienen un icono <img> (los "planos" suelen
  // venir así). Deduplicamos por href.
  const tmp = document.createElement('div');
  tmp.innerHTML = html;
  const seenHref = new Set();
  const downloads = [];
  const ICONS = {pdf:'📄',doc:'📝',docx:'📝',xls:'📊',xlsx:'📊',zip:'🗜️',jpg:'🖼️',jpeg:'🖼️',png:'🖼️',gif:'🖼️',gpx:'🛰️',kmz:'🛰️',kml:'🛰️',mp4:'🎬'};
  const labelFromHref = (h)=>{
    try{ const seg = decodeURIComponent(h.split('?')[0].split('/').pop()||''); return seg.replace(/[_-]+/g,' ').replace(/\.[a-z0-9]+$/i,'').slice(0,60) || h; }
    catch(_){ return h; }
  };
  tmp.querySelectorAll('a[href]').forEach(a=>{
    let href = a.getAttribute('href') || '';
    if(!href || href.startsWith('#') || /^(mailto:|tel:|javascript:)/i.test(href)) return;
    // Solo nos interesan ficheros adjuntos / multimedia, no navegación
    const isFile = /\.(pdf|docx?|xlsx?|zip|jpe?g|png|gif|gpx|kmz|kml|mp4|svg|tif?f)(\?|$)/i.test(href);
    const linkTxt = (a.textContent||'').trim();
    const hasImgChild = !!a.querySelector('img');
    // También aceptamos links cuyo texto sea claramente un documento aunque
    // el href no termine en extensión (algunos servidores hacen content-disposition).
    const looksDocByText = /reglament|inscripci|bases|cartel|plano|track|recorrido|mapa|dorsal|circuit|trayecto|cronometra/i.test(linkTxt);
    if(!isFile && !hasImgChild && !looksDocByText) return;
    // Normalizar href absoluto
    if(!/^https?:/i.test(href)){
      href = href.startsWith('/') ? 'https://fccv.es'+href : 'https://fccv.es/'+href;
    }
    if(seenHref.has(href)) return;
    seenHref.add(href);
    // Etiqueta: texto del enlace si lo hay, si no, alt de la imagen, si no, nombre del fichero
    let label = linkTxt;
    if(!label){
      const img = a.querySelector('img');
      label = img?.getAttribute('alt') || img?.getAttribute('title') || '';
    }
    if(!label) label = labelFromHref(href);
    const ext = (href.match(/\.([a-z0-9]+)(\?|$)/i)||[])[1]?.toLowerCase() || '';
    const icon = ICONS[ext] || '📎';
    downloads.push({href, label, icon, ext});
  });
  const dlHtml = downloads.length
    ? `<div style="margin-bottom:14px;padding:12px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:10px">
        <div style="font-weight:800;color:#1d4ed8;font-size:12px;margin-bottom:8px;text-transform:uppercase;letter-spacing:.3px">📎 Descargas (${downloads.length})</div>
        <div style="display:flex;flex-wrap:wrap;gap:6px">
          ${downloads.map(d=>`<a href="${d.href}" target="_blank" rel="noopener" title="${escapeHtml(d.href)}" style="display:inline-flex;align-items:center;gap:6px;padding:7px 12px;background:#fff;color:#1d4ed8;text-decoration:none;border:1px solid #bfdbfe;border-radius:7px;font-weight:700;font-size:12px"><span>${d.icon}</span><span>${escapeHtml(d.label)}</span>${d.ext?`<span style="background:#dbeafe;color:#1d4ed8;font-size:10px;padding:1px 5px;border-radius:4px;text-transform:uppercase">${d.ext}</span>`:''}</a>`).join('')}
        </div>
      </div>`
    : '';

  const old = document.getElementById('_fccvDetailsDialog');
  if(old) old.remove();
  const overlay = document.createElement('div');
  overlay.id = '_fccvDetailsDialog';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.onclick = (e)=>{ if(e.target===overlay) overlay.remove(); };
  const fccvCalUrl = race ? `https://fccv.es/index.php/es/smartweb/seccion/calendario/valenciana/${race.date.slice(0,4)}` : 'https://fccv.es/';
  // URL base de la ficha de detalle (extraída del botón "Más" de la fila).
  // Los tabs de la FCCV (Información, Documentos, Deportistas, Técnicos/Otros,
  // Clasificación) viven dentro de esta misma página: la mayoría se gestionan
  // por hash/fragmento o por subruta. Le ofrecemos al usuario un botón por tab
  // probando los patrones más comunes; si la FCCV no reconoce el fragmento,
  // simplemente cae a la pestaña Información que es la por defecto.
  const detailUrl = race && race.fccvDetailUrl ? race.fccvDetailUrl : '';
  const tabBtn = (label, hashes, color)=>{
    if(!detailUrl) return '';
    // hashes = [posibles fragments]; usamos el primero; el usuario puede
    // hacer clic en otros tabs dentro de la página si éste no funciona
    const url = hashes && hashes.length ? `${detailUrl}#${hashes[0]}` : detailUrl;
    return `<a href="${url}" target="_blank" rel="noopener" style="background:${color};color:#fff;border:none;border-radius:8px;padding:8px 12px;font-weight:700;font-size:12px;text-decoration:none;display:inline-flex;align-items:center;gap:4px">${label}</a>`;
  };
  const tabsHtml = detailUrl
    ? `<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px;padding:12px;background:#fef3c7;border:1px solid #fcd34d;border-radius:10px">
        <div style="width:100%;font-weight:800;color:#78350f;font-size:11px;letter-spacing:.4px;text-transform:uppercase;margin-bottom:4px">🗂️ Acceso directo a tabs FCCV</div>
        ${tabBtn('📋 Información',['informacion','info'],'#1e40af')}
        ${tabBtn('📎 Documentos',['documentos','docs'],'#0891b2')}
        ${tabBtn('🚴 Deportistas',['deportistas','inscritos'],'#16a34a')}
        ${tabBtn('👤 Técnicos/Otros',['tecnicos','otros'],'#7c3aed')}
        ${tabBtn('🏁 Clasificación',['clasificacion','resultados'],'#dc2626')}
       </div>`
    : '';
  overlay.innerHTML = `
    <div style="background:#fff;border-radius:14px;max-width:800px;width:100%;max-height:90vh;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.4)">
      <div style="background:linear-gradient(135deg,#1e40af,#0b2f6b);color:#fff;padding:16px 20px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px">
        <div style="flex:1;min-width:0">
          <div style="font-size:11px;opacity:.85;letter-spacing:.6px;text-transform:uppercase;margin-bottom:3px">Ficha oficial FCCV · prueba ${pruebaId}${titleDate?` · ${titleDate}`:''}</div>
          <div style="font-size:17px;font-weight:800;line-height:1.25">${escapeHtml(titleName)}</div>
        </div>
        <button onclick="document.getElementById('_fccvDetailsDialog').remove()" style="background:rgba(255,255,255,.18);color:#fff;border:none;border-radius:8px;width:32px;height:32px;font-size:18px;font-weight:800;cursor:pointer;flex-shrink:0">✕</button>
      </div>
      <div style="padding:18px 20px;overflow-y:auto;flex:1;font-size:13px;line-height:1.5;color:#1f2937">
        ${tabsHtml}
        ${dlHtml}
        <div class="_fccvDetailContent" style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:14px">${html}</div>
      </div>
      <div style="border-top:1px solid #e5e7eb;padding:12px 20px;display:flex;justify-content:flex-end;gap:8px;background:#f9fafb">
        ${detailUrl?`<a href="${detailUrl}" target="_blank" rel="noopener" style="background:#1e40af;color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;font-size:12px;text-decoration:none">↗ Ficha completa FCCV</a>`:''}
        <a href="${fccvCalUrl}" target="_blank" rel="noopener" style="background:#fff;color:#0b2f6b;border:1.5px solid #0b2f6b;border-radius:8px;padding:8px 14px;font-weight:700;font-size:12px;text-decoration:none">↗ Calendario FCCV</a>
        <button onclick="document.getElementById('_fccvDetailsDialog').remove()" style="background:#0b2f6b;color:#fff;border:none;border-radius:8px;padding:8px 18px;font-weight:700;cursor:pointer">Cerrar</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  // Estilo defensivo para tablas/imágenes dentro del modal FCCV
  const style = document.createElement('style');
  style.textContent = `._fccvDetailContent img{max-width:100%;height:auto}._fccvDetailContent table{width:100%;border-collapse:collapse;font-size:12px}._fccvDetailContent td,._fccvDetailContent th{padding:5px 8px;border:1px solid #e5e7eb;text-align:left}._fccvDetailContent a{color:#1d4ed8;font-weight:600}`;
  overlay.appendChild(style);
}

async function _fccvAddRace(idx){
  const race = _fccvLastResults[idx];
  if(!race){ alert('Carrera no encontrada.'); return; }
  if(!_sb){ alert('Necesitas estar conectado a Supabase para añadir carreras al calendario.'); return; }

  const normalize = (s)=>(s||'').toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g,'')
    .replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim();

  // Comprobar si ya está en planificadas (match flexible)
  const existing = (_calPlanned||[]).find(p=>{
    const a=normalize(p.name), b=normalize(race.name);
    if(!a||!b) return false;
    return a===b || a.includes(b.slice(0,Math.min(20,b.length))) || b.includes(a.slice(0,Math.min(20,a.length)));
  });

  try{
    if(existing){
      // Actualizar fecha (intelligent update — preserva el resto del notes JSON)
      const sameDate = (existing.dateStr||'').slice(0,10) === race.date;
      if(sameDate){ alert('Esta carrera ya estaba en tu calendario con la misma fecha.'); return; }
      const oldDate = existing.dateStr||'';
      let extra = {};
      try{
        // Recuperar el notes original de Supabase para no perder otros campos
        const {data} = await _sb.from('races').select('notes').eq('id', existing.id).maybeSingle();
        if(data && data.notes){ try{ extra = JSON.parse(data.notes); }catch(_){} }
      }catch(_){}
      // Añadir traza de la actualización + identificadores FCCV
      extra.fccvSync = {previousDate: oldDate, syncedAt: new Date().toISOString(), source:'FCCV'};
      if(race.location && !extra.localidad) extra.localidad = race.location;
      if(race.fccvId) extra.fccvId = race.fccvId;
      if(race.fccvDetailUrl) extra.fccvDetailUrl = race.fccvDetailUrl;
      if(race.modality && !extra.modality) extra.modality = race.modality;
      if(race.category && !extra.cat) extra.cat = race.category;
      const {error} = await _sb.from('races').update({date: race.date, notes: JSON.stringify(extra)}).eq('id', existing.id);
      if(error) throw error;
      alert(`✅ Fecha actualizada para "${race.name}":\n${oldDate} → ${race.date}\n\nLos demás datos (categoría, notas, etc.) se han mantenido.`);
    } else {
      // Insertar nueva planificada (guardamos identificadores FCCV para que
      // futuros clicks en "ℹ️ Info" abran la ficha correcta de forma inequívoca)
      const notes = JSON.stringify({
        localidad: race.location || '',
        cat: race.category || '',
        modality: race.modality || '',
        notes: '',
        fccvId: race.fccvId || '',
        fccvDetailUrl: race.fccvDetailUrl || '',
        fccvSync: {syncedAt: new Date().toISOString(), source:'FCCV'}
      });
      const {error} = await _sb.from('races').insert({name: race.name, date: race.date, notes, race_type:'planificada'});
      if(error) throw error;
      // Toast
      try{
        const t=document.createElement('div');
        t.style.cssText='position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#10b981;color:#fff;padding:12px 18px;border-radius:10px;font-weight:700;box-shadow:0 6px 18px rgba(0,0,0,.25);z-index:99999;font-size:14px';
        t.textContent=`✓ "${race.name}" añadida al calendario (planificada)`;
        document.body.appendChild(t);
        setTimeout(()=>t.remove(),3500);
      }catch(_){}
    }
    // Refrescar calendario
    await _calLoadData();
    _calRender();
    // Refrescar la tabla de resultados FCCV (para que actualice los badges)
    _fccvRenderResults(_fccvLastResults);
  } catch(e){
    alert('❌ Error guardando en el calendario: '+(e.message||String(e)));
    console.error(e);
  }
}

async function _calSavePlanned(){
  const name  = document.getElementById('calPlanName')?.value.trim();
  const date  = document.getElementById('calPlanDate')?.value;
  const cat   = document.getElementById('calPlanCat')?.value.trim();
  const loc   = document.getElementById('calPlanLoc')?.value.trim();
  const notes = document.getElementById('calPlanNotes')?.value.trim();
  const msg   = document.getElementById('calModalMsg');

  if(!name){ if(msg){msg.textContent='⚠️ El nombre es obligatorio.';msg.style.color='#dc2626';} return; }
  if(!date){ if(msg){msg.textContent='⚠️ La fecha es obligatoria.';msg.style.color='#dc2626';} return; }
  if(msg){msg.textContent='Guardando...';msg.style.color='#6b7280';}

  const notesJson = JSON.stringify({cat, localidad:loc, notes});

  if(_calEditingId){
    // ── MODO EDICIÓN ──
    const id = _calEditingId;
    if(_sb && !String(id).startsWith('local-')){
      const {error} = await _sb.from('races').update({name, date, notes:notesJson}).eq('id',id);
      if(error){ if(msg){msg.textContent='❌ Error: '+error.message;msg.style.color='#dc2626';} return; }
    }
    // Actualizar en memoria
    const idx = _calPlanned.findIndex(r=>r.id===id);
    if(idx>=0) _calPlanned[idx] = {..._calPlanned[idx], name, date:new Date(date+'T12:00:00'), dateStr:date, localidad:loc||'', cat:cat||'', notes:notes||''};
  } else {
    // ── MODO AÑADIR ──
    if(_sb){
      const {data, error} = await _sb.from('races').insert({name, date, notes:notesJson, race_type:'planificada'}).select().single();
      if(error){ if(msg){msg.textContent='❌ Error: '+error.message;msg.style.color='#dc2626';} return; }
      _calPlanned.push({id:data.id, date:new Date(date+'T12:00:00'), dateStr:date, name, localidad:loc||'', cat:cat||'', notes:notes||'', type:'planned'});
    } else {
      _calPlanned.push({id:'local-'+Date.now(), date:new Date(date+'T12:00:00'), dateStr:date, name, localidad:loc||'', cat:cat||'', notes:notes||'', type:'planned'});
    }
  }
  _calCloseModal();
  _calRender();
}

async function _calDeletePlanned(id){
  if(!confirm('¿Eliminar esta carrera planificada?')) return;
  if(_sb && !String(id).startsWith('local-')){
    await _sb.from('races').delete().eq('id',id);
  }
  _calPlanned = _calPlanned.filter(r=>r.id!==id);
  _calRender();
}

// ── Filtro de ciclista en Estadísticas ───────────────────────
let _resRiderFilter = ''; // nombre exacto seleccionado
let _resRiderNames  = []; // caché de nombres

function _resRiderSuggest(query){
  const box = document.getElementById('resRiderBox');
  const inp = document.getElementById('resRiderInput');
  if(!box || !inp) return;
  // Construir lista la primera vez
  if(_resRiderNames.length === 0 && _cachedHistory && _cachedHistory.length > 0){
    _resRiderNames = [...new Set(
      _cachedHistory.flatMap(r=>(r.riders||[]).map(x=>normalizeRiderName(x.name)).filter(Boolean))
    )].sort();
  }
  const q = (query||'').trim().toLowerCase();
  const filtered = q ? _resRiderNames.filter(n=>n.toLowerCase().includes(q)) : _resRiderNames;
  if(filtered.length === 0){ box.style.display='none'; return; }
  box.innerHTML = filtered.map(n=>`
    <div onclick="_resRiderPick('${n.replace(/\\/g,'\\\\').replace(/'/g,"\\'")}');"
      style="padding:10px 14px;cursor:pointer;font-size:13px;border-bottom:1px solid #f3f4f6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"
      onmouseenter="this.style.background='#eff6ff'" onmouseleave="this.style.background=''">
      ${q ? escapeHtml(n).replace(new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi'),'<strong style="color:#1a56db">$1</strong>') : escapeHtml(n)}
    </div>`).join('');
  const r = inp.getBoundingClientRect();
  box.style.top   = (r.bottom+4)+'px';
  box.style.left  = r.left+'px';
  box.style.width = Math.max(r.width,240)+'px';
  box.style.display='';
}

function _resRiderKey(e){
  const box = document.getElementById('resRiderBox');
  const items = box ? box.querySelectorAll('div') : [];
  if(e.key==='Escape'){ box.style.display='none'; }
  else if(e.key==='Enter' && items.length>0){ items[0].click(); }
}

function _resRiderPick(name){
  const inp = document.getElementById('resRiderInput');
  const box = document.getElementById('resRiderBox');
  const clearBtn = document.getElementById('resRiderClearBtn');
  if(inp) inp.value = name;
  if(box) box.style.display='none';
  if(clearBtn) clearBtn.style.display='';
  _resRiderFilter = name;
  renderResumen();
}

function _resRiderClear(){
  const inp = document.getElementById('resRiderInput');
  const clearBtn = document.getElementById('resRiderClearBtn');
  if(inp) inp.value='';
  if(clearBtn) clearBtn.style.display='none';
  _resRiderFilter = '';
  renderResumen();
}

document.addEventListener('click', e=>{
  const box = document.getElementById('resRiderBox');
  const inp = document.getElementById('resRiderInput');
  if(box && inp && !box.contains(e.target) && e.target!==inp) box.style.display='none';
});

async function renderResumen(){
  const body = document.getElementById('resumenBody');
  const yearSel = document.getElementById('resumenYear');
  if(!body) return;
  body.innerHTML = '<div style="text-align:center;padding:40px;color:#9ca3af">⏳ Calculando estadísticas...</div>';

  const history = await _ensureHistory();
  // Actualizar caché de nombres para el autocomplete
  if(_resRiderNames.length === 0 && history.length > 0){
    _resRiderNames = [...new Set(history.flatMap(r=>(r.riders||[]).map(x=>normalizeRiderName(x.name)).filter(Boolean)))].sort();
  }

  if(!history || history.length === 0){
    body.innerHTML = '<div style="text-align:center;padding:60px;color:#9ca3af"><div style="font-size:40px">📭</div><p style="margin-top:10px">No hay carreras en el historial todavía.</p></div>';
    return;
  }

  // ── Modo ficha individual de ciclista ──
  if(_resRiderFilter){
    _resRenderRiderProfile(body, history, _resRiderFilter);
    return;
  }

  // Poblar selector de años
  const years = [...new Set(history.map(r=>{
    const y = (r.raceDate||'').split('/').pop() || (r.raceDate||'').split('-')[0];
    return y && y.length===4 ? y : null;
  }).filter(Boolean))].sort((a,b)=>b-a);

  // Guardar valor seleccionado
  const selYear = yearSel ? yearSel.value : '';
  if(yearSel && yearSel.options.length <= 1){
    years.forEach(y=>{ const o=document.createElement('option'); o.value=y; o.textContent='Temporada '+y; yearSel.appendChild(o); });
  }

  // Filtrar por año si se seleccionó uno
  const races = selYear
    ? history.filter(r=>{ const y=(r.raceDate||'').split('/').pop()||(r.raceDate||'').split('-')[0]; return y===selYear; })
    : history;

  if(races.length === 0){
    body.innerHTML = '<div style="text-align:center;padding:40px;color:#9ca3af">No hay carreras para el año seleccionado.</div>';
    return;
  }

  // ── Calcular estadísticas globales ──
  const totalRaces = races.length;
  const totalRiders = new Set(races.flatMap(r=>(r.riders||[]).map(x=>normalizeRiderName(x.name)))).size;
  const kms = races.map(r=>parseFloat(r.km)||0).filter(k=>k>0);
  const totalKm = kms.reduce((a,b)=>a+b,0);
  const avgs = races.map(r=>parseFloat(r.avg)||0).filter(a=>a>0);
  const avgSpeed = avgs.length ? (avgs.reduce((a,b)=>a+b,0)/avgs.length).toFixed(1) : '—';

  // ── Mi equipo stats ──
  const teamCanon = myTeam ? getCanonicalTeam(myTeam).toLowerCase() : '';
  let myRaces=[], myRiders={};
  races.forEach(race=>{
    const myInRace = (race.riders||[]).filter(r=> teamCanon && getCanonicalTeam(r.team||'').toLowerCase()===teamCanon);
    if(myInRace.length > 0){
      myRaces.push({race, riders: myInRace});
      myInRace.forEach(r=>{
        const key = normalizeRiderName(r.name);
        if(!myRiders[key]) myRiders[key]={name:key, races:0, positions:[], best:999, top3:0, top5:0, top10:0};
        myRiders[key].races++;
        myRiders[key].positions.push(r.pos);
        if(r.pos < myRiders[key].best) myRiders[key].best = r.pos;
        if(r.pos<=3) myRiders[key].top3++;
        if(r.pos<=5) myRiders[key].top5++;
        if(r.pos<=10) myRiders[key].top10++;
      });
    }
  });

  // Promedios por ciclista
  Object.values(myRiders).forEach(r=>{
    r.avg = r.positions.length ? (r.positions.reduce((a,b)=>a+b,0)/r.positions.length) : 999;
  });
  const myRidersList = Object.values(myRiders).filter(r=>r.races>0).sort((a,b)=>a.avg-b.avg);

  // Mejor ciclista (más regular = menor promedio con ≥2 carreras)
  const bestRider = myRidersList.find(r=>r.races>=2) || myRidersList[0];
  // Más mejorado (mayor diferencia entre primera y última posición)
  const mostImproved = [...myRidersList].filter(r=>r.races>=3).sort((a,b)=>{
    const diffA = a.positions[0] - a.positions[a.positions.length-1];
    const diffB = b.positions[0] - b.positions[b.positions.length-1];
    return diffB - diffA;
  })[0];
  // Más participaciones
  const mostActive = [...myRidersList].sort((a,b)=>b.races-a.races)[0];

  // Mejores resultados del equipo (top positions)
  const allMyResults = races.flatMap(race=>
    (race.riders||[])
      .filter(r=> teamCanon && getCanonicalTeam(r.team||'').toLowerCase()===teamCanon)
      .map(r=>({...r, raceName:race.raceName, raceDate:race.raceDate}))
  ).sort((a,b)=>a.pos-b.pos).slice(0,10);

  // Podio stats del equipo
  const myTop1  = allMyResults.filter(r=>r.pos===1).length;
  const myTop3  = allMyResults.filter(r=>r.pos<=3).length;
  const myTop5  = allMyResults.filter(r=>r.pos<=5).length;
  const myTop10 = allMyResults.filter(r=>r.pos<=10).length;

  // ── Renderizar ──
  const teamLabel = myTeam || 'Sin equipo configurado';
  const hasTeam = !!myTeam;

  body.innerHTML = `
  <!-- KPIs globales -->
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px;margin-bottom:24px">
    ${_resKpi('🏁','Carreras',totalRaces,'en el historial')}
    ${_resKpi('👥','Ciclistas',totalRiders,'participantes únicos')}
    ${_resKpi('📍','Kilómetros',totalKm>0?Math.round(totalKm)+' km':'—','recorridos en total')}
    ${_resKpi('⚡','Vel. media',avgSpeed>0?avgSpeed+' km/h':'—','de todas las carreras')}
    ${hasTeam?_resKpi('🚴','Carreras equipo',myRaces.length,'con '+escapeHtml(teamLabel)):''}
    ${hasTeam?_resKpi('🥇','Victorias',myTop1,'del equipo'):''}
    ${hasTeam?_resKpi('🏆','Top 3',myTop3,'del equipo'):''}
    ${hasTeam?_resKpi('🎯','Top 10',myTop10,'del equipo'):''}
  </div>

  ${hasTeam && myRidersList.length > 0 ? `
  <!-- Destacados del equipo -->
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-bottom:24px">
    ${bestRider ? _resDestacado('⭐','Más regular',bestRider.name,'Promedio: '+bestRider.avg.toFixed(1)+' · '+bestRider.races+' carreras','#fef9c3','#854d0e') : ''}
    ${mostActive ? _resDestacado('🔥','Más participaciones',mostActive.name,mostActive.races+' carreras disputadas','#f0fdf4','#166534') : ''}
    ${mostImproved ? _resDestacado('📈','Más mejorado',mostImproved.name,'Mejor pos: '+mostImproved.best+' · '+mostImproved.races+' carreras','#eff6ff','#1e40af') : ''}
  </div>
  ` : ''}

  ${hasTeam && allMyResults.length > 0 ? `
  <!-- Mejores resultados -->
  <div style="margin-bottom:24px">
    <div style="font-weight:800;font-size:15px;color:#0b2f6b;margin-bottom:12px">🏅 Mejores resultados del equipo</div>
    <div style="overflow-x:auto;border-radius:12px;border:1px solid #e5e7eb">
      <table style="width:100%;border-collapse:collapse;font-size:13px">
        <thead><tr style="background:#f3f4f6">
          <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151;width:50px">Pos</th>
          <th style="padding:10px 14px;text-align:left;font-weight:800;color:#374151">Ciclista</th>
          <th style="padding:10px 14px;text-align:left;font-weight:800;color:#374151">Carrera</th>
          <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Fecha</th>
          <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Cat</th>
        </tr></thead>
        <tbody>
          ${allMyResults.map((r,i)=>`
          <tr style="border-bottom:1px solid #f3f4f6;background:${i%2===0?'#fff':'#fafafa'}">
            <td style="padding:10px 14px;text-align:center">
              <span style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:50%;font-weight:900;font-size:13px;
                background:${r.pos===1?'#fbbf24':r.pos<=3?'#d1d5db':r.pos<=10?'#dbeafe':'#f3f4f6'};
                color:${r.pos===1?'#78350f':r.pos<=3?'#374151':r.pos<=10?'#1e40af':'#6b7280'}">${r.pos}</span>
            </td>
            <td style="padding:10px 14px;font-weight:600">${escapeHtml(r.name)}</td>
            <td style="padding:10px 14px;color:#374151">${escapeHtml(r.raceName||'—')}</td>
            <td style="padding:10px 14px;text-align:center;color:#6b7280">${escapeHtml(r.raceDate||'—')}</td>
            <td style="padding:10px 14px;text-align:center"><span style="background:#e0e7ff;color:#3730a3;border-radius:6px;padding:2px 8px;font-size:11px;font-weight:700">${escapeHtml(r.cat||'—')}</span></td>
          </tr>`).join('')}
        </tbody>
      </table>
    </div>
  </div>
  ` : !hasTeam ? `<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:12px;padding:18px;text-align:center;color:#92400e;font-size:13px">
    ⚠️ Configura tu equipo en <strong>Mi Equipo</strong> para ver las estadísticas específicas del equipo.
  </div>` : ''}

  <!-- Lista de carreras de la temporada -->
  <div>
    <div style="font-weight:800;font-size:15px;color:#0b2f6b;margin-bottom:12px">📋 Carreras disputadas (${totalRaces})</div>
    <div style="overflow-x:auto;border-radius:12px;border:1px solid #e5e7eb">
      <table style="width:100%;border-collapse:collapse;font-size:13px">
        <thead><tr style="background:#f3f4f6">
          <th style="padding:10px 14px;text-align:left;font-weight:800;color:#374151">Carrera</th>
          <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Fecha</th>
          <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Km</th>
          <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Vel. media</th>
          <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Corredores</th>
          ${hasTeam?'<th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Mejor pos. equipo</th>':''}
        </tr></thead>
        <tbody>
          ${[...races].sort((a,b)=>{
            const da=_parseSpanishDate(a.raceDate)||new Date(0);
            const db=_parseSpanishDate(b.raceDate)||new Date(0);
            return db-da;
          }).map((race,i)=>{
            const myBest = teamCanon ? (race.riders||[]).filter(r=>getCanonicalTeam(r.team||'').toLowerCase()===teamCanon).sort((a,b)=>a.pos-b.pos)[0] : null;
            return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2===0?'#fff':'#fafafa'}">
              <td style="padding:10px 14px;font-weight:600">${escapeHtml(race.raceName||'—')}</td>
              <td style="padding:10px 14px;text-align:center;color:#6b7280">${escapeHtml(race.raceDate||'—')}</td>
              <td style="padding:10px 14px;text-align:center">${race.km||'—'}</td>
              <td style="padding:10px 14px;text-align:center">${race.avg?race.avg+' km/h':'—'}</td>
              <td style="padding:10px 14px;text-align:center">${(race.riders||[]).length}</td>
              ${hasTeam?`<td style="padding:10px 14px;text-align:center">${myBest?`<span style="font-weight:800;color:${myBest.pos<=3?'#b45309':myBest.pos<=10?'#1d4ed8':'#374151'}">${myBest.pos}º ${escapeHtml(myBest.name)}</span>`:'<span style="color:#9ca3af">—</span>'}</td>`:''}
            </tr>`;
          }).join('')}
        </tbody>
      </table>
    </div>
  </div>`;
}

// ── Tabs del Resumen ──────────────────────────────────────────
function _resSetTab(tab){
  // El tab 'cal' fue extraído a su propia vista (view-calendario).
  // Si por compatibilidad alguien llama _resSetTab('cal'), redirigimos.
  if(tab==='cal'){ if(typeof showView==='function') showView('view-calendario'); return; }
  const tabs = {stats:'resTabStats', scout:'resTabScout'};
  const panels = {stats:'resPanelStats', scout:'resPanelScout'};
  Object.entries(tabs).forEach(([k,id])=>{
    const btn = document.getElementById(id);
    if(btn){ btn.style.borderBottomColor = k===tab?'#1a56db':'transparent'; btn.style.color = k===tab?'#1a56db':'#6b7280'; }
  });
  Object.entries(panels).forEach(([k,id])=>{
    const el = document.getElementById(id);
    if(el) el.style.display = k===tab?'':'none';
  });
  if(tab==='scout') _scoutInit();
}

// ── Scouting: inicializar filtros ────────────────────────────
let _scoutHistory = [];
async function _scoutInit(){
  if(_scoutHistory.length === 0) _scoutHistory = await _ensureHistory();
  // Poblar equipos
  const teamSel = document.getElementById('scoutTeamSel');
  if(teamSel && teamSel.options.length <= 1){
    const teams = [...new Set(_scoutHistory.flatMap(r=>(r.riders||[]).map(x=>getCanonicalTeam(x.team||'')).filter(Boolean)))].sort();
    teams.forEach(t=>{ const o=document.createElement('option'); o.value=t; o.textContent=t; teamSel.appendChild(o); });
  }
  // Poblar categorías
  const catSel = document.getElementById('scoutCatSel');
  if(catSel && catSel.options.length <= 1){
    const cats = [...new Set(_scoutHistory.flatMap(r=>(r.riders||[]).map(x=>x.cat||'').filter(Boolean)))].sort();
    cats.forEach(c=>{ const o=document.createElement('option'); o.value=c; o.textContent=c; catSel.appendChild(o); });
  }
}

let _scoutAllNames = [];
let _scoutHlIdx = -1;

function _scoutSuggest(query){
  const box = document.getElementById('scoutSuggestBox');
  const inp = document.getElementById('scoutRiderInput');
  if(!box || !inp) return;

  // Construir lista completa la primera vez
  if(_scoutAllNames.length === 0 && _scoutHistory.length > 0){
    _scoutAllNames = [...new Set(
      _scoutHistory.flatMap(r=>(r.riders||[]).map(x=>normalizeRiderName(x.name)).filter(Boolean))
    )].sort();
  }

  const q = (query||'').trim().toLowerCase();
  const filtered = q
    ? _scoutAllNames.filter(n=>n.toLowerCase().includes(q))
    : _scoutAllNames;

  if(filtered.length === 0){ box.style.display='none'; return; }

  _scoutHlIdx = -1;
  box.innerHTML = filtered.map((n,i)=>`
    <div class="scout-suggest-item" data-idx="${i}" data-name="${escapeHtml(n)}"
      onclick="_scoutPickRider('${n.replace(/\\/g,'\\\\').replace(/'/g,"\\'")}');"
      style="padding:10px 14px;cursor:pointer;font-size:13px;border-bottom:1px solid #f3f4f6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"
      onmouseenter="this.style.background='#eff6ff'" onmouseleave="this.style.background=''">
      ${q ? escapeHtml(n).replace(new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi'),'<strong style="color:#1a56db">$1</strong>') : escapeHtml(n)}
    </div>`).join('');

  // Posicionar bajo el input
  const r = inp.getBoundingClientRect();
  box.style.top    = (r.bottom + 4) + 'px';
  box.style.left   = r.left + 'px';
  box.style.width  = Math.max(r.width, 240) + 'px';
  box.style.display = '';
}

function _scoutSuggestKey(e){
  const box = document.getElementById('scoutSuggestBox');
  const items = box ? box.querySelectorAll('.scout-suggest-item') : [];
  if(!items.length) return;
  if(e.key === 'ArrowDown'){
    e.preventDefault();
    _scoutHlIdx = Math.min(_scoutHlIdx+1, items.length-1);
    items.forEach((el,i)=>el.style.background = i===_scoutHlIdx?'#eff6ff':'');
    items[_scoutHlIdx]?.scrollIntoView({block:'nearest'});
  } else if(e.key === 'ArrowUp'){
    e.preventDefault();
    _scoutHlIdx = Math.max(_scoutHlIdx-1, 0);
    items.forEach((el,i)=>el.style.background = i===_scoutHlIdx?'#eff6ff':'');
    items[_scoutHlIdx]?.scrollIntoView({block:'nearest'});
  } else if(e.key === 'Enter' && _scoutHlIdx >= 0){
    e.preventDefault();
    const name = items[_scoutHlIdx]?.dataset.name;
    if(name) _scoutPickRider(name);
  } else if(e.key === 'Escape'){
    const box = document.getElementById('scoutSuggestBox');
    if(box) box.style.display='none';
  }
}

// Cerrar dropdown al hacer clic fuera
document.addEventListener('click', e=>{
  const box = document.getElementById('scoutSuggestBox');
  const inp = document.getElementById('scoutRiderInput');
  if(box && inp && !box.contains(e.target) && e.target !== inp){
    box.style.display='none';
  }
});

function _scoutPickRider(name){
  const inp = document.getElementById('scoutRiderInput');
  const box = document.getElementById('scoutSuggestBox');
  if(inp) inp.value = name;
  if(box) box.style.display='none';
  _scoutRender();
}

function _scoutReset(){
  const inp = document.getElementById('scoutRiderInput');
  const box = document.getElementById('scoutSuggestBox');
  const teamSel = document.getElementById('scoutTeamSel');
  const catSel = document.getElementById('scoutCatSel');
  const posSel = document.getElementById('scoutPosSel');
  if(inp) inp.value='';
  if(box) box.style.display='none';
  if(teamSel) teamSel.value='';
  if(catSel) catSel.value='';
  if(posSel) posSel.value='';
  const body = document.getElementById('scoutBody');
  if(body) body.innerHTML='<div style="text-align:center;color:#9ca3af;padding:40px"><div style="font-size:36px">🔍</div><p style="margin-top:8px;font-size:13px">Aplica filtros para buscar ciclistas de cualquier equipo.</p></div>';
}

async function _scoutRender(){
  const body = document.getElementById('scoutBody');
  if(!body) return;
  if(_scoutHistory.length === 0) _scoutHistory = await _ensureHistory();

  const riderQ = (document.getElementById('scoutRiderInput')?.value||'').trim().toLowerCase();
  const teamQ  = (document.getElementById('scoutTeamSel')?.value||'').toLowerCase();
  const catQ   = (document.getElementById('scoutCatSel')?.value||'').toLowerCase();
  const posMax = parseInt(document.getElementById('scoutPosSel')?.value||'0')||0;

  // Construir mapa de ciclistas con sus resultados
  const riderMap = {};
  _scoutHistory.forEach(race=>{
    (race.riders||[]).forEach(r=>{
      const name = normalizeRiderName(r.name);
      const team = getCanonicalTeam(r.team||'');
      const cat  = r.cat||'';
      // Aplicar filtros
      if(riderQ && !name.toLowerCase().includes(riderQ)) return;
      if(teamQ  && team.toLowerCase() !== teamQ) return;
      if(catQ   && cat.toLowerCase() !== catQ) return;
      if(posMax && r.pos > posMax) return;
      if(!riderMap[name]) riderMap[name]={name, team, cat, races:[], best:999, top1:0, top3:0, top5:0, top10:0};
      riderMap[name].races.push({pos:r.pos, raceName:race.raceName, raceDate:race.raceDate, team});
      if(r.pos < riderMap[name].best) riderMap[name].best = r.pos;
      if(r.pos===1) riderMap[name].top1++;
      if(r.pos<=3)  riderMap[name].top3++;
      if(r.pos<=5)  riderMap[name].top5++;
      if(r.pos<=10) riderMap[name].top10++;
    });
  });

  const riders = Object.values(riderMap)
    .map(r=>({ ...r, avg: r.races.reduce((a,b)=>a+b.pos,0)/r.races.length, total: r.races.length }))
    .sort((a,b)=> posMax ? a.best-b.best : a.avg-b.avg);

  if(riders.length === 0){
    body.innerHTML='<div style="text-align:center;color:#9ca3af;padding:40px"><div style="font-size:36px">😕</div><p style="margin-top:8px">No se encontraron ciclistas con esos filtros.</p></div>';
    return;
  }

  body.innerHTML = `
  <div style="font-size:13px;color:#6b7280;margin-bottom:12px">${riders.length} ciclista${riders.length!==1?'s':''} encontrado${riders.length!==1?'s':''} · ordenados por ${posMax?'mejor posición':'promedio'}</div>
  <div style="overflow-x:auto;border-radius:12px;border:1px solid #e5e7eb">
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead><tr style="background:#f3f4f6">
        <th style="padding:10px 14px;text-align:left;font-weight:800;color:#374151">Ciclista</th>
        <th style="padding:10px 14px;text-align:left;font-weight:800;color:#374151">Equipo</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Cat</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Carreras</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Promedio</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Mejor</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">🥇</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Top3</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Top10</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Evolución</th>
      </tr></thead>
      <tbody>
        ${riders.map((r,i)=>{
          // Mini gráfico de evolución (últimas 6 carreras)
          const last6 = [...r.races].sort((a,b)=>{
            const da=_parseSpanishDate(a.raceDate)||new Date(0);
            const db=_parseSpanishDate(b.raceDate)||new Date(0);
            return da-db;
          }).slice(-6);
          const maxPos = Math.max(...last6.map(x=>x.pos), 20);
          const sparkline = last6.map(x=>{
            const h = Math.max(4, Math.round((1-x.pos/maxPos)*28)+4);
            const col = x.pos<=3?'#f59e0b':x.pos<=10?'#3b82f6':'#d1d5db';
            return `<div title="${escapeHtml(x.raceName)}: ${x.pos}º" style="width:8px;height:${h}px;background:${col};border-radius:2px;flex-shrink:0"></div>`;
          }).join('');
          return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2===0?'#fff':'#fafafa'}">
            <td style="padding:10px 14px;font-weight:700">${escapeHtml(r.name)}</td>
            <td style="padding:10px 14px;font-size:12px;color:#374151">${escapeHtml(r.team)}</td>
            <td style="padding:10px 14px;text-align:center"><span style="background:#e0e7ff;color:#3730a3;border-radius:6px;padding:2px 8px;font-size:11px;font-weight:700">${escapeHtml(r.cat)}</span></td>
            <td style="padding:10px 14px;text-align:center;font-weight:700">${r.total}</td>
            <td style="padding:10px 14px;text-align:center;font-weight:700;color:${r.avg<=5?'#b45309':r.avg<=15?'#1d4ed8':'#374151'}">${r.avg.toFixed(1)}</td>
            <td style="padding:10px 14px;text-align:center"><span style="font-weight:900;font-size:15px;color:${r.best===1?'#b45309':r.best<=3?'#6b7280':'#374151'}">${r.best}º</span></td>
            <td style="padding:10px 14px;text-align:center;font-weight:700;color:#b45309">${r.top1||'—'}</td>
            <td style="padding:10px 14px;text-align:center;font-weight:700">${r.top3||'—'}</td>
            <td style="padding:10px 14px;text-align:center;font-weight:700">${r.top10||'—'}</td>
            <td style="padding:10px 14px">
              <div style="display:flex;align-items:flex-end;gap:2px;height:32px">${sparkline||'<span style="color:#9ca3af;font-size:11px">—</span>'}</div>
            </td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>
  </div>`;
}

// ── Ficha individual de ciclista ─────────────────────────────
function _resRenderRiderProfile(body, history, riderName){
  const riderQ = riderName.toLowerCase();
  // Recoger todas las participaciones del ciclista
  const participaciones = [];
  history.forEach(race=>{
    const match = (race.riders||[]).find(r=>normalizeRiderName(r.name).toLowerCase()===riderQ);
    if(match) participaciones.push({
      raceName:   race.raceName,
      raceDate:   race.raceDate,
      localidad:  race.localidad||'—',
      km:         race.km||'—',
      avg:        race.avg||'—',
      circuitType:race.circuitType||'—',
      pos:        match.pos,
      cat:        match.cat||'—',
      team:       match.team||'—',
      time:       match.time||'—',
      totalRiders:(race.riders||[]).length
    });
  });

  if(participaciones.length === 0){
    body.innerHTML=`<div style="text-align:center;padding:40px;color:#9ca3af"><div style="font-size:36px">😕</div><p style="margin-top:8px">No se encontraron carreras para <strong>${escapeHtml(riderName)}</strong>.</p></div>`;
    return;
  }

  // Ordenar por fecha
  const sorted = [...participaciones].sort((a,b)=>{
    const da=_parseSpanishDate(a.raceDate)||new Date(0);
    const db=_parseSpanishDate(b.raceDate)||new Date(0);
    return da-db;
  });

  // Stats
  const positions = sorted.map(r=>r.pos);
  const avgPos    = (positions.reduce((a,b)=>a+b,0)/positions.length).toFixed(1);
  const bestPos   = Math.min(...positions);
  const top1      = positions.filter(p=>p===1).length;
  const top3      = positions.filter(p=>p<=3).length;
  const top5      = positions.filter(p=>p<=5).length;
  const top10     = positions.filter(p=>p<=10).length;
  const teams     = [...new Set(sorted.map(r=>r.team))].filter(t=>t&&t!=='—').join(', ');

  // Tendencia: comparar primera mitad vs segunda mitad
  const mid = Math.floor(sorted.length/2);
  const avgFirst = sorted.slice(0,mid||1).reduce((a,b)=>a+b.pos,0)/(mid||1);
  const avgLast  = sorted.slice(mid).reduce((a,b)=>a+b.pos,0)/(sorted.length-mid||1);
  const tendencia = avgLast < avgFirst ? '📈 Mejorando' : avgLast > avgFirst ? '📉 Empeorando' : '➡️ Estable';

  body.innerHTML = `
  <!-- Cabecera del ciclista -->
  <div style="background:linear-gradient(135deg,#0b2f6b,#1a56db);color:#fff;border-radius:16px;padding:20px 24px;margin-bottom:20px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px">
    <div>
      <div style="font-size:22px;font-weight:900">${escapeHtml(riderName)}</div>
      <div style="opacity:.8;font-size:13px;margin-top:3px">${escapeHtml(teams)} · ${escapeHtml(sorted[0]?.cat||'—')}</div>
    </div>
    <div style="font-size:28px">${tendencia}</div>
  </div>

  <!-- KPIs del ciclista -->
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin-bottom:20px">
    ${_resKpi('🏁','Carreras',participaciones.length,'en el historial')}
    ${_resKpi('📊','Promedio',avgPos,'posición media')}
    ${_resKpi('⭐','Mejor pos.',bestPos+'º','su mejor resultado')}
    ${_resKpi('🥇','Victorias',top1||'—','1er puesto')}
    ${_resKpi('🏆','Top 3',top3||'—','podios')}
    ${_resKpi('🎯','Top 10',top10||'—','resultados')}
  </div>

  <!-- Historial completo de carreras -->
  <div style="font-weight:800;font-size:15px;color:#0b2f6b;margin-bottom:12px">📋 Historial completo de carreras</div>
  <div style="overflow-x:auto;border-radius:12px;border:1px solid #e5e7eb">
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead><tr style="background:#f3f4f6">
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151;width:50px">Pos</th>
        <th style="padding:10px 14px;text-align:left;font-weight:800;color:#374151">Carrera</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Fecha</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Localidad</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Km</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Vel.</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Corredores</th>
        <th style="padding:10px 14px;text-align:center;font-weight:800;color:#374151">Tiempo</th>
      </tr></thead>
      <tbody>
        ${sorted.map((r,i)=>`
        <tr style="border-bottom:1px solid #f3f4f6;background:${i%2===0?'#fff':'#fafafa'}">
          <td style="padding:10px 14px;text-align:center">
            <span style="display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;border-radius:50%;font-weight:900;font-size:13px;
              background:${r.pos===1?'#fbbf24':r.pos<=3?'#e5e7eb':r.pos<=10?'#dbeafe':'#f3f4f6'};
              color:${r.pos===1?'#78350f':r.pos<=3?'#374151':r.pos<=10?'#1e40af':'#6b7280'}">${r.pos}</span>
          </td>
          <td style="padding:10px 14px;font-weight:600">${escapeHtml(r.raceName||'—')}</td>
          <td style="padding:10px 14px;text-align:center;color:#6b7280">${escapeHtml(r.raceDate||'—')}</td>
          <td style="padding:10px 14px;text-align:center;color:#6b7280">${escapeHtml(r.localidad)}</td>
          <td style="padding:10px 14px;text-align:center">${r.km}</td>
          <td style="padding:10px 14px;text-align:center">${r.avg!=='—'?r.avg+' km/h':r.avg}</td>
          <td style="padding:10px 14px;text-align:center;color:#6b7280">${r.totalRiders}</td>
          <td style="padding:10px 14px;text-align:center;font-family:monospace">${r.time}</td>
        </tr>`).join('')}
      </tbody>
    </table>
  </div>`;
}

function _resKpi(icon, label, value, sub){
  return `<div style="background:#f8fbff;border:1px solid #e0e7ff;border-radius:14px;padding:16px 18px">
    <div style="font-size:22px">${icon}</div>
    <div style="font-size:22px;font-weight:900;color:#0b2f6b;margin:4px 0">${value}</div>
    <div style="font-size:12px;font-weight:700;color:#374151">${label}</div>
    <div style="font-size:11px;color:#9ca3af;margin-top:2px">${sub}</div>
  </div>`;
}

function _resDestacado(icon, label, name, sub, bg, color){
  return `<div style="background:${bg};border-radius:14px;padding:16px 18px;border:1px solid rgba(0,0,0,.06)">
    <div style="font-size:20px">${icon}</div>
    <div style="font-size:11px;font-weight:800;color:${color};text-transform:uppercase;letter-spacing:.5px;margin:6px 0 2px">${label}</div>
    <div style="font-size:16px;font-weight:900;color:#111827">${escapeHtml(name)}</div>
    <div style="font-size:12px;color:#6b7280;margin-top:3px">${sub}</div>
  </div>`;
}

