// Umbral para colapsar automáticamente (cubre iPad, iPad Pro landscape, tablets)
const _NAV_COLLAPSE_WIDTH = 1200;

let _navCollapsed = (()=>{
  const saved = localStorage.getItem('navCollapsed');
  if(saved !== null) return saved === '1';
  return window.innerWidth <= _NAV_COLLAPSE_WIDTH; // iPad y tablets: colapsar por defecto
})();

function _applyNavState(animate){
  const nav    = document.getElementById('sideNav');
  const layout = document.querySelector('.spa-layout');
  const btn    = document.getElementById('navToggleBtn');
  if(!nav) return;
  if(!animate) nav.style.transition = 'none';
  if(_navCollapsed){
    nav.classList.add('collapsed');
    if(layout) layout.classList.add('nav-collapsed');
    // Icono ☰ cuando está plegado: más reconocible que »
    if(btn){ btn.textContent='☰'; btn.title='Expandir menú'; btn.setAttribute('aria-label','Expandir menú'); }
  } else {
    nav.classList.remove('collapsed');
    if(layout) layout.classList.remove('nav-collapsed');
    if(btn){ btn.textContent='«'; btn.title='Contraer menú'; btn.setAttribute('aria-label','Contraer menú'); }
  }
  if(!animate) setTimeout(()=>{ nav.style.transition=''; }, 50);
}

function _toggleNav(){
  _navCollapsed = !_navCollapsed;
  localStorage.setItem('navCollapsed', _navCollapsed ? '1' : '0');
  _applyNavState(true);
}

// Aplicar estado inicial sin animación (evita flash al cargar)
document.addEventListener('DOMContentLoaded', ()=>_applyNavState(false));
// Fallback si DOMContentLoaded ya pasó
if(document.readyState !== 'loading') _applyNavState(false);
// Al rotar el dispositivo o redimensionar ventana, ajustar automáticamente
let _navResizeTimer;
window.addEventListener('resize', ()=>{
  clearTimeout(_navResizeTimer);
  _navResizeTimer = setTimeout(()=>{
    const shouldCollapse = window.innerWidth <= _NAV_COLLAPSE_WIDTH;
    // Solo auto-colapsar si el usuario no ha guardado preferencia explícita
    const saved = localStorage.getItem('navCollapsed');
    if(saved === null){
      _navCollapsed = shouldCollapse;
      _applyNavState(false);
    }
  }, 200);
});

