let _meAllTeams = [];
let _meHlIndex  = -1;

async function _meLoadTeams(){
  if(_meAllTeams.length) return;
  try{
    const history = await _ensureHistory();
    const fromHistory = [...new Set(history.flatMap(r=>(r.riders||[]).map(x=>getCanonicalTeam(x.team||'')).filter(Boolean)))].sort();
    _meAllTeams = [...new Set([...fromHistory, ..._meAllTeams])].sort();
  }catch(e){ /* silencioso si no hay conexión */ }
}

function _meRender(query){
  const dd = document.getElementById('meDropdown');
  const wrap = document.getElementById('meWrap');
  if(!dd) return;
  const q = (query||'').toLowerCase().trim();
  const filtered = q ? _meAllTeams.filter(t=>t.toLowerCase().includes(q)) : _meAllTeams;
  const currentVal = (document.getElementById('miEquipoInput')?.value||'').trim().toLowerCase();
  if(!filtered.length){
    dd.innerHTML = '<div class="me-item no-results">'+(q?'Sin coincidencias para "'+escapeHtml(q)+'"':'Cargando equipos...')+'</div>';
  } else {
    dd.innerHTML = filtered.map(t=>{
      const isActive = t.toLowerCase()===currentVal;
      return `<div class="me-item${isActive?' highlighted':''}" data-team="${escapeAttr(t)}">${isActive?'✓ ':''}${escapeHtml(t)}</div>`;
    }).join('');
    // Hacer scroll hasta el equipo activo
    if(currentVal) setTimeout(()=>{ const a=dd.querySelector('.highlighted'); if(a) a.scrollIntoView({block:'nearest'}); },0);
  }
  dd.classList.add('open');
  if(wrap) wrap.classList.add('open');
  _meHlIndex = -1;
}

function _meClose(){
  const dd = document.getElementById('meDropdown');
  const wrap = document.getElementById('meWrap');
  if(dd) dd.classList.remove('open');
  if(wrap) wrap.classList.remove('open');
}

function _meMarkUnsaved(){
  const btn = document.getElementById('btnSaveEquipo');
  if(btn) btn.classList.add('unsaved');
}

(function _initMeAutocomplete(){
  const inp = document.getElementById('miEquipoInput');
  const dd  = document.getElementById('meDropdown');
  if(!inp || !dd) return;

  // Abrir al hacer clic o focus → siempre mostrar TODA la lista
  inp.addEventListener('focus', async function(){
    await _meLoadTeams();
    _meRender('');
  });
  inp.addEventListener('click', async function(e){
    e.stopPropagation();
    await _meLoadTeams();
    _meRender('');
  });

  // Filtrar solo cuando el usuario escribe
  inp.addEventListener('input', function(){
    _meRender(this.value);
    _meMarkUnsaved();
  });

  // Navegación con teclado
  inp.addEventListener('keydown', function(e){
    if(!dd.classList.contains('open')) return;
    const items = dd.querySelectorAll('.me-item:not(.no-results)');
    if(e.key==='ArrowDown'){
      e.preventDefault();
      _meHlIndex = Math.min(_meHlIndex+1, items.length-1);
      items.forEach((el,i)=>el.classList.toggle('highlighted',i===_meHlIndex));
      if(items[_meHlIndex]) items[_meHlIndex].scrollIntoView({block:'nearest'});
    } else if(e.key==='ArrowUp'){
      e.preventDefault();
      _meHlIndex = Math.max(_meHlIndex-1, 0);
      items.forEach((el,i)=>el.classList.toggle('highlighted',i===_meHlIndex));
      if(items[_meHlIndex]) items[_meHlIndex].scrollIntoView({block:'nearest'});
    } else if(e.key==='Enter'){
      if(_meHlIndex>=0 && items[_meHlIndex]){
        inp.value = items[_meHlIndex].dataset.team;
        _meClose(); _meMarkUnsaved();
      }
    } else if(e.key==='Escape'){
      _meClose();
    }
  });

  // Seleccionar con clic en item
  dd.addEventListener('mousedown', function(e){
    const item = e.target.closest('.me-item:not(.no-results)');
    if(item){ inp.value = item.dataset.team; _meClose(); _meMarkUnsaved(); }
  });

  // Cerrar al hacer clic fuera
  document.addEventListener('click', function(e){
    if(!e.target.closest('.mi-equipo-wrap')){ _meClose(); }
  });
})();
