function updateMyTeamSuggestions(){
  // Agregar equipos de la carrera actual al caché del autocomplete
  const fromCurrent = [...new Set(riders.map(r=>getCanonicalTeam(r.team||'')).filter(Boolean))];
  if(fromCurrent.length){
    _meAllTeams = [...new Set([..._meAllTeams, ...fromCurrent])].sort();
  }
}
function formatKmValue(v){
  // COMENTARIO: formato robusto de kilómetros; limpia texto y conserva un único separador decimal.
  let s=cleanSpaces(String(v||'')).toLowerCase().replace('km','').replace(/[^0-9,.]/g,'');
  if(!s)return '';
  const firstSep=s.search(/[,.]/);
  if(firstSep>=0){
    const int=s.slice(0,firstSep).replace(/[,.]/g,'');
    const dec=s.slice(firstSep+1).replace(/[,.]/g,'');
    s=int+(dec?','+dec:'');
  }else{
    s=s.replace(/[,.]/g,'');
  }
  return s?`${s} km`:'';
}

function _calcAvgSpeed(){
  // Calcula la velocidad media del ganador si tenemos km y tiempo del 1º
  const km=parseKmValue();
  if(!km) return;
  const winner=riders.find(r=>r.pos===1);
  if(!winner) return;
  const secs=winner.totalSeconds??timeToSeconds(winner.time??'');
  if(!secs||secs<=0) return;
  const avgField=$('raceAvg');
  if(!avgField) return;
  // Solo sobreescribe si está vacío o tenía un valor calculado antes
  const badge=$('avgCalcBadge');
  const alreadyManual=avgField.dataset.manual==='1';
  if(alreadyManual) return;
  const speed=(km/(secs/3600)).toFixed(2).replace('.',',');
  avgField.value=speed+' km/h';
  if(badge) badge.style.display='';
}

function detectSameTimes(list){
  // COMENTARIO: detección de mismo tiempo sin falsear tiempos absolutos.
  // Si una fila viene vacía, se deja vacía para que enrichRiders herede el gap del bloque anterior.
  // Si viene como "a 0:00", se normaliza explícitamente a gap cero.
  const sorted=list.slice().sort((a,b)=>a.pos-b.pos);
  const fixed=new Map();

  sorted.forEach((r)=>{
    let nr={...r};
    const visible=cleanSpaces(nr.time||'');

    if(/^a\s*0:?00(?::00)?$/i.test(visible)){
      nr.time='a 0:00';
    }

    fixed.set(nr.pos+'|'+nr.bib+'|'+nr.name,nr);
  });

  return list.map(r=>fixed.get(r.pos+'|'+r.bib+'|'+r.name)||r);
}

function parseKmValue(){const raw=String($('raceKm').value||'').replace(',', '.');const m=raw.match(/[0-9]+(?:\.[0-9]+)?/);return m?Number(m[0]):0}
function normalizeTimeStr(t){
  if(!t) return '';
  let s=cleanSpaces(String(t)).trim();
  // Eliminar milisegundos: "01:25:19.000" o "01:25:19,000" → "01:25:19"
  s=s.replace(/(\d{2})[.,]\d+$/, '$1');
  // Normalizar a HH:MM:SS para evitar ambigüedad (11:51 podría ser 11h o 11min)
  // Formato 3 partes H:MM:SS → zero-pad HH
  const three=s.match(/^(\d{1,2}):(\d{2}):(\d{2})$/);
  if(three) return String(three[1]).padStart(2,'0')+':'+three[2]+':'+three[3];
  // Formato 2 partes M:SS o MM:SS (típico de pruebas cadete <1h) → 00:MM:SS
  const two=s.match(/^(\d{1,2}):(\d{2})$/);
  if(two) return '00:'+String(two[1]).padStart(2,'0')+':'+two[2];
  return s;
}
function timeToSeconds(t){
  t=normalizeTimeStr(String(t||'')).replace(/^a\s+/i,'');
  const m=t.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if(!m) return null;
  const a=Number(m[1]), b=Number(m[2]), c=m[3]!=null?Number(m[3]):null;
  return c==null ? a*60+b : a*3600+b*60+c;
}
function gapSecondsFromTime(t,pos){
  if(pos===1) return 0;
  const raw=cleanSpaces(String(t||''));
  if(/^a\s+/i.test(raw)) return timeToSeconds(raw);
  return null;
}
// Formato HH:MM:SS siempre — usado en la columna TIEMPO para evitar ambigüedad
function formatHMS(sec){
  if(sec==null || Number.isNaN(sec)) return '—';
  sec=Math.round(sec);
  const h=Math.floor(sec/3600), m=Math.floor((sec%3600)/60), s=sec%60;
  return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');
}
function formatSeconds(sec){
  if(sec==null || Number.isNaN(sec)) return '—';
  sec=Math.round(sec);
  const h=Math.floor(sec/3600), m=Math.floor((sec%3600)/60), s=sec%60;
  if(h>0) return h+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');
  return m+':'+String(s).padStart(2,'0');
}
// Propaga la CCAA dentro de cada equipo: si algún corredor del equipo tiene
// CCAA conocida, todos los demás del mismo equipo heredan esa CCAA.
// Resuelve el caso "edité una y los demás se quedan vacíos".
function inferRegionsFromTeam(list){
  if(!list || !list.length) return;
  const teamRegion=new Map();
  // Primera pasada: para cada equipo, contar las CCAAs no vacías
  list.forEach(r=>{
    const team=(r.team||'').trim().toLowerCase();
    const region=(r.region||'').trim();
    if(!team || !region) return;
    if(!teamRegion.has(team)) teamRegion.set(team, new Map());
    const counts=teamRegion.get(team);
    counts.set(region, (counts.get(region)||0)+1);
  });
  // Segunda pasada: rellenar CCAAs vacías con la más frecuente del equipo
  list.forEach(r=>{
    if((r.region||'').trim()) return;
    const team=(r.team||'').trim().toLowerCase();
    if(!team || !teamRegion.has(team)) return;
    const counts=teamRegion.get(team);
    let best=null, bestN=0;
    counts.forEach((n,reg)=>{ if(n>bestN){bestN=n;best=reg;} });
    if(best) r.region=best;
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// DB GLOBAL DE EQUIPOS → CCAA (aprende del historial Supabase)
// ═══════════════════════════════════════════════════════════════════════════
const _REGION_MAP_GLOBAL={
  'cv':'Comunitat Valenciana','c v':'Comunitat Valenciana','vlc':'Comunitat Valenciana',
  'comunitat valenciana':'Comunitat Valenciana','comunidad valenciana':'Comunitat Valenciana',
  'valenciana':'Comunitat Valenciana','valencia':'Comunitat Valenciana',
  'c valencia':'Comunitat Valenciana','pais valenciano':'Comunitat Valenciana',
  'cat':'Cataluña','catalunya':'Cataluña','cataluña':'Cataluña','cataluna':'Cataluña',
  'mad':'Madrid','madrid':'Madrid','comunidad de madrid':'Madrid','c madrid':'Madrid',
  'and':'Andalucía','andalucia':'Andalucía',
  'ara':'Aragón','aragon':'Aragón','ar':'Aragón',
  'ast':'Asturias','asturias':'Asturias','principado de asturias':'Asturias','p asturias':'Asturias',
  'can':'Canarias','canarias':'Canarias','islas canarias':'Canarias',
  'cant':'Cantabria','cantabria':'Cantabria',
  'clm':'Castilla-La Mancha','castilla la mancha':'Castilla-La Mancha','castilla-la mancha':'Castilla-La Mancha',
  'cyl':'Castilla y León','castilla y leon':'Castilla y León','castilla y león':'Castilla y León','castilla leon':'Castilla y León',
  'ext':'Extremadura','extremadura':'Extremadura',
  'gal':'Galicia','galicia':'Galicia',
  'bal':'Islas Baleares','baleares':'Islas Baleares','islas baleares':'Islas Baleares','illes balears':'Islas Baleares',
  'rio':'La Rioja','la rioja':'La Rioja','rioja':'La Rioja',
  'mur':'Murcia','murcia':'Murcia','region de murcia':'Murcia',
  'nav':'Navarra','navarra':'Navarra','comunidad foral de navarra':'Navarra',
  'pv':'País Vasco','pais vasco':'País Vasco','euskadi':'País Vasco','euskal herria':'País Vasco',
  'ceu':'Ceuta','mel':'Melilla'
};
function canonicalRegion(r){
  if(!r) return '';
  const k=String(r).toLowerCase().trim()
    .replace(/\./g,'').replace(/\s+/g,' ')
    .normalize('NFD').replace(/[̀-ͯ]/g,'');
  return _REGION_MAP_GLOBAL[k] || String(r).trim();
}
function teamKey(name){
  return (name||'').trim().toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g,'')
    .replace(/[.,_\-]/g,' ').replace(/\s+/g,' ').trim();
}
// Palabras genéricas a ignorar al comparar equipos
const _TEAM_STOPWORDS=new Set([
  'club','team','cycling','ciclismo','ciclista','ciclistas','equipo','sociedad',
  'asociacion','asociación','agrupacion','agrupación','deportivo','deportiva',
  'union','unión','cc','cd','ce','sd','cf','ud','ad','sa','sl','sad',
  'el','la','los','las','de','del','y','i','e','o','u','con',
  'masculino','femenino','elite','sub23','sub','cadete','cadetes','junior','master',
  'amateur','aficionados','aficionado'
]);
function teamSignificantTokens(name){
  return teamKey(name).split(/\s+/)
    .filter(t=>t.length>=2 && !_TEAM_STOPWORDS.has(t));
}
// Búsqueda difusa de equipo en la DB: matching por tokens significativos compartidos
function findTeamMatch(teamName, db){
  if(!teamName||!db||db.size===0) return null;
  const tk=teamKey(teamName);
  if(db.has(tk)) return {region:db.get(tk), matchedKey:tk, score:1, exact:true};
  const myTokens=teamSignificantTokens(teamName);
  if(myTokens.length===0) return null;
  const mySet=new Set(myTokens);
  const candidates=[];
  for(const [dbKey,region] of db){
    const dbTokens=teamSignificantTokens(dbKey);
    if(dbTokens.length===0) continue;
    const dbSet=new Set(dbTokens);
    let shared=0;
    mySet.forEach(t=>{ if(dbSet.has(t)) shared++; });
    if(shared===0) continue;
    const minSize=Math.min(mySet.size,dbSet.size);
    const maxSize=Math.max(mySet.size,dbSet.size);
    const score=shared/maxSize; // 1.0 si total contenido en el más grande
    const isContained=shared===minSize;
    const isStrong=shared>=2 && (shared/mySet.size)>=0.5;
    // Acepta si el más pequeño está completamente dentro del más grande (rare-name match)
    // o si hay buena similitud con >=2 tokens en común
    if(isContained || isStrong){
      candidates.push({region, matchedKey:dbKey, score, shared, minSize});
    }
  }
  if(!candidates.length) return null;
  candidates.sort((a,b)=>b.score-a.score || b.shared-a.shared);
  const top=candidates[0];
  // Si el top tiene la misma puntuación que otros con DIFERENTE región → ambiguo, descarta
  const tiedTop=candidates.filter(c=>c.score===top.score);
  const tiedRegions=new Set(tiedTop.map(c=>c.region));
  if(tiedRegions.size>1) return null;
  // Score mínimo razonable
  if(top.score<0.4 && !top.exact) return null;
  return {...top, exact:false};
}
let _teamRegionDB=null;
function buildTeamRegionDB(){
  const counts=new Map();
  const history=Array.isArray(_cachedHistory)?_cachedHistory:[];
  history.forEach(race=>{
    (race.riders||[]).forEach(r=>{
      const tk=teamKey(r.team);
      const rg=canonicalRegion(r.region);
      if(!tk||!rg) return;
      if(!counts.has(tk)) counts.set(tk,new Map());
      const c=counts.get(tk);
      c.set(rg,(c.get(rg)||0)+1);
    });
  });
  // También incluir la carrera actual en memoria
  (Array.isArray(riders)?riders:[]).forEach(r=>{
    const tk=teamKey(r.team);
    const rg=canonicalRegion(r.region);
    if(!tk||!rg) return;
    if(!counts.has(tk)) counts.set(tk,new Map());
    const c=counts.get(tk);
    c.set(rg,(c.get(rg)||0)+1);
  });
  const result=new Map();
  counts.forEach((c,tk)=>{
    let best=null,bestN=0;
    c.forEach((n,rg)=>{ if(n>bestN){bestN=n;best=rg;} });
    if(best) result.set(tk,best);
  });
  _teamRegionDB=result;
  console.log(`[TeamRegionDB] ${result.size} equipos con CCAA conocida (de ${history.length} carreras + carrera actual)`);
  return result;
}
function getTeamRegionDB(){ if(!_teamRegionDB) buildTeamRegionDB(); return _teamRegionDB; }
function invalidateTeamRegionDB(){ _teamRegionDB=null; }

// Migración: canonicaliza TODAS las CCAAs de TODAS las pruebas guardadas en Supabase
async function canonicalizeAllRegionsInHistory(){
  if(!_sb){ alert('Supabase no disponible.'); return; }
  const ok=confirm(
    '⚠️ NORMALIZAR CCAAs EN TODO EL HISTORIAL\n\n'+
    'Esta operación recorrerá TODAS las pruebas guardadas en Supabase y '+
    'unificará las CCAAs a su forma canónica:\n\n'+
    '  • VLC, Valencia, C.V. → Comunitat Valenciana\n'+
    '  • CLM, Castilla La Mancha → Castilla-La Mancha\n'+
    '  • MAD → Madrid\n'+
    '  • CYL → Castilla y León\n'+
    '  • etc. (17 CCAA + Ceuta + Melilla)\n\n'+
    'Es seguro (solo cambia textos a su versión canónica) pero modifica '+
    'registros en la base de datos. ¿Continuar?'
  );
  if(!ok) return;
  showLoading('Cargando historial…','Obteniendo todas las pruebas de Supabase.');
  try{
    const {data:races,error}=await _sb
      .from('races')
      .select('id, name, notes')
      .eq('race_type','clasificacion');
    if(error) throw error;
    const changesSummary=new Map(); // raw → Map(canonical → count)
    let updatedRaces=0, totalChangedRegions=0;
    for(let i=0;i<races.length;i++){
      const race=races[i];
      if(i%5===0) showLoading('Normalizando CCAAs…',`Prueba ${i+1}/${races.length} — ${race.name||''}`);
      let extra={};
      try{ extra=JSON.parse(race.notes||'{}'); }catch(e){ continue; }
      const regions=extra.regions||{};
      let changed=false;
      for(const k of Object.keys(regions)){
        const raw=String(regions[k]||'').trim();
        if(!raw) continue;
        const canon=canonicalRegion(raw);
        if(canon && canon!==raw){
          if(!changesSummary.has(raw)) changesSummary.set(raw, new Map());
          const inner=changesSummary.get(raw);
          inner.set(canon, (inner.get(canon)||0)+1);
          regions[k]=canon;
          changed=true;
          totalChangedRegions++;
        }
      }
      if(changed){
        extra.regions=regions;
        const {error:updErr}=await _sb.from('races').update({notes:JSON.stringify(extra)}).eq('id',race.id);
        if(!updErr) updatedRaces++;
        else console.error('Error updating race',race.id,updErr);
      }
    }
    _cachedHistory=null;
    invalidateTeamRegionDB();
    if(typeof _sbLoadHistory==='function'){
      _sbLoadHistory().then(h=>{ _cachedHistory=h; invalidateTeamRegionDB(); });
    }
    hideLoading();
    let summary='✅ NORMALIZACIÓN COMPLETADA\n\n';
    summary+=`📊 ${updatedRaces} prueba(s) actualizada(s) de ${races.length} total\n`;
    summary+=`📝 ${totalChangedRegions} CCAA(s) cambiada(s)\n\n`;
    if(changesSummary.size){
      summary+='Cambios aplicados (ordenados por frecuencia):\n';
      const sorted=[...changesSummary.entries()].sort((a,b)=>{
        const sumA=[...a[1].values()].reduce((s,n)=>s+n,0);
        const sumB=[...b[1].values()].reduce((s,n)=>s+n,0);
        return sumB-sumA;
      });
      sorted.slice(0,20).forEach(([raw, canons])=>{
        canons.forEach((count, canon)=>{
          summary+=`  • "${raw}" → "${canon}" (${count}×)\n`;
        });
      });
      if(sorted.length>20) summary+=`  … y ${sorted.length-20} más\n`;
    } else {
      summary+='✨ Ya estaba todo canonicalizado. Nada que cambiar.';
    }
    alert(summary);
    // Cerrar diálogo de equipos sin CCAA si está abierto
    document.getElementById('_teamRegionsDialog')?.remove();
  } catch(e){
    hideLoading();
    alert('❌ Error: '+(e.message||e));
    console.error(e);
  }
}
function showTeamRegionsDialog(){
  invalidateTeamRegionDB();
  const db=getTeamRegionDB();
  const currentTeams=new Set();
  (Array.isArray(riders)?riders:[]).forEach(r=>{ if(r.team) currentTeams.add(teamKey(r.team)); });
  const knownInCurrent=[], fuzzyInCurrent=[], unknownInCurrent=[];
  currentTeams.forEach(tk=>{
    const orig=(riders.find(r=>teamKey(r.team)===tk)||{}).team||tk;
    if(db.has(tk)){
      knownInCurrent.push({team:orig, region:db.get(tk)});
    } else {
      const m=findTeamMatch(orig, db);
      if(m){
        fuzzyInCurrent.push({team:orig, matched:m.matchedKey, region:m.region, score:m.score});
      } else {
        unknownInCurrent.push(orig);
      }
    }
  });
  const totalDB=db.size;
  let html=`<div style="padding:20px;max-width:680px"><h3 style="margin-top:0">📋 Base de datos Equipos → CCAA</h3>`;
  html+=`<div style="background:#fffbeb;border:1px solid #fbbf24;border-radius:10px;padding:12px 14px;margin-bottom:14px">
    <div style="font-weight:700;color:#92400e;margin-bottom:4px">🔄 Mantenimiento</div>
    <div style="font-size:13px;color:#78350f;margin-bottom:10px">¿Tienes pruebas antiguas con CCAAs en formato no unificado (VLC, CLM, MAD…)? Esto recorre el historial de Supabase y normaliza todas a su forma canónica para que los filtros funcionen.</div>
    <button class="btn" style="background:#d97706;color:#fff;font-weight:700" onclick="canonicalizeAllRegionsInHistory()">🔄 Normalizar CCAAs en todo el historial</button>
  </div>`;
  html+=`<p>Total equipos conocidos en historial: <strong>${totalDB}</strong></p>`;
  html+=`<p>Equipos en esta carrera: <strong>${currentTeams.size}</strong></p>`;
  html+=`<p style="margin-top:0;font-size:13px;color:#6b7280">✅ ${knownInCurrent.length} match exacto · 🔵 ${fuzzyInCurrent.length} match por similitud · <span style="color:#dc2626"><strong>⚠️ ${unknownInCurrent.length} sin CCAA</strong></span></p>`;
  if(unknownInCurrent.length){
    html+=`<h4 style="color:#dc2626;margin-bottom:6px">⚠️ Equipos sin CCAA (edita un ciclista de cada uno para añadirlos)</h4>`;
    html+=`<ul style="max-height:160px;overflow:auto;background:#fef2f2;padding:10px 10px 10px 30px;border-radius:8px">`;
    unknownInCurrent.sort().forEach(t=>{ html+=`<li>${escapeHtml(t)}</li>`; });
    html+=`</ul>`;
  }
  if(fuzzyInCurrent.length){
    html+=`<h4 style="color:#2563eb;margin-bottom:6px;margin-top:14px">🔵 Equipos con CCAA por similitud (revisa que sean correctos)</h4>`;
    html+=`<ul style="max-height:160px;overflow:auto;background:#eff6ff;padding:10px 10px 10px 30px;border-radius:8px;font-size:13px">`;
    fuzzyInCurrent.sort((a,b)=>b.score-a.score).forEach(f=>{
      const pct=Math.round(f.score*100);
      html+=`<li><strong>${escapeHtml(f.team)}</strong> → <em>${escapeHtml(f.region)}</em> <span style="color:#9ca3af">(${pct}% similar a "${escapeHtml(f.matched)}")</span></li>`;
    });
    html+=`</ul>`;
  }
  if(knownInCurrent.length){
    html+=`<h4 style="color:#059669;margin-bottom:6px;margin-top:14px">✅ Equipos con CCAA conocida</h4>`;
    html+=`<ul style="max-height:200px;overflow:auto;background:#f0fdf4;padding:10px 10px 10px 30px;border-radius:8px">`;
    knownInCurrent.sort((a,b)=>a.team.localeCompare(b.team)).forEach(k=>{
      html+=`<li><strong>${escapeHtml(k.team)}</strong> → <em>${escapeHtml(k.region)}</em></li>`;
    });
    html+=`</ul>`;
  }
  html+=`<div style="text-align:right;margin-top:16px"><button class="btn" onclick="document.getElementById('_teamRegionsDialog')?.remove()">Cerrar</button></div></div>`;
  const old=document.getElementById('_teamRegionsDialog');
  if(old) old.remove();
  const overlay=document.createElement('div');
  overlay.id='_teamRegionsDialog';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.onclick=e=>{ if(e.target===overlay) overlay.remove(); };
  overlay.innerHTML=`<div style="background:#fff;border-radius:14px;max-width:700px;max-height:90vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.3)">${html}</div>`;
  document.body.appendChild(overlay);
}
function autoFillRegionsFromTeamDB(list){
  if(!list||!list.length) return 0;
  const db=getTeamRegionDB();
  let filled=0,fuzzyFilled=0,canonicalized=0;
  const fuzzyMatches=[];
  list.forEach(r=>{
    // Canonicalizar CCAAs existentes (VLC → Comunitat Valenciana, etc.)
    if(r.region){
      const canon=canonicalRegion(r.region);
      if(canon!==r.region){ r.region=canon; canonicalized++; }
    }
    // Rellenar CCAAs vacías con matching exacto + difuso
    if(!r.region && r.team){
      const match=findTeamMatch(r.team, db);
      if(match){
        r.region=match.region;
        filled++;
        if(!match.exact){
          fuzzyFilled++;
          fuzzyMatches.push({team:r.team, matched:match.matchedKey, region:match.region, score:match.score.toFixed(2)});
        }
      }
    }
  });
  if(filled>0||canonicalized>0){
    console.log(`[autoFillRegions] ${filled} rellenadas (${fuzzyFilled} por similitud), ${canonicalized} canonicalizadas`);
    if(fuzzyMatches.length>0){
      console.table(fuzzyMatches.slice(0,20));
    }
  }
  return filled;
}

function enrichRiders(list){
  // COMENTARIO: cálculo robusto de gaps y tiempos totales.
  // - Tiempo absoluto sin "a": se interpreta como tiempo real de carrera.
  // - Diferencia con "a": se interpreta como gap respecto al ganador.
  // - Campo vacío: hereda el gap del bloque anterior.
  autoFillRegionsFromTeamDB(list);
  inferRegionsFromTeam(list);
  const sorted=list.slice().sort((a,b)=>a.pos-b.pos);
  const km=parseKmValue();

  let winner=sorted.find(r=>r.pos===1);
  let winnerAbs=winner ? timeToSeconds(winner.time) : null;

  if(winnerAbs==null){
    const firstAbs=sorted.find(r=>r.time && !/^a\s+/i.test(r.time) && timeToSeconds(r.time)!=null);
    if(firstAbs){
      winnerAbs=timeToSeconds(firstAbs.time);
      console.warn('COMENTARIO: tiempo del ganador no encontrado; se usa el primer tiempo absoluto disponible como referencia.');
    }else{
      console.warn('COMENTARIO: no se ha detectado ningún tiempo absoluto. Solo se calcularán gaps si aparecen diferencias tipo "a 0:00".');
    }
  }

  let lastGap=0;
  const enrichedByKey=new Map();

  sorted.forEach(r=>{
    const raw=cleanSpaces(r.time||'');
    let gap=null;
    let abs=null;

    if(r.pos===1){
      if(raw && !/^a\s+/i.test(raw)){
        abs=timeToSeconds(raw);
        if(abs!=null && winnerAbs==null) winnerAbs=abs;
      }
      gap=0;
      if(abs==null && winnerAbs!=null) abs=winnerAbs;
      // fallback: si no se pudo recalcular desde la cadena, conservar totalSeconds existente
      if(abs==null && r.totalSeconds>0){ abs=r.totalSeconds; if(winnerAbs==null) winnerAbs=abs; }
      lastGap=0;
    }else if(!raw){
      gap=lastGap;
      if(winnerAbs!=null) abs=winnerAbs+gap;
    }else if(/^a\s+/i.test(raw)){
      gap=timeToSeconds(raw);
      if(gap==null) gap=lastGap;
      if(winnerAbs!=null) abs=winnerAbs+gap;
      lastGap=gap;
    }else{
      abs=timeToSeconds(raw);
      if(abs!=null && winnerAbs!=null) gap=Math.max(0,abs-winnerAbs);
      else gap=lastGap;
      lastGap=gap;
    }

    if(abs==null && winnerAbs!=null && gap!=null) abs = winnerAbs + gap;
    // fallback gapSeconds: si no se pudo calcular el gap desde la cadena de tiempo,
    // conservar el valor anterior (solo para no-ganadores, donde gap=0 es el default vacío)
    if(r.pos!==1 && gap===0 && r.gapSeconds>0) gap=r.gapSeconds;
    // fallback abs desde gap recuperado
    if(abs==null && winnerAbs!=null && gap!=null) abs=winnerAbs+gap;
    // fallback totalSeconds: conservar valor existente si todo lo demás falló
    if(abs==null && r.totalSeconds>0) abs=r.totalSeconds;

    const secKm=(gap!=null && km>0)?gap/km:null;
    enrichedByKey.set(r.pos+'|'+r.bib+'|'+r.name,{...r,gapSeconds:gap,totalSeconds:abs,secPerKm:secKm});
  });

  const catCounters = new Map();
  return sorted.map(r=>{
    const item = enrichedByKey.get(r.pos+'|'+r.bib+'|'+r.name)||r;
    const c = String(r.cat || 'DESCONOCIDA');
    const count = (catCounters.get(c) || 0) + 1;
    catCounters.set(c, count);
    return { ...item, catPos: count };
  });
}
function getColorForCategory(cat){
  const key=String(cat||'').toUpperCase();
  const map={'CAD-1':'#1f6feb','CAD-2':'#12b76a','F-CAD':'#f79009','F-JUN':'#7a5af8','JUN':'#06aed4','SUB23':'#ef6820','ELITE':'#667085','MASTER30':'#a855f7','MASTER40':'#8b5cf6','MASTER50':'#7c3aed','MASTER60':'#6d28d9'};
  return map[key]||'#475467';
}


function extractWinnerTime(text){
  const lines=(text||'').split(/\n+/).map(cleanSpaces).filter(Boolean);
  const catRe='CAD-1|CAD-2|F-CAD|F-JUN|JUN|ELITE|SUB23|MASTER\\s?\\d*';
  for(const line of lines){
    const m=line.match(new RegExp('^\\s*1\\s+\\d{1,3}\\s+.+?\\s+(?:'+catRe+')\\s+.+?\\s+(\\d{1,2}:\\d{2}:\\d{2})\\s*$','i'));
    if(m) return m[1];
  }
  const oneLine=(text||'').replace(/\s+/g,' ');
  const m2=oneLine.match(new RegExp('\\b1\\s+\\d{1,3}\\s+.+?\\s+(?:'+catRe+')\\s+.+?\\s+(\\d{1,2}:\\d{2}:\\d{2})\\b','i'));
  return m2?m2[1]:'';
}
function extractMeta(text){const oneLine=(text||'').replace(/\s+/g,' ');const title=(oneLine.match(/((?:XXIX|XXX|XVI|XVII|[A-ZÁÉÍÓÚÑ0-9]).{10,90}?)(?:\s+Km:|\s+CLASIFICACIÓN|\s+Vmedia)/i)||[])[1];if(title)$('raceName').value=cleanSpaces(title);const km=(oneLine.match(/Km:\s*([0-9,.]+)/i)||[])[1];if(km)$('raceKm').value=formatKmValue(km);const avg=(oneLine.match(/Vmedia\s*:?\s*([0-9,.]+)\s*Km/i)||[])[1];if(avg)$('raceAvg').value=avg+' km/h';const date=(oneLine.match(/(\d{1,2}[-\/]\d{1,2}[-\/]\d{2,4})/)||[])[1];if(date){const _iso=_parseSpanishDate(date);$('raceDate').value=_iso?formatDateDisplay(_iso):date;}}

function stripTeamNoise(t){
  return cleanSpaces(String(t||'')
    .replace(/\b(?:a\s*)?\d{1,2}:\d{2}(?::\d{2})?\b/gi,'')
    .replace(/\s+\d+\s*$/,'')
    .replace(/[.,;:]+$/,'')
    .replace(/\s+-\s*$/,''));
}
function normKey(s){return stripTeamNoise(s).toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]+/g,' ').trim();}
function extractCanonicalTeams(text){
  const lines=(text||'').split(/\n+/).map(cleanSpaces).filter(Boolean);
  let inTeams=false, teams=[];
  for(const line of lines){
    if(/CLASIFICACIÓN\s+EQUIPOS/i.test(line)){inTeams=true;continue;}
    if(inTeams && /CLASIFICACIÓN\s+METAS|METAS\s+VOLANTES|CLASIFICACION\s+METAS/i.test(line)) break;
    if(!inTeams) continue;
    const m=line.match(/^\d{1,2}\s+(.+?)\s+(?:\d+\s+)?\d{1,2}:\d{2}:\d{2}\s*$/);
    if(m) teams.push(stripTeamNoise(m[1]));
  }
  // Correcciones conocidas para PDFs donde la general corta el nombre del equipo.
  const known=['GRAU PASCUAL RET AMIANTO-SAXUN','GRUPO DEPORTIVO LLOPIS','TBG-WIXUM','JUAN GINER-ULEVEL-VITALDINSPOR','INFINOBRAS - GRUPO SIME','IKASCOLA TX. AEL-RESPETAD','HOSTAL SAVOY - ULEVEL','SUMISTOCK-IN BIKE','DIPUTACION DE ALBACETE - ARCOS','GUEROLA'];
  return [...new Set([...teams,...known].filter(Boolean))];
}
function normalizeTeamName(team, canonicals){
  let t=stripTeamNoise(team);
  if(!t) return '';
  const key=normKey(t);
  const manual={
    'GRAU PASCUAL RET AMIANT':'GRAU PASCUAL RET AMIANTO-SAXUN',
    'GRAU PASCUAL RET AMIA':'GRAU PASCUAL RET AMIANTO-SAXUN',
    'GRUPO DEPORTIVO LLOPI':'GRUPO DEPORTIVO LLOPIS',
    'JUAN GINER ULEVEL VITALDI':'JUAN GINER-ULEVEL-VITALDINSPOR',
    'JUAN GINER ULEVEL VITA':'JUAN GINER-ULEVEL-VITALDINSPOR',
    'INFINOBRAS GRUPO SIM':'INFINOBRAS - GRUPO SIME',
    'IKASCOLA TX AEL RESPET':'IKASCOLA TX. AEL-RESPETAD',
    'DIPUTACION DE ALBACETE':'DIPUTACION DE ALBACETE - ARCOS',
    'DIPUTACION DE ALBACET':'DIPUTACION DE ALBACETE - ARCOS'
  };
  if(manual[key]) return manual[key];
  let best=null, bestScore=0;
  const words=new Set(key.split(/\s+/).filter(w=>w.length>1));
  for(const c of canonicals||[]){
    const ck=normKey(c); if(!ck) continue;
    if(ck===key) return c;
    if(ck.startsWith(key) || key.startsWith(ck)) return c.length>=t.length?c:t;
    const cwords=new Set(ck.split(/\s+/).filter(w=>w.length>1));
    let common=0; words.forEach(w=>{if(cwords.has(w)) common++});
    const score=common/Math.max(1,Math.min(words.size,cwords.size));
    if(score>bestScore){bestScore=score;best=c;}
  }
  return bestScore>=0.75 ? best : t;
}
function parseRiders(text){
  const lines=(text||'').split(/\n+/).map(cleanSpaces).filter(Boolean);
  let arr=[];
  const catRe='CAD-1|CAD-2|F-CAD|F-JUN|JUN|ELITE|SUB23|MASTER\\s?\\d*';
  for(let line of lines){
    if(/CLASIFICACIÓN EQUIPOS|METAS VOLANTES|CADETES 1|CADETES 2|CADETE FEMENINO|JUNIOR FEMENINO/i.test(line)) continue;
    let m=line.match(new RegExp('^(\\d{1,3})\\s+(\\d{1,3})\\s+(.+?)\\s+('+catRe+')\\s+(.+)$','i'));
    if(!m) continue;
    let pos=+m[1], bib=m[2], name=cleanSpaces(m[3]), cat=cleanSpaces(m[4]).replace(/\s+/g,''), tail=cleanSpaces(m[5]);
    tail=tail.replace(/\s+\d{1,3}\s+\d{1,3}\s+.+$/,'');
    let time='';
    let tm=tail.match(/\b(?:a\s*)?\d{1,2}:\d{2}(?::\d{2}(?:[.,]\d+)?)?\s*$/i);
    if(tm){time=normalizeTimeStr(cleanSpaces(tm[0]));tail=cleanSpaces(tail.slice(0,tm.index));}
    if(pos>=1 && pos<=500 && bib) arr.push({pos,bib,name:normalizeRiderName(name),time,cat,region:'',team:tail});
  }
  if(arr.length<3){arr=parseCSVLike(text)}
  return dedupe(arr).sort((a,b)=>a.pos-b.pos);
}
function parseCSVLike(text){
  // COMENTARIO: parseo robusto para CSV, TSV y tablas pegadas como texto, incluyendo C.A Participante.
  const rawLines=text.split(/\n/).map(l=>l.trim()).filter(Boolean);
  if(!rawLines.length)return [];

  const seps=[',',';','\t','|'];
  let bestSep=';', bestScore=-1;

  seps.forEach(sep=>{
    const counts=rawLines.slice(0,25).map(l=>l.split(sep).length).filter(n=>n>1);
    if(!counts.length)return;
    const avg=counts.reduce((s,n)=>s+n,0)/counts.length;
    const consistent=counts.filter(n=>Math.abs(n-avg)<=1).length;
    const score=avg*consistent;
    if(score>bestScore){bestScore=score;bestSep=sep;}
  });

  let rows=rawLines.map(l=>l.split(bestSep).map(cleanSpaces));

  if(bestScore<6){
    rows=rawLines.map(l=>l.split(/\s{2,}/).map(cleanSpaces));
  }

  const normalizeHeader=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\\/g,'/');

  let headerIdx=rows.findIndex(r=>{
    const h=r.map(normalizeHeader).join(' ');
    return /(pos|puesto|clasif|\bpl[\. ])/.test(h) && /(dorsal|dor)/.test(h) && /(nombre|ciclista|corredor)/.test(h);
  });

  let map={pos:0,bib:1,name:2,surname:null,cat:null,team:4,region:null,time:5};
  // Guardamos estado para el diálogo de confirmación de columna CCAA
  window._lastCsvRows = rows;
  window._lastCsvMap  = map;
  window._lastCsvHeaderIdx = headerIdx;
  window._lastCsvUnmapped  = [];

  if(headerIdx>=0){
    const h=rows[headerIdx].map(normalizeHeader);
    const find=(regs,def=null)=>{const i=h.findIndex(c=>regs.some(re=>re.test(c)));return i>=0?i:def};

    map.pos=find([/^pos/,/puesto/,/clas/],0);
    map.bib=find([/dorsal/,/^dor/,/num/],1);
    map.name=find([/^nombre$/,/nombre(?!.*equipo)/,/ciclista/,/corredor/,/name/],2);
    map.surname=find([/apellido/,/surname/,/last name/],null);
    map.team=find([/club.*equipo/,/equipo/,/club/,/^team$/],4);
    // Regex ampliado: acepta espacio entre C. y A. (ej: "C. A. Participante")
    map.region=find([/c\.?\s*a\.?\s*participante/,/comunidad/,/autonom/,/^ca$/,/ccaa/,/c\.?c\.?aa/,/fed.*territ/,/territ/,/region/,/provincia/],null);
    map.time=find([/tiempo/,/dif/,/gap/,/^time$/],5);
    map.cat=find([/^categoria$/,/categoria deportiva/,/^cat$/,/category/],null);

    // Detectar columnas del header que no se han mapeado a ningún campo conocido
    const usedCols=new Set(Object.values(map).filter(v=>v!=null));
    window._lastCsvUnmapped = h.map((col,i)=>({idx:i,label:rows[headerIdx][i]}))
      .filter(({idx,label})=>!usedCols.has(idx) && label && label.trim().length>1);
    window._lastCsvMap = map;
  }

  const startRow=headerIdx>=0?headerIdx+1:0;
  let out=[];

  rows.slice(startRow).forEach(parts=>{
    if(parts.length<3)return;
    const posVal=parts[map.pos]||parts[0]||'';
    if(!/^\d+$/.test(posVal))return;

    let namePart=parts[map.name]||'';
    let surnamePart=map.surname!=null ? (parts[map.surname]||'') : '';
    let fullName=surnamePart ? `${namePart} ${surnamePart}` : namePart;

    let team=parts[map.team]||'';
    let region=map.region!=null ? (parts[map.region]||'') : '';
    let time=normalizeTimeStr(parts[map.time]||'');

    out.push({
      pos:+posVal,
      bib:parts[map.bib]||'',
      name:surnamePart?normalizeRiderName(null,namePart,surnamePart,null):normalizeRiderName(fullName),
      cat:map.cat!=null ? ((parts[map.cat]||'CADETE').replace(/\s+/g,'')) : 'CADETE',
      region:cleanSpaces(region),
      team:cleanSpaces(team),
      time:cleanSpaces(time)
    });
  });

  return out;
}
function dedupe(a){const seen=new Set();return a.filter(r=>{let k=r.pos+'-'+r.bib+'-'+r.name;if(seen.has(k))return false;seen.add(k);return true})}

async function _checkUnmappedRegionCol(){
  // Solo actúa si todos los riders tienen región vacía y hay columnas sin mapear
  if(!riders.length) return;
  const allEmpty=riders.every(r=>!r.region);
  if(!allEmpty) return;
  const unmapped=window._lastCsvUnmapped||[];
  if(!unmapped.length) return;
  const rows=window._lastCsvRows;
  const map=window._lastCsvMap;
  const headerIdx=window._lastCsvHeaderIdx;
  if(!rows||headerIdx==null) return;

  // Filtrar candidatos: columnas que tienen datos reales (no todo vacío)
  const startRow=headerIdx+1;
  const dataRows=rows.slice(startRow).filter(p=>p.length>2);
  const candidates=unmapped.filter(({idx})=>{
    return dataRows.some(p=>p[idx]&&cleanSpaces(p[idx]).length>1);
  });
  if(!candidates.length) return;

  // Preguntar por cada candidato (normalmente solo habrá uno)
  for(const col of candidates){
    const ejemplos=[...new Set(dataRows.slice(0,5).map(p=>cleanSpaces(p[col.idx]||'')).filter(Boolean))].slice(0,3);
    const respuesta=await _dialogoCCAA(col.label, ejemplos);
    if(respuesta){
      // Aplicar la columna como región a todos los riders
      const newMap={...map, region:col.idx};
      window._lastCsvMap=newMap;
      riders=riders.map((r,i)=>{
        const parts=dataRows[i];
        if(!parts) return r;
        return {...r, region:cleanSpaces(parts[col.idx]||'')};
      });
      filtered=filtered.map(fr=>riders.find(r=>r.pos===fr.pos&&r.bib===fr.bib&&r.name===fr.name)||fr);
      populateFilters();
      applyFilters();
      break; // Con uno confirmado ya es suficiente
    }
  }
}

function _dialogoCCAA(nombreCol, ejemplos){
  return new Promise(resolve=>{
    const overlay=document.createElement('div');
    overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
    const ejHtml=ejemplos.length
      ?`<div style="background:#f8fbff;border:1px solid #cce7ff;border-radius:8px;padding:8px 12px;font-size:13px;color:#374151;margin:10px 0">
          Ejemplos de valores: <b>${ejemplos.map(e=>escapeHtml(e)).join(' · ')}</b>
        </div>`:'';
    overlay.innerHTML=`
      <div style="background:#fff;border-radius:18px;padding:26px 24px;max-width:440px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,.18)">
        <div style="font-size:20px;margin-bottom:8px">🗺️ Columna no reconocida</div>
        <p style="color:#374151;font-size:15px;line-height:1.5;margin:0 0 4px">
          He encontrado una columna llamada <b>"${escapeHtml(nombreCol)}"</b> que no he podido identificar automáticamente.
        </p>
        ${ejHtml}
        <p style="color:#374151;font-size:15px;line-height:1.5;margin:0 0 20px">
          ¿Corresponde a la <b>Comunidad Autónoma (CCAA)</b> de los participantes?
        </p>
        <div style="display:flex;gap:10px;flex-wrap:wrap">
          <button id="_ccaaSi" style="flex:1;background:#1f6feb;color:#fff;border:0;border-radius:10px;padding:11px 18px;font-weight:800;font-size:14px;cursor:pointer">✅ Sí, es la CCAA</button>
          <button id="_ccaaNo" style="flex:1;background:#fff;color:#667085;border:1.5px solid #d0d5dd;border-radius:10px;padding:11px 18px;font-weight:700;font-size:14px;cursor:pointer">No, ignorar</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    const cleanup=v=>{document.body.removeChild(overlay);resolve(v);};
    overlay.querySelector('#_ccaaSi').onclick=()=>cleanup(true);
    overlay.querySelector('#_ccaaNo').onclick=()=>cleanup(false);
    overlay.onclick=e=>{if(e.target===overlay)cleanup(false);};
  });
}
function formatName(n){return cleanSpaces(n).toLowerCase().replace(/(^|[\s,\-])\p{L}/gu,c=>c.toUpperCase())}

function _titleCase(s){if(!s)return'';return cleanSpaces(s).toLowerCase().replace(/(^|[\s,\-])\p{L}/gu,c=>c.toUpperCase());}

/* Canonical "PrimerApellido, Nombre" format — always single apellido.
   1. Separate columns: (null,"Ivan","Sanchez Toral",null) → "Sanchez, Ivan"
   2. Comma:  "BELTRAN SULLER, ALEX"  → "Beltran, Alex"
   3. Mixed:  "Ivan Sanchez Toral"    → "Sanchez, Ivan"  (first word = nombre)
   4. AllCaps:"SANCHEZ TORAL IVAN"    → "Sanchez, Ivan"  (last word = nombre, first = apellido) */
function normalizeRiderName(rawName, nombre, apellido1, apellido2){
  // ── LIMPIEZA DEFENSIVA: eliminar sufijos de posición/categoría que a veces
  // se quedan pegados al nombre cuando el CSV o PDF mezcla columnas. Patrones:
  //   "Pastor, Mauro 1 De 30"   → "Pastor, Mauro"
  //   "Pastor, Mauro 1/30"      → "Pastor, Mauro"
  //   "Pastor, Mauro (1/30)"    → "Pastor, Mauro"
  //   "Pastor, Mauro 1º"        → "Pastor, Mauro"
  function _stripPosSuffix(s){
    if(!s) return s;
    let v = String(s);
    // " N de M" o " N De M" o " N/M"
    v = v.replace(/\s+\d+\s+[Dd][Ee]\s+\d+\s*$/u, '');
    v = v.replace(/\s+\d+\s*\/\s*\d+\s*$/u, '');
    v = v.replace(/\s*\(\s*\d+\s*\/\s*\d+\s*\)\s*$/u, '');
    v = v.replace(/\s+\d+[º°]\s*$/u, '');
    return v.trim();
  }
  rawName = _stripPosSuffix(rawName);
  nombre = _stripPosSuffix(nombre);
  apellido1 = _stripPosSuffix(apellido1);
  apellido2 = _stripPosSuffix(apellido2);

  if(apellido1){
    const n=_titleCase((nombre||'').trim());
    const a1=_titleCase((apellido1||'').trim().split(/\s+/)[0]); // solo primer apellido
    return a1?`${a1}, ${n}`:n;
  }
  const raw=(rawName||'').trim();
  if(!raw)return'';
  const comma=raw.match(/^([^,]+),\s*(.+)$/);
  if(comma){
    const ap=_titleCase(comma[1].trim().split(/\s+/)[0]); // solo primer apellido
    const nm=_titleCase(comma[2].trim());
    return ap?`${ap}, ${nm}`:nm;
  }
  const words=raw.split(/\s+/).filter(Boolean);
  if(words.length<2)return _titleCase(raw);
  const isAllCaps=raw===raw.toUpperCase()&&/[A-ZÁÉÍÓÚÑ]/.test(raw);
  if(isAllCaps){
    // "SANCHEZ TORAL IVAN" → primer apellido = words[0], nombre = last word
    return `${_titleCase(words[0])}, ${_titleCase(words[words.length-1])}`;
  }
  // "GREUS I SORIANO Marc" → APELLIDOS EN MAYÚSCULAS + nombre en minúsculas al final
  // Detectar: primera palabra toda mayúsculas, última palabra con minúsculas (no toda mayúsculas)
  const lastWord=words[words.length-1];
  const firstWord=words[0];
  const lastHasLower=lastWord!==lastWord.toUpperCase()&&/[A-Za-záéíóúñ]/.test(lastWord);
  const firstIsAllUpper=firstWord===firstWord.toUpperCase()&&/[A-ZÁÉÍÓÚÑ]/.test(firstWord);
  if(lastHasLower&&firstIsAllUpper){
    // primer apellido = words[0], nombre = último word
    return `${_titleCase(firstWord)}, ${_titleCase(lastWord)}`;
  }
  // "Ivan Sanchez Toral" → nombre = words[0], primer apellido = words[1]
  return `${_titleCase(words[1])}, ${_titleCase(words[0])}`;
}

/* Matching key: "apellido, nombre" — lowercase, no accents, no 2nd surname, no extra spaces.
   Works on any format produced by normalizeRiderName or legacy formatName. */
function normalizeForMatching(name){
  if(!name)return'';
  const s=name.trim();
  const comma=s.match(/^([^,]+),\s*(.+)$/);
  let ap,nm;
  if(comma){
    ap=(comma[1].trim().split(/\s+/)[0])||'';
    nm=(comma[2].trim().split(/\s+/)[0])||'';
  }else{
    const parts=s.split(/\s+/).filter(Boolean);
    if(parts.length<2)return s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
    nm=parts[0]; ap=parts[1];
  }
  return (ap+', '+nm).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
}

// ── Matcher tolerante al orden (Tier 1.5 fix) ─────────────────────────────
// Devuelve un Set de tokens significativos (≥3 chars) sin acentos / puntuación.
// Útil para comparar "GARCIA PEREZ JUAN" con "Juan Garcia, Perez" → ambas
// producen {garcia, perez, juan}.
function _nameTokenSet(name){
  if(!name) return new Set();
  return new Set(
    String(name).toLowerCase()
      .normalize('NFD').replace(/[̀-ͯ]/g,'')
      .replace(/[.,;]/g,' ')
      .split(/\s+/)
      .map(t=>t.trim())
      .filter(t=>t.length>=3)
  );
}
// Cuenta cuántos tokens significativos comparten dos nombres.
function _nameSharedTokens(a,b){
  const A = _nameTokenSet(a), B = _nameTokenSet(b);
  let n = 0;
  A.forEach(t=>{ if(B.has(t)) n++; });
  return n;
}
// Match flexible: si ambos nombres tienen ≥2 palabras significativas en común
// → consideramos que es el mismo corredor. (Apellido + nombre suele bastar.)
function namesMatchFlexible(a,b){
  if(!a || !b) return false;
  // Match exacto por normalizeForMatching (rápido)
  if(normalizeForMatching(a) === normalizeForMatching(b)) return true;
  // Match por intersección de tokens
  return _nameSharedTokens(a,b) >= 2;
}
/* Actualiza el datalist del buscador de ciclistas según los filtros activos */
function _updateSearchDatalist(){
  const dl=$('searchSuggestions');
  if(!dl||!riders.length) return;
  const teamSel=$('teamFilter')?.value||'';
  const myTeamLocal=localStorage.getItem('myTeam')||'';
  let pool=riders;
  // Prioridad: si "Solo mi equipo" está activo → filtrar por mi equipo
  if(onlyMyTeam && myTeamLocal){
    pool=riders.filter(r=>(r.team||'').toLowerCase()===myTeamLocal.toLowerCase());
  } else if(teamSel){
    pool=riders.filter(r=>r.team===teamSel);
  }
  const names=[...new Set(pool.map(r=>r.name).filter(Boolean))].sort();
  dl.innerHTML=names.map(n=>`<option value="${escapeHtml(n)}">`).join('');
}

/* Al cambiar el filtro de equipo: limpia el nombre y actualiza el datalist */
function _onTeamFilterChange(){
  const inp=$('searchInput');
  if(inp) inp.value='';
  _updateSearchDatalist();
  applyFilters();
}

/* Botón ▼: limpia el texto y abre el datalist */
function _clearAndOpenSearch(){
  const inp=$('searchInput');
  if(!inp)return;
  inp.value='';
  applyFilters();
  _updateSearchDatalist();
  inp.focus();
  // Trick para forzar que el navegador abra el datalist
  inp.dispatchEvent(new Event('input'));
  inp.click();
}

function populateFilters(){
  let teams=[...new Set(riders.map(r=>r.team).filter(Boolean))].sort();
  let cats=[...new Set(riders.map(r=>r.cat).filter(Boolean))].sort();
  let regions=[...new Set(riders.map(r=>r.region).filter(Boolean))].sort();
  $('teamFilter').innerHTML='<option value="">Todos los equipos</option>'+teams.map(t=>`<option>${escapeHtml(t)}</option>`).join('');
  
  // Renderizar Chips de Categorías (multi-selección)
  const chipWrap = $('catFilterChips');
  if(chipWrap){
    chipWrap.innerHTML = '<div class="chip ' + (selectedCatChips.size===0?'active':'') + '" onclick="selectCatChip(\'\')">Todas</div>' +
      cats.map(c=>`<div class="chip ${selectedCatChips.has(c)?'active':''}" onclick="selectCatChip('${escapeHtml(c)}')">${escapeHtml(c)}</div>`).join('');
  }

  if($('regionFilter'))$('regionFilter').innerHTML='<option value="">Todas las CCAA</option>'+regions.map(r=>`<option>${escapeHtml(r)}</option>`).join('');
  
  // Desplegable de equipos del buscador de Análisis Individual
  if($('analysisTeamFilter')){
    const teams=[...new Set(riders.map(r=>r.team).filter(Boolean))].sort();
    $('analysisTeamFilter').innerHTML='<option value="">— Todos los equipos —</option>'+
      teams.map(t=>`<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join('');
  }
  updateAnalysisSuggestions();
  if($('compareTeamA')&&$('compareTeamB')){
    const opts='<option value="">Seleccionar equipo</option>'+teams.map(t=>`<option>${escapeHtml(t)}</option>`).join('');
    $('compareTeamA').innerHTML=opts;
    $('compareTeamB').innerHTML=opts;
    if(teams.length>1){
      // Por defecto: Mi Equipo en la izquierda, Mejor Equipo en la derecha
      if(myTeam && teams.includes(myTeam)) {
        $('compareTeamA').value = myTeam;
      } else {
        $('compareTeamA').value = teams[0];
      }
      
      const metrics = teams.map(t => teamMetrics(t)).filter(Boolean);
      metrics.sort((a,b) => a.avg - b.avg); // Ordenar por mejor posición media
      
      if(metrics.length > 0) {
        // Buscar el mejor que no sea el seleccionado en A
        const bestTeam = metrics.find(m => m.team !== $('compareTeamA').value) || metrics[0];
        $('compareTeamB').value = bestTeam.team;
      }
    }
  }
  teamRankingCategories=cats.slice();
  renderTeamCategoryFilter();
  updateMyTeamSuggestions();
  _updateSearchDatalist();
}
function selectCatChip(cat){
  if(cat === ''){
    // "Todas" — limpiar toda la selección
    selectedCatChips.clear();
  } else if(selectedCatChips.has(cat)){
    // Deseleccionar si ya estaba activo
    selectedCatChips.delete(cat);
  } else {
    // Añadir a la selección múltiple
    selectedCatChips.add(cat);
  }
  populateFilters();
  applyFilters();
}
function clearAllFilters(){
  $('searchInput').value = '';
  $('teamFilter').value = '';
  if($('regionFilter')) $('regionFilter').value = '';
  $('topFilter').value = '';
  selectedCatChips.clear();
  onlyMyTeam = false;
  
  const btn = $('toggleMyTeam');
  if(btn){
    btn.classList.remove('active');
    $('toggleIcon').textContent = '⚪';
  }
  
  populateFilters();
  applyFilters();
}
function toggleMyTeamFilter(){
  if(!myTeam) {
    alert("Primero configura 'Mi Equipo' en la pestaña de Carga y Resumen");
    return;
  }
  onlyMyTeam = !onlyMyTeam;
  const btn = $('toggleMyTeam');
  if(btn){
    btn.classList.toggle('active', onlyMyTeam);
    $('toggleIcon').textContent = onlyMyTeam ? '🟢' : '⚪';
  }
  // Limpiar búsqueda de nombre al cambiar de contexto de equipo
  const inp=$('searchInput'); if(inp) inp.value='';
  _updateSearchDatalist();
  applyFilters();
}
function applyFilters(){
  const q=$('searchInput').value.toLowerCase();
  const team=$('teamFilter').value;
  const region=$('regionFilter')?$('regionFilter').value:'';
  const top=+$('topFilter').value||0;

  filtered=riders.filter(r=>{
    if(q && !(r.name+' '+r.team+' '+r.bib+' '+(r.region||'')).toLowerCase().includes(q)) return false;
    if(team && r.team!==team) return false;
    if(selectedCatChips.size > 0 && !selectedCatChips.has(r.cat)) return false;
    if(region && r.region!==region) return false;
    if(top && r.pos>top) return false;
    if(onlyMyTeam && !isMyTeam(r)) return false;
    return true;
  });
  applySortToFiltered();
  renderAll();
}
function selectAndAnalyzeRiderByKey(key){
  // COMENTARIO: selecciona un ciclista, lo pasa al buscador/filtro, cambia a la vista de análisis y ejecuta automáticamente el análisis individual.
  const r=riders.find(x=>getRiderKey(x)===key);
  if(!r)return;
  $('searchInput').value=r.name;
  if($('analysisSearchInput')) $('analysisSearchInput').value=r.name;
  
  applyFilters();
  showView('view-analisis');
  analyseSelectedRider();
  
  setTimeout(()=>{($('analysisPanel')||$('individualResult'))?.scrollIntoView({behavior:'smooth',block:'start'});},100);
}
function autoAnalyzeIfSingleMatch(){
  // COMENTARIO: si el filtro deja un único ciclista claro, lanza el análisis sin pulsar el botón.
  if(!hasValidData||!riders.length)return;
  const q=(($('analysisSearchInput')&&$('analysisSearchInput').value)||$('searchInput').value).toLowerCase().trim();
  if(q.length<2)return;
  const matches=riders.filter(r=>(r.name+' '+r.bib).toLowerCase().includes(q));
  if(matches.length===1){
    analyseSelectedRider();
  }
}

function setSort(key){
  // COMENTARIO: ordenación por columna con flecha ascendente/descendente.
  if(sortState.key===key) sortState.dir=sortState.dir==='asc'?'desc':'asc';
  else sortState={key,dir:'asc'};
  applyFilters();
}
function sortValue(r,key){
  if(key==='pos')return r.pos;
  if(key==='catPos')return r.catPos;
  if(key==='bib')return Number(r.bib)||r.bib;
  if(key==='time')return r.totalSeconds ?? r.gapSeconds ?? 9999999;
  if(key==='gap')return r.gapSeconds ?? 9999999;
  if(key==='secPerKm')return r.secPerKm ?? 9999999;
  return String(r[key]??'').toLowerCase();
}
function applySortToFiltered(){
  filtered.sort((a,b)=>{
    const av=sortValue(a,sortState.key), bv=sortValue(b,sortState.key);
    let cmp=(typeof av==='number'&&typeof bv==='number')?av-bv:String(av).localeCompare(String(bv),'es');
    return sortState.dir==='asc'?cmp:-cmp;
  });
}
function renderSortIndicators(){
  ['pos','bib','name','time','gap','secPerKm','cat','catPos','region','team'].forEach(k=>{const el=$('sort-'+k);if(el)el.textContent=sortState.key===k?(sortState.dir==='asc'?'↑':'↓'):'';});
}
function renderAll(){riders=enrichRiders(riders);filtered=filtered.map(fr=>riders.find(r=>r.pos===fr.pos&&r.bib===fr.bib&&r.name===fr.name)||fr);applySortToFiltered();renderStats();renderTable();renderTop10();renderTeamSummary();renderCharts();_notasLoad();renderCompare();renderTeamCategoryFilter();renderTeamTimeRanking();renderTeamComparison(false);renderTeamDupPanel();}
function updateRaceHeader(viewId){
  const el=$('raceHeader');
  if(!el) return;
  // Ocultar en Evolución (abarca toda la temporada, no una prueba concreta)
  const hideIn=['view-evolucion'];
  if(hideIn.includes(viewId||'')){el.classList.remove('visible');return;}
  const name=($('raceName')?.value||'').trim();
  if(!name||!riders.length){el.classList.remove('visible');return;}
  $('raceHeaderTitle').textContent=name;
  const date=formatDateDisplay(parseRaceDate(($('raceDate')?.value||'').trim()))||($('raceDate')?.value||'').trim();
  const km=($('raceKm')?.value||'').trim();
  const avg=($('raceAvg')?.value||'').trim();
  const loc=($('raceLocalidad')?.value||'').trim();
  const type=($('raceCircuitType')?.value||'').trim();
  const parts=[];
  if(date) parts.push('📅 '+date);
  if(loc)  parts.push('📍 '+escapeHtml(loc));
  if(km)   parts.push('📏 '+escapeHtml(km));
  if(avg)  parts.push('💨 '+escapeHtml(avg));
  if(type) parts.push('🔄 '+escapeHtml(type));
  const sep='<span class="race-header-sep">·</span>';
  $('raceHeaderMeta').innerHTML=parts.join(sep);
  el.classList.add('visible');
}

function renderStats(){
  $('totalRiders').textContent=riders.length;
  $('totalTeams').textContent=new Set(riders.map(r=>r.team).filter(Boolean)).size;
  $('totalCats').textContent=new Set(riders.map(r=>r.cat).filter(Boolean)).size;
  const w=riders.find(r=>r.pos===1)||riders[0];
  $('winner').textContent=w?`${w.name}${w.team?' · '+w.team:''}${w.time?' · '+w.time:''}`:'—';
  // ===== BLOQUE 1: KPIs Mi Equipo (Fase 2 no-bloqueo) =====
  // Si hay equipo: mostramos KPIs del equipo. Si NO hay equipo: mostramos KPIs
  // globales de la prueba (mejor de la carrera, equipos distintos en top 10,
  // spread global del top 3) y añadimos un chip discreto invitando a configurar.
  const kpiSection = document.getElementById('myTeamKpis');
  if(riders.length && kpiSection){
    kpiSection.style.display = 'grid';
    const sortedAll = [...riders].sort((a,b)=>a.pos-b.pos);
    if(myTeam){
      const myRiders = riders.filter(r=>isMyTeam(r)).sort((a,b)=>a.pos-b.pos);
      if(myRiders.length){
        const best = myRiders[0];
        $('kpiMyBest') && ($('kpiMyBest').textContent = best.pos + 'º — ' + best.name);
        const top10teams = new Set(riders.filter(r=>r.pos<=10 && !isMyTeam(r)).map(r=>r.team));
        $('kpiRivals') && ($('kpiRivals').textContent = top10teams.size + ' equipos distintos');
        const spread = myRiders.length>=3 ? myRiders[2].pos - myRiders[0].pos : (myRiders.length>1 ? myRiders[myRiders.length-1].pos - myRiders[0].pos : null);
        const spreadEl = $('kpiSpread');
        if(spreadEl){
          if(spread===null){ spreadEl.textContent='— (pocos datos)'; }
          else { spreadEl.textContent = spread + ' posiciones'; spreadEl.className = 'value ' + (spread<=8?'spread-low':spread<=20?'spread-mid':'spread-high'); }
        }
      } else {
        $('kpiMyBest') && ($('kpiMyBest').textContent = '— no clasificado');
        $('kpiRivals') && ($('kpiRivals').textContent = '—');
        $('kpiSpread') && ($('kpiSpread').textContent = '—');
      }
    } else {
      // Sin equipo: KPIs globales de la prueba
      const winner = sortedAll[0];
      $('kpiMyBest') && winner && ($('kpiMyBest').textContent = '1º — ' + winner.name + (winner.team?' ('+winner.team+')':''));
      const top10TeamsAll = new Set(sortedAll.slice(0,10).map(r=>r.team).filter(Boolean));
      $('kpiRivals') && ($('kpiRivals').textContent = top10TeamsAll.size + ' equipos en Top 10');
      // Spread = diferencia entre mejor y 3er clasificado overall (informativo)
      const sp = sortedAll.length>=3 ? sortedAll[2].pos - sortedAll[0].pos : null;
      const spreadEl = $('kpiSpread');
      if(spreadEl){
        if(sp===null){ spreadEl.textContent='— (pocos datos)'; }
        else { spreadEl.textContent = sp + ' posiciones (Top 3 global)'; spreadEl.className='value spread-low'; }
      }
      // Etiquetas más informativas en modo global (modificamos los labels)
      const labels = kpiSection.querySelectorAll('.label');
      if(labels[0]) labels[0].textContent = '🟢 Ganador';
      if(labels[1]) labels[1].textContent = '👥 Top 10';
      if(labels[2]) labels[2].textContent = '📏 Spread Top 3';
      // Chip discreto invitando a configurar Mi Equipo
      if(!document.getElementById('kpiNoTeamChip')){
        const chip = document.createElement('div');
        chip.id = 'kpiNoTeamChip';
        chip.style.cssText='grid-column:1/-1;background:#fef3c7;border:1px solid #fcd34d;color:#78350f;border-radius:8px;padding:6px 10px;font-size:11.5px;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px;margin-top:-4px';
        chip.title='Configurar Mi Equipo';
        chip.onclick=()=>{ document.getElementById('gfMyTeam')?.focus(); };
        chip.innerHTML='⚙️ Mostrando KPIs GLOBALES de esta prueba. <span style="text-decoration:underline">Configura tu equipo</span> para ver los KPIs específicos del tuyo.';
        kpiSection.appendChild(chip);
      }
    }
    // Si hay equipo, quitar el chip si existía
    if(myTeam){
      const chip = document.getElementById('kpiNoTeamChip');
      if(chip) chip.remove();
      // Restaurar etiquetas originales
      const labels = kpiSection.querySelectorAll('.label');
      if(labels[0]) labels[0].textContent = '🟢 Mejor puesto (mi equipo)';
      if(labels[1]) labels[1].textContent = '⚠️ Equipos rivales en Top 10';
      if(labels[2]) labels[2].textContent = '📏 Spread mi equipo';
    }
  } else if(kpiSection){
    kpiSection.style.display = 'none';
  }
  // Actualizar banner de prueba activa
  const activeView=document.querySelector('.spa-view.active');
  updateRaceHeader(activeView?activeView.id:'');
}
function renderTable(){
  // Propagar CCAA dentro de cada equipo en cada render (red de seguridad)
  if(typeof inferRegionsFromTeam==='function'){ inferRegionsFromTeam(riders); }
  renderSortIndicators();
  $('shownCount').textContent=filtered.length+' corredores mostrados';
  $('resultsBody').innerHTML=filtered.length?filtered.map((r,idx)=>{
    const checked=selectedCompare.some(x=>x.pos===r.pos&&x.bib===r.bib&&x.name===r.name)?'checked':'';
    const gapText=formatSeconds(r.gapSeconds);
    const timeText=formatHMS(r.totalSeconds);
    const isOwnTeam = isMyTeam(r);
    
    // Medallas (Absolutas y por Categoría)
    let medal = '';
    if(r.pos===1) medal='🥇'; else if(r.pos===2) medal='🥈'; else if(r.pos===3) medal='🥉';
    else if(r.catPos===1) medal='🥇'; else if(r.catPos===2) medal='🥈'; else if(r.catPos===3) medal='🥉';
    
    const rkey=escapeAttr(getRiderKey(r));
    return `<tr data-rkey="${rkey}" onclick="selectAndAnalyzeRiderByKey('${rkey}')" class="${isOwnTeam?'my-team-row':''}" style="cursor:pointer">
      <td onclick="event.stopPropagation()" style="text-align:center;padding:4px">
        <button class="edit-btn" onclick="editTableRow('${rkey}')" title="Editar fila">✏️</button>
      </td>
      <td><b>${medal}${r.pos}º</b></td>
      <td>${r.bib}</td>
      <td>${escapeHtml(r.name)}${isOwnTeam?' <small>(Mi Equipo)</small>':''}</td>
      <td>${timeText}</td>
      <td>${gapText}</td>
      <td>${r.secPerKm!=null?r.secPerKm.toFixed(1):'—'}</td>
      <td><span class="pill"><span class="cat-dot" style="background:${getColorForCategory(r.cat)}"></span>${escapeHtml(r.cat)}</span></td>
      <td class="pos-cat-val">${r.catPos}º</td>
      <td>${escapeHtml(r.region||'—')}</td>
      <td>${escapeHtml(r.team)}</td>
    </tr>`;
  }).join(''):'<tr><td colspan="11" class="empty">No hay resultados con esos filtros.</td></tr>';
}

// ─── Edición inline de filas ──────────────────────────────────────────────────
let _editingRowKey=null;

function editTableRow(key){
  // Si ya hay otra fila en edición, cancelarla primero
  if(_editingRowKey && _editingRowKey!==key) cancelTableRowEdit(_editingRowKey);
  _editingRowKey=key;

  const r=filtered.find(x=>getRiderKey(x)===key);
  if(!r) return;

  const rowEl=document.querySelector(`tr[data-rkey="${CSS.escape(key)}"]`);
  if(!rowEl) return;

  const isOwnTeam=isMyTeam(r);
  rowEl.className='row-editing'+(isOwnTeam?' my-team-row':'');
  rowEl.removeAttribute('onclick');

  rowEl.innerHTML=`
    <td onclick="event.stopPropagation()" style="white-space:nowrap;text-align:center">
      <button class="save-row-btn" onclick="saveTableRowEdit('${escapeAttr(key)}')" title="Guardar cambios">✓</button>
      <button class="cancel-row-btn" onclick="cancelTableRowEdit('${escapeAttr(key)}')" title="Cancelar">✗</button>
      <button onclick="deleteTableRow('${escapeAttr(key)}')" title="Eliminar este resultado de la base de datos" style="background:#fee2e2;color:#dc2626;border:1px solid #fca5a5;border-radius:6px;padding:3px 7px;font-weight:800;font-size:12px;cursor:pointer;margin-left:4px">🗑️</button>
    </td>
    <td><input class="edit-input" id="eri-pos" type="number" value="${r.pos}" style="width:42px"></td>
    <td><input class="edit-input" id="eri-bib" type="number" value="${r.bib}" style="width:48px"></td>
    <td><input class="edit-input" id="eri-name" value="${escapeAttr(r.name)}" style="width:150px"></td>
    <td><input class="edit-input" id="eri-time" value="${escapeAttr(r.time||formatSeconds(r.totalSeconds)||'')}" style="width:68px" placeholder="h:mm:ss"></td>
    <td><input class="edit-input" id="eri-gap" value="${escapeAttr(formatSeconds(r.gapSeconds)||'')}" style="width:60px" placeholder="h:mm:ss"></td>
    <td style="color:#999;font-size:11px;text-align:center">${r.secPerKm!=null?r.secPerKm.toFixed(1):'—'}</td>
    <td><input class="edit-input" id="eri-cat" value="${escapeAttr(r.cat||'')}" style="width:62px"></td>
    <td><input class="edit-input" id="eri-catpos" type="number" value="${r.catPos||''}" style="width:42px"></td>
    <td><input class="edit-input" id="eri-region" value="${escapeAttr(r.region||'')}" style="width:68px" placeholder="CCAA"></td>
    <td><input class="edit-input" id="eri-team" value="${escapeAttr(r.team||'')}" style="width:130px"></td>
  `;
  // Focus en CCAA que es el campo más frecuente a corregir
  setTimeout(()=>{ const el=$('eri-region'); if(el){el.focus();el.select();} },50);
}

async function saveTableRowEdit(key){
  const r=riders.find(x=>getRiderKey(x)===key);
  const rf=filtered.find(x=>getRiderKey(x)===key);
  if(!r){ cancelTableRowEdit(key); return; }

  const oldRegion=(r.region||'').trim();
  const oldName=(r.name||'').trim();
  const oldCat=(r.cat||'').trim();

  const newPos   =parseInt($('eri-pos')?.value)||r.pos;
  const newBib   =parseInt($('eri-bib')?.value)||r.bib;
  const newName  =($('eri-name')?.value||'').trim()||r.name;
  const newTime  =($('eri-time')?.value||'').trim();
  const newCat   =($('eri-cat')?.value||'').trim()||r.cat;
  const newCatPos=parseInt($('eri-catpos')?.value)||r.catPos;
  const newRegion=($('eri-region')?.value||'').trim();
  const newTeam  =($('eri-team')?.value||'').trim()||r.team;

  // Calcular gapSeconds desde el campo tiempo/gap si ha cambiado
  const fields={pos:newPos,bib:newBib,name:newName,cat:newCat,catPos:newCatPos,region:newRegion,team:newTeam};
  if(newTime) fields.time=newTime;

  Object.assign(r,fields);
  if(rf) Object.assign(rf,fields);

  // ── Propagar CCAA a TODOS los riders del mismo equipo en esta carrera ──
  const regionChanged=newRegion && newRegion!==oldRegion;
  let teamPropagatedCount=0;
  if(regionChanged && newTeam){
    const teamKey=newTeam.trim().toLowerCase();
    riders.forEach(other=>{
      if(other===r) return;
      if((other.team||'').trim().toLowerCase()===teamKey && (other.region||'')!==newRegion){
        other.region=newRegion;
        teamPropagatedCount++;
      }
    });
    filtered.forEach(other=>{
      if(other===rf) return;
      if((other.team||'').trim().toLowerCase()===teamKey) other.region=newRegion;
    });
  }

  _editingRowKey=null;
  // Si cambió la CCAA, invalidar la DB global de team→region para que se rebuild
  if(regionChanged && typeof invalidateTeamRegionDB==='function') invalidateTeamRegionDB();
  // Usar renderAll para que enrichRiders → inferRegionsFromTeam se ejecute
  if(typeof renderAll==='function') renderAll(); else { renderTable(); renderStats(); }

  console.log('[CCAA edit]', {oldRegion, newRegion, regionChanged, newTeam, teamPropagatedCount});

  if(teamPropagatedCount>0){
    // Toast visible al usuario
    try{
      const t=document.createElement('div');
      t.style.cssText='position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#10b981;color:#fff;padding:12px 18px;border-radius:10px;font-weight:700;box-shadow:0 6px 18px rgba(0,0,0,.25);z-index:99999;font-size:14px';
      t.textContent=`✓ CCAA "${newRegion}" aplicada a ${teamPropagatedCount} compañero(s) de "${newTeam}"`;
      document.body.appendChild(t);
      setTimeout(()=>t.remove(),3500);
    }catch(_){}
  }

  // ── Propagar cambio de CCAA a todo el historial ──────────────────────────
  if(regionChanged){
    const extraMsg=teamPropagatedCount>0 ? `\n\n(También se ha aplicado a ${teamPropagatedCount} compañero(s) del mismo equipo "${newTeam}" en esta carrera.)` : '';
    // Pequeño delay para que el render termine antes del confirm
    await new Promise(res=>setTimeout(res,100));
    const ok=confirm(
      `CCAA modificada: "${oldRegion||'(vacío)'}" → "${newRegion}"\n\n`+
      `¿Aplicar este cambio a TODAS las pruebas de "${newName}" guardadas en el historial?\n\n`+
      `Esto actualizará los registros en Supabase.${extraMsg}`
    );
    if(ok) await propagateRegionChange(newName,newRegion);
  }

  // ── Propagar cambio de CATEGORÍA del rider a todo el historial ───────────
  const catChanged = newCat && newCat !== oldCat;
  if(catChanged){
    const raceYear = (typeof _getRaceYear==='function' ? _getRaceYear() : new Date().getFullYear());
    // 1) Guardar override LOCAL (instantáneo: getRiderCorrectCat lo lee en todas las vistas)
    try{
      const overrides = (typeof _loadRiderCatOverrides==='function' ? _loadRiderCatOverrides() : []);
      const nameKey = newName.trim().toLowerCase();
      const cleaned = overrides.filter(o =>
        !(o.riderName.trim().toLowerCase() === nameKey && parseInt(o.year) === raceYear)
      );
      cleaned.push({riderName:newName, year:raceYear, correctCat:newCat});
      if(typeof _saveRiderCatOverrides==='function') _saveRiderCatOverrides(cleaned);
    }catch(e){ console.warn('No se pudo guardar override local de categoría', e); }

    // 2) Toast visible
    try{
      const t=document.createElement('div');
      t.style.cssText='position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#0b2f6b;color:#fff;padding:12px 18px;border-radius:10px;font-weight:700;box-shadow:0 6px 18px rgba(0,0,0,.25);z-index:99999;font-size:14px';
      t.textContent=`✓ Categoría "${newCat}" guardada para "${newName}" (${raceYear})`;
      document.body.appendChild(t);
      setTimeout(()=>t.remove(),3500);
    }catch(_){}

    // 3) Ofrecer propagación a Supabase
    await new Promise(res=>setTimeout(res,200));
    const okCat = confirm(
      `Categoría modificada: "${oldCat||'(vacío)'}" → "${newCat}"\n\n`+
      `¿Aplicar este cambio a TODAS las pruebas de "${newName}" del año ${raceYear} guardadas en el historial?\n\n`+
      `Se actualizarán los registros en Supabase para que el cambio sea permanente y se vea en todos los dispositivos.`
    );
    if(okCat) await propagateCategoryChange(newName, raceYear, newCat);
  }
}

// ─── Propagación global de CATEGORÍA del rider ────────────────────────────
async function propagateCategoryChange(riderName, year, newCat){
  if(!_sb){ alert('Supabase no disponible — el cambio está guardado solo localmente.'); return; }
  if(typeof showLoading==='function') showLoading('Actualizando historial…',`Aplicando categoría "${newCat}" a "${riderName}" (${year}).`);
  try{
    const {data:races,error}=await _sb
      .from('races')
      .select('id, date, race_results(id, name, cat)')
      .eq('race_type','clasificacion');
    if(error) throw error;

    const normTarget = normalizeForMatching(riderName);
    let updated = 0;
    for(const race of (races||[])){
      const raceYear = (race.date||'').slice(0,4);
      if(year && String(raceYear) !== String(year)) continue;
      for(const rr of (race.race_results||[])){
        if(normalizeForMatching(rr.name) !== normTarget) continue;
        if((rr.cat||'') === newCat) continue;
        const {error:updErr} = await _sb.from('race_results').update({cat:newCat}).eq('id', rr.id);
        if(!updErr) updated++;
      }
    }
    _cachedHistory = null;
    if(typeof invalidateTeamRegionDB==='function') invalidateTeamRegionDB();
    if(typeof hideLoading==='function') hideLoading();
    alert(`✅ Categoría "${newCat}" aplicada a "${riderName}" en ${updated} resultado(s) del historial (${year}).`);
  }catch(e){
    if(typeof hideLoading==='function') hideLoading();
    alert('Error al actualizar la categoría en el historial: '+(e.message||e));
    console.error(e);
  }
}

function cancelTableRowEdit(key){
  _editingRowKey=null;
  renderTable();
}

// Borra el resultado individual de la BD (race_results) y refresca la tabla.
// Útil para eliminar entradas duplicadas (mismo corredor figurando en 2 teams
// distintos en la misma prueba — bug de carga de clasificaciones).
async function deleteTableRow(key){
  const r = riders.find(x=>getRiderKey(x)===key);
  if(!r){ cancelTableRowEdit(key); return; }
  if(!r.id){
    alert('Este resultado no tiene ID en la base de datos (puede ser una carga local sin guardar). No se puede borrar.');
    return;
  }
  if(!confirm(`¿Eliminar este resultado DEFINITIVAMENTE de la base de datos?\n\n` +
              `Corredor: ${r.name}\nDorsal: ${r.bib}\nPos: ${r.pos}\nEquipo: ${r.team||'—'}\n\n` +
              `Esta acción NO se puede deshacer.`)) return;
  if(!_sb){ alert('Supabase no disponible.'); return; }
  try{
    const {error} = await _sb.from('race_results').delete().eq('id', r.id);
    if(error) throw error;
    // Quitar del estado local
    riders = riders.filter(x=>x!==r);
    filtered = filtered.filter(x=>getRiderKey(x)!==key);
    _editingRowKey = null;
    _cachedHistory = null; // invalidar caché
    if(typeof invalidateTeamRegionDB==='function') invalidateTeamRegionDB();
    if(typeof renderAll==='function') renderAll();
    // Pequeño toast de confirmación
    try{
      const t=document.createElement('div');
      t.style.cssText='position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#10b981;color:#fff;padding:12px 18px;border-radius:10px;font-weight:700;box-shadow:0 6px 18px rgba(0,0,0,.25);z-index:99999;font-size:14px';
      t.textContent=`🗑️ Resultado de "${r.name}" eliminado correctamente`;
      document.body.appendChild(t);
      setTimeout(()=>t.remove(),3500);
    }catch(_){}
  }catch(e){
    console.error(e);
    alert('Error borrando el resultado: '+(e.message||String(e)));
  }
}

// ─── Propagación global de CCAA ──────────────────────────────────────────────
async function propagateRegionChange(riderName, newRegion){
  if(!_sb){ alert('Supabase no disponible.'); return; }
  showLoading('Actualizando historial…',`Aplicando CCAA "${newRegion}" a "${riderName}" en todas las pruebas.`);

  try{
    // Traer todas las carreras con notes y race_results (solo nombre)
    const {data:races,error}=await _sb
      .from('races')
      .select('id, notes, race_results(name)')
      .eq('race_type','clasificacion');
    if(error) throw error;

    const normTarget=normalizeForMatching(riderName);
    let updated=0;

    for(const race of (races||[])){
      let extra={};
      try{ extra=JSON.parse(race.notes||'{}'); }catch(e){}
      const regions=extra.regions||{};

      // Buscar claves existentes que coincidan con el ciclista
      let changed=false;
      for(const k of Object.keys(regions)){
        if(normalizeForMatching(k)===normTarget){
          regions[k]=newRegion;
          changed=true;
        }
      }

      // Si el ciclista aparece en race_results pero no tiene región → añadirla
      const appearsInRace=(race.race_results||[]).some(rr=>normalizeForMatching(rr.name)===normTarget);
      if(appearsInRace && !changed){
        // Buscar la clave exacta del nombre en race_results para mantener coherencia
        const rawName=(race.race_results||[]).find(rr=>normalizeForMatching(rr.name)===normTarget)?.name||riderName;
        regions[rawName]=newRegion;
        changed=true;
      }

      if(changed){
        extra.regions=regions;
        const {error:updErr}=await _sb.from('races').update({notes:JSON.stringify(extra)}).eq('id',race.id);
        if(!updErr) updated++;
      }
    }

    _cachedHistory=null; _prFiltersReady=false; _prSelectedCats=new Set(); _trendFiltersReady=false; // invalidar caché
    hideLoading();
    alert(`✅ CCAA "${newRegion}" aplicada a "${riderName}" en ${updated} prueba${updated!==1?'s':''} del historial.`);

  }catch(e){
    hideLoading();
    alert('Error al actualizar el historial: '+(e.message||e));
  }
}

// ═════════════════════════════════════════════════════════════════════
// VISTA "Equipos y CCAA" — gestión coherente de comunidad autónoma
// por equipo. Detecta el equipo en TODOS los race_results del histórico,
// agrupa por nombre, calcula la CCAA dominante de sus corredores y
// permite fijar una CCAA canónica que se propaga a TODAS las pruebas.
// ═════════════════════════════════════════════════════════════════════
let _eqCcaaData = []; // [{team, riders:Set, regionCounts:Map, races:Set, totalRows}]

async function _eqCcaaInit(){
  const box = document.getElementById('eqCcaaTable');
  const sum = document.getElementById('eqCcaaSummary');
  if(!_sb){
    if(box) box.innerHTML = `<div style="padding:24px;text-align:center;color:#dc2626;font-weight:700">Supabase no disponible.</div>`;
    return;
  }
  if(box) box.innerHTML = `<div style="padding:30px;text-align:center;color:#6b7280">⏳ Cargando histórico…</div>`;
  if(sum) sum.textContent = '';

  try{
    const {data:races, error} = await _sb
      .from('races')
      .select('id, notes, race_results(name, team)')
      .eq('race_type','clasificacion');
    if(error) throw error;

    // Agregar: team → {riders, regionCounts, races, totalRows}
    const agg = new Map();
    for(const race of (races||[])){
      let extra = {};
      try{ extra = JSON.parse(race.notes||'{}'); }catch(_){}
      const regions = extra.regions||{};
      // Normalizar nombres de region para conteo coherente
      const canon = typeof canonicalRegion==='function' ? canonicalRegion : (s=>s);
      for(const rr of (race.race_results||[])){
        const team = (rr.team||'').trim();
        if(!team) continue;
        const rider = (rr.name||'').trim();
        // Buscar región de este corredor en notes.regions (busca por nombre normalizado)
        let region = '';
        if(regions[rider]) region = regions[rider];
        else {
          const normR = typeof normalizeForMatching==='function' ? normalizeForMatching(rider) : rider.toLowerCase();
          for(const k of Object.keys(regions)){
            const nk = typeof normalizeForMatching==='function' ? normalizeForMatching(k) : k.toLowerCase();
            if(nk===normR){ region = regions[k]; break; }
          }
        }
        region = (region||'').trim();
        if(region) region = canon(region);

        if(!agg.has(team)) agg.set(team, {team, riders:new Set(), regionCounts:new Map(), races:new Set(), totalRows:0});
        const a = agg.get(team);
        a.riders.add(rider);
        a.races.add(race.id);
        a.totalRows++;
        if(region){
          a.regionCounts.set(region, (a.regionCounts.get(region)||0) + 1);
        }
      }
    }

    _eqCcaaData = [...agg.values()].map(a=>{
      const counts = [...a.regionCounts.entries()].sort((x,y)=>y[1]-x[1]);
      const dominant = counts[0]?.[0] || '';
      const distinctRegions = counts.length;
      const hasConflict = distinctRegions > 1;
      const missing = distinctRegions === 0;
      return {...a, dominant, distinctRegions, hasConflict, missing, counts};
    });
    // Orden: conflictos primero, luego missing, luego alfabético
    _eqCcaaData.sort((a,b)=>{
      if(a.hasConflict !== b.hasConflict) return a.hasConflict ? -1 : 1;
      if(a.missing !== b.missing) return a.missing ? -1 : 1;
      return a.team.localeCompare(b.team);
    });

    _eqCcaaRender();
  }catch(e){
    console.error(e);
    if(box) box.innerHTML = `<div style="padding:24px;text-align:center;color:#dc2626;font-weight:700">Error cargando: ${escapeHtml(e.message||String(e))}</div>`;
  }
}

function _eqCcaaRender(){
  const box = document.getElementById('eqCcaaTable');
  const sum = document.getElementById('eqCcaaSummary');
  if(!box) return;
  const q = (document.getElementById('eqCcaaSearch')?.value || '').toLowerCase().trim();
  const onlyProblems = document.getElementById('eqCcaaOnlyProblems')?.checked;

  let data = _eqCcaaData;
  if(q) data = data.filter(d=>d.team.toLowerCase().includes(q));
  if(onlyProblems) data = data.filter(d=>d.hasConflict || d.missing);

  // CCAA disponibles del histórico para el dropdown
  const allRegions = new Set();
  for(const d of _eqCcaaData){ for(const [r] of d.counts) allRegions.add(r); }
  const sortedRegions = [...allRegions].sort();

  // Resumen
  if(sum){
    const totalTeams = _eqCcaaData.length;
    const nConflict = _eqCcaaData.filter(d=>d.hasConflict).length;
    const nMissing  = _eqCcaaData.filter(d=>d.missing).length;
    sum.textContent = `${data.length}/${totalTeams} equipos · ⚠️ ${nConflict} conflictos · ❌ ${nMissing} sin CCAA`;
  }

  if(!data.length){
    box.innerHTML = `<div style="padding:30px;text-align:center;color:#6b7280">No hay equipos que coincidan con los filtros.</div>`;
    return;
  }

  box.innerHTML = `<div style="background:#fff;border-radius:10px;overflow:hidden;border:1px solid #e5e7eb;overflow-x:auto">
    <table style="width:100%;border-collapse:collapse;font-size:13px;table-layout:fixed">
      <colgroup>
        <col style="width:22%">
        <col style="width:6%">
        <col style="width:6%">
        <col style="width:25%">
        <col style="width:22%">
        <col style="width:9%">
        <col style="width:10%">
      </colgroup>
      <thead style="background:#f8fafc">
        <tr>
          <th style="padding:10px 12px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#475569">Equipo</th>
          <th style="padding:10px 6px;text-align:center;font-size:11px;color:#475569" title="Número de corredores únicos en histórico">👥</th>
          <th style="padding:10px 6px;text-align:center;font-size:11px;color:#475569" title="Número de pruebas donde aparece el equipo">🏁</th>
          <th style="padding:10px 12px;text-align:left;font-size:11px;color:#475569">Distribución CCAA</th>
          <th style="padding:10px 12px;text-align:left;font-size:11px;color:#475569">Fijar CCAA</th>
          <th style="padding:10px 6px;text-align:left;font-size:11px;color:#475569">o nueva</th>
          <th style="padding:10px 6px;text-align:center;font-size:11px;color:#475569">Acción</th>
        </tr>
      </thead>
      <tbody>
        ${data.map((d,idx)=>{
          const rowBg = d.missing ? '#fef2f2' : (d.hasConflict ? '#fffbeb' : '#fff');
          const badge = d.missing
            ? `<span style="background:#fee2e2;color:#991b1b;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:800">❌ Sin CCAA</span>`
            : d.hasConflict
              ? `<span style="background:#fef3c7;color:#92400e;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:800">⚠️ Conflicto</span>`
              : `<span style="background:#dcfce7;color:#15803d;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:800">✓ OK</span>`;
          const dist = d.counts.length
            ? d.counts.map(([r,c])=>`<span style="background:#e0e7ff;color:#3730a3;padding:1px 7px;border-radius:6px;font-size:11px;font-weight:700;margin-right:4px;display:inline-block;margin-bottom:2px">${escapeHtml(r)}×${c}</span>`).join('')
            : '<span style="color:#9ca3af;font-size:11px">—</span>';
          const idAttr = `eqCcaaSel_${idx}`;
          const opts = ['<option value="">— elegir —</option>']
            .concat(sortedRegions.map(r=>`<option value="${escapeAttr(r)}" ${r===d.dominant?'selected':''}>${escapeHtml(r)}</option>`))
            .join('');
          return `<tr style="background:${rowBg};border-top:1px solid #f3f4f6">
            <td style="padding:10px 12px;font-weight:800;color:#0b2f6b;word-break:break-word">
              <span onclick="_eqCcaaShowTeamModal('${escapeAttr(d.team)}')" title="Ver corredores del equipo en el año actual" style="cursor:pointer;text-decoration:underline;text-underline-offset:3px;text-decoration-color:#84caff;text-decoration-thickness:2px">${escapeHtml(d.team)}</span>
              <div style="margin-top:3px">${badge}</div>
            </td>
            <td style="padding:10px 6px;text-align:center;font-weight:700;color:#475569">${d.riders.size}</td>
            <td style="padding:10px 6px;text-align:center;font-weight:700;color:#475569">${d.races.size}</td>
            <td style="padding:10px 12px">${dist}</td>
            <td style="padding:10px 8px">
              <select id="${idAttr}" style="width:100%;border:1.5px solid #c7d7f5;border-radius:7px;padding:6px 8px;font-size:12px;font-weight:700;background:#fff">${opts}</select>
            </td>
            <td style="padding:10px 6px">
              <input type="text" placeholder="nueva…" id="${idAttr}_custom" style="width:100%;border:1px solid #e5e7eb;border-radius:6px;padding:5px 8px;font-size:11px;box-sizing:border-box">
            </td>
            <td style="padding:10px 6px;text-align:center">
              <button onclick="_eqCcaaApplyTeam('${escapeAttr(d.team)}','${idAttr}')" style="background:#10b981;color:#fff;border:none;border-radius:7px;padding:7px 10px;font-weight:800;font-size:12px;cursor:pointer;white-space:nowrap">✓ Aplicar</button>
            </td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>
  </div>`;
}

async function _eqCcaaApplyTeam(team, selectId){
  const sel = document.getElementById(selectId);
  const customInp = document.getElementById(selectId+'_custom');
  const customVal = (customInp?.value||'').trim();
  const newRegion = customVal || sel?.value || '';
  if(!newRegion){ alert('Elige una CCAA del desplegable o escribe una nueva en el campo de texto.'); return; }
  if(!confirm(`¿Aplicar CCAA "${newRegion}" a todos los corredores del equipo "${team}" en TODAS las pruebas del histórico?\n\nEsto sobrescribirá cualquier valor previo.`)) return;

  // Encontrar el registro del equipo en _eqCcaaData
  const teamData = _eqCcaaData.find(d=>d.team===team);
  if(!teamData){ alert('Equipo no encontrado en los datos cargados.'); return; }

  // Snapshot de problemas ANTES del apply
  const beforeConflicts = _eqCcaaData.filter(d=>d.hasConflict).length;
  const beforeMissing = _eqCcaaData.filter(d=>d.missing).length;
  showLoading('Aplicando CCAA al equipo…', `Equipo: ${team} · CCAA: ${newRegion}`);
  try{
    const normTeam = (team||'').trim().toLowerCase();
    // Una sola consulta a la BD con todas las pruebas (incluye name/date para
    // que los mensajes de error sean comprensibles)
    const {data:races, error} = await _sb
      .from('races')
      .select('id, name, date, notes, race_results(name, team)')
      .eq('race_type','clasificacion');
    if(error) throw error;

    // Por cada prueba: para cada race_results cuya `team` coincida con el
    // equipo objetivo, fijar regions[name]=newRegion. PERO: si un mismo nombre
    // de corredor aparece en 2+ teams en la MISMA carrera (duplicación de
    // datos), NO se toca su región — porque regions[name] es compartido por
    // todos los teams en esa carrera y cambiarlo crearía conflictos en otros.
    let racesUpdated = 0, ridersUpdated = 0, racesWithErrors = 0, errorSamples = [];
    let ambiguousSkipped = 0, ambiguousSamples = [];
    for(const race of (races||[])){
      const matching = (race.race_results||[]).filter(rr=>(rr.team||'').trim().toLowerCase()===normTeam);
      if(!matching.length) continue;
      let extra = {};
      try{ extra = JSON.parse(race.notes||'{}'); }catch(_){}
      const regions = extra.regions||{};
      let changed = false;
      for(const rr of matching){
        const rider = (rr.name||'').trim();
        if(!rider) continue;
        const normTarget = typeof normalizeForMatching==='function' ? normalizeForMatching(rider) : rider.toLowerCase();
        // ¿Aparece este mismo rider también con OTRO team en la misma carrera?
        const inOtherTeams = (race.race_results||[]).some(other=>{
          if(other===rr) return false;
          const oRider = (other.name||'').trim();
          const oTeam = (other.team||'').trim().toLowerCase();
          if(oTeam===normTeam) return false; // mismo team, no es ambiguo
          if(!oTeam) return false;
          const oNorm = typeof normalizeForMatching==='function' ? normalizeForMatching(oRider) : oRider.toLowerCase();
          return oNorm===normTarget;
        });
        if(inOtherTeams){
          ambiguousSkipped++;
          if(ambiguousSamples.length<5){
            // Capturar el otro team con el que está duplicado para mostrarlo
            const otherRow = (race.race_results||[]).find(other=>{
              if(other===rr) return false;
              const oTeam = (other.team||'').trim().toLowerCase();
              if(oTeam===normTeam || !oTeam) return false;
              const oNorm = typeof normalizeForMatching==='function' ? normalizeForMatching((other.name||'').trim()) : (other.name||'').trim().toLowerCase();
              return oNorm===normTarget;
            });
            const otherTeamName = (otherRow?.team||'?').trim();
            const dateStr = (race.date||'').slice(0,10);
            const raceName = (race.name||'').slice(0,40);
            ambiguousSamples.push(`• ${rider}\n   ↳ Prueba: ${raceName} (${dateStr})\n   ↳ Duplicado en team: ${otherTeamName}`);
          }
          continue; // no tocar — su región es compartida y romperíamos otros teams
        }
        // Buscar entrada existente (por nombre exacto o normalizado) y actualizarla
        let found = false;
        for(const k of Object.keys(regions)){
          const nk = typeof normalizeForMatching==='function' ? normalizeForMatching(k) : k.toLowerCase();
          if(nk===normTarget){
            if(regions[k]!==newRegion){ regions[k] = newRegion; changed = true; }
            found = true;
          }
        }
        // Si no había entrada previa para este corredor en esta prueba, crearla
        if(!found){
          regions[rider] = newRegion;
          changed = true;
        }
        ridersUpdated++;
      }
      if(changed){
        extra.regions = regions;
        const {error:updErr} = await _sb.from('races').update({notes:JSON.stringify(extra)}).eq('id', race.id);
        if(updErr){
          racesWithErrors++;
          if(errorSamples.length<3) errorSamples.push(`race id ${race.id}: ${updErr.message}`);
        } else {
          racesUpdated++;
        }
      }
    }
    _cachedHistory = null;
    if(typeof invalidateTeamRegionDB==='function') invalidateTeamRegionDB();
    hideLoading();
    let msg = `✅ CCAA "${newRegion}" aplicada al equipo "${team}":\n` +
              `• ${racesUpdated} prueba(s) actualizadas\n` +
              `• ${ridersUpdated} resultado(s) de corredor afectados`;
    if(racesWithErrors){
      msg += `\n\n⚠️ ${racesWithErrors} prueba(s) NO se pudieron actualizar (posible RLS o permisos):\n` + errorSamples.join('\n');
    }
    if(racesUpdated===0 && !racesWithErrors){
      msg += `\n\n⚠️ No se actualizó ninguna prueba. Posibles causas:\n` +
             `• El equipo ya tenía esa CCAA en todas las pruebas.\n` +
             `• El nombre del equipo no coincide exactamente con lo guardado.`;
    }
    if(ambiguousSkipped){
      msg += `\n\n🟠 ${ambiguousSkipped} corredor(es) saltado(s) por estar duplicados con otro equipo en la misma carrera. Su CCAA NO se ha cambiado para no romper otros equipos. Ejemplos:\n` + ambiguousSamples.join('\n') +
             `\n\nDebes corregir manualmente esos duplicados (un mismo corredor figura en 2 teams en la misma prueba).`;
    }
    console.log('[CCAA] resultado apply:', {team, newRegion, racesUpdated, ridersUpdated, racesWithErrors, errorSamples});
    // Pausa breve antes de recargar para que Supabase consolide los UPDATE
    // antes del próximo SELECT (evita ver datos pre-update).
    await new Promise(r=>setTimeout(r,500));
    await _eqCcaaInit();
    const afterConflicts = _eqCcaaData.filter(d=>d.hasConflict).length;
    const afterMissing = _eqCcaaData.filter(d=>d.missing).length;
    msg += `\n\n📊 Conteo de problemas:\n` +
           `• Conflictos: ${beforeConflicts} → ${afterConflicts}\n` +
           `• Sin CCAA: ${beforeMissing} → ${afterMissing}`;
    alert(msg);
  }catch(e){
    hideLoading();
    console.error(e);
    alert('Error aplicando la CCAA al equipo: '+(e.message||String(e)));
  }
}

// ═════════════════════════════════════════════════════════════════════
// VISTA "Categorías por ciclista" — gestión coherente de categoría por
// corredor y año. Detecta a todos los ciclistas del año seleccionado,
// agrupa por nombre, calcula la categoría dominante y permite fijar una
// canónica que se propaga a TODAS las pruebas del año vía
// propagateCategoryChange.
// ═════════════════════════════════════════════════════════════════════
let _riderCatData = []; // [{name, catCounts:Map, races:Set, totalRows, dominant, hasConflict, missing, counts}]
let _riderCatYear = '';

async function _riderCatInit(){
  const box = document.getElementById('riderCatTable');
  const sum = document.getElementById('riderCatSummary');
  if(!_sb){
    if(box) box.innerHTML = `<div style="padding:24px;text-align:center;color:#dc2626;font-weight:700">Supabase no disponible.</div>`;
    return;
  }
  // El año se toma de los filtros globales; si no hay, usar el actual
  _riderCatYear = (_globalFilters?.year || String(new Date().getFullYear()));
  if(box) box.innerHTML = `<div style="padding:30px;text-align:center;color:#6b7280">⏳ Cargando ciclistas del año ${_riderCatYear}…</div>`;
  if(sum) sum.textContent = '';

  try{
    const {data:races, error} = await _sb
      .from('races')
      .select('id, date, race_results(name, cat)')
      .eq('race_type','clasificacion');
    if(error) throw error;

    const yearStr = String(_riderCatYear);
    // Agregar por nombre normalizado
    const agg = new Map();
    for(const race of (races||[])){
      const ry = (race.date||'').slice(0,4);
      if(ry !== yearStr) continue;
      for(const rr of (race.race_results||[])){
        const name = (rr.name||'').trim();
        if(!name) continue;
        const nk = typeof normalizeForMatching==='function' ? normalizeForMatching(name) : name.toLowerCase();
        if(!agg.has(nk)) agg.set(nk, {name, nk, catCounts:new Map(), races:new Set(), totalRows:0, displayName:name});
        const a = agg.get(nk);
        // Preferir el nombre con tildes/casing original si es más largo
        if(name.length > (a.displayName||'').length) a.displayName = name;
        a.races.add(race.id);
        a.totalRows++;
        const cat = (rr.cat||'').trim();
        if(cat) a.catCounts.set(cat, (a.catCounts.get(cat)||0)+1);
      }
    }

    _riderCatData = [...agg.values()].map(a=>{
      const counts = [...a.catCounts.entries()].sort((x,y)=>y[1]-x[1]);
      const dominant = counts[0]?.[0] || '';
      const distinct = counts.length;
      const hasConflict = distinct > 1;
      const missing = distinct === 0;
      return {...a, dominant, distinct, hasConflict, missing, counts};
    });
    _riderCatData.sort((a,b)=>{
      if(a.hasConflict !== b.hasConflict) return a.hasConflict ? -1 : 1;
      if(a.missing !== b.missing) return a.missing ? -1 : 1;
      return a.displayName.localeCompare(b.displayName);
    });

    _riderCatRender();
  }catch(e){
    console.error(e);
    if(box) box.innerHTML = `<div style="padding:24px;text-align:center;color:#dc2626;font-weight:700">Error cargando: ${escapeHtml(e.message||String(e))}</div>`;
  }
}

function _riderCatRender(){
  const box = document.getElementById('riderCatTable');
  const sum = document.getElementById('riderCatSummary');
  if(!box) return;
  const q = (document.getElementById('riderCatSearch')?.value || '').toLowerCase().trim();
  const onlyProblems = document.getElementById('riderCatOnlyProblems')?.checked;

  let data = _riderCatData;
  if(q) data = data.filter(d=>d.displayName.toLowerCase().includes(q));
  if(onlyProblems) data = data.filter(d=>d.hasConflict || d.missing);

  // Categorías disponibles del histórico para el dropdown
  const allCats = new Set();
  for(const d of _riderCatData){ for(const [c] of d.counts) allCats.add(c); }
  const sortedCats = [...allCats].sort();

  if(sum){
    const total = _riderCatData.length;
    const nConflict = _riderCatData.filter(d=>d.hasConflict).length;
    const nMissing  = _riderCatData.filter(d=>d.missing).length;
    sum.textContent = `${data.length}/${total} ciclistas · año ${_riderCatYear} · ⚠️ ${nConflict} conflictos · ❌ ${nMissing} sin categoría`;
  }

  if(!data.length){
    box.innerHTML = `<div style="padding:30px;text-align:center;color:#6b7280">No hay ciclistas que coincidan con los filtros.</div>`;
    return;
  }

  box.innerHTML = `<div style="background:#fff;border-radius:10px;overflow:hidden;border:1px solid #e5e7eb;overflow-x:auto">
    <table style="width:100%;border-collapse:collapse;font-size:13px;table-layout:fixed">
      <colgroup>
        <col style="width:24%">
        <col style="width:7%">
        <col style="width:25%">
        <col style="width:22%">
        <col style="width:12%">
        <col style="width:10%">
      </colgroup>
      <thead style="background:#f8fafc">
        <tr>
          <th style="padding:10px 12px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#475569">Ciclista</th>
          <th style="padding:10px 6px;text-align:center;font-size:11px;color:#475569" title="Número de pruebas en este año">🏁</th>
          <th style="padding:10px 12px;text-align:left;font-size:11px;color:#475569">Distribución categoría</th>
          <th style="padding:10px 12px;text-align:left;font-size:11px;color:#475569">Fijar categoría</th>
          <th style="padding:10px 6px;text-align:left;font-size:11px;color:#475569">o nueva</th>
          <th style="padding:10px 6px;text-align:center;font-size:11px;color:#475569">Acción</th>
        </tr>
      </thead>
      <tbody>
        ${data.map((d,idx)=>{
          const rowBg = d.missing ? '#fef2f2' : (d.hasConflict ? '#fffbeb' : '#fff');
          const badge = d.missing
            ? `<span style="background:#fee2e2;color:#991b1b;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:800">❌ Sin categoría</span>`
            : d.hasConflict
              ? `<span style="background:#fef3c7;color:#92400e;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:800">⚠️ Conflicto</span>`
              : `<span style="background:#dcfce7;color:#15803d;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:800">✓ OK</span>`;
          const dist = d.counts.length
            ? d.counts.map(([c,n])=>`<span style="background:#e0e7ff;color:#3730a3;padding:1px 7px;border-radius:6px;font-size:11px;font-weight:700;margin-right:4px;display:inline-block;margin-bottom:2px">${escapeHtml(c)}×${n}</span>`).join('')
            : '<span style="color:#9ca3af;font-size:11px">—</span>';
          const idAttr = `riderCatSel_${idx}`;
          const opts = ['<option value="">— elegir —</option>']
            .concat(sortedCats.map(c=>`<option value="${escapeAttr(c)}" ${c===d.dominant?'selected':''}>${escapeHtml(c)}</option>`))
            .join('');
          return `<tr style="background:${rowBg};border-top:1px solid #f3f4f6">
            <td style="padding:10px 12px;font-weight:800;color:#0b2f6b;word-break:break-word">
              ${escapeHtml(d.displayName)}
              <div style="margin-top:3px">${badge}</div>
            </td>
            <td style="padding:10px 6px;text-align:center;font-weight:700;color:#475569">${d.races.size}</td>
            <td style="padding:10px 12px">${dist}</td>
            <td style="padding:10px 8px">
              <select id="${idAttr}" style="width:100%;border:1.5px solid #c7d7f5;border-radius:7px;padding:6px 8px;font-size:12px;font-weight:700;background:#fff">${opts}</select>
            </td>
            <td style="padding:10px 6px">
              <input type="text" placeholder="nueva…" id="${idAttr}_custom" style="width:100%;border:1px solid #e5e7eb;border-radius:6px;padding:5px 8px;font-size:11px;box-sizing:border-box">
            </td>
            <td style="padding:10px 6px;text-align:center">
              <button onclick="_riderCatApply('${escapeAttr(d.displayName)}','${idAttr}')" style="background:#10b981;color:#fff;border:none;border-radius:7px;padding:7px 10px;font-weight:800;font-size:12px;cursor:pointer;white-space:nowrap">✓ Aplicar</button>
            </td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>
  </div>`;
}

async function _riderCatApply(riderName, selectId){
  const sel = document.getElementById(selectId);
  const customInp = document.getElementById(selectId+'_custom');
  const customVal = (customInp?.value||'').trim();
  const newCat = customVal || sel?.value || '';
  if(!newCat){ alert('Elige una categoría del desplegable o escribe una nueva en el campo de texto.'); return; }
  if(!confirm(`¿Aplicar categoría "${newCat}" a "${riderName}" en TODAS las pruebas del año ${_riderCatYear}?\n\nEsto sobrescribirá cualquier valor previo.`)) return;

  const beforeConflicts = _riderCatData.filter(d=>d.hasConflict).length;
  const beforeMissing = _riderCatData.filter(d=>d.missing).length;
  try{
    // Reutilizamos la función existente que ya recorre el histórico y
    // actualiza race_results.cat para ese ciclista en ese año.
    await propagateCategoryChange(riderName, parseInt(_riderCatYear,10), newCat);
    // propagateCategoryChange ya muestra su propio alert; recargamos
    await new Promise(r=>setTimeout(r,500));
    await _riderCatInit();
    const afterConflicts = _riderCatData.filter(d=>d.hasConflict).length;
    const afterMissing = _riderCatData.filter(d=>d.missing).length;
    // Mensaje resumen extra de progreso
    try{
      const t=document.createElement('div');
      t.style.cssText='position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#10b981;color:#fff;padding:12px 18px;border-radius:10px;font-weight:700;box-shadow:0 6px 18px rgba(0,0,0,.25);z-index:99999;font-size:14px;white-space:pre-line';
      t.textContent=`📊 Conflictos: ${beforeConflicts} → ${afterConflicts} · Sin cat: ${beforeMissing} → ${afterMissing}`;
      document.body.appendChild(t);
      setTimeout(()=>t.remove(),4000);
    }catch(_){}
  }catch(e){
    console.error(e);
    alert('Error aplicando la categoría: '+(e.message||String(e)));
  }
}

// Modal con la plantilla del equipo en el año actual (corredores + categoría).
// Reutiliza _buildTeamRosterData y _openTeamRosterPDFWindow (mismo formato que
// usamos en Explorador de Clubes y Informe de Plantilla). Incluye filtro por
// categoría y ordenación por columna (clic en cabecera).
let _eqRosterState = null; // {teamName, year, data, sortKey, sortDir, catFilter}

async function _eqCcaaShowTeamModal(teamName){
  const year = (_globalFilters?.year || String(new Date().getFullYear()));
  const history = await _ensureHistory();
  const data = _buildTeamRosterData(history, teamName, year);
  _eqRosterState = { teamName, year, data, sortKey:'score', sortDir:'asc', catFilter:'' };

  const old = document.getElementById('_eqCcaaTeamDialog');
  if(old) old.remove();
  const overlay = document.createElement('div');
  overlay.id = '_eqCcaaTeamDialog';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.onclick = e=>{ if(e.target===overlay) overlay.remove(); };

  // Categorías únicas (orden alfabético) para el desplegable de filtro
  const allCats = [...new Set(data.riders.map(r=>r.cat||'').filter(Boolean))].sort();

  overlay.innerHTML = `
    <div style="background:#fff;border-radius:14px;max-width:1000px;width:100%;max-height:90vh;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.4)">
      <div style="background:linear-gradient(135deg,#0b2f6b,#1565c0);color:#fff;padding:16px 20px;display:flex;justify-content:space-between;align-items:center;gap:12px">
        <div style="flex:1;min-width:0">
          <div style="font-size:11px;opacity:.85;letter-spacing:.6px;text-transform:uppercase">Plantilla del equipo · ${escapeHtml(year)}</div>
          <div style="font-size:18px;font-weight:900;margin-top:2px">${escapeHtml(teamName)}</div>
          <div style="font-size:11px;opacity:.85;margin-top:3px">${data.riders.length} corredor(es) · ${data.totalRaces} prueba(s) · 🏆 ${data.teamWins} · 🥉 ${data.teamPodiums} · Top10: ${data.teamTop10}</div>
        </div>
        <button onclick="document.getElementById('_eqCcaaTeamDialog').remove()" style="background:rgba(255,255,255,.18);color:#fff;border:none;border-radius:8px;width:32px;height:32px;font-size:18px;font-weight:800;cursor:pointer;flex-shrink:0">✕</button>
      </div>

      <!-- Barra de filtro/orden -->
      <div style="background:#fef3c7;border-bottom:1px solid #fcd34d;padding:10px 18px;display:flex;align-items:center;gap:12px;flex-wrap:wrap">
        <label style="font-size:11px;font-weight:800;color:#78350f;text-transform:uppercase;letter-spacing:.4px">🎽 Filtrar por categoría:</label>
        <select id="eqRosterCatFilter" onchange="_eqRosterRerender()" style="border:1.5px solid #fcd34d;border-radius:7px;padding:5px 10px;font-size:12px;font-weight:700;background:#fff;min-width:140px">
          <option value="">Todas (${data.riders.length})</option>
          ${allCats.map(c=>{
            const n = data.riders.filter(r=>(r.cat||'')===c).length;
            return `<option value="${escapeAttr(c)}">${escapeHtml(c)} (${n})</option>`;
          }).join('')}
        </select>
        <button onclick="_eqRosterResetSort()" style="background:#fff;color:#78350f;border:1.5px solid #fcd34d;border-radius:7px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer">🔄 Quitar filtros</button>
        <span id="eqRosterCount" style="font-size:11px;color:#92400e;font-weight:700;margin-left:auto"></span>
      </div>

      <div style="padding:14px 18px;overflow-y:auto;flex:1">
        <div id="eqRosterTableBox"></div>
      </div>
      <div style="border-top:1px solid #e5e7eb;padding:12px 20px;display:flex;justify-content:flex-end;gap:8px;background:#f9fafb">
        <button onclick="_eqCcaaTeamRosterPDF('${escapeAttr(teamName)}','${escapeAttr(year)}')" style="background:#dc2626;color:#fff;border:none;border-radius:8px;padding:9px 16px;font-weight:800;font-size:13px;cursor:pointer">📄 Exportar PDF</button>
        <button onclick="document.getElementById('_eqCcaaTeamDialog').remove()" style="background:#0b2f6b;color:#fff;border:none;border-radius:8px;padding:9px 16px;font-weight:700;cursor:pointer">Cerrar</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  _eqRosterRerender();
}

function _eqRosterSort(key){
  if(!_eqRosterState) return;
  if(_eqRosterState.sortKey===key){
    _eqRosterState.sortDir = _eqRosterState.sortDir==='asc' ? 'desc' : 'asc';
  } else {
    _eqRosterState.sortKey = key;
    // Por defecto las stats van descendente (mejor primero), las de "posición" ascendente
    _eqRosterState.sortDir = ['wins','podiums','top10','races'].includes(key) ? 'desc' : 'asc';
  }
  _eqRosterRerender();
}

function _eqRosterResetSort(){
  if(!_eqRosterState) return;
  _eqRosterState.sortKey = 'score';
  _eqRosterState.sortDir = 'asc';
  _eqRosterState.catFilter = '';
  const sel = document.getElementById('eqRosterCatFilter');
  if(sel) sel.value = '';
  _eqRosterRerender();
}

function _eqRosterRerender(){
  if(!_eqRosterState) return;
  const sel = document.getElementById('eqRosterCatFilter');
  _eqRosterState.catFilter = (sel?.value || '').trim();
  const {data, sortKey, sortDir, catFilter, year} = _eqRosterState;

  // Filtrar
  let rows = [...data.riders];
  if(catFilter) rows = rows.filter(r=>(r.cat||'')===catFilter);

  // Ordenar
  const sortMul = sortDir==='asc' ? 1 : -1;
  rows.sort((a,b)=>{
    const va = a[sortKey], vb = b[sortKey];
    // Para nombre/cat (strings)
    if(sortKey==='displayName' || sortKey==='cat'){
      return (va||'').localeCompare(vb||'') * sortMul;
    }
    return ((va||0) - (vb||0)) * sortMul;
  });

  // Contador
  const cnt = document.getElementById('eqRosterCount');
  if(cnt) cnt.textContent = `Mostrando ${rows.length} de ${data.riders.length} corredor(es)`;

  // Render
  const box = document.getElementById('eqRosterTableBox');
  if(!box) return;

  const arrow = (key)=>{
    if(sortKey!==key) return '<span style="opacity:.3">↕</span>';
    return sortDir==='asc' ? '<span style="color:#1d4ed8">▲</span>' : '<span style="color:#1d4ed8">▼</span>';
  };
  const th = (key, label, align='left')=>`<th onclick="_eqRosterSort('${key}')" style="padding:9px 10px;text-align:${align};font-size:11px;color:#475569;cursor:pointer;user-select:none;background:${sortKey===key?'#dbeafe':'#f8fafc'}" title="Clic para ordenar">${label} ${arrow(key)}</th>`;

  const rowsHtml = rows.length
    ? rows.map((r,i)=>`<tr style="border-top:1px solid #f3f4f6">
        <td style="padding:8px 10px;font-weight:700;color:#475569;width:36px;text-align:center">${i+1}</td>
        <td style="padding:8px 10px;font-weight:800;color:#0b2f6b">${escapeHtml(r.displayName)}</td>
        <td style="padding:8px 10px;font-size:12px">
          ${r.cat?`<span style="background:#e0e7ff;color:#3730a3;padding:2px 8px;border-radius:99px;font-weight:700">${escapeHtml(r.cat)}</span>`:'<span style="color:#9ca3af">—</span>'}
        </td>
        <td style="padding:8px 10px;text-align:center;font-weight:700;color:#475569">${r.races}/${r.totalRaces}</td>
        <td style="padding:8px 10px;text-align:center;font-weight:700">${r.wins}</td>
        <td style="padding:8px 10px;text-align:center;font-weight:700">${r.podiums}</td>
        <td style="padding:8px 10px;text-align:center;font-weight:700">${r.top10}</td>
        <td style="padding:8px 10px;text-align:center;font-weight:700;color:#475569">${r.avg.toFixed(1)}</td>
        <td style="padding:8px 10px;text-align:center;font-weight:700;color:#16a34a">${r.best}</td>
      </tr>`).join('')
    : `<tr><td colspan="9" style="padding:30px;text-align:center;color:#9ca3af">No hay corredores que coincidan con el filtro.</td></tr>`;

  box.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:13px">
    <thead>
      <tr>
        <th style="padding:9px 10px;text-align:center;font-size:11px;color:#475569;background:#f8fafc">#</th>
        ${th('displayName','Corredor','left')}
        ${th('cat','Categoría','left')}
        ${th('races','📊 Participación','center')}
        ${th('wins','🏆','center')}
        ${th('podiums','🥉','center')}
        ${th('top10','Top10','center')}
        ${th('avg','Pos. med.','center')}
        ${th('best','Mejor','center')}
      </tr>
    </thead>
    <tbody>${rowsHtml}</tbody>
  </table>`;
}

// Wrapper para exportar el roster a PDF (recalcula data por si el modal lleva
// tiempo abierto y el histórico ha cambiado)
async function _eqCcaaTeamRosterPDF(teamName, year){
  const history = await _ensureHistory();
  const data = _buildTeamRosterData(history, teamName, year);
  _openTeamRosterPDFWindow(teamName, year, data);
}

async function exportTableAsPNG(){
  const target = $('captureTable');
  if(!target) return;
  showLoading('Generando imagen...','Capturando tabla para compartir.');
  try {
    const canvas = await html2canvas(target, {
      backgroundColor: '#ffffff',
      scale: 2, // Mayor calidad
      logging: false,
      useCORS: true
    });
    const link = document.createElement('a');
    link.download = 'clasificacion_ciclista_' + (new Date().getTime()) + '.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
  } catch(e) {
    alert('No se pudo generar la imagen. Inténtalo de nuevo.');
    console.error(e);
  } finally {
    hideLoading();
  }
}
/* ─── Paletas Top 10 ─── */
const _T10_BG    =['#dbeafe','#dcfce7','#fef9c3','#ede9fe','#cffafe','#fce7f3','#d1fae5','#ffedd5','#e0f2fe','#fef2f2'];
const _T10_BORDER=['#93c5fd','#86efac','#fde047','#c4b5fd','#67e8f9','#f9a8d4','#6ee7b7','#fdba74','#7dd3fc','#fca5a5'];
const _T10_SOLID =['#1d4ed8','#15803d','#a16207','#6d28d9','#0e7490','#be185d','#047857','#c2410c','#0369a1','#b91c1c'];

function renderTop10(){
  // Destruir charts previos (ya no se usan pero limpiamos por si acaso)
  if(chartTop10Teams){chartTop10Teams.destroy();chartTop10Teams=null;}
  if(chartTop10Cat){chartTop10Cat.destroy();chartTop10Cat=null;}

  const base = getTeamRankingFilteredRiders();
  const top  = base.slice().sort((a,b)=>a.pos-b.pos).slice(0,10);

  // --- Sin datos ---
  if(!top.length){
    ['top10Podium','top10Legend','top10','top10Commentary','top10HeaderStats',
     'top10Dominance','top10Groups','top10MyTeam'].forEach(id=>{
      const el=$(id); if(el) el.innerHTML='';
    });
    return;
  }

  // Asignar índice de color a cada equipo (por orden de aparición en top10)
  const teamsOrdered=[...new Set(top.map(r=>r.team))];
  const teamIdx={};
  teamsOrdered.forEach((t,i)=>{ teamIdx[t]=i; });

  const winner = top[0];
  const winnerTime = winner.totalSeconds
    ? formatSeconds(winner.totalSeconds)
    : (winner.time && winner.time!=='—' ? winner.time : '—');

  // ── PODIO ──────────────────────────────────────────────────────────────
  const podiumEl=$('top10Podium');
  if(podiumEl){
    const medals=['🥇','🥈','🥉'];
    const podiumClass=['p1','p2','p3'];
    podiumEl.innerHTML=top.slice(0,3).map((r,i)=>{
      const ci=teamIdx[r.team]||0;
      const t=r.totalSeconds
        ? formatSeconds(r.totalSeconds)
        : (r.gapSeconds===0 ? winnerTime : (r.time||'—'));
      const gapStr=i===0?'':(r.gapSeconds?`<div style="font-size:11px;color:#667085;margin-top:2px">+${formatSeconds(r.gapSeconds)}</div>`:'');
      return `<div class="top10-podium-card ${podiumClass[i]}"
          style="border-color:${_T10_BORDER[ci]};background:linear-gradient(160deg,${_T10_BG[ci]},#fff)">
        <span class="top10-medal">${medals[i]}</span>
        <div class="top10-podium-pos" style="color:${_T10_SOLID[ci]}">${r.pos}º</div>
        <div class="top10-podium-name">${escapeHtml(r.name)}</div>
        <div class="top10-podium-team">${escapeHtml(r.team)}</div>
        <div class="top10-podium-time" style="color:${_T10_SOLID[ci]}">${t}</div>
        ${gapStr}
        <span class="pill" style="font-size:10px;margin-top:6px;display:inline-block">
          <span class="cat-dot" style="background:${getColorForCategory(r.cat)}"></span>${escapeHtml(r.cat)}
        </span>
        <button onclick="analyzeRiderByKey('${escapeAttr(getRiderKey(r))}');showView('view-analisis')"
          style="margin-top:8px;font-size:11px;padding:4px 10px;border-radius:20px;border:1.5px solid ${_T10_SOLID[ci]};background:transparent;color:${_T10_SOLID[ci]};cursor:pointer;font-weight:600"
          title="Ir al análisis individual">👤 Ver análisis</button>
      </div>`;
    }).join('');
  }

  // ── LEYENDA DE EQUIPOS ─────────────────────────────────────────────────
  const legendEl=$('top10Legend');
  if(legendEl){
    legendEl.innerHTML=teamsOrdered.map((t,i)=>{
      const cnt=top.filter(r=>r.team===t).length;
      return `<span class="top10-legend-chip"
          style="background:${_T10_BG[i]};border-color:${_T10_BORDER[i]};color:${_T10_SOLID[i]}">
        <span style="width:8px;height:8px;border-radius:50%;background:${_T10_SOLID[i]}"></span>
        ${escapeHtml(t)} &nbsp;<b>${cnt}</b>
      </span>`;
    }).join('');
  }

  // ── TABLA ──────────────────────────────────────────────────────────────
  const headerStEl=$('top10HeaderStats');
  if(headerStEl){
    const teams10=teamsOrdered.length;
    const cats10=[...new Set(top.map(r=>r.cat))].length;
    headerStEl.textContent=`${teams10} equipo${teams10!==1?'s':''} · ${cats10} categoría${cats10!==1?'s':''}`;
  }

  const posBadge=i=>i===0?'🥇':i===1?'🥈':i===2?'🥉':`<b>${top[i].pos}</b>`;

  const rows=top.map((r,i)=>{
    const ci=teamIdx[r.team]||0;
    const rowBg= i<3 ? _T10_BG[ci]+'cc' : _T10_BG[ci]+'66';
    // Tiempo: siempre mostrar algo real
    let timeDisplay;
    if(r.totalSeconds){
      timeDisplay=formatSeconds(r.totalSeconds);
      if(i>0 && r.gapSeconds) timeDisplay+=`<span style="font-size:11px;color:#667085;display:block">+${formatSeconds(r.gapSeconds)}</span>`;
    } else if(r.gapSeconds===0){
      timeDisplay=winnerTime+`<span style="font-size:10px;color:#667085;display:block">mismo grupo</span>`;
    } else if(r.gapSeconds){
      timeDisplay=`+${formatSeconds(r.gapSeconds)}`;
    } else {
      timeDisplay=escapeHtml(r.time||'—');
    }
    return `<tr style="background:${rowBg};border-left:4px solid ${_T10_SOLID[ci]}">
      <td>${posBadge(i)}</td>
      <td class="t-name">${escapeHtml(r.name)}</td>
      <td class="t-time">${timeDisplay}</td>
      <td><span class="pill"><span class="cat-dot" style="background:${getColorForCategory(r.cat)}"></span>${escapeHtml(r.cat)}</span></td>
      <td>${escapeHtml(r.region||'—')}</td>
      <td class="t-team"><span style="display:inline-flex;align-items:center;gap:5px">
        <span style="width:8px;height:8px;border-radius:50%;background:${_T10_SOLID[ci]};flex-shrink:0"></span>
        ${escapeHtml(r.team)}
      </span></td>
      <td><button onclick="analyzeRiderByKey('${escapeAttr(getRiderKey(r))}');showView('view-analisis')"
        title="Ver análisis individual"
        style="background:none;border:none;cursor:pointer;font-size:15px;padding:2px 4px;opacity:.55;transition:opacity .15s"
        onmouseover="this.style.opacity=1" onmouseout="this.style.opacity=.55">👤</button></td>
    </tr>`;
  }).join('');

  $('top10').innerHTML=`<div class="table-wrap" style="max-height:none">
    <table class="top10-table">
      <thead><tr><th>Pos.</th><th>Ciclista</th><th>Tiempo</th><th>Cat.</th><th>CCAA</th><th>Equipo</th><th></th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>`;

  // ── COMENTARIO DIRECTOR ────────────────────────────────────────────────
  const commentEl=$('top10Commentary');
  if(commentEl){
    const domTeam=teamsOrdered.reduce((best,t)=>{
      const cnt=top.filter(r=>r.team===t).length;
      return cnt>(best.cnt||0)?{t,cnt}:best;
    },{});
    const teamsInPodium=[...new Set(top.slice(0,3).map(r=>r.team))];
    const gapLast=top[top.length-1].gapSeconds;
    const cats=[...new Set(top.map(r=>r.cat))];
    const myInTop10=top.filter(r=>isMyTeam(r));

    let html=`<b>🧠 Análisis del director</b><br><br>`;
    html+=`🏆 Ganador: <b>${escapeHtml(winner.name)}</b> <span style="color:#667085">(${escapeHtml(winner.team)})</span> — Tiempo: <b>${winnerTime}</b>.<br>`;

    if(domTeam.cnt>=3)
      html+=`💪 <b>${escapeHtml(domTeam.t)}</b> domina con <b>${domTeam.cnt} corredores</b> en el Top 10.<br>`;

    if(teamsInPodium.length===1)
      html+=`🔒 Podio completo del mismo equipo: <b>${escapeHtml(teamsInPodium[0])}</b>.<br>`;
    else if(teamsInPodium.length===3)
      html+=`⚔️ El podio tiene tres equipos distintos: alta competitividad.<br>`;

    if(gapLast!=null && gapLast>0)
      html+=`⏱️ El décimo entra a <b>+${formatSeconds(gapLast)}</b> del ganador.<br>`;

    if(cats.length>1)
      html+=`📊 ${cats.length} categorías en el Top 10: ${cats.map(c=>`<b>${escapeHtml(c)}</b>`).join(', ')}.<br>`;

    if(myInTop10.length>0)
      html+=`<br>⭐ <b style="color:#1f6feb">Mi equipo</b> tiene <b>${myInTop10.length} corredor${myInTop10.length!==1?'es':''}</b> en el Top 10: `+
        myInTop10.map(r=>`<b>${escapeHtml(r.name)}</b> (${r.pos}º)`).join(', ')+'.<br>';
    else
      html+=`<br>ℹ️ Ningún corredor de mi equipo en el Top 10 con los filtros actuales.<br>`;

    html+=`<br><span class="small" style="color:#9ca3af">💡 Usa el botón 👤 en cada fila o en las tarjetas del podio para abrir el análisis individual del ciclista.</span>`;
    commentEl.innerHTML=html;
  }

  // ── DOMINIO POR EQUIPO ────────────────────────────────────────────────
  const domEl=$('top10Dominance');
  if(domEl){
    const teamsSorted=teamsOrdered.slice().sort((a,b)=>
      top.filter(r=>r.team===b).length - top.filter(r=>r.team===a).length
    );
    domEl.innerHTML=teamsSorted.map(t=>{
      const ci=teamIdx[t]||0;
      const teamRiders=top.filter(r=>r.team===t).sort((a,b)=>a.pos-b.pos);
      const badges=teamRiders.map(r=>{
        const isTop3=r.pos<=3;
        return `<span class="dom-pos-badge" title="${escapeAttr(r.name)}"
          style="border-color:${_T10_SOLID[ci]};color:${_T10_SOLID[ci]};background:${isTop3?_T10_BG[ci]:'transparent'}">${r.pos}</span>`;
      }).join('');
      const barPct=(teamRiders.length/10*100).toFixed(0);
      return `<div class="dom-team-row">
        <div class="dom-team-label">
          <span style="width:10px;height:10px;border-radius:50%;background:${_T10_SOLID[ci]};flex-shrink:0"></span>
          <span class="tname" title="${escapeAttr(t)}">${escapeHtml(t)}</span>
        </div>
        <div class="dom-pos-badges">${badges}</div>
        <div style="width:60px;background:#f3f4f6;border-radius:4px;height:6px;flex-shrink:0">
          <div style="width:${barPct}%;height:100%;border-radius:4px;background:${_T10_SOLID[ci]}"></div>
        </div>
        <span style="font-size:12px;font-weight:700;color:${_T10_SOLID[ci]};min-width:20px;text-align:right">${teamRiders.length}</span>
      </div>`;
    }).join('');
  }

  // ── ANÁLISIS DE GRUPOS Y DISTANCIAS ───────────────────────────────────
  const groupEl=$('top10Groups');
  if(groupEl){
    const hasGaps=top.some(r=>r.gapSeconds!=null && r.gapSeconds>0);
    if(!hasGaps){
      groupEl.innerHTML=`<div style="color:#9ca3af;font-size:13px;padding:8px 0">Sin datos de tiempo para detectar grupos.</div>`;
    } else {
      const GROUP_THRESHOLD=8; // segundos de diferencia entre consecutivos para considerar mismo grupo
      const groups=[];
      let cur=[top[0]];
      for(let i=1;i<top.length;i++){
        const diff=(top[i].gapSeconds||0)-(top[i-1].gapSeconds||0);
        if(diff<=GROUP_THRESHOLD) cur.push(top[i]);
        else{ groups.push(cur); cur=[top[i]]; }
      }
      groups.push(cur);
      const GRP_COLORS=['#1a7f37','#0b2f6b','#9a3412','#5b21b6','#0e7490','#92400e'];
      groupEl.innerHTML=groups.map((g,gi)=>{
        const color=GRP_COLORS[gi%GRP_COLORS.length];
        const gapLabel=gi===0?'LÍDER':'+'+formatSeconds(g[0].gapSeconds);
        const spread=g.length>1?(g[g.length-1].gapSeconds-g[0].gapSeconds):0;
        const spreadStr=spread>0?` · dispersión ${formatSeconds(spread)}`:'';
        const riderList=g.map(r=>{
          const medal=r.pos<=3?['🥇','🥈','🥉'][r.pos-1]:'';
          return `${medal||r.pos+'º'} ${escapeHtml(r.name)}`;
        }).join('<br>');
        return `<div class="group-chip" style="border-left-color:${color}">
          <div style="flex:1">
            <div class="group-chip-label" style="color:${color}">GRUPO ${gi+1} · ${gapLabel}</div>
            <div class="group-chip-meta">${g.length} corredor${g.length!==1?'es':''}${spreadStr}</div>
            <div class="group-chip-riders">${riderList}</div>
          </div>
        </div>`;
      }).join('');
    }
  }

  // ── MI EQUIPO EN EL TOP 10 ────────────────────────────────────────────
  const myEl=$('top10MyTeam');
  if(myEl){
    const myRiders=top.filter(r=>isMyTeam(r));
    if(!myRiders.length){
      myEl.innerHTML=`<div style="color:#9ca3af;font-size:13px;padding:8px 0">Ningún corredor de tu equipo en el Top 10${myTeam?' ('+escapeHtml(myTeam)+')':`<br><span style="font-size:11px">Configura tu equipo en el filtro superior.</span>`}.</div>`;
    } else {
      myEl.innerHTML=myRiders.map(r=>{
        const ci=teamIdx[r.team]||0;
        let t=r.totalSeconds?formatSeconds(r.totalSeconds):(r.gapSeconds===0?winnerTime:(r.time||'—'));
        const gapStr=(r.pos>1&&r.gapSeconds)?`<span style="font-size:11px;color:#667085;display:block">+${formatSeconds(r.gapSeconds)} del ganador</span>`:'';
        const medal=r.pos<=3?['🥇','🥈','🥉'][r.pos-1]:'';
        return `<div class="myteam-rider-card" style="border-color:${_T10_SOLID[ci]};background:${_T10_BG[ci]}">
          <span style="font-size:22px;font-weight:900;color:${_T10_SOLID[ci]};min-width:38px;text-align:center">${medal||r.pos+'º'}</span>
          <div style="flex:1;min-width:0">
            <div style="font-weight:700;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(r.name)}</div>
            <div style="font-size:11px;color:#667085">${escapeHtml(r.cat)}</div>
          </div>
          <div style="text-align:right">
            <div style="font-family:monospace;font-size:13px;font-weight:700;color:${_T10_SOLID[ci]}">${t}</div>
            ${gapStr}
          </div>
          <button onclick="analyzeRiderByKey('${escapeAttr(getRiderKey(r))}');showView('view-analisis')"
            style="background:none;border:none;cursor:pointer;font-size:15px;opacity:.55;transition:opacity .15s;padding:4px"
            onmouseover="this.style.opacity=1" onmouseout="this.style.opacity=.55" title="Análisis individual">👤</button>
        </div>`;
      }).join('');
    }
  }
}
function spreadClass(spread){
  if(spread==null)return '';
  if(spread<=8)return 'spread-low';
  if(spread<=20)return 'spread-mid';
  return 'spread-high';
}

// ─── Exportación del Top 10 ───────────────────────────────────────────────────
async function _captureTop10Canvas(){
  const target=document.querySelector('#view-top10 > section');
  if(!target) throw new Error('No se encontró la sección Top 10.');

  // Guardar estilos originales
  const origOverflow=target.style.overflow;
  const origHeight=target.style.height;
  target.style.overflow='visible';
  target.style.height='auto';

  // Forzar la visibilidad del view
  const view=$('view-top10');
  const origDisplay=view?view.style.display:'';
  if(view) view.style.display='block';

  // Recoger datos del encabezado de la prueba del DOM vivo
  const _raceName=($('raceName')?.value||'').trim();
  const _raceDate=formatDateDisplay(parseRaceDate(($('raceDate')?.value||'').trim()))||($('raceDate')?.value||'').trim();
  const _km=($('raceKm')?.value||'').trim();
  const _avg=($('raceAvg')?.value||'').trim();
  const _loc=($('raceLocalidad')?.value||'').trim();
  const _type=($('raceCircuitType')?.value||'').trim();
  const _metaParts=[];
  if(_raceDate) _metaParts.push('📅 '+_raceDate);
  if(_loc)      _metaParts.push('📍 '+_loc);
  if(_km)       _metaParts.push('📏 '+_km+' km');
  if(_avg)      _metaParts.push('💨 '+_avg+' km/h');
  if(_type)     _metaParts.push('🔄 '+_type);
  const _metaHtml=_metaParts.join('<span style="color:rgba(255,255,255,.35);margin:0 4px">·</span>');

  // windowWidth holgado para que el grid de 2 columnas no colapse
  // width de captura = ancho del contenido real sin espacio vacío del viewport
  const WINDOW_W=1520;
  const EXPORT_W=1400; // ancho de captura: columna izquierda + columna derecha sin exceso
  const PAD=28;        // padding lateral simétrico
  const H=target.scrollHeight||target.offsetHeight;

  const canvas=await html2canvas(target,{
    backgroundColor:'#f4f7fb',
    scale:2,
    useCORS:true,
    allowTaint:true,
    scrollX:0,
    scrollY:0,
    width:EXPORT_W,
    height:H+130,
    windowWidth:WINDOW_W,
    windowHeight:H+300,
    logging:false,
    onclone:(clonedDoc)=>{
      // 1. Quitar max-height para que toda la tabla sea visible
      clonedDoc.querySelectorAll('.table-wrap').forEach(el=>{
        el.style.maxHeight='none';
        el.style.overflow='visible';
      });

      const sec=clonedDoc.querySelector('#view-top10 > section');
      if(!sec) return;

      // 2. Fijar ancho = EXPORT_W y padding simétrico
      sec.style.width=EXPORT_W+'px';
      sec.style.maxWidth=EXPORT_W+'px';
      sec.style.boxSizing='border-box';
      sec.style.padding=`10px ${PAD}px 28px ${PAD}px`;
      sec.style.backgroundColor='#f4f7fb';

      // 3. Inyectar el encabezado de la prueba en azul arriba del todo
      const headerEl=clonedDoc.createElement('div');
      headerEl.style.cssText=[
        'background:linear-gradient(135deg,#0b2f6b 0%,#1565c0 60%,#1286c7 100%)',
        `padding:18px ${PAD}px`,
        `margin:0 -${PAD}px 20px -${PAD}px`, // sangra hasta los bordes del padding del section
        'box-sizing:border-box'
      ].join(';');
      headerEl.innerHTML=
        `<div style="font-size:22px;font-weight:900;color:#fff;margin:0 0 7px;letter-spacing:-.3px;line-height:1.2">${_raceName||'Top 10'}</div>`+
        (_metaHtml?`<div style="display:flex;flex-wrap:wrap;gap:5px 0;align-items:center;font-size:13px;color:rgba(255,255,255,.88)">${_metaHtml}</div>`:'');
      sec.insertBefore(headerEl, sec.firstChild);
    }
  });

  // Restaurar
  target.style.overflow=origOverflow;
  target.style.height=origHeight;
  if(view) view.style.display=origDisplay;

  return canvas;
}

async function exportTop10AsPNG(){
  if(!hasValidData){alert('Carga una clasificación primero.');return;}
  showLoading('Generando infografía PNG…','Capturando el Top 10 completo en alta calidad.');
  try{
    const canvas=await _captureTop10Canvas();
    const raceName=($('raceName')?.value||'Top10').replace(/[<>:"/\\|?*]/g,'').trim();
    const link=document.createElement('a');
    link.download=`Top10_${raceName}.png`;
    link.href=canvas.toDataURL('image/png');
    link.click();
    hideLoading();
  }catch(e){
    hideLoading();
    alert('Error al generar el PNG: '+(e.message||e));
  }
}

async function exportTop10AsPDF(){
  if(!hasValidData){alert('Carga una clasificación primero.');return;}
  showLoading('Generando PDF del Top 10…','Capturando la infografía para PDF. Puede tardar unos segundos.');
  try{
    const canvas=await _captureTop10Canvas();
    const imgData=canvas.toDataURL('image/png');
    const raceName=($('raceName')?.value||'Top10').replace(/[<>:"/\\|?*]/g,'').trim();
    const raceDate=($('raceDate')?.value||'').trim();

    // Calcular dimensiones exactas de la página en mm a partir del canvas
    // canvas.width/height son el doble del lógico (scale:2), dividimos por 2
    const logicW=canvas.width/2;
    const logicH=canvas.height/2;
    const MM=0.264583; // 1px a 96dpi = 0.264583mm
    const pageWmm=Math.round(logicW*MM);
    const pageHmm=Math.round(logicH*MM);

    const win=window.open('','_blank','width=1000,height=800');
    if(!win){hideLoading();alert('El navegador bloqueó la ventana emergente. Permite las ventanas emergentes e inténtalo de nuevo.');return;}

    win.document.open();
    win.document.write(`<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<title>${raceName} – Top 10</title>
<style>
  /* Página del mismo tamaño exacto que la imagen → sin escala, sin recorte, sin márgenes */
  @page{size:${pageWmm}mm ${pageHmm}mm;margin:0}
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{width:${pageWmm}mm;height:${pageHmm}mm;background:#f4f7fb;overflow:hidden}
  img{display:block;width:${pageWmm}mm;height:${pageHmm}mm;object-fit:fill}
  @media print{
    html,body{background:#f4f7fb}
    img{width:${pageWmm}mm;height:${pageHmm}mm}
  }
</style>
</head>
<body>
  <img src="${imgData}" alt="Top 10 – ${raceName}">
<script>
  window.onload=function(){setTimeout(function(){window.print();},600);}
<\/script>
</body>
</html>`);
    win.document.close();
    hideLoading();
  }catch(e){
    hideLoading();
    alert('Error al generar el PDF: '+(e.message||e));
  }
}

function renderTeamSummary(){
  // Calcular el ranking oficial por equipos para usarlo como criterio de ordenación principal
  const baseRiders = getTeamRankingFilteredRiders();
  const rankMap = {};
  baseRiders.forEach(r => { if(r.team) { if(!rankMap[r.team]) rankMap[r.team] = []; rankMap[r.team].push(r); } });

  let officialRank = [];
  if(teamRankingMode === 'points'){
    officialRank = Object.entries(rankMap).map(([team,rs])=>{
      const top3 = rs.slice().sort((a,b)=>a.pos-b.pos).slice(0,3);
      if(top3.length<3) return null;
      return {team, val: top3.reduce((s,r)=>s+r.pos,0), best: top3[0].pos};
    }).filter(Boolean).sort((a,b)=>a.val - b.val || a.best - b.best);
  } else {
    officialRank = Object.entries(rankMap).map(([team,rs])=>{
      const withTime = rs.filter(r=>r.totalSeconds!=null).slice().sort((a,b)=>a.pos-b.pos);
      const top3 = withTime.slice(0,3);
      if(top3.length<3) return null;
      return {team, val: top3.reduce((s,r)=>s+r.totalSeconds,0)};
    }).filter(Boolean).sort((a,b)=>a.val - b.val);
  }

  const teamInfo = {};
  officialRank.forEach((x, i) => { teamInfo[x.team] = { rank: i + 1, val: x.val }; });

  let map={};
  baseRiders.forEach(r=>{if(!map[r.team])map[r.team]=[];map[r.team].push(r)});
  let rows=Object.entries(map).map(([team,rs])=>{
    const sorted=rs.slice().sort((a,b)=>a.pos-b.pos);
    const spread=sorted.length>=3 ? sorted[2].pos-sorted[0].pos : null;
    const info = teamInfo[team] || { rank: 999, val: null };
    return {team,count:rs.length,best:Math.min(...rs.map(r=>r.pos)),avg:rs.reduce((s,r)=>s+r.pos,0)/rs.length,spread,rank:info.rank,val:info.val};
  }).sort((a,b)=>a.rank - b.rank || a.avg - b.avg);

  const valHeader = teamRankingMode === 'time' ? 'Tiempo (3)' : 'Puntos (3)';
  $('teamSummary').innerHTML='<div class="table-wrap" style="max-height:420px"><table><thead><tr><th>Pos.</th><th>Equipo</th><th>'+valHeader+'</th><th>N.º Clas.</th><th>Top Pos.</th><th>Media</th><th>Dispersión</th></tr></thead><tbody>'+
    rows.map(x=>{
      const valTxt = x.val == null ? '—' : (teamRankingMode === 'time' ? formatTeamTotalSeconds(x.val) : x.val);
      return `<tr><td><b>${x.rank===999?'—':x.rank+'º'}</b></td><td>${escapeHtml(x.team)}</td><td>${valTxt}</td><td>${x.count}</td><td>${x.best}</td><td>${x.avg.toFixed(1)}</td><td class="${spreadClass(x.spread)}">${x.spread==null?'—':x.spread}</td></tr>`
    }).join('')+
    '</tbody></table></div><div class="chart-help">El ranking (Pos.) se basa estrictamente en el <b>'+valHeader+'</b> (suma de los 3 mejores). La <b>Media</b> y <b>Dispersión</b> describen el comportamiento del resto del equipo (bloque vs individualidades). En ambos casos, <b>cuanto más bajo sea el valor, mejor</b> es el rendimiento global o la cohesión.</div>';
}
function miniTable(list){return '<div class="table-wrap" style="max-height:360px"><table><thead><tr><th>Pos.</th><th>Ciclista</th><th>Tiempo / diferencia</th><th>Cat.</th><th>CCAA</th><th>Equipo</th></tr></thead><tbody>'+list.map(r=>`<tr><td>${r.pos}</td><td>${escapeHtml(r.name)}</td><td>${escapeHtml(r.time||'—')}</td><td>${escapeHtml(r.cat)}</td><td>${escapeHtml(r.region||'—')}</td><td>${escapeHtml(r.team)}</td></tr>`).join('')+'</tbody></table></div>'}

function chartColors(n){
  const palette=['#1f6feb','#12b76a','#f79009','#7a5af8','#06aed4','#f04438','#667085','#15b79e','#ef6820','#4e5ba6','#2e90fa','#039855'];
  return Array.from({length:n},(_,i)=>palette[i%palette.length]);
}
/* ── Gráficos: variables auxiliares ─────────────────────── */
let _grafTopTeamRows=[];
let _grafTopTeamCutoffs=[10,20,50];
let _grafTopTeamCurrentMode='abs';

/* ── Gráficos: render Top Equipos (abs / pct) ───────────── */
function _renderTopTeamChart(){
  if(chartTopTeam){chartTopTeam.destroy();chartTopTeam=null;}
  const rows=_grafTopTeamRows; const cutoffs=_grafTopTeamCutoffs;
  const isPct=_grafTopTeamCurrentMode==='pct';
  const datasets=cutoffs.map((c,i)=>({
    label: isPct?`Top ${c} %`:`Top ${c}`,
    data: rows.map(x=> isPct ? +(x.vals[i]/x.total*100).toFixed(1) : x.vals[i]),
    backgroundColor:['#1f6feb','#12b76a','#f79009'][i],
    borderRadius:6
  }));
  chartTopTeam=new Chart($('topTeamChart'),{plugins:[valueLabelsPlugin],type:'bar',
    data:{labels:rows.map(x=>x.team),datasets},
    options:{responsive:true,maintainAspectRatio:false,indexAxis:'y',
      plugins:{tooltip:{callbacks:{label:(ctx)=>{
        const r=rows[ctx.dataIndex];
        return isPct
          ? `${ctx.dataset.label}: ${ctx.raw}% (${r.vals[cutoffs.indexOf(parseInt(ctx.dataset.label.replace('Top ','').replace(' %','')))]||0} de ${r.total})`
          : `${ctx.dataset.label}: ${ctx.raw} corredores`;
      },afterLabel:()=>'Clic para filtrar este equipo'}}},
      scales:{x:{beginAtZero:true,ticks:{precision:0,callback:(v)=>isPct?v+'%':v},title:{display:true,text:isPct?'% de corredores del equipo':'Número de corredores'}},y:{ticks:{autoSkip:false,font:{size:11}}}},
      onClick:(evt,els)=>{if(els.length){$('teamFilter').value=rows[els[0].index].team;applyFilters();}}}
  });
}
function _topTeamMode(mode){
  _grafTopTeamCurrentMode=mode;
  $('topTeamAbsBtn')?.classList.toggle('active',mode==='abs');
  $('topTeamPctBtn')?.classList.toggle('active',mode==='pct');
  if(_grafTopTeamRows.length) _renderTopTeamChart();
}

/* ── Gráficos: ayuda contextual ─────────────────────────── */
function _grafHelp(id){
  const el=document.getElementById(id); if(!el) return;
  el.style.display=el.style.display==='none'?'block':'none';
}

/* ── Notas tácticas: guardar / cargar ───────────────────── */
function _notasKey(){
  const name=($('raceName')?.value||'').trim();
  const date=($('raceDate')?.value||'').trim();
  return 'notas_'+(name+'_'+date).replace(/[^a-z0-9]/gi,'_').slice(0,80);
}
let _notasSaveTimer=null;
function _notasSave(){
  clearTimeout(_notasSaveTimer);
  _notasSaveTimer=setTimeout(()=>{
    const key=_notasKey();
    if(!key||key==='notas_') return;
    const data={ataques:$('notaAtaques')?.value||'',incidentes:$('notaIncidentes')?.value||'',control:$('notaControl')?.value||'',libre:$('notaLibre')?.value||''};
    try{localStorage.setItem(key,JSON.stringify(data));}catch(e){}
    const st=$('notasSaveStatus');
    if(st){st.textContent='✓ Guardado';setTimeout(()=>{if(st)st.textContent='';},2000);}
  },600);
}
function _notasLoad(){
  const key=_notasKey();
  if(!key||key==='notas_') return;
  try{
    const raw=localStorage.getItem(key);
    if(!raw) return;
    const data=JSON.parse(raw);
    if($('notaAtaques'))    $('notaAtaques').value    = data.ataques||'';
    if($('notaIncidentes')) $('notaIncidentes').value = data.incidentes||'';
    if($('notaControl'))    $('notaControl').value    = data.control||'';
    if($('notaLibre'))      $('notaLibre').value      = data.libre||'';
  }catch(e){}
}
