function runExportCSV(){const mode=$('exportMode')?$('exportMode').value:'current';if(mode==='history')exportHistoryCSV();else exportCurrentViewCSV();}
function exportCurrentViewCSV(){
  if(!filtered.length){alert('No hay corredores visibles para exportar.');return}
  const rows=[['Carrera','Fecha','Km','Vmedia','Puesto','Dorsal','Ciclista','Categoria','CCAA','Equipo','Tiempo/Diferencia','Gap segundos','Gap','Segundos por km']];
  filtered.forEach(r=>rows.push([
    $('raceName').value||'',
    $('raceDate').value||'',
    $('raceKm').value||'',
    $('raceAvg').value||'',
    r.pos,
    r.bib,
    r.name,
    r.cat,
    (r.region||''),
    r.team,
    r.time||'',
    r.gapSeconds??'',
    formatSeconds(r.gapSeconds),
    r.secPerKm!=null?r.secPerKm.toFixed(1):''
  ]));
  let csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\n');
  const base=($('raceName').value||'vista_actual').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_|_$/g,'').toLowerCase();
  downloadBlob(csv,(base||'vista_actual')+'_filtrada.csv','text/csv;charset=utf-8');
}
async function exportHistoryCSV(){
  const hist=await _sbLoadHistory();
  if(!hist.length){alert('No hay histórico para exportar.');return;}
  let rows=[['Carrera','Fecha','Km','Vmedia','Puesto','Dorsal','Ciclista','Categoria','CCAA','Equipo','Tiempo/Diferencia']];
  hist.forEach(h=>h.riders.forEach(r=>rows.push([h.raceName,h.raceDate,h.km,h.avg,r.pos,r.bib,r.name,r.cat,(r.region||''),r.team,r.time])));
  let csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\n');
  downloadBlob(csv,'historico_clasificaciones.csv','text/csv;charset=utf-8');
}
function downloadBlob(content,name,type){let blob=new Blob([content],{type});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
// ===== BLOQUE COMPARATIVO DE CICLISTAS =====
// Array fijo de 6 posiciones (null = slot vacío)
let comparativoRiders=Array(6).fill(null);let compGapChart=null;let compRadarChart=null;
const COMP_COLORS=['#1f6feb','#12b76a','#f79009','#7a5af8','#06aed4','#f04438'];
// Helper: riders reales (sin nulls)
function _compFilled(){ return comparativoRiders.filter(Boolean); }

function _autoFillComparativo(){
  if(!riders.length) return;

  const teamBest={};
  riders.forEach(r=>{
    if(!r.team) return;
    const k=r.team.toLowerCase();
    if(!teamBest[k]||r.pos<teamBest[k].pos) teamBest[k]=r;
  });

  const officialRanked=getOfficialTeamRanking().map(x=>x.team.toLowerCase());
  const remaining=Object.keys(teamBest)
    .filter(k=>!officialRanked.includes(k))
    .sort((a,b)=>teamBest[a].pos-teamBest[b].pos);
  const allTeamsOrdered=[...officialRanked,...remaining];

  const myTeamLower=(localStorage.getItem('myTeam')||'').toLowerCase().trim();
  const selection=[];

  if(myTeamLower && teamBest[myTeamLower]) selection.push(teamBest[myTeamLower]);

  for(const k of allTeamsOrdered){
    if(selection.length>=6) break;
    if(k===myTeamLower) continue;
    const best=teamBest[k];
    if(best && !selection.some(x=>getRiderKey(x)===getRiderKey(best))) selection.push(best);
  }

  comparativoRiders=Array.from({length:6},(_,i)=>selection[i]||null);
}

function initComparativo(){
  _destroyCompCharts();
  _autoFillComparativo();
  renderComparativo();
}

function _destroyCompCharts(){
  if(compGapChart){compGapChart.destroy();compGapChart=null;}
  if(compRadarChart){compRadarChart.destroy();compRadarChart=null;}
}

function removeFromComparativo(slotIdx){
  comparativoRiders[slotIdx]=null;
  _destroyCompCharts();
  renderComparativo();
}

function clearComparativo(){
  comparativoRiders=Array(6).fill(null);
  _destroyCompCharts();
  renderComparativo();
}

/* Actualiza el select de ciclistas al cambiar de equipo en un slot */
function updateCompSlotRiders(slotIdx){
  const teamSel=document.getElementById('compSlotTeam'+slotIdx);
  const riderSel=document.getElementById('compSlotRider'+slotIdx);
  if(!teamSel||!riderSel)return;
  const team=teamSel.value;
  if(!team){
    riderSel.innerHTML='<option value="">— Primero elige equipo —</option>';
    riderSel.disabled=true;
    // Si había un rider en este slot, limpiarlo ya que cambió el equipo
    if(comparativoRiders[slotIdx]){comparativoRiders[slotIdx]=null;_destroyCompCharts();renderComparativo();}
    return;
  }
  // Al cambiar equipo en slot lleno, limpiar el slot
  if(comparativoRiders[slotIdx] && comparativoRiders[slotIdx].team!==team){
    comparativoRiders[slotIdx]=null;
    _destroyCompCharts();
  }
  const currentKey=comparativoRiders[slotIdx]?getRiderKey(comparativoRiders[slotIdx]):null;
  // Excluir riders ya en OTROS slots (no en el slot actual)
  const otherKeys=new Set(comparativoRiders.filter((_,i)=>i!==slotIdx&&comparativoRiders[i]).map(x=>getRiderKey(x)));
  const pool=riders
    .filter(r=>r.team===team && !otherKeys.has(getRiderKey(r)))
    .sort((a,b)=>a.pos-b.pos);
  riderSel.innerHTML='<option value="">— Ciclista —</option>'+
    pool.map(r=>`<option value="${escapeAttr(getRiderKey(r))}" ${getRiderKey(r)===currentKey?'selected':''}>${r.pos}º · ${escapeHtml(r.name)}</option>`).join('');
  riderSel.disabled=false;
}

/* Selecciona/reemplaza un ciclista en un slot específico */
function selectCompSlotRider(slotIdx){
  const riderSel=document.getElementById('compSlotRider'+slotIdx);
  if(!riderSel||!riderSel.value)return;
  const key=riderSel.value;
  const r=riders.find(x=>getRiderKey(x)===key);
  if(!r)return;
  // Si este rider ya está en otro slot, liberarlo
  comparativoRiders=comparativoRiders.map((x,i)=>i!==slotIdx&&x&&getRiderKey(x)===key?null:x);
  comparativoRiders[slotIdx]=r;
  _destroyCompCharts();
  renderComparativo();
}

/* Añade desde los checkboxes de la tabla principal */
function addToComparativo(keyOrName){
  if(!hasValidData)return;
  if(keyOrName){
    const r=riders.find(x=>getRiderKey(x)===keyOrName);
    if(!r)return;
    if(_compFilled().some(x=>getRiderKey(x)===keyOrName)) return;
    const emptyIdx=comparativoRiders.findIndex(x=>x===null);
    if(emptyIdx<0){alert('Máximo 6 ciclistas.');return;}
    comparativoRiders[emptyIdx]=r;
    _destroyCompCharts();
    renderComparativo();
  }
}

function renderComparativo(){
  const grid=document.getElementById('compSlotGrid');
  const resultsEl=document.getElementById('compResults');
  if(!grid)return;

  const teams=[...new Set(riders.map(r=>r.team).filter(Boolean))].sort();
  const otherKeysBySlot=i=>new Set(comparativoRiders.filter((_,j)=>j!==i&&comparativoRiders[j]).map(x=>getRiderKey(x)));

  grid.innerHTML=Array.from({length:6},(_,i)=>{
    const r=comparativoRiders[i];
    const color=COMP_COLORS[i];

    // Opciones de equipo (con pre-selección si hay rider)
    const teamOpts=teams.map(t=>`<option value="${escapeHtml(t)}" ${r&&t===r.team?'selected':''}>${escapeHtml(t)}</option>`).join('');

    // Opciones de ciclista (con pre-selección si hay rider)
    let riderOptsHtml='<option value="">— Ciclista —</option>';
    let riderDisabled=true;
    if(r){
      const otherKeys=otherKeysBySlot(i);
      const pool=riders.filter(x=>x.team===r.team&&!otherKeys.has(getRiderKey(x))).sort((a,b)=>a.pos-b.pos);
      riderOptsHtml='<option value="">— Ciclista —</option>'+
        pool.map(x=>`<option value="${escapeAttr(getRiderKey(x))}" ${getRiderKey(x)===getRiderKey(r)?'selected':''}>${x.pos}º · ${escapeHtml(x.name)}</option>`).join('');
      riderDisabled=false;
    } else if(false){ // vacío sin equipo elegido → disabled
      riderDisabled=true;
    }

    const selectsHtml=`
      <div style="display:flex;flex-direction:column;gap:4px;margin-bottom:6px">
        <select class="comp-slot-select" id="compSlotTeam${i}" onchange="updateCompSlotRiders(${i})"
          style="font-size:11px;padding:5px 7px;border-color:${r?color:'#d0d5dd'}">
          <option value="">— Equipo —</option>${teamOpts}
        </select>
        <select class="comp-slot-select" id="compSlotRider${i}" onchange="selectCompSlotRider(${i})"
          ${riderDisabled&&!r?'disabled':''}
          style="font-size:11px;padding:5px 7px;border-color:${r?color:'#d0d5dd'}">
          ${riderOptsHtml}
        </select>
      </div>`;

    if(r){
      const sameCat=riders.filter(x=>x.cat===r.cat).sort((a,b)=>a.pos-b.pos);
      const catPos=sameCat.findIndex(x=>getRiderKey(x)===getRiderKey(r))+1;
      const gap=r.gapSeconds!=null?(r.gapSeconds===0?'Ganador':'+'+formatSeconds(r.gapSeconds)):'—';
      return `<div class="comp-slot filled" style="border-color:${color}">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
          <div class="comp-slot-num" style="color:${color}">Ciclista ${i+1}</div>
          <button class="comp-slot-remove" onclick="removeFromComparativo(${i})" title="Vaciar slot">✕</button>
        </div>
        ${selectsHtml}
        <div class="comp-slot-pos" style="color:${color}">${r.pos}º</div>
        <div class="comp-slot-name">${escapeHtml(r.name)}</div>
        <div class="comp-slot-meta">
          <span class="pill" style="font-size:10px;padding:2px 7px"><span class="cat-dot" style="background:${getColorForCategory(r.cat)}"></span>${escapeHtml(r.cat)}</span><br>
          ${catPos}º cat &nbsp;·&nbsp; ${gap}
        </div>
      </div>`;
    } else {
      return `<div class="comp-slot" id="compSlot${i}">
        <div class="comp-slot-num" style="margin-bottom:4px">Ciclista ${i+1}</div>
        ${selectsHtml}
        <div class="comp-slot-empty-label">Slot vacío</div>
      </div>`;
    }
  }).join('');

  const filled=_compFilled();
  if(resultsEl) resultsEl.style.display=filled.length?'block':'none';
  if(filled.length){
    renderComparativoTable();
    renderComparativoCharts();
    renderComparativoConclusion();
  }
}

function renderComparativoTable(){
  const el=document.getElementById('compTable');
  if(!el)return;
  const sorted=_compFilled().slice().sort((a,b)=>a.pos-b.pos);
  const best=sorted[0];
  el.innerHTML=`<div class="table-wrap" style="max-height:none;margin-bottom:16px"><table class="compare-table"><thead><tr><th></th><th>Ciclista</th><th>Equipo</th><th>Pos. General</th><th>Categoría</th><th>Pos. Cat.</th><th>Tiempo</th><th>Diferencia</th><th>Seg/km</th><th>Percentil</th><th>CCAA</th></tr></thead><tbody>${sorted.map(r=>{
    const isLeader=getRiderKey(r)===getRiderKey(best);
    const pct=((riders.length-r.pos)/Math.max(1,riders.length-1)*100);
    const sameCat=riders.filter(x=>x.cat===r.cat).sort((a,b)=>a.pos-b.pos);
    const catPos=sameCat.findIndex(x=>getRiderKey(x)===getRiderKey(r))+1;
    const c=COMP_COLORS[comparativoRiders.findIndex(x=>x&&getRiderKey(x)===getRiderKey(r))]||'#475467';
    return `<tr class="${isLeader?'compare-leader':''}"><td><span style="display:inline-block;width:12px;height:12px;border-radius:50%;background:${c};flex-shrink:0"></span></td><td><b>${escapeHtml(r.name)}</b>${isLeader?' ✅':''}</td><td>${escapeHtml(r.team)}</td><td><b>${r.pos}º</b> de ${riders.length}</td><td><span class="pill"><span class="cat-dot" style="background:${getColorForCategory(r.cat)}"></span>${escapeHtml(r.cat)}</span></td><td>${catPos}º de ${sameCat.length}</td><td>${formatSeconds(r.totalSeconds)}</td><td>${formatSeconds(r.gapSeconds)}</td><td>${r.secPerKm!=null?r.secPerKm.toFixed(1)+' s/km':'—'}</td><td>${pct.toFixed(1)}%</td><td>${escapeHtml(r.region||'—')}</td></tr>`;
  }).join('')}</tbody></table></div>`;
}

function renderComparativoCharts(){
  if(!window.Chart)return;
  const sorted=_compFilled().slice().sort((a,b)=>a.pos-b.pos);
  const rColors=sorted.map(r=>COMP_COLORS[comparativoRiders.findIndex(x=>x&&getRiderKey(x)===getRiderKey(r))]||'#475467');

  // Gap chart
  if(compGapChart){compGapChart.destroy();compGapChart=null;}
  const gapEl=document.getElementById('compGapChart');
  if(gapEl){
    compGapChart=new Chart(gapEl,{
      plugins:[valueLabelsPlugin],
      type:'bar',
      data:{labels:sorted.map(r=>r.name),datasets:[{label:'Gap (seg)',data:sorted.map(r=>r.gapSeconds??0),backgroundColor:rColors,borderRadius:8}]},
      options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,title:{display:true,text:'Segundos al ganador'}},x:{ticks:{maxRotation:30,font:{size:10}}}},onClick:(evt,els)=>{if(els.length){const r=sorted[els[0].index];if($('analysisSearchInput'))$('analysisSearchInput').value=r.name;analyzeRiderByKey(getRiderKey(r));showView('view-analisis');}}}
    });
  }

  // Radar chart
  if(compRadarChart){compRadarChart.destroy();compRadarChart=null;}
  const radarEl=document.getElementById('compRadarChart');
  const radarHelp=document.getElementById('compRadarHelp');
  if(radarEl&&sorted.length>=2){
    if(radarHelp)radarHelp.textContent='Toca o pasa el ratón sobre el radar para ver valores.';
    const maxPos=riders.length;
    const allSecKm=riders.map(x=>x.secPerKm).filter(v=>v!=null);
    const maxSecKm=allSecKm.length?Math.max(...allSecKm):1;
    const minSecKm=allSecKm.length?Math.min(...allSecKm):0;
    const datasets=sorted.map((r,i)=>{
      const pct=((maxPos-r.pos)/Math.max(1,maxPos-1))*100;
      const sameCat=riders.filter(x=>x.cat===r.cat).sort((a,b)=>a.pos-b.pos);
      const catIdx=sameCat.findIndex(x=>getRiderKey(x)===getRiderKey(r));
      const catPct=((sameCat.length-(catIdx+1))/Math.max(1,sameCat.length-1))*100;
      const normSecKm=r.secPerKm!=null?((maxSecKm-r.secPerKm)/Math.max(0.01,maxSecKm-minSecKm))*100:50;
      const normPos=((maxPos-r.pos)/Math.max(1,maxPos-1))*100;
      const c=rColors[i];
      return{label:r.name,data:[Math.round(normPos),Math.round(normSecKm),Math.round(pct),Math.round(catPct)],backgroundColor:c+'33',borderColor:c,borderWidth:2,pointBackgroundColor:c,pointRadius:4};
    });
    compRadarChart=new Chart(radarEl,{
      type:'radar',
      data:{labels:['Pos. General','Ritmo (inv)','Percentil global','Pos. Categoría'],datasets},
      options:{responsive:true,maintainAspectRatio:false,scales:{r:{min:0,max:100,ticks:{display:false,stepSize:25},grid:{color:'#e5e7eb'},pointLabels:{font:{size:11}}}},plugins:{legend:{position:'bottom',labels:{font:{size:11},usePointStyle:true}}}}
    });
  } else if(radarEl){
    if(radarHelp)radarHelp.textContent='Añade al menos 2 ciclistas para ver el radar comparativo.';
  }
}

function renderComparativoConclusion(){
  const el=document.getElementById('compConclusion');
  const _cf=_compFilled();
  if(!el||!_cf.length){return;}
  const sorted=_cf.slice().sort((a,b)=>a.pos-b.pos);
  const best=sorted[0];
  const worst=sorted[sorted.length-1];
  const km=parseKmValue();
  let html=`<b>🧠 Conclusión Estratégica</b><br><br>`;
  html+=`✅ <b>${escapeHtml(best.name)}</b> lidera este grupo con el puesto <b>${best.pos}º</b>`;
  if(best.gapSeconds!=null)html+=` a <b>${formatSeconds(best.gapSeconds)}</b> del ganador`;
  html+='.<br>';
  if(sorted.length>=2){
    for(let i=0;i<sorted.length-1;i++){
      const a=sorted[i],b=sorted[i+1];
      if(a.gapSeconds!=null&&b.gapSeconds!=null){
        const diff=Math.abs(b.gapSeconds-a.gapSeconds);
        html+=`⏱️ <b>${escapeHtml(a.name)}</b> supera a <b>${escapeHtml(b.name)}</b> por <b>${formatSeconds(diff)}</b>`;
        if(km>0&&diff>0)html+=` (${(diff/km).toFixed(2)} s/km)`;
        html+='.<br>';
      }
    }
    if(km>0&&worst.totalSeconds!=null&&best.totalSeconds!=null&&worst!==best){
      const timeDiff=worst.totalSeconds-best.totalSeconds;
      const secKmNeeded=(timeDiff/km).toFixed(2);
      html+=`📈 Para que <b>${escapeHtml(worst.name)}</b> igualara a <b>${escapeHtml(best.name)}</b>, necesitaría mejorar <b>${secKmNeeded} s/km</b> de media en toda la carrera.<br>`;
    }
  }
  const teams=[...new Set(sorted.map(r=>r.team))];
  if(teams.length>1)html+=`🚴 Hay corredores de <b>${teams.length} equipos</b> diferentes en esta selección.<br>`;
  else html+=`🚴 Todos son del mismo equipo: <b>${escapeHtml(teams[0])}</b>.<br>`;
  const cats=[...new Set(sorted.map(r=>r.cat))];
  if(cats.length===1)html+=`🏷️ Todos compiten en categoría <b>${escapeHtml(cats[0])}</b>.`;
  else html+=`🏷️ Hay <b>${cats.length} categorías</b>: ${cats.map(c=>escapeHtml(c)).join(', ')}.`;
  el.innerHTML=html;
}
// ===== FIN BLOQUE COMPARATIVO =====

// ===== BLOQUE TÁCTICA Y VALIDACIÓN JS =====
function detectAnomalies(){
  const list=$('anomalyList');
  const summary=$('validacionSummary');
  const ok=$('validacionOk');
  if(!list || !riders.length) return;
  
  let anomalies=[];
  const bibs=new Map();
  
  riders.forEach(r=>{
    // 1. Tiempo faltante o inválido
    if(r.totalSeconds==null || r.totalSeconds===0){
      anomalies.push({type:'error',msg:`<b>Tiempo no detectado</b> para ${r.name} (#${r.bib})`,sub:'Aparece sin tiempo o gap. Revisa el origen de datos.',rider:r});
    }
    // 2. Dorsales duplicados
    const b=String(r.bib);
    if(b && b!=='0'){
      if(bibs.has(b)) anomalies.push({type:'warn',msg:`<b>Dorsal duplicado</b>: #${b}`,sub:`Detectado en ${r.name} y ${bibs.get(b).name}`,rider:r});
      else bibs.set(b, r);
    }
    // 3. Posición inconsistente
    if(r.pos > riders.length+5){
      anomalies.push({type:'warn',msg:`<b>Salto de posición</b>: ${r.name} (#${r.bib}) está en P${r.pos}`,sub:`Hay ${riders.length} corredores pero su puesto es muy alto.`,rider:r});
    }
  });

  if(!anomalies.length){
    list.innerHTML=''; summary.style.display='none'; ok.style.display='block';
    return;
  }

  ok.style.display='none';
  summary.style.display='block';
  summary.innerHTML=`🔍 Detectadas <b>${anomalies.length} anomalías</b> en los datos. Pulsa en corregir para intentar subsanarlas.`;
  
  list.innerHTML=anomalies.map(a=>`
    <div class="anomaly-item ${a.type==='warn'?'warn':''}">
      <span class="anomaly-icon">${a.type==='warn'?'⚠️':'🚨'}</span>
      <div class="anomaly-info">
        <b>${a.msg}</b>
        <span>${a.sub}</span>
      </div>
      <button class="anomaly-action" onclick="openManualEdit('${escapeAttr(getRiderKey(a.rider))}')">✏️ Corregir</button>
    </div>
  `).join('');
}

function openManualEdit(key){
  const r=riders.find(x=>getRiderKey(x)===key);
  if(!r) return;
  const newTime=prompt(`Corregir tiempo para ${r.name} (#${r.bib}).\nFormato actual: ${r.time||'vacío'}\nIntroduce nuevo tiempo (ej: 2:34:56 o a 5:20):`, r.time||'');
  if(newTime!==null){
    r.time=newTime;
    riders=enrichRiders(riders);
    detectAnomalies();
    renderAll();
    alert('Datos actualizados.');
  }
}

function renderTactica(){
  const myTeamName=localStorage.getItem('myTeam');
  const estado=$('tacticaEstado');
  const rival=$('tacticaRival');
  const zona=$('tacticaZona');

  // Fase 2 no-bloqueo: si entras a Estrategia sin prueba cargada, mostramos
  // un estado vacío amable en lugar de bloquear o redirigir.
  if(!riders || !riders.length){
    if(estado) estado.textContent='Sin prueba cargada';
    if(rival)  rival.textContent='---';
    if(zona)   zona.textContent='---';
    const obj = $('tacticaObjetivos');
    if(obj) obj.innerHTML = `<div style="background:#fef3c7;border:1px solid #fcd34d;color:#78350f;border-radius:10px;padding:14px 16px;font-size:13px;font-weight:600;line-height:1.5">
      📋 La Estrategia se calcula sobre una prueba concreta. <br>
      <button onclick="showView('view-historial')" style="margin-top:10px;background:#1f6feb;color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;font-size:12px;cursor:pointer">📁 Elegir prueba del histórico</button>
    </div>`;
    const list = $('tacticaRivalList'); if(list) list.innerHTML='';
    return;
  }

  renderCatSelectorsAll();

  const catRiders=getTeamRankingFilteredRiders();
  const myRiders=catRiders.filter(r=>r.team===myTeamName);
  const catLabel=getTeamRankingCategoryLabel();

  if(!myTeamName||myRiders.length===0){
    // ── Fase 2 no-bloqueo: mostramos estado GLOBAL en lugar de bloquear ──
    const teamStats=getOfficialTeamRanking();
    const totalTeams=teamStats.length;
    if(!totalTeams){
      estado.textContent='Sin datos';
      rival.textContent='---';
      zona.textContent='---';
      $('tacticaObjetivos').innerHTML=`<p class="help" style="padding:10px">Carga una clasificación para ver el plan táctico.</p>`;
      $('tacticaRivalList').innerHTML='';
      return;
    }
    const topTeam = teamStats[0];
    estado.textContent = `Vista global · ${totalTeams} equipos en ${escapeHtml(catLabel)}`;
    rival.textContent = topTeam ? `1º ${topTeam.team}` : '---';
    zona.textContent = 'Sin equipo configurado';
    const chipReason = !myTeamName
      ? `Estás viendo datos <strong>globales</strong>. <span onclick="document.getElementById('gfMyTeam')?.focus()" style="cursor:pointer;text-decoration:underline">Configura tu equipo</span> en la barra de filtros para activar el plan táctico personalizado.`
      : `Tu equipo <strong>${escapeHtml(myTeamName)}</strong> no tiene corredores en ${escapeHtml(catLabel)}. Mientras tanto se muestra ranking global.`;
    $('tacticaObjetivos').innerHTML = `<div style="background:#fef3c7;border:1px solid #fcd34d;color:#78350f;border-radius:8px;padding:10px 12px;font-size:12px;font-weight:600;margin:8px 0">⚙️ ${chipReason}</div>`;
    // Listado de top 5 equipos como referencia global
    const top5 = teamStats.slice(0,5);
    $('tacticaRivalList').innerHTML = top5.length
      ? `<div style="font-size:11px;color:#475569;font-weight:700;text-transform:uppercase;margin:8px 0 4px">🏁 Top equipos en ${escapeHtml(catLabel)}</div>` + top5.map((t,i)=>`<div style="padding:6px 10px;border-radius:7px;background:${i===0?'#dcfce7':'#fff'};border:1px solid #e5e7eb;margin-bottom:4px;font-size:12px;display:flex;justify-content:space-between"><strong>${i+1}º ${escapeHtml(t.team)}</strong><span style="color:#475569">${t.points||'—'} pts</span></div>`).join('')
      : '';
    return;
  }

  const teamStats=getOfficialTeamRanking();
  const myIdx=teamStats.findIndex(x=>x.team===myTeamName);
  const myTeamData=myIdx>=0?teamStats[myIdx]:null;
  const totalTeams=teamStats.length;
  const teamRank=myIdx+1;
  const totalRiders=catRiders.length;
  const bestPos=Math.min(...myRiders.map(r=>r.pos));
  const worstPos=Math.max(...myRiders.map(r=>r.pos));
  const spread=worstPos-bestPos;
  const top10Count=myRiders.filter(r=>r.pos<=10).length;
  const top20Count=myRiders.filter(r=>r.pos<=20).length;
  const myTop3=myRiders.slice().sort((a,b)=>a.pos-b.pos).slice(0,3);
  const myScore=myTop3.reduce((s,r)=>s+r.pos,0);
  const rivalTeam=myIdx>0?teamStats[myIdx-1]:null;
  const teamBehind=myIdx<totalTeams-1?teamStats[myIdx+1]:null;
  const scoreGap=rivalTeam?(myScore-rivalTeam.score):0;
  const scoreAdvantage=teamBehind?(teamBehind.score-myScore):0;
  const teamPercentile=Math.round((1-(myIdx/totalTeams))*100);

  let estadoLabel,estadoColor,estadoEmoji;
  if(teamRank===1){estadoLabel='Líder';estadoColor='#065f46';estadoEmoji='🥇';}
  else if(teamPercentile>=70){estadoLabel='Muy bueno';estadoColor='#0b6e4f';estadoEmoji='🟢';}
  else if(teamPercentile>=45){estadoLabel='En zona media';estadoColor='#b54708';estadoEmoji='🟡';}
  else{estadoLabel='Mejorable';estadoColor='#b42318';estadoEmoji='🔴';}

  const hasEnoughRiders=myTop3.length>=3;
  const scoreLabel=hasEnoughRiders
    ?`Score: ${myScore} pts · ${teamRank}º de ${totalTeams} equipos`
    :`Solo ${myTop3.length} corredor${myTop3.length!==1?'es':''} · ${teamRank}º (incompleto)`;

  estado.innerHTML=`<span style="color:${estadoColor};font-size:1.05em">${estadoEmoji} ${estadoLabel}</span><br><small style="font-size:13px;color:#667085">${scoreLabel}</small>`;

  if(rivalTeam){
    rival.innerHTML=`<span style="font-size:0.85em">${escapeHtml(rivalTeam.team)}</span><br><small style="font-size:13px;color:#667085">Os separan <b>${scoreGap} puntos</b> de score (suma top 3)</small>`;
  } else {
    rival.innerHTML=`<span style="color:#065f46">¡Líderes! 🏆</span><br><small style="font-size:13px;color:#667085">El mejor score de equipos</small>`;
  }

  if(rivalTeam&&scoreGap>0){
    const weakest=myTop3[myTop3.length-1];
    const targetPos=weakest?weakest.pos-scoreGap:null;
    zona.innerHTML=`<span style="font-size:0.85em">${escapeHtml(weakest?.name||'—')} al puesto ~${targetPos>0?targetPos:'?'}</span><br><small style="font-size:13px;color:#667085">Tu 3er ciclista necesita remontar ${scoreGap} pos. para superar a ${escapeHtml(rivalTeam.team)}</small>`;
  } else if(!rivalTeam){
    zona.innerHTML=`<span style="color:#065f46">Defender ventaja</span><br><small style="font-size:13px;color:#667085">${teamBehind?`${escapeHtml(teamBehind.team)} está a ${scoreAdvantage} pts`:'---'}</small>`;
  } else {
    zona.innerHTML=`<span style="color:#065f46">Score igualado</span><br><small style="font-size:13px;color:#667085">Cualquier movimiento puede cambiar el ranking</small>`;
  }

  const spreadQuality=spread<=10?'✅ Muy cohesionado':spread<=20?'⚠️ Dispersión moderada':'🔴 Alta dispersión';
  const spreadExplain=spread<=10?'Tu equipo compite de forma uniforme. Eso es una fortaleza táctica.':spread<=20?'Hay diferencia notable entre tu mejor y peor corredor.':'Tu equipo está muy disperso. Estudia si los corredores de cola pueden remontar.';
  const top3Names=myTop3.map(r=>`${r.name} (${r.pos}º)`).join(', ');

  let objetivosHTML=`<div style="padding:4px 10px">`;

  objetivosHTML+=`
    <div style="background:#f8fbff;border:1px dashed #84caff;border-radius:12px;padding:10px 14px;margin-bottom:10px;font-size:13px">
      <b style="color:#0b2f6b">ℹ️ Categoría: ${escapeHtml(catLabel)} · Ranking por suma top 3</b>
      <p style="margin:5px 0 0;color:#374151;line-height:1.45">Tus 3 que cuentan: <b>${escapeHtml(top3Names)}</b> → Score: <b>${myScore}</b>.</p>
    </div>`;

  if(rivalTeam){
    const rivalTop3=rivalTeam.riders.slice().sort((a,b)=>a.pos-b.pos).slice(0,3);
    const rivalTop3Names=rivalTop3.map(r=>`${r.name} (${r.pos}º)`).join(', ');
    objetivosHTML+=`
    <div style="background:#eff8ff;border:1px solid #84caff;border-radius:12px;padding:12px 14px;margin-bottom:10px">
      <b style="color:#0b2f6b;font-size:15px">🎯 Superar a ${escapeHtml(rivalTeam.team)}</b>
      <p style="margin:6px 0 0;color:#374151;font-size:14px;line-height:1.5">
        Su score: <b>${rivalTeam.score}</b> (${escapeHtml(rivalTop3Names)}). El tuyo: <b>${myScore}</b>. Gap: <b>${scoreGap} puntos</b>.
        ${scoreGap<=3?'⚡ Gap mínimo. Con que uno de tus top3 mejore 1-3 puestos, les superas.':`Tu 3er corredor (${escapeHtml(myTop3[2]?.name||'—')}, ${myTop3[2]?.pos}º) debe subir ${scoreGap} posiciones.`}
      </p>
    </div>`;
  }

  objetivosHTML+=`
    <div style="background:#ecfdf3;border:1px solid #6ee7b7;border-radius:12px;padding:12px 14px;margin-bottom:10px">
      <b style="color:#065f46;font-size:15px">🏆 Proteger a ${escapeHtml(myTop3[0]?.name||'tu líder')} (${bestPos}º)</b>
      <p style="margin:6px 0 0;color:#374151;font-size:14px;line-height:1.5">
        ${top10Count>0?`<b>${top10Count} corredor${top10Count>1?'es':''} en el Top 10</b>.`:top20Count>0?`<b>${top20Count} en el Top 20</b>.`:'Trabaja para meter corredores en el Top 20.'}
        Proteger este puesto tiene impacto directo en el score.
      </p>
    </div>`;

  objetivosHTML+=`
    <div style="background:#fff;border:1px solid #d0d5dd;border-radius:12px;padding:12px 14px;margin-bottom:10px">
      <b style="color:#182230;font-size:15px">📐 Cohesión: ${spreadQuality}</b>
      <p style="margin:6px 0 0;color:#374151;font-size:14px;line-height:1.5">${spreadExplain}</p>
      <p style="margin:6px 0 0;color:#667085;font-size:13px">Mejor: ${bestPos}º · Peor: ${worstPos}º · Spread: <b>${spread} pos.</b></p>
    </div>`;

  if(teamBehind){
    objetivosHTML+=`
    <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:12px;padding:12px 14px">
      <b style="color:#92400e;font-size:15px">🛡️ Ojo con ${escapeHtml(teamBehind.team)} (${teamBehind.rank}º)</b>
      <p style="margin:6px 0 0;color:#374151;font-size:14px;line-height:1.5">
        A solo <b>${scoreAdvantage} puntos</b> por detrás.
        ${scoreAdvantage<=3?'⚡ Gap muy pequeño. Cuidado.':'Tienes margen pero no te confíes.'}
      </p>
    </div>`;
  }

  objetivosHTML+=`</div>`;
  $('tacticaObjetivos').innerHTML=objetivosHTML;

  const threats=[];
  myRiders.forEach(myR=>{
    catRiders.forEach(r=>{
      if(r.team===myTeamName) return;
      const gap=r.pos-myR.pos;
      if(Math.abs(gap)<=5) threats.push({...r,myRider:myR,gap});
    });
  });
  const uniqueThreats=[];
  const seen=new Set();
  threats.sort((a,b)=>Math.abs(a.gap)-Math.abs(b.gap)).forEach(t=>{
    const key=t.name+t.team;
    if(!seen.has(key)){seen.add(key);uniqueThreats.push(t);}
  });
  const topThreats=uniqueThreats.slice(0,10);
  const myTop3Keys=new Set(myTop3.map(r=>r.name+r.team));

  if(!topThreats.length){
    $('tacticaRivalList').innerHTML=`<p style="padding:10px;color:#667085">No hay rivales directos a ±5 posiciones.</p>`;
  } else {
    $('tacticaRivalList').innerHTML=`
      <p style="font-size:13px;color:#667085;padding:4px 2px 8px">Rivales a <b>5 posiciones o menos</b> de alguno de los tuyos. 🔑 = afecta al score de equipo.</p>
      <div style="overflow-x:auto">
      <table style="width:100%;font-size:13px;border-collapse:collapse">
        <thead><tr style="background:#f9fafb">
          <th style="padding:8px 10px;text-align:left;border-bottom:1px solid #eaecf0;font-size:11px;text-transform:uppercase;color:#475467">Rival</th>
          <th style="padding:8px 10px;text-align:left;border-bottom:1px solid #eaecf0;font-size:11px;text-transform:uppercase;color:#475467">Equipo</th>
          <th style="padding:8px 10px;text-align:center;border-bottom:1px solid #eaecf0;font-size:11px;text-transform:uppercase;color:#475467">Pos.</th>
          <th style="padding:8px 10px;text-align:left;border-bottom:1px solid #eaecf0;font-size:11px;text-transform:uppercase;color:#475467">Tu corredor</th>
          <th style="padding:8px 10px;text-align:left;border-bottom:1px solid #eaecf0;font-size:11px;text-transform:uppercase;color:#475467">Diferencia</th>
          <th style="padding:8px 10px;text-align:left;border-bottom:1px solid #eaecf0;font-size:11px;text-transform:uppercase;color:#475467">Impacto</th>
        </tr></thead>
        <tbody>
          ${topThreats.map(t=>{
            const isAhead=t.gap<0;
            const myRiderCountsForScore=myTop3Keys.has(t.myRider.name+t.myRider.team);
            const urgencia=Math.abs(t.gap)<=2
              ?'<span style="background:#fee2e2;color:#991b1b;padding:2px 8px;border-radius:999px;font-weight:800;font-size:11px">🔴 Duelo directo</span>'
              :'<span style="background:#fffbeb;color:#92400e;padding:2px 8px;border-radius:999px;font-weight:800;font-size:11px">⚠️ Vigilar</span>';
            const scoreImpact=myRiderCountsForScore
              ?'<span style="color:#7c3aed;font-weight:800;font-size:12px">🔑 Score</span>'
              :'<span style="color:#9ca3af;font-size:12px">Individual</span>';
            return `<tr style="border-bottom:1px solid #f2f4f7">
              <td style="padding:8px 10px"><b>${escapeHtml(t.name)}</b></td>
              <td style="padding:8px 10px;color:#667085;font-size:12px">${escapeHtml(t.team)}</td>
              <td style="padding:8px 10px;font-weight:700;color:#0b2f6b;text-align:center">${t.pos}º</td>
              <td style="padding:8px 10px;color:${myRiderCountsForScore?'#1d4ed8':'#047857'};font-weight:700">${escapeHtml(t.myRider.name)} (${t.myRider.pos}º)</td>
              <td style="padding:8px 10px;font-weight:700;color:${isAhead?'#b42318':'#065f46'}">${isAhead?'▲ '+Math.abs(t.gap)+' por delante':'▼ '+t.gap+' por detrás'}</td>
              <td style="padding:8px 10px">${urgencia} ${scoreImpact}</td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>
      </div>`;
  }

  // ── ALERTAS DE MARCAJE ──────────────────────────────────────────────────
  const alertas = [];

  // 1. Análisis numérico en el Top 10
  const top10ByTeam = {};
  catRiders.filter(r => r.pos <= 10).forEach(r => {
    top10ByTeam[r.team] = (top10ByTeam[r.team] || 0) + 1;
  });
  const top10Sorted = Object.entries(top10ByTeam).sort((a,b) => b[1]-a[1]);
  const dominantTeam = top10Sorted[0];
  const dominantTeamName = dominantTeam ? dominantTeam[0] : null;
  const dominantTeamCount = dominantTeam ? dominantTeam[1] : 0;
  const myTop10CountFull = top10ByTeam[myTeamName] || 0;

  if (dominantTeamName && dominantTeamName !== myTeamName && dominantTeamCount >= 3 && myTop10CountFull < dominantTeamCount) {
    alertas.push({
      tipo: 'danger', icono: '🚨',
      titulo: 'Inferioridad numérica en el corte ganador',
      texto: `${escapeHtml(dominantTeamName)} tiene <b>${dominantTeamCount} corredores en el Top 10</b> frente a tus <b>${myTop10CountFull}</b>. Superioridad numérica rival en la zona decisiva.`
    });
  } else if (myTop10CountFull > 0 && dominantTeamName === myTeamName) {
    alertas.push({
      tipo: 'ok', icono: '✅',
      titulo: 'Superioridad numérica en el corte ganador',
      texto: `Lideras el Top 10 con <b>${myTop10CountFull} corredor${myTop10CountFull > 1 ? 'es' : ''}</b>. Superioridad táctica en la zona de decisión.`
    });
  } else if (myTop10CountFull === 0 && catRiders.length > 0) {
    alertas.push({
      tipo: 'warn', icono: '⚠️',
      titulo: 'Sin presencia en el Top 10',
      texto: `Ninguno de tus corredores está entre los 10 primeros. Difícil influir en la táctica desde las posiciones de cabeza.`
    });
  }

  // 2. Corredor líder aislado (sin compañeros a ±10 posiciones)
  const leaderRider = myRiders.slice().sort((a,b) => a.pos-b.pos)[0];
  if (leaderRider && myRiders.length > 1) {
    const companions = myRiders.filter(r => r.name !== leaderRider.name && Math.abs(r.pos - leaderRider.pos) <= 10);
    if (companions.length === 0) {
      alertas.push({
        tipo: 'warn', icono: '⚠️',
        titulo: `${escapeHtml(leaderRider.name)} está aislado`,
        texto: `Tu líder (${leaderRider.pos}º) no tiene compañeros a menos de 10 posiciones. Sin apoyo en la zona de decisión.`
      });
    }
  }

  // 3. Opción de podio o corredor en podio
  if (bestPos <= 6) {
    const gap3 = bestPos - 3;
    if (gap3 <= 0) {
      alertas.push({
        tipo: 'ok', icono: '🥇',
        titulo: '¡Corredor en el podio!',
        texto: `${escapeHtml(leaderRider?.name || 'Tu líder')} está en <b>${bestPos}º</b>. Protege esta posición a toda costa.`
      });
    } else {
      alertas.push({
        tipo: 'info', icono: '🎯',
        titulo: 'Opción real de podio',
        texto: `${escapeHtml(leaderRider?.name || 'Tu líder')} está en <b>${bestPos}º</b>, a solo <b>${gap3} posición${gap3 > 1 ? 'es' : ''}</b> del podio. Momento de activar el ataque.`
      });
    }
  }

  // 4. Gap crítico con el equipo rival
  if (rivalTeam && scoreGap > 0 && scoreGap <= 3) {
    alertas.push({
      tipo: 'danger', icono: '⚡',
      titulo: 'Gap crítico con el equipo líder',
      texto: `Solo <b>${scoreGap} punto${scoreGap > 1 ? 's' : ''} de score</b> os separan de ${escapeHtml(rivalTeam.team)}. Un cambio de posición puede voltear el ranking de equipos.`
    });
  }

  // 5. Equipo rival muy agrupado (control de carrera)
  if (rivalTeam && rivalTeam.riders.length >= 3) {
    const rSorted = rivalTeam.riders.slice().sort((a,b) => a.pos-b.pos);
    const rSpread = rSorted[rSorted.length-1].pos - rSorted[0].pos;
    if (rSpread <= 8) {
      alertas.push({
        tipo: 'warn', icono: '🛡️',
        titulo: `${escapeHtml(rivalTeam.team)} está muy agrupado`,
        texto: `Sus corredores están concentrados entre el ${rSorted[0].pos}º y el ${rSorted[rSorted.length-1].pos}º. Equipo rival en posición de control total de la carrera.`
      });
    }
  }

  // 6. Ventaja sólida como líderes
  if (!rivalTeam && scoreAdvantage >= 5) {
    alertas.push({
      tipo: 'ok', icono: '🏆',
      titulo: 'Ventaja sólida en la cima',
      texto: `Lideras por <b>${scoreAdvantage} puntos</b> sobre ${escapeHtml(teamBehind?.team || 'el segundo')}. Gestionar esfuerzos y proteger las posiciones clave.`
    });
  }

  const alertasEl = $('tacticaAlertas');
  if (alertas.length === 0) {
    alertasEl.innerHTML = `<p style="padding:10px;color:#667085">Sin alertas destacadas para esta clasificación.</p>`;
  } else {
    alertasEl.innerHTML = `<div class="alerta-grid">${alertas.map(a => `
      <div class="alerta-item alerta-${a.tipo}">
        <span style="font-size:22px;line-height:1;flex-shrink:0">${a.icono}</span>
        <div>
          <div style="font-weight:700;color:#182230;margin-bottom:3px">${a.titulo}</div>
          <div style="color:#374151">${a.texto}</div>
        </div>
      </div>`).join('')}
    </div>`;
  }

  // ── INFORME DE DIRECTOR ─────────────────────────────────────────────────
  const _now = new Date();
  const _fechaHoy = _now.toLocaleDateString('es-ES', {day:'2-digit',month:'2-digit',year:'numeric'});
  const _raceName = ($('raceName')?.value || '').trim();
  const _raceDate = ($('raceDate')?.value || '').trim();
  const _top3Str = myTop3.map((r,i) => `  ${i+1}. ${r.name} (${r.pos}º)`).join('\n');

  let _accion = '';
  if (!rivalTeam) {
    _accion = `Somos líderes. Gestionar esfuerzos y defender ventaja de ${scoreAdvantage} pts sobre ${teamBehind?.team || 'el 2º'}.`;
  } else if (scoreGap <= 3) {
    _accion = `Gap crítico de ${scoreGap} pts. Un movimiento puede cambiarlo todo — ATACAR AHORA.`;
  } else {
    const _target = myTop3[2] || myTop3[myTop3.length-1];
    _accion = `${_target?.name || 'Nuestro 3er corredor'} debe subir ${scoreGap} posiciones para superar a ${rivalTeam.team}.`;
  }

  const _alertaLines = alertas.length > 0
    ? `\n🚨 ALERTAS:\n` + alertas.map(a => `  • ${a.titulo}`).join('\n')
    : '';

  const _topRivalTop10 = top10Sorted.filter(([t]) => t !== myTeamName)[0];
  const _rivalTop10Line = _topRivalTop10 && _topRivalTop10[1] >= 2
    ? `\n⚠️  Rival ${_topRivalTop10[0]} tiene ${_topRivalTop10[1]} en Top 10.`
    : '';

  const _podioActual = catRiders.filter(r => r.pos <= 3).sort((a,b) => a.pos-b.pos);
  const _podioStr = _podioActual.length
    ? _podioActual.map(r => `  ${r.pos}. ${r.name} (${r.team})`).join('\n')
    : '  Sin datos de podio';

  const _perdimosOPodioLine = (bestPos > 3 && bestPos <= 8)
    ? `\n😤 PERDIMOS EL PODIO: ${leaderRider?.name || 'Nuestro líder'} a ${bestPos - 3} pos. del podio.`
    : '';

  const _pruebaLine = _raceName ? `🏁 PRUEBA: ${_raceName}` : `📅 FECHA: ${_fechaHoy}`;
  const _fechaLine = _raceName && _raceDate ? `📅 FECHA: ${_raceDate}` : (_raceName ? `📅 ${_fechaHoy}` : '');

  const informeTexto =
`📋 INFORME DE DIRECTOR — ${_fechaHoy}
${_pruebaLine}${_fechaLine ? '\n'+_fechaLine : ''}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🏆 POSICIÓN: ${teamRank}º de ${totalTeams} equipos (Score: ${myScore} pts)
👑 MEJOR: ${leaderRider?.name || '—'} (${bestPos}º)
📊 NUESTRO TOP 3:
${_top3Str}
🥇 PODIO GENERAL:
${_podioStr}
⚔️  RIVAL: ${rivalTeam ? `${rivalTeam.team} (+${scoreGap} pts de gap)` : '¡Líderes! Sin rival delante'}${_rivalTop10Line}${_perdimosOPodioLine}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🎯 ACCIÓN: ${_accion}${_alertaLines}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
#ciclismo #director #tactica`;

  $('tacticaInformePanel').innerHTML = `
    <textarea id="informeTextoArea" class="informe-textarea" readonly>${informeTexto.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea>
    <button class="informe-copy-btn" id="informeCopyBtn" onclick="(function(btn){
      const ta=document.getElementById('informeTextoArea');
      const txt=ta.value;
      if(navigator.clipboard&&navigator.clipboard.writeText){
        navigator.clipboard.writeText(txt).then(()=>{
          btn.textContent='✅ ¡Copiado!';btn.classList.add('copied');
          setTimeout(()=>{btn.textContent='📋 Copiar para WhatsApp';btn.classList.remove('copied');},2500);
        });
      } else {
        ta.select();ta.setSelectionRange(0,99999);
        document.execCommand('copy');
        btn.textContent='✅ ¡Copiado!';btn.classList.add('copied');
        setTimeout(()=>{btn.textContent='📋 Copiar para WhatsApp';btn.classList.remove('copied');},2500);
      }
    })(this)">📋 Copiar para WhatsApp</button>`;
}
// ===== FIN BLOQUE TÁCTICA Y VALIDACIÓN JS =====

// ===== TOAST / NOTIFICACIÓN ===================================================
function showToast(msg, type='ok', duration=3500){
  let wrap=document.getElementById('_toastWrap');
  if(!wrap){
    wrap=document.createElement('div');
    wrap.id='_toastWrap';
    wrap.style.cssText='position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:9999;display:flex;flex-direction:column;align-items:center;gap:8px;pointer-events:none';
    document.body.appendChild(wrap);
  }
  const t=document.createElement('div');
  const bg=type==='ok'?'#065f46':type==='warn'?'#92400e':'#b42318';
  const icon=type==='ok'?'✅':type==='warn'?'⚠️':'❌';
  t.style.cssText=`background:${bg};color:#fff;padding:11px 22px;border-radius:14px;font-size:14px;font-weight:600;box-shadow:0 6px 20px rgba(0,0,0,.25);opacity:0;transition:opacity .25s;white-space:nowrap;pointer-events:none`;
  t.innerHTML=`${icon} ${msg}`;
  wrap.appendChild(t);
  requestAnimationFrame(()=>{t.style.opacity='1';});
  setTimeout(()=>{
    t.style.opacity='0';
    setTimeout(()=>t.remove(),300);
  },duration);
}
// ===== NORMALIZACIÓN DE NOMBRES DE EQUIPO =====
const _TEAM_ALIASES_KEY = 'cdTeamAliasesV1';

function _loadTeamAliases() {
  try { return JSON.parse(localStorage.getItem(_TEAM_ALIASES_KEY) || '[]'); }
  catch(e) { return []; }
}
function _saveTeamAliases(arr) {
  localStorage.setItem(_TEAM_ALIASES_KEY, JSON.stringify(arr));
}

// Extrae el año de la carrera cargada actualmente
function _getRaceYear() {
  const raw = ($('raceDate')?.value || '').trim();
  if (!raw) return new Date().getFullYear();
  // Intenta formato DD/MM/YYYY o YYYY-MM-DD
  const m1 = raw.match(/(\d{4})/);
  return m1 ? parseInt(m1[1]) : new Date().getFullYear();
}

// Devuelve el nombre canónico si existe alias guardado, o el original.
// Sin parámetro: busca alias del año de la carrera cargada + globales (year=0).
function getCanonicalTeam(rawName) {
  const year = _getRaceYear();
  const aliases = _loadTeamAliases();
  // Busca alias específico del año actual O global (year=0)
  const hit = aliases.find(a =>
    a.alias.toLowerCase() === rawName.toLowerCase() &&
    a.canonical !== '__ignored__' &&
    (a.year === year || a.year === 0)
  );
  return hit ? hit.canonical : rawName;
}

// Clave normalizada para comparación
function _teamNormKey(name) {
  return (name || '').toUpperCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[^A-Z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

// Similitud entre dos nombres de equipo (0–1)
function _teamSimilarity(a, b) {
  const na = _teamNormKey(a);
  const nb = _teamNormKey(b);
  if (na === nb) return 1.0;
  // Uno contiene al otro (caso "IKASCOLA AEL" vs "IKASCOLA AEL 1,5")
  if (na.startsWith(nb + ' ') || nb.startsWith(na + ' ') ||
      na.startsWith(nb)       || nb.startsWith(na)) return 0.95;
  // Jaccard sobre tokens de más de 2 letras
  const ta = new Set(na.split(' ').filter(t => t.length > 2));
  const tb = new Set(nb.split(' ').filter(t => t.length > 2));
  if (ta.size === 0 || tb.size === 0) return 0;
  const inter = [...ta].filter(t => tb.has(t)).length;
  const union = new Set([...ta, ...tb]).size;
  return inter / union;
}

// Helper interno: calcula pares similares de una lista de nombres de equipo
function _findDupPairs(teams, scopeYear, existingAliases) {
  const pairs = [];
  const seen  = new Set();

  for (let i = 0; i < teams.length; i++) {
    for (let j = i + 1; j < teams.length; j++) {
      const sim = _teamSimilarity(teams[i], teams[j]);
      if (sim < 0.75) continue;
      const key = [teams[i], teams[j]].sort().join('|||');
      if (seen.has(key)) continue;
      seen.add(key);

      // ¿Ya resuelto o ignorado? (año específico o global)
      const alreadyHandled = existingAliases.some(a =>
        (a.alias.toLowerCase() === teams[i].toLowerCase() ||
         a.alias.toLowerCase() === teams[j].toLowerCase()) &&
        (a.year === scopeYear || a.year === 0)
      );
      if (alreadyHandled) continue;

      // Frecuencia en historial del mismo año
      let histHint = null;
      if (_cachedHistory) {
        const scopeRaces = scopeYear
          ? _cachedHistory.filter(h => h.raceDate &&
              new Date(h.raceDate).getFullYear() === scopeYear)
          : _cachedHistory;
        const countA = scopeRaces.filter(h =>
          h.riders && h.riders.some(r =>
            _teamNormKey(r.team) === _teamNormKey(teams[i]))).length;
        const countB = scopeRaces.filter(h =>
          h.riders && h.riders.some(r =>
            _teamNormKey(r.team) === _teamNormKey(teams[j]))).length;
        if (countA > 0 || countB > 0) {
          const bestHist = countA >= countB ? teams[i] : teams[j];
          histHint = {name: bestHist, countA, countB,
            nameA: teams[i], nameB: teams[j], totalRaces: scopeRaces.length};
        }
      }

      const shorter   = teams[i].length <= teams[j].length ? teams[i] : teams[j];
      const suggested = histHint ? histHint.name : shorter;
      const alias     = suggested === teams[i] ? teams[j] : teams[i];

      pairs.push({alias, canonical: suggested, sim, histHint,
                  teamA: teams[i], teamB: teams[j], scopeYear});
    }
  }
  return pairs.sort((a, b) => b.sim - a.sim);
}

// Detecta pares similares en la carrera actualmente cargada
function _detectDuplicateTeams() {
  if (!riders || riders.length === 0) return [];
  const teams   = [...new Set(riders.map(r => r.team).filter(Boolean))];
  const year    = _getRaceYear();
  const aliases = _loadTeamAliases();
  return _findDupPairs(teams, year, aliases);
}

// Detecta pares similares en todo el historial de Supabase (independiente de carrera cargada)
function _detectDuplicateTeamsInHistory() {
  if (!_cachedHistory || !_cachedHistory.length) return [];
  const allTeams = [...new Set(
    _cachedHistory.flatMap(h => (h.riders || []).map(r => r.team)).filter(Boolean)
  )];
  const aliases = _loadTeamAliases();
  return _findDupPairs(allTeams, null, aliases); // scopeYear=null → busca en todo el historial
}

// Fuerza re-render de la pestaña Evolución activa (para que el desplegable se actualice)
function _refreshEvolIfVisible() {
  try {
    const myTeam = localStorage.getItem('myTeam');
    if (!_evolHistory || !myTeam) return;
    const filtered = _evolFilterByYear(_evolHistory, _evolSelectedYear);
    if (_evolCurrentTab === 'team')    { _evolRenderTeam(filtered, myTeam); return; }
    if (_evolCurrentTab === 'rivals')  { _evolRenderRivals(filtered, myTeam); return; }
    if (_evolCurrentTab === 'riders')  { _evolRenderRiders(filtered, myTeam); return; }
  } catch(e) { /* silencioso */ }
}

// Unifica en la carrera cargada actualmente (renombra riders + guarda alias con año actual)
function mergeTeamNames(alias, canonical) {
  let count = 0;
  riders.forEach(r => { if (r.team === alias) { r.team = canonical; count++; } });
  const year = _getRaceYear();
  const saved = _loadTeamAliases().filter(a =>
    !(a.alias.toLowerCase() === alias.toLowerCase() && a.year === year));
  saved.push({alias, canonical, year});
  _saveTeamAliases(saved);
  // Feedback inmediato ANTES de los renders (para que aparezca aunque algún render falle)
  showToast(`✅ Unificado: "${alias}" → "${canonical}" (${count} corredor${count!==1?'es':''})`);
  try { renderAll(); } catch(e) {}
  try { renderTeamDupPanel(); } catch(e) {}
  try { renderTeamAliasesSaved(); } catch(e) {}
  _refreshEvolIfVisible();
}

// Unifica a nivel de historial completo (guarda alias global year=0, regenera desplegables)
function mergeTeamNamesHistory(alias, canonical) {
  const saved = _loadTeamAliases().filter(a =>
    !(a.alias.toLowerCase() === alias.toLowerCase() && a.year === 0));
  saved.push({alias, canonical, year: 0, scope: 'history'});
  _saveTeamAliases(saved);
  // También aplicar a riders actual si coincide
  riders.forEach(r => { if (r.team === alias) r.team = canonical; });
  // Feedback inmediato ANTES de los renders
  showToast(`✅ Alias guardado: "${alias}" → "${canonical}". Actualizado en Evolución.`);
  try { renderAll(); } catch(e) {}
  try { renderTeamDupPanel(); } catch(e) {}
  try { renderTeamAliasesSaved(); } catch(e) {}
  _refreshEvolIfVisible();
}

// Marcar par como "son distintos" (ignorar)
function ignoreTeamDup(teamA, teamB) {
  const year = _getRaceYear();
  const saved = _loadTeamAliases().filter(a =>
    !(a.alias.toLowerCase() === teamA.toLowerCase() && a.year === year));
  saved.push({alias: teamA, canonical: '__ignored__', year});
  _saveTeamAliases(saved);
  showToast(`Marcado: "${teamA}" y "${teamB}" son equipos distintos.`, 'warn');
  try { renderTeamDupPanel(); } catch(e) {}
  try { renderTeamAliasesSaved(); } catch(e) {}
}

// Borrar todos los alias del año actual
function clearTeamAliasesYear() {
  const year = _getRaceYear();
  if (!confirm(`¿Borrar todos los alias guardados para el año ${year}?`)) return;
  const aliases = _loadTeamAliases().filter(a => a.year !== year);
  _saveTeamAliases(aliases);
  renderTeamDupPanel();
  renderTeamAliasesSaved();
}

// Renderiza el panel de duplicados
// Serializa un valor para usarlo dentro de un atributo onclick="..." (escapa las comillas dobles)
function _qa(val) { return JSON.stringify(val).replace(/"/g, '&quot;'); }

function _renderDupItems(dups, mergeFn) {
  return dups.map(d => {
    const histLine = d.histHint
      ? `<div class="dup-history-hint">
          📚 ${d.histHint.totalRaces} carrera${d.histHint.totalRaces!==1?'s':''} en el historial:
          <b>${escapeHtml(d.histHint.nameA)}</b> aparece <b>${d.histHint.countA}x</b> ·
          <b>${escapeHtml(d.histHint.nameB)}</b> aparece <b>${d.histHint.countB}x</b>
          ${d.histHint.countA !== d.histHint.countB
            ? ` → <b style="color:#0b2f6b">Sugerencia: usar &quot;${escapeHtml(d.histHint.name)}&quot;</b>`
            : ' → Ambas frecuencias iguales'}
         </div>`
      : `<div class="dup-history-hint" style="color:#9ca3af">Sin datos de historial para comparar.</div>`;
    return `
    <div class="dup-team-item">
      <div class="dup-names-row">
        <span class="dup-name-a">${escapeHtml(d.teamA)}</span>
        <span style="color:#9ca3af;font-size:18px;font-weight:300">≈</span>
        <span class="dup-name-b">${escapeHtml(d.teamB)}</span>
        <span class="dup-sim-badge">${Math.round(d.sim*100)}% similitud</span>
      </div>
      ${histLine}
      <div class="dup-actions">
        <button class="dup-btn dup-btn-merge"
          onclick="${mergeFn}(${_qa(d.teamA)},${_qa(d.teamB)})">
          ✅ Usar <b style="margin-left:3px">${escapeHtml(d.teamB)}</b>
        </button>
        <button class="dup-btn dup-btn-swap"
          onclick="${mergeFn}(${_qa(d.teamB)},${_qa(d.teamA)})">
          🔄 Usar <b style="margin-left:3px">${escapeHtml(d.teamA)}</b>
        </button>
        <button class="dup-btn dup-btn-ignore"
          onclick="ignoreTeamDup(${_qa(d.teamA)},${_qa(d.teamB)})">
          ❌ Son equipos distintos
        </button>
      </div>
    </div>`;
  }).join('');
}

function renderTeamDupPanel() {
  const el = $('teamDupPanel');
  if (!el) return;

  const badge    = $('dupBadge');
  const raceDups = _detectDuplicateTeams();           // solo carrera cargada
  const histDups = _detectDuplicateTeamsInHistory();  // todo el historial Supabase
  const total    = raceDups.length + histDups.length;

  if (badge) {
    badge.textContent  = total;
    badge.style.display = total > 0 ? 'inline-flex' : 'none';
  }

  let html = '';

  // ── Sección 1: duplicados en carrera cargada ──────────────────────
  if (riders && riders.length > 0) {
    if (raceDups.length > 0) {
      html += `
        <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:12px;padding:10px 14px;margin-bottom:10px;font-size:13px">
          <b>📋 Clasificación cargada — ${raceDups.length} par${raceDups.length!==1?'es':''} similares</b>
          <span style="color:#374151"> · La unificación renombra el equipo en esta clasificación.</span>
        </div>
        ${_renderDupItems(raceDups, 'mergeTeamNames')}`;
    } else {
      html += `
        <div style="display:flex;align-items:center;gap:10px;padding:11px 14px;background:#ecfdf5;border-radius:12px;border:1px solid #6ee7b7;margin-bottom:10px">
          <span style="font-size:20px">✅</span>
          <span style="font-size:13px;color:#065f46;font-weight:600">Sin duplicados en la clasificación cargada.</span>
        </div>`;
    }
  } else {
    html += `<p class="help" style="padding:4px 2px 10px">Carga una clasificación para detectar duplicados en ella.</p>`;
  }

  // ── Sección 2: duplicados en el historial de Supabase ────────────
  html += `<div style="border-top:1px solid #eaecf0;margin:12px 0 10px"></div>`;
  html += `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
    <b style="font-size:14px;color:#182230">🗄️ Historial Supabase</b>
    <button class="btn light" style="font-size:12px;padding:5px 12px" onclick="_loadHistoryAndRescan()">🔄 Cargar historial y re-escanear</button>
  </div>`;

  if (!_cachedHistory) {
    html += `<p class="help" style="padding:4px 2px">El historial no está cargado aún. Pulsa "Cargar historial y re-escanear".</p>`;
  } else if (histDups.length === 0) {
    html += `
      <div style="display:flex;align-items:center;gap:10px;padding:11px 14px;background:#ecfdf5;border-radius:12px;border:1px solid #6ee7b7">
        <span style="font-size:20px">✅</span>
        <span style="font-size:13px;color:#065f46;font-weight:600">Sin nombres similares en todo el historial. Todos los equipos son únicos.</span>
      </div>`;
  } else {
    html += `
      <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:12px;padding:10px 14px;margin-bottom:10px;font-size:13px">
        <b>⚠️ ${histDups.length} par${histDups.length!==1?'es':''} similares en el historial.</b>
        <span style="color:#374151"> La unificación afecta a cómo se muestran en <b>Evolución</b> y comparativas. No modifica Supabase.</span>
      </div>
      ${_renderDupItems(histDups, 'mergeTeamNamesHistory')}`;
  }

  el.innerHTML = html;
  renderTeamAliasesSaved();
}

// Carga el historial si no está disponible y re-escanea
async function _loadHistoryAndRescan() {
  if (!_cachedHistory) {
    const btn = event?.target;
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Cargando...'; }
    await _ensureHistory();
    if (btn) { btn.disabled = false; btn.textContent = '🔄 Cargar historial y re-escanear'; }
  }
  renderTeamDupPanel();
}

// Renderiza la lista de alias guardados (año actual + globales)
function renderTeamAliasesSaved() {
  const cont = $('teamAliasesSaved');
  const list  = $('teamAliasesList');
  if (!cont || !list) return;
  const year = _getRaceYear();
  const aliases = _loadTeamAliases().filter(a => a.year === year || a.year === 0);
  if (aliases.length === 0) { cont.style.display = 'none'; return; }
  cont.style.display = 'block';
  list.innerHTML = aliases.map(a => {
    const scopeLabel = a.year === 0
      ? `<span style="background:#eff6ff;color:#1d4ed8;font-size:10px;font-weight:700;padding:1px 6px;border-radius:6px;margin-left:4px">GLOBAL</span>`
      : `<span style="background:#f2f4f7;color:#475467;font-size:10px;padding:1px 6px;border-radius:6px;margin-left:4px">${a.year}</span>`;
    return `
    <div class="dup-alias-row">
      <div style="display:flex;align-items:center;flex-wrap:wrap;gap:4px">
        <span style="color:#92400e;font-weight:600">${escapeHtml(a.alias)}</span>
        <span style="color:#9ca3af;margin:0 2px">→</span>
        ${a.canonical === '__ignored__'
          ? `<span style="color:#9ca3af;font-style:italic">ignorado (son distintos)</span>`
          : `<span style="color:#065f46;font-weight:600">${escapeHtml(a.canonical)}</span>`}
        ${scopeLabel}
      </div>
      <button class="dup-btn dup-btn-ignore" style="font-size:11px;padding:4px 10px"
        onclick="deleteTeamAlias(${_qa(a.alias)}, ${a.year})">🗑</button>
    </div>`;
  }).join('');
}

// Eliminar un alias concreto
function deleteTeamAlias(alias, year) {
  const aliases = _loadTeamAliases().filter(a =>
    !(a.alias.toLowerCase() === alias.toLowerCase() && a.year === year));
  _saveTeamAliases(aliases);
  renderTeamDupPanel();
  renderTeamAliasesSaved();
}
// ===== FIN NORMALIZACIÓN DE EQUIPOS =====

// getCanonicalCat: ya no usa aliases de categoría — devuelve el valor original
// (mantenida para compatibilidad con _cardCats y allCats que filtran sin rider name)
function getCanonicalCat(rawCat, year) { return rawCat || ''; }

// ===== CORRECCIÓN DE CATEGORÍA POR CICLISTA =====

/* Storage */
function _loadRiderCatOverrides(){
  try{return JSON.parse(localStorage.getItem('cdRiderCatV1')||'[]');}catch(e){return[];}
}
function _saveRiderCatOverrides(arr){
  try{localStorage.setItem('cdRiderCatV1',JSON.stringify(arr));}catch(e){}
}

/* Aplicar override por ciclista: devuelve la categoría correcta guardada, o la original */
function getRiderCorrectCat(riderName, year, rawCat){
  if(!rawCat) return rawCat;
  const y=year?parseInt(year):_getRaceYear();
  const nameKey=(riderName||'').trim().toLowerCase();
  const overrides=_loadRiderCatOverrides();
  const hit=overrides.find(o=>
    o.riderName.trim().toLowerCase()===nameKey &&
    parseInt(o.year)===y &&
    o.correctCat !== '__ignored__'
  );
  return hit ? hit.correctCat : rawCat;
}

/* Detectar ciclistas con categorías distintas en el mismo año */
function _detectRiderCatInconsistencies(year){
  const hist=_cachedHistory||[];
  const y=String(year||'');
  // Mapa: riderNameKey → {displayName, cats: {catName: [raceName, ...]}}
  const map={};
  hist.forEach(race=>{
    const raceYear=(_parseSpanishDate(race.raceDate)||'').slice(0,4);
    if(y && raceYear!==y) return;
    (race.riders||[]).forEach(r=>{
      if(!r.cat) return;
      const key=(r.name||'').trim().toLowerCase();
      if(!key) return;
      if(!map[key]) map[key]={displayName:r.name, cats:{}};
      // Usar nombre más largo como displayName
      if((r.name||'').length > map[key].displayName.length) map[key].displayName=r.name;
      const cat=(r.cat||'').trim();
      if(!map[key].cats[cat]) map[key].cats[cat]=[];
      map[key].cats[cat].push(race.raceName||race.id||'?');
    });
  });
  // Filtrar solo los que tienen >1 categoría distinta
  return Object.values(map)
    .filter(e=>Object.keys(e.cats).length>1)
    .map(e=>({
      displayName: e.displayName,
      cats: Object.entries(e.cats).map(([cat,races])=>({cat,count:races.length,races}))
        .sort((a,b)=>b.count-a.count)
    }))
    .sort((a,b)=>a.displayName.localeCompare(b.displayName));
}

/* Poblar selector de año */
function _populateRiderCatYearSel(){
  const sel=$('riderCatYear');
  if(!sel) return;
  const hist=_cachedHistory||[];
  const years=[...new Set(hist.map(h=>(_parseSpanishDate(h.raceDate)||'').slice(0,4)).filter(Boolean))].sort().reverse();
  const cur=sel.value;
  sel.innerHTML=years.map(y=>`<option value="${y}"${y===cur?'selected':''}>${y}</option>`).join('');
  if(!sel.value && years.length) sel.value=years[0];
}

/* Cargar historial y escanear */
async function _loadHistoryAndRescanRiderCats(){
  const btn=document.querySelector('[onclick="_loadHistoryAndRescanRiderCats()"]');
  if(btn){btn.disabled=true;btn.textContent='⏳ Cargando...';}
  await _ensureHistory();
  if(btn){btn.disabled=false;btn.textContent='🔄 Cargar historial';}
  _populateRiderCatYearSel();
  renderRiderCatPanel();
  renderRiderCatSaved();
}

/* Renderizar panel principal */
function renderRiderCatPanel(){
  const panel=$('riderCatPanel');
  if(!panel) return;
  if(!_cachedHistory||!_cachedHistory.length){
    panel.innerHTML=`<p class="help" style="padding:8px 2px">Pulsa "Cargar historial" para detectar inconsistencias de categoría por ciclista.</p>`;
    return;
  }
  const year=$('riderCatYear')?.value||'';
  const inconsistencies=_detectRiderCatInconsistencies(year);
  const badge=$('riderCatBadge');
  if(badge){
    badge.textContent=inconsistencies.length;
    badge.style.display=inconsistencies.length?'inline-flex':'none';
  }
  const overrides=_loadRiderCatOverrides();

  if(!inconsistencies.length){
    panel.innerHTML=`<div style="text-align:center;padding:20px;color:#065f46;background:#f0fdf4;border-radius:12px;font-weight:700">
      ✅ No se detectaron inconsistencias de categoría en ${year||'este período'}.
    </div>`;
    return;
  }

  panel.innerHTML=inconsistencies.map((item,idx)=>{
    const nameKey=item.displayName.trim().toLowerCase();
    const radioGroup=`rcat_${idx}`;
    const existing=overrides.find(o=>o.riderName.trim().toLowerCase()===nameKey&&parseInt(o.year)===(parseInt(year)||0));
    const catsHtml=item.cats.map(({cat,count,races})=>{
      const racesList=races.slice(0,3).map(r=>escapeHtml(r)).join(', ')+(races.length>3?` +${races.length-3} más`:'');
      return `
      <label class="ridercat-option${existing&&existing.correctCat===cat?' ridercat-selected':''}">
        <input type="radio" name="${radioGroup}" value="${escapeHtml(cat)}"
          ${existing&&existing.correctCat===cat?'checked':''}
          onchange="previewRiderCatSelect('${radioGroup}',${_qa(cat)})">
        <div class="ridercat-option-body">
          <span class="ridercat-catname">${escapeHtml(cat)}</span>
          <span class="ridercat-count">${count} carrera${count!==1?'s':''}</span>
          <span class="ridercat-races">${racesList}</span>
        </div>
      </label>`;
    }).join('');

    const savedBadge=existing&&existing.correctCat!=='__ignored__'
      ? `<span style="background:#dcfce7;color:#065f46;font-size:11px;font-weight:700;padding:2px 8px;border-radius:8px;margin-left:8px">✓ ${escapeHtml(existing.correctCat)}</span>`
      : '';

    return `
    <div class="dup-team-item" style="margin-bottom:14px">
      <div style="display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:10px">
        <span style="font-weight:800;color:#182230;font-size:14px">👤 ${escapeHtml(item.displayName)}</span>
        ${savedBadge}
      </div>
      <div style="margin-bottom:10px">${catsHtml}</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="dup-btn dup-btn-merge" onclick="saveRiderCatOverride(${_qa(item.displayName)},${_qa(year)},'${radioGroup}')">
          ✅ Confirmar selección
        </button>
        <button class="dup-btn dup-btn-ignore" onclick="ignoreRiderCatInconsistency(${_qa(item.displayName)},${_qa(year)})">
          Ignorar
        </button>
      </div>
    </div>`;
  }).join('');
}

/* Resaltar la opción seleccionada visualmente */
function previewRiderCatSelect(radioGroup, cat){
  document.querySelectorAll(`input[name="${radioGroup}"]`).forEach(r=>{
    const label=r.closest('label');
    if(label) label.classList.toggle('ridercat-selected', r.value===cat);
  });
}

/* Guardar override seleccionado */
function saveRiderCatOverride(riderName, year, radioGroup){
  const nameKey=riderName.trim().toLowerCase();
  const checked=document.querySelector(`input[name="${radioGroup}"]:checked`);
  if(!checked){showToast('⚠️ Selecciona primero una categoría.','warn');return;}
  const correctCat=checked.value;
  const y=parseInt(year)||0;
  const saved=_loadRiderCatOverrides().filter(o=>
    !(o.riderName.trim().toLowerCase()===nameKey && parseInt(o.year)===y)
  );
  saved.push({riderName:riderName.trim(), year:y, correctCat});
  _saveRiderCatOverrides(saved);
  showToast(`✅ "${escapeHtml(riderName)}" → categoría <b>${escapeHtml(correctCat)}</b> en ${year||'todas las temporadas'}. Guardado.`);
  try{renderRiderCatPanel();}catch(e){}
  try{renderRiderCatSaved();}catch(e){}
  try{_refreshEvolIfVisible();}catch(e){}
}

/* Ignorar inconsistencia (guardar como __ignored__) */
function ignoreRiderCatInconsistency(riderName, year){
  const nameKey=riderName.trim().toLowerCase();
  const y=parseInt(year)||0;
  const saved=_loadRiderCatOverrides().filter(o=>
    !(o.riderName.trim().toLowerCase()===nameKey && parseInt(o.year)===y)
  );
  saved.push({riderName:riderName.trim(), year:y, correctCat:'__ignored__'});
  _saveRiderCatOverrides(saved);
  showToast(`✔ Ignorado: "${escapeHtml(riderName)}" en ${year||'todas las temporadas'}.`,'ok',2500);
  try{renderRiderCatPanel();}catch(e){}
  try{renderRiderCatSaved();}catch(e){}
}

/* Borrar overrides del año seleccionado */
function clearRiderCatYear(){
  const year=parseInt($('riderCatYear')?.value)||0;
  if(!confirm(`¿Eliminar todas las correcciones de categoría para ${year||'este año'}?`)) return;
  const saved=_loadRiderCatOverrides().filter(o=>parseInt(o.year)!==year);
  _saveRiderCatOverrides(saved);
  showToast(`🗑 Correcciones de ${year} eliminadas.`,'ok',2500);
  renderRiderCatPanel();
  renderRiderCatSaved();
}

/* Renderizar lista de correcciones guardadas */
function renderRiderCatSaved(){
  const cont=$('riderCatSaved');
  const list=$('riderCatList');
  if(!cont||!list) return;
  const all=_loadRiderCatOverrides().filter(o=>o.correctCat!=='__ignored__');
  if(!all.length){cont.style.display='none';return;}
  cont.style.display='block';
  list.innerHTML=all.map(o=>{
    const yearLabel=o.year?`<span style="background:#f2f4f7;color:#475467;font-size:10px;padding:1px 6px;border-radius:6px;margin-left:4px">${o.year}</span>`:'';
    return `
    <div class="dup-alias-row">
      <div style="display:flex;align-items:center;flex-wrap:wrap;gap:4px">
        <span style="color:#182230;font-weight:700">${escapeHtml(o.riderName)}</span>
        ${yearLabel}
        <span style="color:#9ca3af;margin:0 4px">→</span>
        <span style="color:#065f46;font-weight:700">${escapeHtml(o.correctCat)}</span>
      </div>
      <button class="dup-btn dup-btn-ignore" style="font-size:11px;padding:4px 10px"
        onclick="deleteRiderCatOverride(${_qa(o.riderName)},${o.year})">🗑</button>
    </div>`;
  }).join('');
}

/* Eliminar una corrección concreta */
function deleteRiderCatOverride(riderName, year){
  const nameKey=riderName.trim().toLowerCase();
  const y=parseInt(year)||0;
  const saved=_loadRiderCatOverrides().filter(o=>
    !(o.riderName.trim().toLowerCase()===nameKey && parseInt(o.year)===y)
  );
  _saveRiderCatOverrides(saved);
  showToast(`🗑 Corrección eliminada para "${escapeHtml(riderName)}".`,'ok',2500);
  renderRiderCatPanel();
  renderRiderCatSaved();
}

// ===== FIN CORRECCIÓN DE CATEGORÍA POR CICLISTA =====

// ===== BLOQUE EVOLUCIÓN JS =====
let evolCharts=[];
let _evolCurrentTab='riders';
let _evolHistory=null;
let _evolSelectedYear=String(new Date().getFullYear()); // Por defecto: año actual
const _MY_BLUE='#1f6feb';
const _RIVAL_ORANGE='#f79009';

/* ── Utilidades ── */
function _evolShortName(s){return s&&s.length>22?s.slice(0,20)+'…':s||'';}
function _evolDestroyCharts(){evolCharts.forEach(c=>{try{c.destroy();}catch(e){}});evolCharts=[];}
function _evolNormCat(cat){
  const c=(cat||'').replace(/[-_\s]/g,'').toUpperCase();
  if(/^CAD/.test(c)) return 'CAD';
  if(/^JUV/.test(c)) return 'JUV';
  if(/^JUN/.test(c)) return 'JUN';
  if(/^ELI/.test(c)) return 'ELI';
  if(/^SUB.?23/.test(c)||c==='S23') return 'SUB23';
  if(/^M(AS)?\d/.test(c)) return 'MAS';
  return cat||'';
}

/* Normaliza "Apellido, Nombre" → "Nombre Apellido" para comparar nombres entre carreras */
function _evolNormName(name){
  if(!name)return'';
  const m=name.match(/^([^,]+),\s*(.+)$/);
  return m?(m[2].trim()+' '+m[1].trim()):name.trim();
}
/* Clave canónica: delega en normalizeForMatching (global) */
function _evolNameKey(name){return normalizeForMatching(name);}
/* Devuelve true si dos nombres se refieren al mismo corredor */
function _evolSameRider(a,b){
  if(!a||!b)return false;
  const ka=_evolNameKey(a), kb=_evolNameKey(b);
  if(ka===kb)return true;
  // "ivan sanchez" ⊆ "ivan sanchez toral" → mismo corredor
  const ta=ka.split(' '), tb=kb.split(' ');
  const[shorter,longer]=ta.length<=tb.length?[ta,tb]:[tb,ta];
  return shorter.length>=2&&shorter.every(t=>longer.includes(t));
}
function _evolSortHist(history){
  return history.slice().sort((a,b)=>{
    const da=_parseSpanishDate(a.raceDate)||a.raceDate||'9999';
    const db=_parseSpanishDate(b.raceDate)||b.raceDate||'9999';
    return da.localeCompare(db);
  });
}
function _evolTrend(positions){
  if(positions.length<2)return{icon:'—',label:'Sin datos'};
  const last=positions[positions.length-1],prev=positions[positions.length-2];
  if(last<prev)return{icon:'⬆️',label:'Mejorando'};
  if(last>prev)return{icon:'⬇️',label:'Bajando'};
  return{icon:'➡️',label:'Estable'};
}
function _evolConsecutive(positions){
  if(positions.length<2)return{dir:'stable',count:0};
  const dir=positions[positions.length-1]<positions[positions.length-2]?'up':'down';
  let count=1;
  for(let i=positions.length-2;i>0;i--){
    const imp=positions[i]<positions[i-1];
    if((dir==='up'&&imp)||(dir==='down'&&!imp))count++;else break;
  }
  return{dir,count};
}
function _evolAllTeamRanks(raceRiders, catFilter){
  const _isFemaleCat=c=>/^f[-_\s]|^fem/i.test(c||'');
  let eligible=(raceRiders||[]).filter(r=>!_isFemaleCat(r.cat));
  // Filtrar por categoría si se especifica — nunca mezclar categorías
  if(catFilter) eligible=eligible.filter(r=>_evolNormCat(r.cat)===catFilter);
  const teams=[...new Set(eligible.map(r=>r.team).filter(Boolean))];
  const ranked=teams.map(team=>{
    const rs=eligible.filter(r=>r.team===team).sort((a,b)=>a.pos-b.pos);
    const top3=rs.slice(0,3);
    if(top3.length<3)return null;
    const posScore=top3.reduce((s,r)=>s+r.pos,0);
    // Mismo criterio que getOfficialTeamRanking: tiempo primero, posición como fallback
    const top3withTime=top3.filter(r=>r.totalSeconds!=null);
    const timeScore=top3withTime.length>=3
      ? top3withTime.reduce((s,r)=>s+r.totalSeconds,0)
      : Infinity;
    return{team,score:posScore,timeScore,top3,best:top3[0].pos};
  }).filter(Boolean).sort((a,b)=>
    a.timeScore - b.timeScore ||
    a.score     - b.score     ||
    a.best      - b.best
  );
  ranked.forEach((x,i)=>x.rank=i+1);
  return ranked;
}

/* ── Tab switcher ── */
/* Filtra el historial por año seleccionado ('' = todos los años) */
function _evolFilterByYear(history, year){
  if(!year) return history;
  return (history||[]).filter(h=>{
    const y=(_parseSpanishDate(h.raceDate)||h.raceDate||'').slice(0,4);
    return y===String(year);
  });
}

/* Pobla el selector de año con los años disponibles en el historial */
function _populateEvolYearSelector(history){
  const sel=$('evolYearFilter');
  if(!sel) return;
  const years=[...new Set((history||[]).map(h=>
    (_parseSpanishDate(h.raceDate)||h.raceDate||'').slice(0,4)).filter(Boolean))
  ].sort().reverse();
  const currentYear=String(new Date().getFullYear());
  // Restaurar selección actual o usar año actual si existe
  const prev=_evolSelectedYear||currentYear;
  sel.innerHTML=`<option value="">Todos los años</option>`+
    years.map(y=>`<option value="${y}"${y===prev?'selected':''}>${y}</option>`).join('');
  // Si el año seleccionado existe en el historial, mantenlo; si no, usar el más reciente
  if(years.length && !years.includes(prev)){
    const fallback=years.includes(currentYear)?currentYear:years[0];
    sel.value=fallback;
    _evolSelectedYear=fallback;
  } else {
    _evolSelectedYear=sel.value||prev;
  }
}

/* Llamado cuando cambia el selector de año */
function _onEvolYearChange(){
  const sel=$('evolYearFilter');
  _evolSelectedYear=sel?.value||'';
  if(!_evolHistory) return;
  const myTeam=localStorage.getItem('myTeam')||'';
  const filtered=_evolFilterByYear(_evolHistory,_evolSelectedYear);
  // Actualizar contador
  const countEl=$('evolCount');
  if(countEl) countEl.textContent=`${filtered.length} carrera${filtered.length!==1?'s':''} en el historial`;
  _evolDestroyCharts();
  if(_evolCurrentTab==='riders')_evolRenderRiders(filtered,myTeam);
  else if(_evolCurrentTab==='team')_evolRenderTeam(filtered,myTeam);
  else if(_evolCurrentTab==='rivals')_evolRenderRivals(filtered,myTeam);
}

function showEvolTab(tab){
  _evolCurrentTab=tab;
  ['riders','team','rivals'].forEach(t=>{
    document.getElementById('evolTab_'+t)?.classList.toggle('active',t===tab);
    const p=document.getElementById('evolPanel_'+t);
    if(p){p.style.display=t===tab?'block':'none';p.classList.toggle('active',t===tab);}
  });
  if(!_evolHistory){renderEvolucion();return;}
  const myTeam=localStorage.getItem('myTeam')||'';
  const filtered=_evolFilterByYear(_evolHistory,_evolSelectedYear);
  if(tab==='riders')_evolRenderRiders(filtered,myTeam);
  else if(tab==='team')_evolRenderTeam(filtered,myTeam);
  else if(tab==='rivals')_evolRenderRivals(filtered,myTeam);
}

/* ── Entry point ── */
async function renderEvolucion(){
  const history=await _sbLoadHistory();
  _cachedHistory=history;
  _evolHistory=_evolSortHist(history);
  _evolDestroyCharts();
  // Poblar selector de año (usa el año actual como defecto)
  _populateEvolYearSelector(_evolHistory);
  const filtered=_evolFilterByYear(_evolHistory,_evolSelectedYear);
  const countEl=$('evolCount');
  if(countEl)countEl.textContent=`${filtered.length} carrera${filtered.length!==1?'s':''} en el historial`;
  const myTeam=localStorage.getItem('myTeam')||'';
  if(_evolCurrentTab==='riders')_evolRenderRiders(filtered,myTeam);
  else if(_evolCurrentTab==='team')_evolRenderTeam(filtered,myTeam);
  else if(_evolCurrentTab==='rivals')_evolRenderRivals(filtered,myTeam);
}

/* ══════════════════════════════════════════
   PESTAÑA 1 — Evolución de mis corredores
══════════════════════════════════════════ */
function _evolRenderRiders(history,myTeam){
  const panel=document.getElementById('evolPanel_riders');
  if(!panel)return;
  if(!myTeam){
    panel.innerHTML='<div class="evol-alert neutral">⚠️ Define primero tu equipo en <b>Carga y Resumen</b> para ver la evolución de tus corredores.</div>';return;
  }
  if(!history.length){
    panel.innerHTML='<div class="evol-alert neutral">📁 Guarda al menos 1 carrera para ver la evolución.</div>';return;
  }
  // Construir mapa nombre → apariciones
  // Normaliza "Apellido, Nombre" ↔ "Nombre Apellido" para unificar el mismo corredor
  const myTeamLower=myTeam.toLowerCase();
  // riderMap: key = clave canónica, value = {displayName, races:[...]}
  const riderMap=new Map();
  history.forEach(race=>{
    (race.riders||[]).filter(r=>(r.team||'').toLowerCase()===myTeamLower).forEach(r=>{
      // Buscar si ya existe este corredor (por nombre canónico)
      let foundKey=null;
      for(const[k,v]of riderMap){
        if(_evolSameRider(k,r.name)){foundKey=k;break;}
      }
      if(!foundKey){
        foundKey=_evolNormName(r.name); // primera vez: usar nombre normalizado como clave
        riderMap.set(foundKey,{displayName:_evolNormName(r.name),races:[]});
      }
      // Preferir el nombre más largo/completo como displayName
      const entry=riderMap.get(foundKey);
      if(_evolNormName(r.name).length>entry.displayName.length){
        entry.displayName=_evolNormName(r.name);
      }
      const catRiders=(race.riders||[]).filter(x=>_evolNormCat(x.cat)===_evolNormCat(r.cat)).sort((a,b)=>a.pos-b.pos);
      entry.races.push({
        raceName:race.raceName,raceDate:race.raceDate,localidad:race.localidad||'',
        pos:r.pos,cat:getRiderCorrectCat(r.name,(_parseSpanishDate(race.raceDate)||'').slice(0,4),r.cat),time:r.time,
        gapSeconds:r.gapSeconds,totalSeconds:r.totalSeconds,
        total:(race.riders||[]).length,
        catPos:catRiders.findIndex(x=>_evolSameRider(x.name,r.name))+1,
        catTotal:catRiders.length
      });
    });
  });
  if(!riderMap.size){
    panel.innerHTML=`<div class="evol-alert neutral">ℹ️ No se encontraron corredores de <b>${escapeHtml(myTeam)}</b> en el historial.</div>`;return;
  }
  // Ordenar por displayName
  const riderKeys=[...riderMap.keys()].sort((a,b)=>riderMap.get(a).displayName.localeCompare(riderMap.get(b).displayName));
  window._evolRiderMap=riderMap;
  panel.innerHTML=`
    <div style="display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin-bottom:6px">
      <div style="flex:1;min-width:240px">
        <label style="font-weight:700;font-size:13px;display:block;margin-bottom:6px">Selecciona un corredor</label>
        <select class="evol-select" id="evolRiderSelect" onchange="evolSelectRider(this.value)" style="margin-bottom:0">
          <option value="">— Elige corredor —</option>
          ${riderKeys.map(k=>{const e=riderMap.get(k);return`<option value="${escapeHtml(k)}">${escapeHtml(e.displayName)} (${e.races.length} carrera${e.races.length!==1?'s':''})</option>`;}).join('')}
        </select>
      </div>
      <button class="btn" id="evolExportImgBtn" onclick="exportEvolRiderImage()" style="background:#0b2f6b;color:#fff;font-weight:700;padding:9px 16px;white-space:nowrap" title="Genera una imagen PNG con la trayectoria del corredor seleccionado">📸 Crear imagen</button>
    </div>
    <div id="evolRiderContent"></div>`;
  // Auto-seleccionar: corredor con más carreras; en empate, mejor posición media
  const bestKey=riderKeys.reduce((best,k)=>{
    const a=riderMap.get(k), b=riderMap.get(best);
    if(a.races.length!==b.races.length) return a.races.length>b.races.length?k:best;
    const avgA=a.races.reduce((s,r)=>s+r.pos,0)/a.races.length;
    const avgB=b.races.reduce((s,r)=>s+r.pos,0)/b.races.length;
    return avgA<avgB?k:best;
  });
  const sel=$('evolRiderSelect');
  if(sel) sel.value=bestKey;
  evolSelectRider(bestKey);
}

function evolSelectRider(key){
  const riderMap=window._evolRiderMap;
  if(!riderMap||!key)return;
  const entry=riderMap.get(key);if(!entry)return;
  const name=entry.displayName;
  // Orden cronológico para el gráfico (izquierda = más antigua)
  const data=entry.races.slice().sort((a,b)=>(_parseSpanishDate(a.raceDate)||'0000').localeCompare(_parseSpanishDate(b.raceDate)||'0000'));
  const container=document.getElementById('evolRiderContent');
  if(!container)return;
  _evolDestroyCharts();
  const best=Math.min(...data.map(x=>x.pos));
  const avg=(data.reduce((s,x)=>s+x.pos,0)/data.length).toFixed(1);
  const trend=_evolTrend(data.map(x=>x.pos));
  const consec=_evolConsecutive(data.map(x=>x.pos));
  let alertHtml='';
  if(consec.count>=3){
    const cls=consec.dir==='up'?'good':'bad';
    const verb=consec.dir==='up'?'mejorando':'empeorando';
    alertHtml=`<div class="evol-alert ${cls}">${consec.dir==='up'?'🔥':'⚠️'} <b>${escapeHtml(name)}</b> lleva <b>${consec.count} carreras consecutivas ${verb}</b> su posición.</div>`;
  }
  // Tabla: más reciente primero
  const tableRows=[...data].reverse().map(x=>`<tr>
    <td>${escapeHtml(x.raceName)}</td>
    <td style="white-space:nowrap">${escapeHtml(x.raceDate||'—')}</td>
    <td style="color:#667085">${x.localidad?'📍 '+escapeHtml(x.localidad):'—'}</td>
    <td><b>${x.pos}º</b><span class="small"> / ${x.total}</span></td>
    <td>${x.catPos}º<span class="small"> / ${x.catTotal} (${escapeHtml(x.cat||'—')})</span></td>
    <td style="font-family:monospace">${x.totalSeconds?formatSeconds(x.totalSeconds):(x.time||'—')}</td>
    <td style="font-family:monospace">${x.gapSeconds?'+'+formatSeconds(x.gapSeconds):(x.pos===1?'🥇 Ganador':'—')}</td>
  </tr>`).join('');
  container.innerHTML=`
    ${alertHtml}
    <div class="evol-kpis">
      <div class="evol-kpi"><div class="ek-label">Carreras</div><div class="ek-value">${data.length}</div></div>
      <div class="evol-kpi"><div class="ek-label">Mejor</div><div class="ek-value" style="color:#12b76a">${best}º</div></div>
      <div class="evol-kpi"><div class="ek-label">Media</div><div class="ek-value">${avg}º</div></div>
      <div class="evol-kpi"><div class="ek-label">Tendencia</div><div class="ek-value" style="font-size:20px">${trend.icon}</div><div class="ek-sub">${trend.label}</div></div>
    </div>
    <div class="evol-main-chart"><canvas id="evolRiderChart"></canvas></div>
    <div class="table-wrap" style="max-height:none;margin-top:4px">
      <table><thead><tr><th>Carrera</th><th>Fecha</th><th>Localidad</th><th>Pos. general</th><th>Pos. categoría</th><th>Tiempo</th><th>Gap al 1º</th></tr></thead>
      <tbody>${tableRows}</tbody></table>
    </div>`;
  requestAnimationFrame(()=>{
    const ctx=document.getElementById('evolRiderChart');
    if(!ctx||!window.Chart)return;
    const maxP=Math.min(Math.max(...data.map(x=>x.pos))+3,data[0]?.total||50);
    // Linear regression projection using last 4 data points
    const lrPts = data.slice(-4).map(x=>x.pos);
    const lrN = lrPts.length;
    let predPos = null;
    if(lrN >= 2){
      const xs = lrPts.map((_,i)=>i+1);
      const sx=xs.reduce((a,v)=>a+v,0), sy=lrPts.reduce((a,v)=>a+v,0);
      const sxx=xs.reduce((a,v)=>a+v*v,0), sxy=xs.map((x,i)=>x*lrPts[i]).reduce((a,v)=>a+v,0);
      const den=lrN*sxx-sx*sx;
      if(den!==0){
        const slope=(lrN*sxy-sx*sy)/den;
        const intercept=(sy-slope*sx)/lrN;
        predPos = Math.max(1, Math.round((slope*(lrN+1)+intercept)*10)/10);
      }
    }
    const projLabels = [...data.map(x=>_trendWrapLabel(x.raceName||'',26)), ...(predPos!=null?['Siguiente →']:[])];
    const projData   = [...data.map(()=>null), ...(predPos!=null?[predPos]:[])];
    // Anchor last real point so dashed line connects from it
    if(predPos!=null && data.length>0) projData[data.length-1]=data[data.length-1].pos;

    const chart=new Chart(ctx,{type:'line',data:{
      labels:projLabels,
      datasets:[
        {label:'Posición',data:[...data.map(x=>x.pos),...(predPos!=null?[null]:[])],
          borderColor:_MY_BLUE,backgroundColor:_MY_BLUE+'22',borderWidth:3,fill:true,tension:0.3,
          pointRadius:7,pointHoverRadius:9,pointBorderColor:'#fff',pointBorderWidth:2,
          pointBackgroundColor:data.map(x=>x.pos===best?'#12b76a':_MY_BLUE)},
        ...(predPos!=null?[{label:'Proyección IA',data:projData,
          borderColor:'#f59e0b',backgroundColor:'transparent',borderWidth:2,
          borderDash:[6,4],fill:false,tension:0,
          pointRadius:projData.map((v,i)=>i===projData.length-1&&v!=null?9:0),
          pointBackgroundColor:'#f59e0b',pointBorderColor:'#fff',pointBorderWidth:2,
          pointStyle:'star',spanGaps:true}]:[])
      ]
    },options:{responsive:true,maintainAspectRatio:false,
      scales:{
        y:{reverse:true,min:1,suggestedMax:maxP,title:{display:true,text:'Posición (arriba = mejor)'},ticks:{precision:0},grid:{color:'#f3f4f6'}},
        x:{ticks:{maxRotation:0,minRotation:0,font:{size:10},autoSkip:false},grid:{display:false}}
      },
      plugins:{
        legend:{display:predPos!=null,labels:{boxWidth:16,font:{size:11}}},
        tooltip:{callbacks:{
          title:ctx=>{const idx=ctx[0].dataIndex;if(idx<data.length){const d=data[idx];return d.raceName+(d.raceDate?' · '+d.raceDate:'');}return 'Proyección IA (próx. carrera)';},
          label:ctx=>{if(ctx.dataset.label==='Proyección IA')return `Posición estimada: ${ctx.raw}º`;return`Posición: ${ctx.raw}º de ${data[ctx.dataIndex]?.total||'?'}`;},
          afterLabel:ctx=>{if(ctx.dataset.label==='Proyección IA')return 'Basado en regresión lineal (últ. 4 carreras)';const d=data[ctx.dataIndex];if(!d)return'';return`Cat: ${d.catPos}º de ${d.catTotal} (${d.cat||'—'})`;}
        }}
      }
    }});
    evolCharts.push(chart);
  });
}

/* ══════════════════════════════════════════
   PESTAÑA 2 — Evolución de mi equipo
══════════════════════════════════════════ */
function _evolRenderTeam(history,myTeam){
  const panel=document.getElementById('evolPanel_team');
  if(!panel)return;
  _evolDestroyCharts();
  if(!myTeam){panel.innerHTML='<div class="evol-alert neutral">⚠️ Define primero tu equipo en <b>Carga y Resumen</b>.</div>';return;}
  if(!history.length){panel.innerHTML='<div class="evol-alert neutral">📁 Guarda al menos 1 carrera para ver la evolución.</div>';return;}
  // Bug 2 fix: use case-insensitive team match to find myTeam in rankings
  const myTeamLower=myTeam.toLowerCase();
  const raceData=history.map(race=>{
    // Determinar la categoría dominante de nuestro equipo en esta carrera
    const myRiders=(race.riders||[]).filter(r=>(r.team||'').toLowerCase()===myTeamLower);
    const catCounts={};
    myRiders.forEach(r=>{const c=_evolNormCat(r.cat);if(c)catCounts[c]=(catCounts[c]||0)+1;});
    const myCat=Object.entries(catCounts).sort((a,b)=>b[1]-a[1])[0]?.[0]||null;
    // Ranking solo dentro de esa categoría
    const allRanks=_evolAllTeamRanks(race.riders||[], myCat);
    const my=allRanks.find(x=>(x.team||'').toLowerCase()===myTeamLower);
    return{raceName:race.raceName,raceDate:race.raceDate,myCat,
      rank:my?.rank||null,score:my?.score||null,top3:my?.top3||[],
      eligible:!!my,totalTeams:allRanks.length};
  }).filter(x=>x.eligible);
  if(!raceData.length){
    panel.innerHTML=`<div class="evol-alert neutral">ℹ️ <b>${escapeHtml(myTeam)}</b> necesita al menos 3 corredores por carrera para calcular el ranking. Aún no hay datos suficientes.</div>`;return;
  }
  const best=Math.min(...raceData.map(x=>x.rank));
  const avg=(raceData.reduce((s,x)=>s+x.rank,0)/raceData.length).toFixed(1);
  const trend=_evolTrend(raceData.map(x=>x.rank));
  const allTeams=[...new Set(history.flatMap(r=>(r.riders||[]).map(x=>x.team)).filter(Boolean)
    .map(t=>getCanonicalTeam(t)))].filter(t=>t.toLowerCase()!==myTeamLower).sort();
  // Tabla: más reciente primero
  const tableRows=[...raceData].reverse().map(x=>`<tr>
    <td>${escapeHtml(x.raceName)}</td>
    <td>${escapeHtml(x.raceDate||'—')}</td>
    <td><b>${x.rank}º</b><span class="small"> de ${x.totalTeams} equipos</span>${x.myCat?`<span class="small" style="color:#9ca3af"> (${escapeHtml(x.myCat)})</span>`:''}
    </td>
    <td style="font-family:monospace;font-weight:700">${x.score||'—'}</td>
    <td style="font-size:12px">${x.top3.map(r=>`<span style="background:#eef4ff;border-radius:6px;padding:1px 6px;margin:1px">${r.pos}º ${escapeHtml(r.name)}</span>`).join(' ')}</td>
  </tr>`).join('');
  panel.innerHTML=`
    <div class="evol-kpis">
      <div class="evol-kpi"><div class="ek-label">Carreras</div><div class="ek-value">${raceData.length}</div></div>
      <div class="evol-kpi"><div class="ek-label">Mejor ranking</div><div class="ek-value" style="color:#12b76a">${best}º</div></div>
      <div class="evol-kpi"><div class="ek-label">Ranking medio</div><div class="ek-value">${avg}º</div></div>
      <div class="evol-kpi"><div class="ek-label">Tendencia</div><div class="ek-value" style="font-size:20px">${trend.icon}</div><div class="ek-sub">${trend.label}</div></div>
    </div>
    <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:4px">
      <span style="font-weight:700;font-size:13px">Comparar con rival:</span>
      <select class="evol-select" style="max-width:320px;margin:0" id="evolTeamRivalSel" onchange="evolTeamRivalChange(this.value)">
        <option value="">— Sin comparación —</option>
        ${allTeams.map(t=>`<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join('')}
      </select>
    </div>
    <div class="evol-main-chart"><canvas id="evolTeamChart"></canvas></div>
    <div id="evolTeamGapInfo" style="font-size:12px;color:#667085;margin:-8px 0 16px;text-align:right"></div>
    <div class="table-wrap" style="max-height:none;margin-top:4px">
      <table><thead><tr><th>Carrera</th><th>Fecha</th><th>Ranking equipo</th><th>Score (Σ top3 pos.)</th><th>Corredores que contaron</th></tr></thead>
      <tbody>${tableRows}</tbody></table>
    </div>`;
  window._evolTeamData={raceData,history,myTeam};
  _evolDrawTeamChart(raceData,null,history,myTeam);
}
function evolTeamRivalChange(rival){
  const d=window._evolTeamData;if(!d)return;
  _evolDrawTeamChart(d.raceData,rival,d.history,d.myTeam);
}
function _evolDrawTeamChart(myData,rivalTeam,history,myTeam){
  _evolDestroyCharts();
  const ctx=document.getElementById('evolTeamChart');
  if(!ctx||!window.Chart)return;
  const datasets=[{
    label:myTeam,data:myData.map(x=>x.rank),
    borderColor:_MY_BLUE,backgroundColor:_MY_BLUE+'22',borderWidth:3,fill:true,tension:0.3,
    pointRadius:6,pointBorderColor:'#fff',pointBorderWidth:2,pointBackgroundColor:_MY_BLUE
  }];
  if(rivalTeam){
    const rivalTeamLower=rivalTeam.toLowerCase();
    const rivalRanks=myData.map(race=>{
      const full=history.find(h=>h.raceName===race.raceName&&h.raceDate===race.raceDate);
      if(!full)return null;
      // usar la misma categoría que nuestro equipo para comparar en igualdad
      // Normalizar nombres de equipo del historial antes de buscar
      const normalizedRiders=(full.riders||[]).map(r=>({...r,team:getCanonicalTeam(r.team)}));
      const e=_evolAllTeamRanks(normalizedRiders, race.myCat).find(x=>(x.team||'').toLowerCase()===rivalTeamLower);
      return e?e.rank:null;
    });
    datasets.push({
      label:rivalTeam,data:rivalRanks,
      borderColor:_RIVAL_ORANGE,backgroundColor:_RIVAL_ORANGE+'22',
      borderWidth:2,fill:false,tension:0.3,borderDash:[5,3],
      pointRadius:5,pointBackgroundColor:_RIVAL_ORANGE
    });
    const gapEl=document.getElementById('evolTeamGapInfo');
    if(gapEl){
      const pairs=myData.map((x,i)=>({my:x.rank,rv:rivalRanks[i]})).filter(p=>p.rv!==null);
      const wMe=pairs.filter(p=>p.my<p.rv).length,wRv=pairs.filter(p=>p.rv<p.my).length;
      gapEl.innerHTML=`<b style="color:${_MY_BLUE}">${escapeHtml(myTeam)}</b> por delante: <b>${wMe}</b> &nbsp;|&nbsp; <b style="color:${_RIVAL_ORANGE}">${escapeHtml(rivalTeam)}</b> por delante: <b>${wRv}</b>`;
    }
  }
  const maxR=Math.max(...myData.map(x=>x.rank))+1;
  const chart=new Chart(ctx,{type:'line',data:{labels:myData.map(x=>_trendWrapLabel(x.raceName||'',26)),datasets},
    options:{responsive:true,maintainAspectRatio:false,
      scales:{
        y:{reverse:true,min:1,suggestedMax:maxR,title:{display:true,text:'Ranking equipo (1º = mejor)'},ticks:{precision:0},grid:{color:'#f3f4f6'}},
        x:{ticks:{maxRotation:0,minRotation:0,font:{size:10},autoSkip:false},grid:{display:false}}
      },
      plugins:{legend:{display:datasets.length>1,position:'bottom',labels:{usePointStyle:true}},
        tooltip:{callbacks:{
          title:ctx=>{const d=myData[ctx[0].dataIndex];return d.raceName+(d.raceDate?' · '+d.raceDate:'');},
          label:ctx=>{
            if(ctx.raw===null)return`${ctx.dataset.label}: sin datos`;
            const d=myData[ctx.dataIndex];
            if(ctx.datasetIndex===0)return`${ctx.dataset.label}: ${ctx.raw}º de ${d.totalTeams} equipos${d.myCat?' ('+d.myCat+')':''}`;
            return`${ctx.dataset.label}: ${ctx.raw}º`;
          }
        }}}
    }
  });
  evolCharts.push(chart);
}

/* ══════════════════════════════════════════
   PESTAÑA 3 — Análisis de rivales
══════════════════════════════════════════ */
function _evolRenderRivals(history,myTeam){
  const panel=document.getElementById('evolPanel_rivals');
  if(!panel)return;
  if(!history.length){panel.innerHTML='<div class="evol-alert neutral">📁 Guarda al menos 1 carrera para ver el análisis de rivales.</div>';return;}
  const allNames=[...new Set(history.flatMap(r=>(r.riders||[]).map(x=>x.name)).filter(Boolean))].sort();
  const allTeams=[...new Set(history.flatMap(r=>(r.riders||[]).map(x=>getCanonicalTeam(x.team)).filter(Boolean)))].sort();
  // Tabla de rivales que más veces superaron a mis corredores
  // Bug 3 fix: count once per (rival, race) — max = nº de carreras, not nº of my riders
  // Bug 1 fix: use case-insensitive team match
  const myTeamLower=myTeam.toLowerCase();
  const rivalBeats=new Map();
  history.forEach(race=>{
    const mine=(race.riders||[]).filter(r=>(r.team||'').toLowerCase()===myTeamLower);
    if(!mine.length)return;
    const rivals=(race.riders||[]).filter(r=>(r.team||'').toLowerCase()!==myTeamLower);
    rivals.forEach(rv=>{
      // Count this rival once per race if they beat at least one of my riders in same cat
      const beatenMine=mine.filter(me=>rv.pos<me.pos&&_evolNormCat(rv.cat)===_evolNormCat(me.cat));
      if(!beatenMine.length)return;
      const rvTeamCanon=getCanonicalTeam(rv.team||'');
      const k=rv.name+'||'+rvTeamCanon;
      if(!rivalBeats.has(k))rivalBeats.set(k,{name:rv.name,team:rvTeamCanon,count:0,races:[]});
      const e=rivalBeats.get(k);
      e.count++;
      // Show the best-positioned of my riders that this rival beat
      const worst=beatenMine.reduce((a,b)=>a.pos>b.pos?a:b);
      e.races.push({race:race.raceName,rvPos:rv.pos,myPos:worst.pos,myName:worst.name});
    });
  });
  const topRivals=[...rivalBeats.values()].sort((a,b)=>b.count-a.count).slice(0,15);
  const rivalRows=topRivals.length?topRivals.map((rv,i)=>`<tr>
    <td style="text-align:center"><b>${i+1}</b></td>
    <td style="cursor:pointer;color:${_MY_BLUE};font-weight:600" onclick="evolSearchRival('${escapeAttr(rv.name)}')">${escapeHtml(rv.name)}</td>
    <td style="font-size:12px">${escapeHtml(rv.team)}</td>
    <td style="text-align:center;font-weight:800;color:#f04438">${rv.count}×</td>
    <td style="font-size:11px;color:#667085">${rv.races.slice(0,3).map(d=>`${escapeHtml(d.race)} (${rv.name} ${d.rvPos}º vs ${escapeHtml(d.myName)} ${d.myPos}º)`).join(' · ')}${rv.races.length>3?` +${rv.races.length-3} más`:''}</td>
  </tr>`).join(''):'<tr><td colspan="5" class="empty">Sin datos — necesitas tener ciclistas de tu equipo en el historial</td></tr>';
  panel.innerHTML=`
    <div class="evol-rivals-grid">
      <div>
        <label style="font-weight:700;font-size:13px;display:block;margin-bottom:6px">👤 Buscar corredor rival</label>
        <input id="evolRivalRiderInput" class="evol-rival-search" list="evolRivalRiderDatalist"
          placeholder="Nombre del corredor…" autocomplete="off"
          oninput="evolSearchRivalRider(this.value)" style="width:100%;margin-bottom:0" />
        <datalist id="evolRivalRiderDatalist">
          ${allNames.map(n=>`<option value="${escapeHtml(n)}">`).join('')}
        </datalist>
      </div>
      <div>
        <label style="font-weight:700;font-size:13px;display:block;margin-bottom:6px">🚴 Buscar por equipo rival</label>
        <select id="evolRivalTeamSelect" class="evol-rival-search"
          onchange="evolSearchRivalTeam(this.value)" style="width:100%;margin-bottom:0;cursor:pointer">
          <option value="">— Selecciona un equipo —</option>
          ${allTeams.filter(t=>t.toLowerCase()!==myTeam.toLowerCase()).map(t=>`<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join('')}
        </select>
      </div>
    </div>
    <div id="evolRivalContent" style="margin-bottom:20px"></div>
    <div style="height:1px;background:#e5e7eb;margin:16px 0"></div>
    <div style="font-weight:700;font-size:15px;margin-bottom:6px">🏆 Rivales que más veces quedaron por delante de tus corredores</div>
    <div style="font-size:12px;color:#667085;margin-bottom:12px">Solo en la misma categoría y misma carrera. Haz clic en el nombre para ver su evolución.</div>
    <div class="table-wrap" style="max-height:none">
      <table><thead><tr><th>#</th><th>Corredor rival</th><th>Equipo</th><th>Veces por delante</th><th>Detalle</th></tr></thead>
      <tbody>${rivalRows}</tbody></table>
    </div>`;
  // Bug 4 fix: always store reference to full _evolHistory so search uses all races
  window._evolRivalsData={history:_evolHistory||history,myTeam,allTeams};
}
/* Buscar corredor rival por nombre */
function evolSearchRivalRider(query){
  const d=window._evolRivalsData;
  const container=document.getElementById('evolRivalContent');
  if(!container)return;
  // Limpiar selector de equipo
  const teamSel=document.getElementById('evolRivalTeamSelect');
  if(teamSel&&query&&query.trim().length>=2) teamSel.value='';
  if(!d||!query||query.trim().length<2){container.innerHTML='';return;}
  if(_evolHistory&&_evolHistory.length>(d.history||[]).length) d.history=_evolHistory;
  _evolRivalRider(container,query.trim(),d.history,d.myTeam);
}

/* Buscar por equipo rival desde el selector */
function evolSearchRivalTeam(teamName){
  const d=window._evolRivalsData;
  const container=document.getElementById('evolRivalContent');
  if(!container)return;
  // Limpiar input de corredor
  const riderInput=document.getElementById('evolRivalRiderInput');
  if(riderInput&&teamName) riderInput.value='';
  if(!d||!teamName){container.innerHTML='';return;}
  if(_evolHistory&&_evolHistory.length>(d.history||[]).length) d.history=_evolHistory;
  _evolRivalTeam(container,teamName,d.history,d.myTeam);
}

/* Mantener evolSearchRival para compatibilidad con clicks en tabla top rivals */
function evolSearchRival(query){
  const d=window._evolRivalsData;
  const container=document.getElementById('evolRivalContent');
  if(!container||!d||!query||query.trim().length<2)return;
  if(_evolHistory&&_evolHistory.length>(d.history||[]).length) d.history=_evolHistory;
  // Actualizar el input de corredor y limpiar el selector
  const riderInput=document.getElementById('evolRivalRiderInput');
  if(riderInput) riderInput.value=query;
  const teamSel=document.getElementById('evolRivalTeamSelect');
  if(teamSel) teamSel.value='';
  _evolRivalRider(container,query.trim(),d.history,d.myTeam);
}
function _evolRivalRider(container,name,history,myTeam){
  _evolDestroyCharts();
  const data=[];
  let displayName=_evolNormName(name); // nombre normalizado para mostrar
  history.forEach(race=>{
    // Buscar por nombre exacto O por coincidencia normalizada (Apellido, Nombre ↔ Nombre Apellido)
    const r=(race.riders||[]).find(x=>_evolSameRider(x.name,name));
    if(!r)return;
    if(_evolNormName(r.name).length>displayName.length)displayName=_evolNormName(r.name);
    const catRiders=(race.riders||[]).filter(x=>_evolNormCat(x.cat)===_evolNormCat(r.cat)).sort((a,b)=>a.pos-b.pos);
    data.push({raceName:race.raceName,raceDate:race.raceDate,
      pos:r.pos,cat:getRiderCorrectCat(r.name,(_parseSpanishDate(race.raceDate)||'').slice(0,4),r.cat),time:r.time,gapSeconds:r.gapSeconds,totalSeconds:r.totalSeconds,
      team:r.team,total:(race.riders||[]).length,
      catPos:catRiders.findIndex(x=>_evolSameRider(x.name,r.name))+1,catTotal:catRiders.length});
  });
  if(!data.length){container.innerHTML=`<div class="evol-alert neutral">ℹ️ No se encontró a "<b>${escapeHtml(displayName)}</b>" en el historial.</div>`;return;}
  const sorted=data.sort((a,b)=>(_parseSpanishDate(a.raceDate)||'9999').localeCompare(_parseSpanishDate(b.raceDate)||'9999'));
  const best=Math.min(...sorted.map(x=>x.pos));
  const avg=(sorted.reduce((s,x)=>s+x.pos,0)/sorted.length).toFixed(1);
  const trend=_evolTrend(sorted.map(x=>x.pos));

  // ── Cara a cara: buscar corredores de mi equipo en las mismas carreras y categoría ──
  const myTeamLower=(myTeam||'').toLowerCase();
  // Para cada carrera en sorted, encontrar los ciclistas de myTeam en la misma categoría que el rival
  const faceOffRaces=sorted.map(entry=>{
    const race=history.find(r=>r.raceName===entry.raceName&&r.raceDate===entry.raceDate);
    if(!race) return null;
    const myRiders=(race.riders||[]).filter(r=>
      (r.team||'').toLowerCase()===myTeamLower &&
      _evolNormCat(r.cat)===_evolNormCat(entry.cat||'')
    ).sort((a,b)=>a.pos-b.pos);
    return{raceName:entry.raceName,raceDate:entry.raceDate,rivalPos:entry.pos,
           myRiders,rivalWins:myRiders.filter(r=>entry.pos<r.pos).length,
           myWins:myRiders.filter(r=>r.pos<entry.pos).length};
  }).filter(Boolean);
  const racesWithMyTeam=faceOffRaces.filter(f=>f.myRiders.length>0);
  const totalRivalWins=racesWithMyTeam.reduce((s,f)=>s+f.rivalWins,0);
  const totalMyWins=racesWithMyTeam.reduce((s,f)=>s+f.myWins,0);

  // Mejor corredor de mi equipo por posición media en las carreras compartidas
  const myRiderMap={};
  racesWithMyTeam.forEach(f=>f.myRiders.forEach(r=>{
    if(!myRiderMap[r.name]) myRiderMap[r.name]={name:r.name,positions:[],wins:0};
    myRiderMap[r.name].positions.push(r.pos);
    if(r.pos<f.rivalPos) myRiderMap[r.name].wins++;
  }));
  const myRidersSorted=Object.values(myRiderMap)
    .map(r=>({...r,avg:r.positions.reduce((s,p)=>s+p,0)/r.positions.length}))
    .sort((a,b)=>a.avg-b.avg);
  const bestMyRider=myRidersSorted[0]||null;

  // Datos de posición del mejor corredor por carrera (para el gráfico)
  const bestMyData=sorted.map(entry=>{
    if(!bestMyRider) return null;
    const race=history.find(r=>r.raceName===entry.raceName&&r.raceDate===entry.raceDate);
    if(!race) return null;
    const found=(race.riders||[]).find(r=>_evolSameRider(r.name,bestMyRider.name)&&(r.team||'').toLowerCase()===myTeamLower);
    return found?found.pos:null;
  });

  const hasFaceOff=racesWithMyTeam.length>0;

  // ── Tabla cara a cara ──
  const faceOffTableRows=racesWithMyTeam.map(f=>{
    const myBest=f.myRiders[0];
    const result=f.rivalPos<myBest.pos
      ? `<span style="color:#f04438;font-weight:800">rival ganó</span>`
      : f.rivalPos>myBest.pos
        ? `<span style="color:#067647;font-weight:800">✓ mi equipo</span>`
        : `<span style="color:#667085">empate</span>`;
    const allMine=f.myRiders.map(r=>`${escapeHtml(_evolNormName(r.name))} ${r.pos}º`).join(', ');
    return `<tr>
      <td style="font-size:12px;font-weight:600">${escapeHtml(f.raceName)}</td>
      <td style="text-align:center;font-weight:800;color:${_RIVAL_ORANGE}">${f.rivalPos}º</td>
      <td style="font-size:12px">${allMine}</td>
      <td style="text-align:center">${result}</td>
    </tr>`;
  }).join('');

  const faceOffHtml=hasFaceOff?`
    <div style="margin-top:18px;border-top:1px solid #e5e7eb;padding-top:14px">
      <div style="font-weight:800;font-size:14px;margin-bottom:10px;color:#182230">
        ⚔️ Cara a cara con <span style="color:#0b2f6b">${escapeHtml(myTeam||'mi equipo')}</span>
        <span style="font-size:12px;font-weight:400;color:#667085;margin-left:8px">(${racesWithMyTeam.length} carreras coincidiendo en la misma categoría)</span>
      </div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px">
        <div style="background:#fff0f0;border:1.5px solid #fca5a5;border-radius:10px;padding:8px 16px;text-align:center">
          <div style="font-size:20px;font-weight:900;color:#f04438">${totalRivalWins}</div>
          <div style="font-size:11px;color:#667085;font-weight:700">veces por delante el rival</div>
        </div>
        <div style="background:#f0fdf4;border:1.5px solid #6ee7b7;border-radius:10px;padding:8px 16px;text-align:center">
          <div style="font-size:20px;font-weight:900;color:#067647">${totalMyWins}</div>
          <div style="font-size:11px;color:#667085;font-weight:700">veces por delante mi equipo</div>
        </div>
        ${bestMyRider?`<div style="background:#eff8ff;border:1.5px solid #bfdbfe;border-radius:10px;padding:8px 16px;text-align:center">
          <div style="font-size:13px;font-weight:800;color:#0b2f6b">${escapeHtml(_evolNormName(bestMyRider.name))}</div>
          <div style="font-size:11px;color:#667085;font-weight:700">mi mejor vs este rival · ${bestMyRider.wins} victorias</div>
        </div>`:''}
      </div>
      <div class="table-wrap" style="max-height:260px">
        <table><thead><tr>
          <th>Carrera</th><th style="text-align:center">Rival</th><th>Mis corredores (misma cat.)</th><th style="text-align:center">Resultado</th>
        </tr></thead><tbody>${faceOffTableRows}</tbody></table>
      </div>
    </div>`:'<div class="evol-alert neutral" style="margin-top:14px">ℹ️ No hay carreras en que este rival y tu equipo coincidan en la misma categoría.</div>';

  container.innerHTML=`
    <div class="evol-alert neutral" style="border-color:${_RIVAL_ORANGE}20">
      ⚔️ <b>${escapeHtml(sorted[0]?.team||'—')}</b> · ${sorted.length} carrera${sorted.length!==1?'s':''}
    </div>
    <div class="evol-kpis" style="grid-template-columns:repeat(3,1fr)">
      <div class="evol-kpi"><div class="ek-label">Mejor</div><div class="ek-value" style="color:${_RIVAL_ORANGE}">${best}º</div></div>
      <div class="evol-kpi"><div class="ek-label">Media</div><div class="ek-value">${avg}º</div></div>
      <div class="evol-kpi"><div class="ek-label">Tendencia</div><div class="ek-value" style="font-size:20px">${trend.icon}</div><div class="ek-sub">${trend.label}</div></div>
    </div>
    <div class="evol-main-chart"><canvas id="evolRivRiderChart"></canvas></div>
    ${faceOffHtml}`;

  requestAnimationFrame(()=>{
    const ctx=document.getElementById('evolRivRiderChart');
    if(!ctx||!window.Chart)return;
    const datasets=[{label:displayName,data:sorted.map(x=>x.pos),
      borderColor:_RIVAL_ORANGE,backgroundColor:_RIVAL_ORANGE+'22',borderWidth:3,fill:true,tension:0.3,
      pointRadius:6,pointBorderColor:'#fff',pointBorderWidth:2,pointBackgroundColor:_RIVAL_ORANGE}];
    // Añadir línea del mejor corredor de mi equipo si hay datos
    if(bestMyRider&&bestMyData.some(v=>v!==null)){
      datasets.unshift({label:_evolNormName(bestMyRider.name)+' (mi equipo)',data:bestMyData,
        borderColor:_MY_BLUE,backgroundColor:'transparent',borderWidth:2,fill:false,tension:0.3,
        borderDash:[5,3],pointRadius:5,pointBackgroundColor:_MY_BLUE,
        pointBorderColor:'#fff',pointBorderWidth:2,spanGaps:true});
    }
    const chart=new Chart(ctx,{type:'line',data:{
      labels:sorted.map(x=>_trendWrapLabel(x.raceName||'',26)),
      datasets
    },options:{responsive:true,maintainAspectRatio:false,
      scales:{y:{reverse:true,min:1,title:{display:true,text:'Posición'},ticks:{precision:0},grid:{color:'#f3f4f6'}},x:{ticks:{maxRotation:0,minRotation:0,font:{size:10},autoSkip:false},grid:{display:false}}},
      plugins:{
        legend:{display:datasets.length>1,position:'bottom',labels:{usePointStyle:true}},
        tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${c.raw}º`}}
      }
    }});
    evolCharts.push(chart);
  });
}
function _evolRivalTeam(container,teamName,history,myTeam){
  _evolDestroyCharts();
  const raceData=history.map(race=>{
    const all=_evolAllTeamRanks(race.riders||[]);
    const rv=all.find(x=>x.team===teamName);
    const my=all.find(x=>x.team===myTeam);
    return{raceName:race.raceName,raceDate:race.raceDate,
      rvRank:rv?.rank||null,myRank:my?.rank||null,
      rvTop3:rv?.top3||[],eligible:!!rv};
  }).filter(x=>x.eligible);
  if(!raceData.length){
    container.innerHTML=`<div class="evol-alert neutral">ℹ️ <b>${escapeHtml(teamName)}</b> no tiene suficientes datos (mín. 3 corredores/carrera).</div>`;return;
  }
  const best=Math.min(...raceData.map(x=>x.rvRank));
  const avg=(raceData.reduce((s,x)=>s+x.rvRank,0)/raceData.length).toFixed(1);
  const coincide=raceData.filter(x=>x.myRank!==null).length;
  container.innerHTML=`
    <div class="evol-alert neutral" style="border-color:${_RIVAL_ORANGE}40">
      ⚔️ <b>${escapeHtml(teamName)}</b> · ${raceData.length} carreras con ranking · ${coincide} coincidencias con ${escapeHtml(myTeam||'tu equipo')}
    </div>
    <div class="evol-kpis" style="grid-template-columns:repeat(3,1fr)">
      <div class="evol-kpi"><div class="ek-label">Mejor ranking</div><div class="ek-value" style="color:${_RIVAL_ORANGE}">${best}º</div></div>
      <div class="evol-kpi"><div class="ek-label">Ranking medio</div><div class="ek-value">${avg}º</div></div>
      <div class="evol-kpi"><div class="ek-label">Coincidencias</div><div class="ek-value">${coincide}</div></div>
    </div>
    <div class="evol-main-chart"><canvas id="evolRivTeamChart"></canvas></div>`;
  requestAnimationFrame(()=>{
    const ctx=document.getElementById('evolRivTeamChart');
    if(!ctx||!window.Chart)return;
    const myValid=raceData.map(x=>x.myRank);
    const datasets=[{label:teamName,data:raceData.map(x=>x.rvRank),
      borderColor:_RIVAL_ORANGE,backgroundColor:_RIVAL_ORANGE+'22',borderWidth:3,fill:true,tension:0.3,
      pointRadius:6,pointBorderColor:'#fff',pointBorderWidth:2,pointBackgroundColor:_RIVAL_ORANGE}];
    if(myTeam&&myValid.some(v=>v!==null)){
      datasets.unshift({label:myTeam,data:myValid,
        borderColor:_MY_BLUE,backgroundColor:'transparent',borderWidth:2,fill:false,tension:0.3,borderDash:[5,3],
        pointRadius:4,pointBackgroundColor:_MY_BLUE});
    }
    const chart=new Chart(ctx,{type:'line',data:{labels:raceData.map(x=>_trendWrapLabel(x.raceName||'',26)),datasets},
      options:{responsive:true,maintainAspectRatio:false,
        scales:{y:{reverse:true,min:1,title:{display:true,text:'Ranking equipo'},ticks:{precision:0},grid:{color:'#f3f4f6'}},x:{ticks:{maxRotation:0,minRotation:0,font:{size:10},autoSkip:false},grid:{display:false}}},
        plugins:{legend:{display:datasets.length>1,position:'bottom',labels:{usePointStyle:true}}}
      }
    });
    evolCharts.push(chart);
  });
}
