/* ── Exportar modal detalle como PNG ────────────────────── */
async function _selExportDetail(slotIdx){
  const rider = _selCurrentSlots[slotIdx]; if(!rider) return;
  const modalEl = document.querySelector('.sel-detail-modal'); if(!modalEl) return;
  try{
    const cv = await html2canvas(modalEl,{scale:2,useCORS:true,backgroundColor:'#fff',logging:false});
    const a = document.createElement('a');
    a.href = cv.toDataURL('image/png');
    a.download = `ficha-${normalizeRiderName(rider.displayName)}-${new Date().toISOString().slice(0,10)}.png`;
    a.click();
  }catch(e){ console.error(e); alert('No se pudo exportar la imagen.'); }
}

/* ── Informe de Convocatoria ────────────────────────────── */
function _selRenderInforme(){
  const body = $('selInformeBody'); if(!body) return;
  const slots = _selCurrentSlots;
  const riders = slots.filter(Boolean);
  if(!riders.length){ body.innerHTML='<div style="color:#9ca3af;text-align:center;padding:40px">Sin ciclistas seleccionados.</div>'; return; }
  const COLORS=['#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6','#06b6d4'];

  body.innerHTML = slots.map((rider,i)=>{
    if(!rider) return '';
    const isTitular = i<4;
    const label = isTitular?`T${i+1}`:`S${i-3}`;
    const hdrClass = isTitular?'sel-informe-hdr-titular':'sel-informe-hdr-suplente';
    const color = COLORS[i%COLORS.length];
    const rows = (rider.raceHistory||[]).map(r=>`
      <tr>
        <td style="color:#6b7280;white-space:nowrap;font-size:11px">${r.raceDate||'—'}</td>
        <td style="font-weight:600">${escapeHtml(r.raceName||'—')}</td>
        <td style="text-align:center">${_selPosBadge(r.pos)}</td>
        <td><span style="background:${r.pos<=3?'#ffbf00':r.pos<=10?'#ff6b00':'#9ca3af'};color:#fff;border-radius:6px;padding:2px 7px;font-size:10px;font-weight:800">${r.pos<=3?'Podio':r.pos<=10?'Top 10':'Resto'}</span></td>
        <td style="color:#6b7280;font-size:11px">${escapeHtml(r.time||'—')}</td>
      </tr>`).join('');
    return `
      <div class="sel-informe-rider">
        <div class="sel-informe-hdr ${hdrClass}">
          <div class="sel-informe-badge">${label}</div>
          <div style="flex:1">
            <div style="font-size:16px;font-weight:900">${escapeHtml(_evolNormName(rider.displayName))}</div>
            <div style="font-size:12px;opacity:.75;margin-top:2px">${escapeHtml(rider.team)}</div>
          </div>
          ${(()=>{
            const _m=Math.max(3,Math.round(rider.avgPos*0.3));
            const _rel=rider.races>0?Math.round((rider.positions||[]).filter(p=>Math.abs(p-rider.avgPos)<=_m).length/rider.races*100):0;
            const _rc=_rel>=75?'#12b76a':_rel>=50?'#f59e0b':'#dc2626';
            const _adn=_computeADN(rider.positions||[],rider.raceHistory||[]);
            return `<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">
              <div style="text-align:center;background:rgba(255,255,255,.18);border-radius:8px;padding:6px 12px"><div style="font-size:18px;font-weight:900">${rider.bestPos}º</div><div style="font-size:8px;opacity:.65;text-transform:uppercase">Mejor</div></div>
              <div style="text-align:center;background:rgba(255,255,255,.18);border-radius:8px;padding:6px 12px"><div style="font-size:18px;font-weight:900">${rider.podiums}</div><div style="font-size:8px;opacity:.65;text-transform:uppercase">Podios</div></div>
              <div style="text-align:center;background:rgba(255,255,255,.18);border-radius:8px;padding:6px 12px"><div style="font-size:18px;font-weight:900">${rider.races}</div><div style="font-size:8px;opacity:.65;text-transform:uppercase">Carreras</div></div>
              <div style="text-align:center;background:rgba(255,255,255,.18);border-radius:8px;padding:6px 12px"><div style="font-size:18px;font-weight:900">${rider.avgPos.toFixed(1)}</div><div style="font-size:8px;opacity:.65;text-transform:uppercase">Media</div></div>
              <div style="text-align:center;background:rgba(255,255,255,.18);border-radius:8px;padding:6px 12px"><div style="font-size:18px;font-weight:900;color:${_rc}">${_rel}%</div><div style="font-size:8px;opacity:.65;text-transform:uppercase">Fiabilidad</div></div>
              <div style="background:rgba(255,255,255,.15);border-radius:8px;padding:6px 12px;display:flex;align-items:center;gap:5px">
                <span style="font-size:16px">${_adn.icon}</span>
                <div><div style="font-size:11px;font-weight:900;color:#fff">${_adn.label}</div><div style="font-size:8px;opacity:.65;text-transform:uppercase">ADN</div></div>
              </div>
            </div>`;
          })()}
        </div>
        <div style="padding:0 4px">
          <table class="sel-informe-tbl">
            <thead><tr><th>Fecha</th><th>Prueba</th><th style="text-align:center">Puesto</th><th>Banda</th><th>Tiempo</th></tr></thead>
            <tbody>${rows}</tbody>
          </table>
        </div>
      </div>`;
  }).join('');
}

/* ── Imprimir Informe Completo ───────────────────────────── */
function _selPrintInforme(){
  const slots = _selCurrentSlots;
  const COLORS=['#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6','#06b6d4'];
  const region = $('selRegionFilter')?.value||'VLC';
  const year   = $('selYearFilter')?.value||new Date().getFullYear();
  const cat    = _selSelectedCats.size>0?[..._selSelectedCats].join('+'):'Todas';
  const dateStr= new Date().toLocaleDateString('es-ES',{day:'2-digit',month:'long',year:'numeric'});
  const _logoPrint = (document.querySelector('img.brand-logo')?.src) || '';

  const ridersHtml = slots.map((rider,i)=>{
    if(!rider) return '';
    const isTitular=i<4; const label=isTitular?`T${i+1}`:`S${i-3}`;
    const rows = (rider.raceHistory||[]).map(r=>`
      <tr><td>${r.raceDate||'—'}</td><td>${escapeHtml(r.raceName||'—')}</td>
      <td style="text-align:center"><span class="pos-badge" style="background:${r.pos<=3?'#12b76a':r.pos<=5?'#22c55e':r.pos<=10?'#1d4ed8':r.pos<=20?'#f59e0b':'#9ca3af'}!important">${r.pos}º</span></td>
      <td><span class="banda" style="background:${r.pos<=3?'#ffbf00':r.pos<=10?'#f97316':'#6b7280'}!important">${r.pos<=3?'Podio':r.pos<=10?'Top 10':'Resto'}</span></td>
      <td style="color:#6b7280">${escapeHtml(r.time||'—')}</td></tr>`).join('');
    return `<div class="rider-block">
      <div class="rider-hdr" style="background:${isTitular?'linear-gradient(135deg,#0b2f6b,#1286c7)':'linear-gradient(135deg,#374151,#6b7280)'}">
        <span class="badge">${label}</span>
        <div><div class="rider-name">${escapeHtml(_evolNormName(rider.displayName))}</div><div class="rider-team">${escapeHtml(rider.team)}</div></div>
        <div class="kpis">
          <span class="kpi">${rider.bestPos}º <small>Mejor</small></span>
          <span class="kpi">${rider.podiums} <small>Podios</small></span>
          <span class="kpi">${rider.races} <small>Carrs.</small></span>
          <span class="kpi">${rider.avgPos.toFixed(1)} <small>Media</small></span>
          ${(()=>{const _m=Math.max(3,Math.round(rider.avgPos*0.3));const _rel=rider.races>0?Math.round((rider.positions||[]).filter(p=>Math.abs(p-rider.avgPos)<=_m).length/rider.races*100):0;const _adn=_computeADN(rider.positions||[],rider.raceHistory||[]);return `<span class="kpi" style="color:#fff">${_rel}% <small>Fiabilidad</small></span><span class="kpi">${_adn.icon} ${_adn.label} <small>ADN</small></span>`;})()}
        </div>
      </div>
      <table><thead><tr><th>Fecha</th><th>Prueba</th><th>Pos.</th><th>Banda</th><th>Tiempo</th></tr></thead>
      <tbody>${rows}</tbody></table>
    </div>`;
  }).join('');

  const w = window.open('','_blank');
  w.document.write(`<!DOCTYPE html><html><head><title>Informe Convocatoria VLC</title>
    <style>
      *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;color-adjust:exact!important}
      body{font-family:Arial,sans-serif;padding:20px;color:#111;font-size:12px}
      .page-hdr{background:linear-gradient(135deg,#0b2f6b,#1286c7)!important;color:#fff!important;padding:18px 22px;border-radius:12px;margin-bottom:20px;display:flex;align-items:center;justify-content:space-between;gap:14px}
      .page-hdr h1{font-size:20px;font-weight:900;margin:0 0 4px;color:#fff!important}
      .page-hdr p{margin:0;font-size:12px;opacity:.85;color:#fff!important}
      .page-hdr .brand{display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.18)!important;padding:7px 12px;border-radius:10px;flex-shrink:0}
      .page-hdr .brand img{height:32px;width:auto;filter:brightness(0) invert(1)}
      .page-hdr .brand span{font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;opacity:.85}
      .rider-block{border:1px solid #e5e7eb;border-radius:10px;margin-bottom:16px;overflow:hidden;page-break-inside:avoid}
      .rider-hdr{padding:12px 16px;color:#fff!important;display:flex;align-items:center;gap:12px}
      .rider-hdr *{color:#fff!important}
      .badge{background:rgba(255,255,255,.25)!important;border-radius:7px;padding:4px 9px;font-size:10px;font-weight:900;flex-shrink:0}
      .rider-name{font-size:15px;font-weight:900}.rider-team{font-size:11px;opacity:.8;margin-top:2px}
      .kpis{display:flex;gap:8px;margin-left:auto;flex-wrap:wrap}
      .kpi{background:rgba(255,255,255,.22)!important;border-radius:7px;padding:5px 10px;font-weight:900;font-size:13px;text-align:center}
      .kpi small{display:block;font-size:8px;opacity:.7;font-weight:400;text-transform:uppercase}
      table{width:100%;border-collapse:collapse}
      th{background:#f0f4f8!important;padding:6px 8px;text-align:left;font-size:9px;text-transform:uppercase;color:#475467;font-weight:700}
      td{padding:6px 8px;border-bottom:1px solid #f3f4f6}
      .pos-badge{display:inline-block;width:26px;height:26px;border-radius:50%;text-align:center;line-height:26px;font-weight:900;font-size:11px;color:#fff!important}
      .banda{display:inline-block;border-radius:5px;padding:2px 7px;font-size:10px;font-weight:800;color:#fff!important}
      @media print{body{padding:10px}@page{margin:1.2cm}}
    </style></head><body>
    <div class="page-hdr">
      <div>
        <h1>${_convoMode==='myteam'?`🎽 ${escapeHtml(myTeam||'Mi Equipo')} · Convocados próxima prueba`:'🏆 Informe de Convocatoria — Selección VLC (4+2)'}</h1>
        <p>${escapeHtml(cat)} · ${escapeHtml(String(year))} · ${escapeHtml(region)} · Generado el ${dateStr}</p>
      </div>
      ${_logoPrint?`<div class="brand"><img src="${_logoPrint}" alt="MFPP"><span>MFPP Cycling</span></div>`:''}
    </div>
    ${ridersHtml}
    <script>window.onload=()=>window.print()<\/script></body></html>`);
  w.document.close();
}

/* ── Exportar Informe de Convocatoria como PNG ──────────── */
async function _selExportInforme(){
  const informeBody = $('selInformeBody');
  if(!informeBody){ alert('No hay informe para exportar.'); return; }
  const riders = _selCurrentSlots.filter(Boolean);
  if(!riders.length){ alert('No hay ciclistas seleccionados.'); return; }

  // Asegurar que el informe está renderizado
  _selRenderInforme();

  // Wrapper con fondo y padding para la captura
  const wrap = document.createElement('div');
  wrap.style.cssText = 'position:fixed;top:0;left:-9999px;z-index:-1;background:#f4f7fb;font-family:Arial,sans-serif;width:900px;padding:24px 28px;box-sizing:border-box';

  // Cabecera
  const year   = $('selYearFilter')?.value  || new Date().getFullYear();
  const region = $('selRegionFilter')?.value || 'VLC';
  const cat    = _selSelectedCats.size>0 ? [..._selSelectedCats].join('+') : 'Todas las categorías';
  const dateStr= new Date().toLocaleDateString('es-ES',{day:'2-digit',month:'long',year:'numeric'});
  const hdr = document.createElement('div');
  hdr.style.cssText = 'background:linear-gradient(135deg,#0b2f6b,#1286c7);color:#fff;padding:22px 28px;border-radius:14px;margin-bottom:20px';
  const _logoInfHdr = (document.querySelector('img.brand-logo')?.src) || '';
  hdr.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:14px">
      <div style="flex:1;min-width:0">
        <div style="font-size:10px;font-weight:700;letter-spacing:2.5px;opacity:.65;text-transform:uppercase;margin-bottom:4px">📄 ${_convoMode==='myteam' ? 'Convocatoria del Equipo' : 'Informe de Convocatoria'}</div>
        <div style="font-size:22px;font-weight:900;line-height:1.1">${_convoMode==='myteam' ? (escapeHtml(myTeam||'Mi Equipo')+' · Convocados próxima prueba') : 'Selección Autonómica VLC'}</div>
        <div style="font-size:13px;opacity:.8;margin-top:4px">${escapeHtml(cat)} · ${escapeHtml(String(year))} · ${escapeHtml(region)}</div>
      </div>
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px">
        ${_logoInfHdr?`<div style="display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.18);padding:7px 12px;border-radius:10px"><img src="${_logoInfHdr}" alt="MFPP" style="height:32px;width:auto;filter:brightness(0) invert(1)"><span style="font-size:11px;font-weight:800;letter-spacing:1px;text-transform:uppercase;opacity:.85">MFPP Cycling</span></div>`:''}
        <div style="opacity:.6;font-size:11px">${dateStr}</div>
      </div>
    </div>`;
  wrap.appendChild(hdr);

  // Clonar el cuerpo del informe
  const clone = informeBody.cloneNode(true);
  clone.style.cssText = 'background:transparent';
  wrap.appendChild(clone);

  document.body.appendChild(wrap);
  try{
    const cv = await html2canvas(wrap,{scale:2,useCORS:true,backgroundColor:'#f4f7fb',logging:false,width:900,windowWidth:900});
    const a = document.createElement('a');
    a.href = cv.toDataURL('image/png');
    a.download = `informe-convocatoria-vlc-${String(year)}.png`;
    a.click();
  }catch(e){ console.error(e); alert('No se pudo exportar la imagen.'); }
  finally{ document.body.removeChild(wrap); }
}

/* ── Tooltip historial ──────────────────────────────────── */
function _selShowHistoryTip(event, slotIdx){
  const tip = $('selHistoryTip'); if(!tip) return;
  const rider = _selCurrentSlots[slotIdx]; if(!rider) return;
  const COLORS_POS = pos => pos<=3?'#12b76a':pos<=10?'#1d4ed8':pos<=20?'#f79009':'#b42318';

  const rows = (rider.raceHistory||[]).map(r=>{
    const short = (r.raceName||'').length>34 ? (r.raceName||'').slice(0,32)+'…' : (r.raceName||'');
    return `<div class="sel-history-tip-row">
      <span class="sel-history-tip-pos" style="color:${COLORS_POS(r.pos)}">${r.pos}º</span>
      <span class="sel-history-tip-race">${escapeHtml(short)}</span>
      <span class="sel-history-tip-date">${r.raceDate||''}</span>
    </div>`;
  }).join('');

  tip.innerHTML = `
    <div class="sel-history-tip-name">📋 ${escapeHtml(_evolNormName(rider.displayName))}</div>
    <div style="font-size:10px;color:#6b7280;margin-bottom:6px">${rider.races} carrera${rider.races!==1?'s':''} · Mejor: ${rider.bestPos}º · Media: ${rider.avgPos.toFixed(1)}</div>
    ${rows}`;
  tip.style.display = 'block';
  _selMoveTip(event);
}
function _selMoveTip(event){
  const tip = $('selHistoryTip'); if(!tip||tip.style.display==='none') return;
  const x = event.clientX + 16;
  const y = event.clientY - 10;
  const maxX = window.innerWidth  - (tip.offsetWidth  || 270) - 10;
  const maxY = window.innerHeight - (tip.offsetHeight || 250) - 10;
  tip.style.left = Math.min(x, maxX) + 'px';
  tip.style.top  = Math.max(10, Math.min(y, maxY)) + 'px';
}
function _selHideTip(){
  const tip = $('selHistoryTip'); if(tip) tip.style.display='none';
}

/* ── Picker de ciclista ─────────────────────────────────── */
function _selOpenPicker(slot){
  _selPickerSlot = slot;
  const inp = $('selPickerInput'); if(inp) inp.value='';
  _selPickerFilter();
  const ov = $('selPickerOverlay'); if(ov) ov.style.display='flex';
  setTimeout(()=>{ const inp=$('selPickerInput'); if(inp) inp.focus(); },80);
}
function _selPickerClose(){
  const ov = $('selPickerOverlay'); if(ov) ov.style.display='none';
}
function _selPickerFilter(){
  const q = ($('selPickerInput')?.value||'').toLowerCase().trim();
  const list = $('selPickerList'); if(!list) return;
  const riders = q
    ? _selPickerAllRiders.filter(r=>r.displayName.toLowerCase().includes(q)||r.team.toLowerCase().includes(q))
    : _selPickerAllRiders;
  list.innerHTML = riders.slice(0,60).map(r=>`
    <div class="sel-picker-item" onclick="_selPickerSelect('${escapeAttr(r.name)}')">
      <div>
        <div class="sel-picker-item-name">${escapeHtml(_evolNormName(r.displayName))}</div>
        <div class="sel-picker-item-meta">${escapeHtml(r.team)} &nbsp;·&nbsp; Media: ${r.avgPos.toFixed(1)} &nbsp;·&nbsp; ${r.races} carreras</div>
      </div>
      <div style="font-size:12px;font-weight:900;color:#1d4ed8;white-space:nowrap">${r.bestPos}º mejor</div>
    </div>`).join('');
}
function _selPickerSelect(nameKey){
  if(_selPickerSlot<0) return;
  _selManualOverrides[_selPickerSlot] = nameKey;
  _selPickerClose();
  const _ps = _convoTitularCount + 2;
  const baseN = _selPickerAllRiders.slice(0, _ps);
  const currentN = [];
  for(let i=0;i<_ps;i++){
    const ov=_selManualOverrides[i];
    currentN.push(ov?((_selPickerAllRiders.find(c=>c.name===ov))||baseN[i]||null):(baseN[i]||null));
  }
  _selCurrentSlots = currentN;
  _selRenderCards(currentN);
  _selRenderRadar(currentN);
  _selRenderMerits(currentN);
}

/* ── Panel de méritos (derecha del radar) ───────────────── */
function _selRenderMerits(slots){
  const panel = $('selMeritsPanel'); if(!panel) return;
  const riders = slots.filter(Boolean);
  if(!riders.length){
    panel.innerHTML='<div style="color:#9ca3af;font-size:13px;text-align:center;padding:40px 0">Sin datos disponibles</div>';
    return;
  }
  const COLORS=['#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6','#06b6d4'];
  const totalRaces   = riders.reduce((s,r)=>s+r.races,0);
  const totalPodiums = riders.reduce((s,r)=>s+r.podiums,0);
  const totalTop10   = riders.reduce((s,r)=>s+r.top10,0);
  const avgTeam      = (riders.reduce((s,r)=>s+r.avgPos,0)/riders.length).toFixed(1);

  const row = (r,i,label,labelColor)=>`
    <div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:1px solid #f3f4f6">
      <div style="width:26px;height:26px;border-radius:8px;background:${labelColor};display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:900;color:#fff;flex-shrink:0;letter-spacing:.5px">${label}</div>
      <div style="flex:1;min-width:0">
        <div style="font-weight:800;font-size:13px;color:#111827;line-height:1.2">${escapeHtml(_evolNormName(r.displayName))}</div>
        <div style="font-size:11px;color:#6b7280;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escapeHtml(r.team)}</div>
      </div>
      <div style="text-align:right;flex-shrink:0;min-width:72px">
        <div style="font-size:14px;font-weight:900;color:${labelColor}">${r.bestPos}º mejor</div>
        <div style="font-size:10px;color:#9ca3af">${r.podiums} pod · ${r.avgPos.toFixed(1)} media</div>
      </div>
    </div>`;

  panel.innerHTML=`
    <!-- KPIs globales del equipo -->
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:14px;padding-bottom:14px;border-bottom:2px solid #f3f4f6">
      <div style="text-align:center;background:#f8fbff;border-radius:10px;padding:10px 4px">
        <div style="font-size:22px;font-weight:900;color:#0b2f6b">${totalRaces}</div>
        <div style="font-size:9px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-top:2px">Apariciones</div>
      </div>
      <div style="text-align:center;background:#f0fdf4;border-radius:10px;padding:10px 4px">
        <div style="font-size:22px;font-weight:900;color:#12b76a">${totalPodiums}</div>
        <div style="font-size:9px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-top:2px">Podios</div>
      </div>
      <div style="text-align:center;background:#eff6ff;border-radius:10px;padding:10px 4px">
        <div style="font-size:22px;font-weight:900;color:#1d4ed8">${totalTop10}</div>
        <div style="font-size:9px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-top:2px">Top 10</div>
      </div>
      <div style="text-align:center;background:#fff7ed;border-radius:10px;padding:10px 4px">
        <div style="font-size:22px;font-weight:900;color:#f59e0b">${avgTeam}</div>
        <div style="font-size:9px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-top:2px">Media equipo</div>
      </div>
    </div>
    <!-- Titulares -->
    <div style="font-size:10px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;color:#6b7280;margin-bottom:6px">🔵 Titulares</div>
    ${slots.slice(0,4).map((r,i)=>r?row(r,i,`T${i+1}`,COLORS[i]):'').join('')}
    <!-- Suplentes -->
    <div style="font-size:10px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;color:#6b7280;margin:12px 0 6px">⚫ Suplentes</div>
    ${slots.slice(4,6).map((r,i)=>r?row(r,i+4,`S${i+1}`,'#6b7280'):'').join('')}`;
}

/* ── Radar comparativo ──────────────────────────────────── */
function _selRiderMetrics(rider){
  if(!rider||!rider.positions.length) return {rendimiento:0,podios:0,top10:0,regularidad:0,participacion:0};
  const n   = rider.positions.length;
  const tot = _selLastHistory ? _selLastHistory.length : n;
  const avg = rider.avgPos;
  const maxP = Math.max(...rider.positions, 20);
  const rend = maxP>1 ? Math.max(0, Math.round((1-(avg-1)/(maxP-1))*100)) : 50;
  const stdDev = n>1 ? Math.sqrt(rider.positions.map(p=>Math.pow(p-avg,2)).reduce((s,v)=>s+v)/n) : 0;
  return {
    rendimiento : rend,
    podios      : Math.round(rider.podiums/n*100),
    top10       : Math.round(rider.top10/n*100),
    regularidad : Math.max(0, Math.round(100-stdDev*3)),
    participacion: Math.round(Math.min(n,tot)/tot*100)
  };
}
function _selRenderRadar(slots){
  const canvas = $('selRadarCanvas'); if(!canvas) return;
  const riders = slots.filter(Boolean);
  if(!riders.length){ if(_selRadarChart){_selRadarChart.destroy();_selRadarChart=null;} return; }
  const COLORS = ['#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6','#06b6d4'];
  const labels = ['Rendimiento','Podios %','Top 10 %','Regularidad','Participación'];
  const datasets = riders.map((r,i)=>({
    label: _evolNormName(r.displayName),
    data: Object.values(_selRiderMetrics(r)),
    borderColor: COLORS[i%COLORS.length],
    backgroundColor: COLORS[i%COLORS.length]+'22',
    borderWidth: 2, pointRadius: 3
  }));
  if(_selRadarChart){_selRadarChart.destroy();_selRadarChart=null;}
  _selRadarChart = new Chart(canvas,{
    type:'radar',
    data:{labels,datasets},
    options:{
      responsive:true, maintainAspectRatio:false,
      scales:{r:{min:0,max:100,ticks:{stepSize:25,font:{size:9}},pointLabels:{font:{size:11,weight:'bold'}}}},
      plugins:{legend:{position:'bottom',labels:{font:{size:11},boxWidth:12}}}
    }
  });
}

