// ═══════════════════════════════════════════════════════════════════════════
// SIMULADOR DE CARRERAS — Predicción Fase 1
// 1. Selector de prueba con startlist
// 2. Algoritmo de cruce con histórico
// 3. KPIs Nivel de Dificultad + Predictibilidad
// 4. Top 10 esperado
// 5. Manejo de debutantes (fallback equipo)
// 6. Exportar PDF
// ═══════════════════════════════════════════════════════════════════════════

let _simSelectedRaceId = null;
let _simCurrentData = null; // {race, inscritos[], grid[], kpis}

function renderSimulador(){
  const sel = document.getElementById('simRaceSelect');
  if(!sel) return;
  // Cargar las pruebas del histórico que tienen inscritos (incluye pre-inscripciones)
  const hist = _cachedHistory || [];
  const racesWithIns = hist.filter(h => Array.isArray(h.inscritos) && h.inscritos.length>0);
  if(!racesWithIns.length){
    sel.innerHTML = '<option value="">— No hay pruebas con startlist guardada —</option>';
    sel.disabled = true;
    _simShowEmpty('No hay ninguna prueba con lista de inscritos guardada en el histórico. Sube una startlist desde Carga y Resumen o Historial para empezar a simular.');
    return;
  }
  sel.disabled = false;
  // Ordenar: pruebas futuras (pre-inscripciones) primero, luego más recientes
  const today = (new Date()).toISOString().slice(0,10);
  racesWithIns.sort((a,b)=>{
    const da = _parseSpanishDate(a.raceDate)||'0000-00-00';
    const db = _parseSpanishDate(b.raceDate)||'0000-00-00';
    const aFuture = da >= today;
    const bFuture = db >= today;
    if(aFuture && !bFuture) return -1;
    if(bFuture && !aFuture) return 1;
    return db.localeCompare(da);
  });
  const opts = racesWithIns.map(h=>{
    const iso = _parseSpanishDate(h.raceDate)||'';
    const dt = formatDateDisplay(iso) || h.raceDate || '';
    const future = iso && iso >= today;
    const ridersN = (h.riders||[]).length;
    const tag = future ? '🔮' : (ridersN>=3 ? '🏁' : '📋');
    return `<option value="${escapeAttr(h.id)}">${tag} ${escapeHtml(dt)} · ${escapeHtml(h.raceName||'')} · ${h.inscritos.length} inscritos${ridersN>=3?` · ${ridersN} clasif.`:' (sin clasificar)'}</option>`;
  }).join('');
  sel.innerHTML = '<option value="">— Selecciona una prueba —</option>' + opts;
  // Si tenemos uno seleccionado, mantenerlo
  if(_simSelectedRaceId && [...sel.options].some(o=>o.value===_simSelectedRaceId)){
    sel.value = _simSelectedRaceId;
    _simOnRaceChange();
  } else {
    _simShowEmpty();
  }
}

function _simShowEmpty(customMsg){
  document.getElementById('simEmptyPanel').style.display = '';
  document.getElementById('simKpiPanel').style.display = 'none';
  document.getElementById('simTopPanel').style.display = 'none';
  document.getElementById('simGridPanel').style.display = 'none';
  document.getElementById('simRaceMeta').style.display = 'none';
  document.getElementById('simCatPickerWrap').style.display = 'none';
  document.getElementById('simExportBtn').style.display = 'none';
  if(customMsg){
    const empty = document.getElementById('simEmptyPanel');
    empty.querySelector('p').textContent = customMsg;
  }
}

function _simOnRaceChange(){
  const sel = document.getElementById('simRaceSelect');
  const id = sel?.value || '';
  if(!id){ _simShowEmpty(); _simSelectedRaceId = null; return; }
  _simSelectedRaceId = id;
  _simBuildData(id);
  _simRenderCurrent();
}

// ═══════════════════════════════════════════════════════════════════════════
// MOTOR ESTADÍSTICO — FUNCIONES HELPER
// Funciones puras y documentadas. Cada una protegida contra null/NaN.
// ═══════════════════════════════════════════════════════════════════════════

// — Fiabilidad: % de consistencia + techo por posición media —
// Un corredor que SIEMPRE acaba en la cola NO puede tener fiabilidad alta:
//   pos. media > 75% del pelotón → techo 40%
//   pos. media > 50% del pelotón → techo 65%
// Esto evita que corredores siempre últimos aparezcan como "100% fiables".
function _simReliability(positions, refGridSize){
  if(!positions || !positions.length) return null;
  if(positions.length === 1) return 50; // 1 sola carrera: incertidumbre alta
  const mu = positions.reduce((a,b)=>a+b,0) / positions.length;
  // Banda estricta del 15% (antes 30%), mínimo ±3 puestos
  const band = Math.max(3, mu * 0.15);
  const inBand = positions.filter(p => Math.abs(p - mu) <= band).length;
  let raw = Math.round((inBand / positions.length) * 100);
  // Techo por posición relativa al pelotón típico
  const N = refGridSize > 0 ? refGridSize : 60;
  if(mu > N * 0.75)      raw = Math.min(raw, 40);
  else if(mu > N * 0.50) raw = Math.min(raw, 65);
  else if(mu > N * 0.30) raw = Math.min(raw, 85);
  return Math.max(0, Math.min(100, raw));
}

// — Tendencia unificada (últimas N carreras) —
// Compara promedio reciente vs promedio anterior. Umbral ±2 puestos.
function _simTrend(recentForm){
  if(!recentForm || recentForm.length < 2) return 'unknown';
  let recent, older;
  if(recentForm.length >= 4){
    recent = (recentForm[0] + recentForm[1]) / 2;
    const rest = recentForm.slice(2);
    older = rest.reduce((a,b)=>a+b,0) / rest.length;
  } else {
    recent = recentForm[0];
    older = recentForm[recentForm.length - 1];
  }
  const delta = older - recent;          // delta>0 → ha mejorado (baja la posición)
  if(delta >  2.0) return 'up';
  if(delta < -2.0) return 'down';
  return 'stable';
}

// — Probabilidad Bernoulli con Laplace smoothing —
// Reemplaza Poisson: matemáticamente correcto para "1 carrera futura".
// P = (éxitos + 1) / (intentos + 2). El smoothing evita 0% y 100% absurdos
// con muestras pequeñas y representa el prior uniforme Beta(1,1).
function _simBernoulli(hits, total){
  if(total == null || total <= 0) return null;
  if(hits == null || hits < 0)    return null;
  return (hits + 1) / (total + 2);
}

// — Categoría cadete: detecta año por la cadena, sin solaparse con experiencia —
// Devuelve {isCadet, year:1|2|null}
function _simCadetCategory(catStr){
  const c = String(catStr||'').toLowerCase();
  const isCadet = /cad(ete|et)?/.test(c);
  if(!isCadet) return {isCadet:false, year:null};
  // Marca explícita "1" o "m1"/"f1" tras la palabra cadete o separador
  if(/(?:cad\w*\s*\-?\s*|^|[\s\-])(m|f)?1\b/.test(c)) return {isCadet:true, year:1};
  if(/(?:cad\w*\s*\-?\s*|^|[\s\-])(m|f)?2\b/.test(c)) return {isCadet:true, year:2};
  return {isCadet:true, year:null};
}

// — Sigmoide protegida —
function _simSigmoid(z){
  if(!isFinite(z)) return z > 0 ? 100 : 0;
  return Math.max(0, Math.min(100, Math.round(100 / (1 + Math.exp(-z)))));
}

// — Acota una posición al rango físico [1, max] —
function _simCapPos(p, max){
  if(p == null) return null;
  const m = max > 0 ? max : 999;
  return Math.max(1, Math.min(m, Math.round(p)));
}

// Construye el grid analizado: para cada inscrito, calcula sus métricas históricas
function _simBuildData(raceId){
  const hist = _cachedHistory || [];
  const race = hist.find(h => h.id === raceId);
  if(!race){ _simCurrentData = null; return; }
  const inscritos = race.inscritos || [];
  // Índices del histórico (excluyendo la propia prueba si no se ha disputado, para no contaminar)
  const historicalRaces = hist.filter(h => h.id !== raceId && (h.riders||[]).length >= 3);
  // Index: nameKey → array de {pos, total, raceDate, cat, team}
  const byRider = new Map();
  // Index: teamKey → array de posiciones de cualquier corredor
  const byTeam = new Map();
  historicalRaces.forEach(h=>{
    (h.riders||[]).forEach(r=>{
      const nk = normalizeForMatching(r.name||'');
      if(nk){
        if(!byRider.has(nk)) byRider.set(nk, []);
        byRider.get(nk).push({pos:r.pos, raceDate:h.raceDate, cat:r.cat, team:r.team});
      }
      const tk = (r.team||'').toLowerCase().trim();
      if(tk){
        if(!byTeam.has(tk)) byTeam.set(tk, []);
        byTeam.get(tk).push(r.pos);
      }
    });
  });

  // Para cada inscrito, calcular métricas
  const myTeamLower = (myTeam||'').toLowerCase().trim();
  const totalInsRef = inscritos.length || 60; // tamaño de pelotón de referencia
  const grid = inscritos.map((ins, idx)=>{
    const nk = normalizeForMatching(ins.name||'');
    const hits = nk ? (byRider.get(nk)||[]) : [];
    const tkey = (ins.team||'').toLowerCase().trim();
    const isMyTeam = myTeamLower && tkey === myTeamLower;
    let avgPos=null, bestPos=null, reliability=null, status='known', source='rider', confidence='nula';
    let recentForm = []; // últimas 5 posiciones (más reciente primero)
    let predictedPos=null, predLower=null, predUpper=null, trend='unknown';
    // Árbol de Regresión — nodos y clasificación de rango
    let rangeClass='none', treeNode=[];
    // Probabilidades brutas Bernoulli (sin ajuste de dificultad)
    let probTop10Raw=null, probPodiumRaw=null;
    // Factores aplicados (transparencia)
    let cadetFactor=1.0, relPenalty=1.0;

    if(hits.length){
      const positions = hits.map(h=>h.pos).filter(p=>p>0);
      if(positions.length){
        avgPos  = positions.reduce((s,p)=>s+p,0)/positions.length;
        bestPos = Math.min(...positions);
        reliability = _simReliability(positions, totalInsRef);
        confidence  = positions.length>=5 ? 'alta' : positions.length>=3 ? 'media' : 'baja';

        // ── Bernoulli con Laplace smoothing (sustituye al Poisson) ─────────
        // Usa SOLO carreras válidas (positions.length) — coherente con avgPos
        probTop10Raw  = _simBernoulli(positions.filter(p=>p<=10).length, positions.length);
        probPodiumRaw = _simBernoulli(positions.filter(p=>p<=3).length,  positions.length);

        // Recent form: ordenar por fecha desc y coger 5
        const sorted = hits.slice().sort((a,b)=>{
          const da = _parseSpanishDate(a.raceDate)||'0000-00-00';
          const db = _parseSpanishDate(b.raceDate)||'0000-00-00';
          return db.localeCompare(da);
        });
        recentForm = sorted.slice(0,5).map(h=>h.pos).filter(p=>p>0);
        trend = _simTrend(recentForm);

        // ══ ÁRBOL DE REGRESIÓN ════════════════════════════════════════════════
        // — RAMA A: Categoría y experiencia —
        const {isCadet, year} = _simCadetCategory(ins.cat);
        if(isCadet && year === 1){
          cadetFactor = 1.20;
          treeNode.push('A1:cadete-1er-año');
        } else if(isCadet && year === 2 && hits.length < 3){
          // 2º año pero apenas ha competido: penalización suavizada
          cadetFactor = 1.10;
          treeNode.push('A2b:cadete-2º-novato');
        } else if(isCadet && year === 2){
          treeNode.push('A2:cadete-2º-veterano');
        } else if(isCadet && hits.length < 3){
          cadetFactor = 1.15;
          treeNode.push('A3:cadete-sin-año-novato');
        } else if(isCadet){
          treeNode.push('A3:cadete');
        } else {
          treeNode.push('A0:base');
        }

        // — Fórmula ponderada 60/40: 60% forma reciente + 40% histórico —
        const recent3 = recentForm.slice(0,3);
        const recentMean = recent3.length ? recent3.reduce((s,p)=>s+p,0)/recent3.length : null;
        predictedPos = recentMean!=null ? 0.6*recentMean + 0.4*avgPos : avgPos;
        predictedPos *= cadetFactor;

        // — Penalización transparente por fiabilidad —
        // Documentada en el panel de ayuda: ×1.00 / ×1.08 / ×1.15 / ×1.20
        relPenalty = reliability >= 75 ? 1.00
                   : reliability >= 50 ? 1.08
                   : reliability >= 25 ? 1.15
                   : 1.20;
        predictedPos *= relPenalty;

        // — RAMA C: Fiabilidad → ajuste del intervalo de confianza —
        let relFactor;
        if(reliability >= 75){
          relFactor = 0.6; rangeClass = 'stable';
          treeNode.push('C1:alta-fiabilidad');
        } else if(reliability < 40){
          relFactor = 1.4; rangeClass = 'unstable';
          treeNode.push('C3:baja-fiabilidad');
        } else {
          relFactor = 0.8; rangeClass = 'normal';
          treeNode.push('C2:fiabilidad-media');
        }

        if(positions.length >= 2){
          const variance = positions.reduce((s,p)=>s+(p-avgPos)**2,0)/positions.length;
          const std = Math.sqrt(variance);
          predLower = predictedPos - std * relFactor;
          predUpper = predictedPos + std * relFactor;
        } else {
          const pct = reliability>=75 ? 0.10 : reliability<40 ? 0.30 : 0.15;
          predLower = predictedPos * (1 - pct);
          predUpper = predictedPos * (1 + pct);
        }
        // ══ FIN ÁRBOL DE REGRESIÓN ════════════════════════════════════════════
      } else {
        status = 'deb';
      }
    } else {
      // ══ RAMA B: Sin historial individual → fallback al club ═══════════════
      status = 'deb';
      if(tkey && byTeam.has(tkey)){
        const teamPositions = byTeam.get(tkey).filter(p=>p>0);
        if(teamPositions.length){
          avgPos  = teamPositions.reduce((s,p)=>s+p,0)/teamPositions.length;
          bestPos = Math.min(...teamPositions);
          // Fiabilidad del club, capada al 70% por incertidumbre del debutante
          const clubRel = _simReliability(teamPositions, totalInsRef);
          reliability = clubRel != null ? Math.min(70, clubRel) : 35;
          predictedPos = avgPos;
          predLower = avgPos * 0.78;
          predUpper = avgPos * 1.22;
          rangeClass = 'club-fb';
          source = 'team';
          status = 'team-fb';
          confidence = 'baja';
          treeNode.push('B:club-fallback');
          probTop10Raw  = _simBernoulli(teamPositions.filter(p=>p<=10).length, teamPositions.length);
          probPodiumRaw = _simBernoulli(teamPositions.filter(p=>p<=3).length,  teamPositions.length);
        } else {
          treeNode.push('B:deb-sin-datos');
        }
      } else {
        treeNode.push('B:deb-sin-club');
      }
    }
    return {
      idx,
      bib: ins.bib || '',
      name: ins.name || '',
      team: ins.team || '',
      cat: ins.cat || '',
      isMyTeam,
      hasHistory: hits.length > 0,
      avgPos, bestPos, reliability, status, source, confidence,
      raceCount: hits.length,
      recentForm, trend,
      // Árbol de Regresión — predicción enriquecida (acotada en post-proceso)
      predictedPos, predLower, predUpper,
      rangeClass, treeNode,
      // Bernoulli — brutas, ajustadas por dificultad en post-proceso
      probTop10Raw, probPodiumRaw,
      // Transparencia
      cadetFactor, relPenalty
    };
  });

  // ── ACOTAR posiciones al rango físico [1, totalIns] ─────────────────────
  const _capN = inscritos.length || 60;
  grid.forEach(g=>{
    g.predictedPos = _simCapPos(g.predictedPos, _capN);
    g.predLower    = _simCapPos(g.predLower,    _capN);
    g.predUpper    = _simCapPos(g.predUpper,    _capN);
  });

  // ══ KPIs GLOBALES ═════════════════════════════════════════════════════════
  const withMetrics = grid.filter(g=>g.avgPos!=null);
  // Dificultad: % de RIVALES (no de mi equipo) con avgPos<15
  const rivalsWithHist = grid.filter(g => !g.isMyTeam && g.avgPos != null);
  const strongRivals   = rivalsWithHist.filter(g => g.avgPos < 15).length;
  const totalIns = inscritos.length;
  // Denominador: nº de rivales con historial (excluye mi equipo y debutantes sin datos)
  const difficulty = rivalsWithHist.length
    ? Math.round((strongRivals / rivalsWithHist.length) * 100)
    : 0;

  // ══ Ajuste de probabilidades por dificultad ═════════════════════════════
  // Factor lineal documentado: dif=0 → ×1.00, dif=50 → ×0.75, dif=100 → ×0.50
  const _diffFactor = 1 - (difficulty * 0.5 / 100);
  grid.forEach(g=>{
    g.probTop10Poisson  = g.probTop10Raw  != null ? Math.max(0, Math.min(100, Math.round(g.probTop10Raw  * _diffFactor * 100))) : null;
    g.probPodiumPoisson = g.probPodiumRaw != null ? Math.max(0, Math.min(100, Math.round(g.probPodiumRaw * _diffFactor * 100))) : null;
  });

  // ══ REGRESIÓN LOGÍSTICA ══════════════════════════════════════════════════
  // Calibrada para ser COHERENTE con el Árbol de Regresión:
  //   un favorito predicho como 1º debe tener ≥70% de podio (no 14%).
  // Pesos transparentes — el panel los muestra al usuario.
  grid.forEach(g=>{
    const pos = g.predictedPos;
    const rel = g.reliability;
    if(pos == null || rel == null){
      g.probPodiumLogistic = null;
      g.probCutLogistic    = null;
      return;
    }
    const tVal = g.trend==='up' ? 1 : g.trend==='down' ? -1 : 0;
    const relN = rel / 100;

    // — Prob. Podio (sigmoide) —
    // z = -1.0 - 0.30·(pos-1) + 1.00·trend + 1.50·rel
    //   pos=1 + rel=80% + trend=up   → z=1.7 → 85%
    //   pos=3 + rel=70% + trend=stab → z=-0.55 → 37%
    //   pos=10+ rel=50% + trend=down → z=-3.95 → 2%
    const zPodium = -1.0
      - 0.30 * Math.max(0, pos - 1)
      + 1.00 * tVal
      + 1.50 * relN;
    g.probPodiumLogistic = _simSigmoid(zPodium);

    // — Riesgo de corte/abandono —
    // z = -3.0 + 0.05·(pos-1) - 1.00·trend - 2.50·rel + 0.040·dif
    //   rel=25% + dif=80% + trend=down + pos=25 → z=2.0 → 88%
    //   rel=80% + dif=30% + trend=up   + pos=5  → z=-4.5 → 1%
    //   rel=50% + dif=60% + trend=stab + pos=15 → z=-0.85 → 30%
    const zCut = -3.0
      + 0.05 * Math.max(0, pos - 1)
      - 1.00 * tVal
      - 2.50 * relN
      + 0.040 * difficulty;
    g.probCutLogistic = _simSigmoid(zCut);
  });
  // ══ FIN REGRESIÓN LOGÍSTICA ═══════════════════════════════════════════════
  // Predictibilidad: media de reliability solo de los conocidos (con muestra)
  const knownRel = grid.filter(g=>g.hasHistory && g.reliability!=null);
  const avgReliability = knownRel.length ? Math.round(knownRel.reduce((s,g)=>s+g.reliability,0)/knownRel.length) : 0;
  const coverage = totalIns ? Math.round((grid.filter(g=>g.hasHistory).length/totalIns)*100) : 0;
  const predictability = Math.round(avgReliability * (coverage/100)); // pondera por cobertura

  const myTeamCount = grid.filter(g=>g.isMyTeam).length;
  const myTeamWithHist = grid.filter(g=>g.isMyTeam && g.hasHistory).length;

  _simCurrentData = {
    race, inscritos, grid,
    kpis:{ totalIns, strongRivals, difficulty, avgReliability, coverage, predictability, myTeamCount, myTeamWithHist }
  };
}

function _simRenderCurrent(){
  if(!_simCurrentData){ _simShowEmpty(); return; }
  const {race, inscritos, grid, kpis} = _simCurrentData;
  // Mostrar paneles
  document.getElementById('simEmptyPanel').style.display = 'none';
  document.getElementById('simKpiPanel').style.display = '';
  document.getElementById('simTopPanel').style.display = '';
  document.getElementById('simGridPanel').style.display = '';
  document.getElementById('simRaceMeta').style.display = 'flex';
  document.getElementById('simExportBtn').style.display = 'inline-block';
  // Meta de la carrera
  const ridersN = (race.riders||[]).length;
  const isPre = ridersN < 3;
  const stateChip = isPre
    ? '<span class="ib-chip" style="background:#eef2ff;border-color:#c7d2fe;color:#1e3a8a">🔮 Pre-carrera</span>'
    : `<span class="ib-chip ok">🏁 Disputada · ${ridersN} clasificados</span>`;
  document.getElementById('simRaceMeta').innerHTML = `
    <b>🏁 ${escapeHtml(race.raceName||'')}</b>
    ${race.raceDate?`<span>📅 ${escapeHtml(race.raceDate)}</span>`:''}
    ${race.localidad?`<span>📍 ${escapeHtml(race.localidad)}</span>`:''}
    ${race.circuitType?`<span>🛣️ ${escapeHtml(race.circuitType)}</span>`:''}
    <span>📋 ${inscritos.length} inscritos</span>
    ${stateChip}
  `;
  // Categorías disponibles en los inscritos
  const cats = [...new Set(inscritos.map(i=>i.cat).filter(Boolean))].sort();
  const catWrap = document.getElementById('simCatPickerWrap');
  const catSel = document.getElementById('simCatSelect');
  if(cats.length > 1){
    catWrap.style.display = '';
    if(catSel.options.length <= 1 || catSel.dataset.race !== race.id){
      catSel.innerHTML = '<option value="">— Todas —</option>' + cats.map(c=>`<option value="${escapeAttr(c)}">${escapeHtml(c)}</option>`).join('');
      catSel.dataset.race = race.id;
    }
  } else {
    catWrap.style.display = 'none';
    catSel.value = '';
  }

  // KPIs
  _simRenderKpis(kpis);
  // Aplicar filtros
  const catFilter = catSel.value || '';
  const q = (document.getElementById('simSearchInput')?.value || '').toLowerCase().trim();
  const onlyMy = document.getElementById('simOnlyMyTeam')?.checked;
  const onlyKnown = document.getElementById('simOnlyKnown')?.checked;
  let filtered = grid.slice();
  if(catFilter) filtered = filtered.filter(g => (g.cat||'') === catFilter);
  if(q) filtered = filtered.filter(g => `${g.name} ${g.team} ${g.bib}`.toLowerCase().includes(q));
  if(onlyMy) filtered = filtered.filter(g => g.isMyTeam);
  if(onlyKnown) filtered = filtered.filter(g => g.hasHistory);
  // Top 10 esperado
  _simRenderTop10(grid.slice(), catFilter);
  // Tabla
  _simRenderGrid(filtered);
}

function _simRenderKpis(k){
  const body = document.getElementById('simKpiBody');
  if(!body) return;
  // Color de dificultad: <30% verde, 30-60 amarillo, >60 rojo
  const diffColor = k.difficulty<30?'#16a34a':k.difficulty<60?'#f59e0b':'#dc2626';
  const diffLabel = k.difficulty<30?'Asequible':k.difficulty<60?'Competitiva':'Exigente';
  // Color de predictibilidad: >=70 verde, 40-69 amarillo, <40 rojo
  const predColor = k.predictability>=70?'#16a34a':k.predictability>=40?'#f59e0b':'#dc2626';
  const predLabel = k.predictability>=70?'Alta':k.predictability>=40?'Media':'Baja';
  // Cobertura
  const covColor = k.coverage>=70?'#16a34a':k.coverage>=40?'#f59e0b':'#dc2626';

  body.innerHTML = `
    <div class="sim-kpi-card sim-kpi-difficulty">
      <div class="sim-kpi-label">⚠️ Dificultad de la prueba</div>
      <div class="sim-kpi-value" style="color:${diffColor}">${k.difficulty}%</div>
      <div class="sim-kpi-sub">${k.strongRivals} rivales fuertes (pos. media &lt; 15)</div>
      <div class="sim-kpi-sub" style="margin-top:2px;font-weight:700;color:${diffColor}">${diffLabel}</div>
      <div class="sim-kpi-bar"><div class="sim-kpi-bar-fill" style="width:${k.difficulty}%;background:${diffColor}"></div></div>
    </div>
    <div class="sim-kpi-card sim-kpi-predict">
      <div class="sim-kpi-label">🎯 Predictibilidad</div>
      <div class="sim-kpi-value" style="color:${predColor}">${k.predictability}%</div>
      <div class="sim-kpi-sub">Fiabilidad media: ${k.avgReliability}% · Cobertura histórica: ${k.coverage}%</div>
      <div class="sim-kpi-sub" style="margin-top:2px;font-weight:700;color:${predColor}">${predLabel}</div>
      <div class="sim-kpi-bar"><div class="sim-kpi-bar-fill" style="width:${k.predictability}%;background:${predColor}"></div></div>
    </div>
    <div class="sim-kpi-card sim-kpi-coverage">
      <div class="sim-kpi-label">🔍 Cobertura histórica</div>
      <div class="sim-kpi-value" style="color:${covColor}">${k.coverage}%</div>
      <div class="sim-kpi-sub">${k.totalIns - Math.round(k.totalIns*(1-k.coverage/100))} de ${k.totalIns} inscritos con histórico</div>
      <div class="sim-kpi-sub" style="margin-top:2px">${k.totalIns - Math.round(k.totalIns*k.coverage/100)} debutantes / sin datos</div>
      <div class="sim-kpi-bar"><div class="sim-kpi-bar-fill" style="width:${k.coverage}%;background:${covColor}"></div></div>
    </div>
    ${ (myTeam && k.myTeamCount>0) ? `
    <div class="sim-kpi-card sim-kpi-mine">
      <div class="sim-kpi-label">🔵 Mi equipo en parrilla</div>
      <div class="sim-kpi-value">${k.myTeamCount}</div>
      <div class="sim-kpi-sub">${k.myTeamWithHist} con historial · ${k.myTeamCount-k.myTeamWithHist} debutantes</div>
      <div class="sim-kpi-sub" style="margin-top:2px;font-weight:700;color:#1d4ed8">${escapeHtml(myTeam)}</div>
    </div>` : ''}
  `;
}

function _simRenderTop10(grid, catFilter){
  const body = document.getElementById('simTopBody');
  if(!body) return;
  let pool = grid.filter(g=>g.predictedPos!=null || g.avgPos!=null);
  if(catFilter) pool = pool.filter(g=>(g.cat||'')===catFilter);
  // Ordenar por predictedPos (fórmula 60/40 + penalización fiabilidad)
  // Si no hay predictedPos calculado, usar avgPos con penalización suave
  pool.forEach(g=>{
    if(g.predictedPos==null){
      const rel = g.reliability ?? 30;
      g.predictedPos = (g.avgPos||99) * (1 + (100-rel)/200);
    }
  });
  pool.sort((a,b)=>(a.predictedPos||99) - (b.predictedPos||99));
  const top = pool.slice(0,10);
  if(!top.length){
    body.innerHTML = '<p class="small" style="text-align:center;padding:14px;color:#9ca3af">Sin datos históricos suficientes para predecir el podio.</p>';
    return;
  }
  body.innerHTML = `<div class="sim-top-list">${top.map((g,i)=>{
    const rank = i+1;
    const rankCls = rank===1?'gold':rank===2?'silver':rank===3?'bronze':'def';
    const confDot = `<span class="sim-conf ${g.confidence}" title="Confianza ${g.confidence}"></span>`;
    const trendIcon = g.trend==='up'
      ? '<span title="Mejorando" style="color:#16a34a;font-size:14px;font-weight:900">⬆️</span>'
      : g.trend==='down'
      ? '<span title="Empeorando" style="color:#dc2626;font-size:14px;font-weight:900">⬇️</span>'
      : '<span title="Estable" style="color:#9ca3af;font-size:13px">➡️</span>';
    const _rc2 = g.rangeClass||'normal';
    const _rc2c = _rc2==='stable'?'#16a34a':_rc2==='unstable'?'#d97706':_rc2==='club-fb'?'#2563eb':'#7c3aed';
    const _rc2i = _rc2==='stable'?'🔒':_rc2==='unstable'?'⚠️':_rc2==='club-fb'?'📊':'';
    const rangeStr = (g.predLower!=null && g.predUpper!=null)
      ? `<span style="color:${_rc2c}">${_rc2i} ${g.predLower}º–${g.predUpper}º</span>`
      : (g.predictedPos!=null ? `<span style="color:${_rc2c}">${_rc2i} ${Math.round(g.predictedPos)}º</span>` : '—');
    return `<div class="sim-top-row ${g.isMyTeam?'sim-my-team':''}">
      <div class="sim-top-rank ${rankCls}">${rank}º</div>
      <div class="sim-top-info">
        <div class="sim-top-name">${confDot}${g.isMyTeam?'🔵 ':''}${escapeHtml(g.name)} ${trendIcon}</div>
        <div class="sim-top-team">${escapeHtml(g.team||'(sin equipo)')}${g.cat?' · '+escapeHtml(g.cat):''}${g.bib?' · #'+escapeHtml(g.bib):''}${g.status==='team-fb'?' · <span style="color:#3730a3;font-weight:700">[fallback equipo]</span>':''}</div>
      </div>
      <div class="sim-top-metrics">
        <div class="sim-top-metric sim-predicted-metric"><div class="sim-top-metric-v" style="color:#7c3aed">${rangeStr}</div><div class="sim-top-metric-l">🤖 Pos. IA</div></div>
        <div class="sim-top-metric"><div class="sim-top-metric-v">${g.avgPos!=null?g.avgPos.toFixed(1)+'º':'—'}</div><div class="sim-top-metric-l">Media</div></div>
        <div class="sim-top-metric"><div class="sim-top-metric-v">${g.bestPos!=null?g.bestPos+'º':'—'}</div><div class="sim-top-metric-l">Mejor</div></div>
        <div class="sim-top-metric"><div class="sim-top-metric-v">${g.reliability??'—'}%</div><div class="sim-top-metric-l">Fiab.</div></div>
        <div class="sim-top-metric"><div class="sim-top-metric-v">${g.raceCount||0}</div><div class="sim-top-metric-l">Carrs.</div></div>
      </div>
    </div>`;
  }).join('')}</div>`;
}

function _simRenderGrid(rows){
  const body = document.getElementById('simGridBody');
  const count = document.getElementById('simGridCount');
  if(!body) return;
  if(count) count.textContent = `${rows.length} inscritos mostrados`;
  if(!rows.length){
    body.innerHTML = '<p class="small" style="text-align:center;padding:14px;color:#9ca3af">Sin inscritos que coincidan con los filtros.</p>';
    return;
  }
  // Ordenar por predictedPos (fórmula 60/40 + penalización fiabilidad). Sin valor al final.
  rows.sort((a,b)=>{
    const pa = a.predictedPos ?? (a.avgPos!=null ? a.avgPos * 1.5 : null);
    const pb = b.predictedPos ?? (b.avgPos!=null ? b.avgPos * 1.5 : null);
    if(pa==null && pb==null) return (a.name||'').localeCompare(b.name||'');
    if(pa==null) return 1;
    if(pb==null) return -1;
    return pa - pb;
  });
  body.innerHTML = `
    <div class="table-wrap" style="max-height:560px;overflow:auto">
      <table class="sim-grid-table">
        <thead><tr>
          <th>#</th>
          <th>Corredor</th>
          <th>Club</th>
          <th>Cat.</th>
          <th>Historial</th>
          <th style="text-align:center">🤖 Pos. IA</th>
          <th style="text-align:center">Tendencia</th>
          <th style="text-align:center">Media hist.</th>
          <th style="text-align:center">Mejor</th>
          <th style="text-align:center">Fiab.</th>
          <th style="text-align:center">C.</th>
          <th style="text-align:center;white-space:nowrap">🎯 Top10</th>
          <th style="text-align:center;white-space:nowrap">🥇 Podio</th>
          <th style="text-align:center;white-space:nowrap">🚨 Riesgo</th>
          <th>Forma reciente</th>
        </tr></thead>
        <tbody>${rows.map((g,rowIdx)=>{
          const cls = [];
          if(g.isMyTeam) cls.push('sim-my-team');
          if(g.status==='deb') cls.push('sim-debutant');
          let badge;
          if(g.status==='known') badge = '<span class="sim-status-badge known">✓ Sí</span>';
          else if(g.status==='team-fb') badge = '<span class="sim-status-badge team-fb">📊 Equipo</span>';
          else badge = '<span class="sim-status-badge deb">🆕 Debutante</span>';
          const relColor = g.reliability==null?'#9ca3af':g.reliability>=75?'#16a34a':g.reliability>=50?'#f59e0b':'#dc2626';
          const confDot = `<span class="sim-conf ${g.confidence}" title="Confianza ${g.confidence} (${g.raceCount} carreras)"></span>`;
          // Flecha de tendencia
          const trendCell = g.trend==='up'
            ? '<span title="Mejorando forma" style="font-size:16px">⬆️</span>'
            : g.trend==='down'
            ? '<span title="Empeorando forma" style="font-size:16px">⬇️</span>'
            : g.recentForm.length>=2
            ? '<span title="Forma estable" style="font-size:14px;color:#9ca3af">➡️</span>'
            : '<span style="color:#d1d5db">—</span>';
          // Rango IA — color y etiqueta según rangeClass (árbol de regresión)
          const _rc = g.rangeClass || 'normal';
          const _rcColor = _rc==='stable'?'#16a34a':_rc==='unstable'?'#d97706':_rc==='club-fb'?'#2563eb':'#7c3aed';
          const _rcIcon  = _rc==='stable'?'🔒':_rc==='unstable'?'⚠️':_rc==='club-fb'?'📊':'';
          const _rcLabel = _rc==='unstable'?'<span style="font-size:9px;font-weight:700;color:#d97706;display:block;line-height:1">inestable</span>':'';
          const rangeStr = (g.predLower!=null && g.predUpper!=null)
            ? `<b style="color:${_rcColor}">${_rcIcon} ${g.predLower}º–${g.predUpper}º</b>${_rcLabel}`
            : (g.predictedPos!=null
              ? `<b style="color:${_rcColor}">${_rcIcon} ${Math.round(g.predictedPos)}º</b>${_rcLabel}`
              : '<span style="color:#d1d5db">—</span>');
          const formHtml = (g.recentForm||[]).length
            ? g.recentForm.map(p=>{
                const c = p<=3?'#fbbf24':p<=10?'#3b82f6':p<=20?'#9ca3af':'#475569';
                return `<span style="display:inline-block;background:${c};color:#fff;border-radius:50%;width:21px;height:21px;line-height:21px;text-align:center;font-size:10px;font-weight:800;margin-right:2px">${p}</span>`;
              }).join('')
            : '<span class="small" style="color:#9ca3af">—</span>';
          return `<tr class="${cls.join(' ')}">
            <td style="font-weight:700;color:#94a3b8;text-align:center;font-size:11px">${rowIdx+1}</td>
            <td>${confDot}${g.isMyTeam?'🔵 ':''}<b>${escapeHtml(g.name)}</b>${g.bib?` <span style="color:#94a3b8;font-size:10px">#${escapeHtml(g.bib)}</span>`:''}</td>
            <td style="font-size:12px">${escapeHtml(g.team||'(sin equipo)')}</td>
            <td><span class="pill" style="background:#f3f6fb;font-size:11px">${escapeHtml(g.cat||'—')}</span></td>
            <td>${badge}</td>
            <td style="text-align:center" title="Árbol: ${(g.treeNode||[]).join(' → ')}">${rangeStr}</td>
            <td style="text-align:center">${trendCell}</td>
            <td style="text-align:center;color:#475569">${g.avgPos!=null?g.avgPos.toFixed(1)+'º':'—'}</td>
            <td style="text-align:center;color:#475569">${g.bestPos!=null?g.bestPos+'º':'—'}</td>
            <td style="text-align:center"><b style="color:${relColor}">${g.reliability!=null?g.reliability+'%':'—'}</b></td>
            <td style="text-align:center;color:#64748b">${g.raceCount||0}</td>
            <td style="text-align:center">${(()=>{
              const p = g.probTop10Poisson;
              if(p==null) return '<span style="color:#d1d5db">—</span>';
              const c = p>=70?'#16a34a':p>=40?'#d97706':'#94a3b8';
              const bg = p>=70?'#dcfce7':p>=40?'#fef3c7':'#f1f5f9';
              return `<span style="display:inline-block;min-width:36px;padding:2px 5px;border-radius:6px;background:${bg};color:${c};font-size:11px;font-weight:800">${p}%</span>`;
            })()}</td>
            <td style="text-align:center">${(()=>{
              const p = g.probPodiumLogistic;
              if(p==null) return '<span style="color:#d1d5db">—</span>';
              const c  = p>=60?'#15803d':p>=30?'#d97706':'#94a3b8';
              const bg = p>=60?'#dcfce7':p>=30?'#fef3c7':'#f1f5f9';
              const medal = p>=60?' 🥇':'';
              return `<span style="display:inline-block;min-width:36px;padding:2px 5px;border-radius:6px;background:${bg};color:${c};font-size:11px;font-weight:800">${p}%${medal}</span>`;
            })()}</td>
            <td style="text-align:center">${(()=>{
              const p = g.probCutLogistic;
              if(p==null) return '<span style="color:#d1d5db">—</span>';
              const c  = p>50?'#b91c1c':p>25?'#d97706':'#94a3b8';
              const bg = p>50?'#fee2e2':p>25?'#fef3c7':'#f1f5f9';
              const icon = p>50?' ⚠️':'';
              return `<span style="display:inline-block;min-width:36px;padding:2px 5px;border-radius:6px;background:${bg};color:${c};font-size:11px;font-weight:800">${p}%${icon}</span>`;
            })()}</td>
            <td>${formHtml}</td>
          </tr>`;
        }).join('')}</tbody>
      </table>
    </div>
    <p class="small" style="margin-top:8px;color:#6b7280;line-height:1.7">
      <b style="color:#7c3aed">🤖 Árbol</b>: pos = (0.6·recent + 0.4·media) × factores · posición acotada al pelotón ·
      🔒 <b style="color:#16a34a">estable</b> (fiab. ≥75%) ·
      ⚠️ <b style="color:#d97706">inestable</b> (&lt;40%) ·
      📊 <b style="color:#2563eb">por club</b> (Rama B) ·
      <span class="sim-conf alta"></span> ≥5 carr. ·
      <span class="sim-conf media"></span> 3-4 ·
      <span class="sim-conf baja"></span> 1-2 ·
      <span class="sim-conf nula"></span> sin datos ·
      <b>🎯 Top10</b>: Bernoulli (Top10+1)/(carr+2) ajustada por dif. ·
      <b>🥇 Podio</b> y <b>🚨 Riesgo</b>: σ(z) logística — ver "🧠 Motor Estadístico" para pesos.
    </p>
  `;
}

// Exportar predicción a PDF
function _simExportPDF(){
  if(!_simCurrentData){ alert('Selecciona una prueba primero.'); return; }
  const {race, grid, kpis} = _simCurrentData;
  const logoSrc = (document.querySelector('img.brand-logo')?.src) || '';
  const esc = s => String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const now = new Date().toLocaleString('es-ES');
  // Top 10 — ordenado por predictedPos (fórmula 60/40)
  const pool = grid.filter(g=>g.predictedPos!=null||g.avgPos!=null);
  pool.forEach(g=>{ if(g.predictedPos==null){ const rel=g.reliability??30; g.predictedPos=(g.avgPos||99)*(1+(100-rel)/200); } });
  pool.sort((a,b)=>(a.predictedPos||99)-(b.predictedPos||99));
  const top10 = pool.slice(0,10);
  // Ordenar todo el grid por predictedPos
  const gridSorted = grid.slice().sort((a,b)=>{
    const pa = a.predictedPos ?? (a.avgPos!=null?a.avgPos*1.5:null);
    const pb = b.predictedPos ?? (b.avgPos!=null?b.avgPos*1.5:null);
    if(pa==null&&pb==null) return 0;
    if(pa==null) return 1;
    if(pb==null) return -1;
    return pa-pb;
  });
  // Helper para formatear cada probabilidad con color
  const fmtProb = (p, type) => {
    if(p==null) return '<span style="color:#9ca3af">—</span>';
    let c, bg;
    if(type==='top10'){ c=p>=70?'#15803d':p>=40?'#92400e':'#475569'; bg=p>=70?'#dcfce7':p>=40?'#fef3c7':'#f1f5f9'; }
    else if(type==='podium'){ c=p>=60?'#15803d':p>=30?'#92400e':'#475569'; bg=p>=60?'#dcfce7':p>=30?'#fef3c7':'#f1f5f9'; }
    else /* risk */ { c=p>50?'#991b1b':p>25?'#92400e':'#475569'; bg=p>50?'#fee2e2':p>25?'#fef3c7':'#f1f5f9'; }
    const icon = (type==='podium' && p>=60) ? ' 🥇' : (type==='risk' && p>50) ? ' ⚠️' : '';
    return `<span style="background:${bg};color:${c};padding:1px 4px;border-radius:3px;font-weight:800">${p}%${icon}</span>`;
  };

  const topRows = top10.map((g,i)=>{
    const trendTxt = g.trend==='up'?'⬆️':g.trend==='down'?'⬇️':'➡️';
    const rangeStr = (g.predLower!=null&&g.predUpper!=null)?`${g.predLower}º–${g.predUpper}º`:(g.predictedPos!=null?Math.round(g.predictedPos)+'º':'—');
    return `<tr ${g.isMyTeam?'style="background:#dbeafe"':''}>
    <td style="text-align:center;font-weight:800">${i+1}</td>
    <td>${g.isMyTeam?'🔵 ':''}<b>${esc(g.name)}</b></td>
    <td>${esc(g.team||'')}</td>
    <td>${esc(g.cat||'')}</td>
    <td style="text-align:center;font-weight:700;color:#7c3aed">${rangeStr} ${trendTxt}</td>
    <td style="text-align:center">${fmtProb(g.probTop10Poisson,'top10')}</td>
    <td style="text-align:center">${fmtProb(g.probPodiumLogistic,'podium')}</td>
    <td style="text-align:center">${fmtProb(g.probCutLogistic,'risk')}</td>
    <td style="text-align:center;color:#475569">${g.avgPos!=null?g.avgPos.toFixed(1)+'º':'—'}</td>
    <td style="text-align:center">${g.reliability??'—'}%</td>
  </tr>`;}).join('');
  const gridRows = gridSorted.map((g,gi)=>{
    const statusTxt = g.status==='known' ? '✓ Sí' : g.status==='team-fb' ? '📊 Equipo' : '🆕 Debutante';
    const tTxt = g.trend==='up'?'⬆️':g.trend==='down'?'⬇️':g.recentForm.length>=2?'➡️':'—';
    const rStr = (g.predLower!=null&&g.predUpper!=null)?`${g.predLower}º–${g.predUpper}º`:(g.predictedPos!=null?Math.round(g.predictedPos)+'º':'—');
    return `<tr ${g.isMyTeam?'style="background:#dbeafe"':''}>
      <td style="text-align:center;color:#94a3b8;font-size:9px">${gi+1}</td>
      <td>${g.isMyTeam?'🔵 ':''}<b>${esc(g.name)}</b>${g.bib?` <span style="color:#94a3b8">#${esc(g.bib)}</span>`:''}</td>
      <td>${esc(g.team||'')}</td>
      <td>${esc(g.cat||'')}</td>
      <td style="text-align:center">${statusTxt}</td>
      <td style="text-align:center;font-weight:700;color:#7c3aed">${rStr} ${tTxt}</td>
      <td style="text-align:center">${fmtProb(g.probTop10Poisson,'top10')}</td>
      <td style="text-align:center">${fmtProb(g.probPodiumLogistic,'podium')}</td>
      <td style="text-align:center">${fmtProb(g.probCutLogistic,'risk')}</td>
      <td style="text-align:center;color:#475569">${g.avgPos!=null?g.avgPos.toFixed(1)+'º':'—'}</td>
      <td style="text-align:center">${g.reliability!=null?g.reliability+'%':'—'}</td>
      <td style="text-align:center">${g.raceCount||0}</td>
    </tr>`;
  }).join('');
  const diffColor = kpis.difficulty<30?'#16a34a':kpis.difficulty<60?'#f59e0b':'#dc2626';
  const predColor = kpis.predictability>=70?'#16a34a':kpis.predictability>=40?'#f59e0b':'#dc2626';
  const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8">
<title>Predicción · ${esc(race.raceName||'')}</title>
<style>
  @page{size:A4;margin:0}
  html,body{margin:0;padding:0;background:#e2e8f0;font-family:'Helvetica Neue',Arial,sans-serif;color:#0f172a}
  .page{box-sizing:border-box;width:210mm;min-height:297mm;padding:14mm 14mm 18mm;background:#fff;margin:0 auto 8mm;page-break-after:always;box-shadow:0 4px 14px rgba(0,0,0,.08);position:relative}
  .page:last-child{page-break-after:auto;margin-bottom:0}
  .header{display:flex;align-items:center;justify-content:space-between;gap:8mm;border-bottom:3px solid #6366f1;padding-bottom:5mm;margin-bottom:5mm}
  .header h1{margin:0 0 1mm;font-size:20px;color:#3730a3;line-height:1.15}
  .header .sub{margin:0;font-size:12px;color:#6366f1;font-weight:800}
  .header .sub2{margin:1mm 0 0;font-size:11px;color:#64748b}
  .brand{display:flex;align-items:center;gap:6px;background:#eef2ff;padding:5px 10px;border-radius:8px}
  .brand img{height:28px;width:auto}
  .brand span{font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:#3730a3}
  .meta{margin:0 0 5mm;padding:3mm 4mm;background:linear-gradient(135deg,#eef2ff,#f0f9ff);border:1px solid #c7d2fe;border-radius:2mm;font-size:11.5px;color:#3730a3;font-weight:700}
  .kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:3mm;margin-bottom:5mm}
  .kpi{padding:3mm 4mm;border-radius:3mm;border:1px solid #e5e7eb;background:#fff}
  .kpi .l{font-size:9px;text-transform:uppercase;letter-spacing:.5px;color:#64748b;font-weight:800;margin-bottom:1mm}
  .kpi .v{font-size:22px;font-weight:900}
  .kpi .s{font-size:10px;color:#475569;margin-top:1mm}
  h2.section{font-size:14px;color:#3730a3;margin:5mm 0 2mm;padding-bottom:1mm;border-bottom:2px solid #c7d2fe}
  table{width:100%;border-collapse:collapse;font-size:9.5px;margin-bottom:3mm}
  th{background:#f3f6fb;text-align:left;padding:2mm 3mm;font-size:8.5px;text-transform:uppercase;letter-spacing:.3px;color:#475569;border-bottom:2px solid #e5e7eb}
  td{padding:1.7mm 3mm;border-bottom:1px solid #f1f5f9}
  tr:nth-child(even) td{background:#fafbfc}
  tr{break-inside:avoid;page-break-inside:avoid}
  .footer{position:absolute;left:14mm;right:14mm;bottom:9mm;padding-top:2mm;border-top:1px solid #e2e8f0;font-size:9px;color:#64748b;display:flex;justify-content:space-between}
  @media print{html,body{background:#fff}.page{box-shadow:none;margin:0}.tb{display:none!important}}
  .tb{position:fixed;top:0;left:0;right:0;padding:10px 14px;background:#3730a3;color:#fff;display:flex;justify-content:space-between;align-items:center;z-index:9999;font-family:Helvetica,Arial,sans-serif}
  .tb button{background:#fff;color:#3730a3;border:0;border-radius:6px;padding:7px 14px;font-weight:800;cursor:pointer;font-size:13px}
  body.has-tb{padding-top:48px}
</style>
</head><body class="has-tb">
<div class="tb">
  <span>🔮 Predicción · ${esc(race.raceName||'')}</span>
  <span><button onclick="window.print()">🖨️ Imprimir / Guardar PDF</button> <button onclick="window.close()" style="margin-left:6px;background:#c7d2fe">✕ Cerrar</button></span>
</div>
<div class="page">
  <div class="header">
    <div>
      <h1>🔮 Predicción de carrera</h1>
      <p class="sub">${esc(race.raceName||'')}</p>
      <p class="sub2">${esc(race.raceDate||'')}${race.localidad?' · 📍 '+esc(race.localidad):''}${race.circuitType?' · 🛣️ '+esc(race.circuitType):''}</p>
    </div>
    ${logoSrc?`<div class="brand"><img src="${logoSrc}" alt="MFPP"><span>MFPP Cycling</span></div>`:''}
  </div>
  <div class="meta">📋 ${grid.length} inscritos analizados${myTeam?' · 🔵 Mi equipo: '+esc(myTeam)+' ('+kpis.myTeamCount+' corredores)':''}</div>
  <div class="kpis">
    <div class="kpi" style="border-color:#fcd34d;background:#fffbeb">
      <div class="l">⚠️ Dificultad</div>
      <div class="v" style="color:${diffColor}">${kpis.difficulty}%</div>
      <div class="s">${kpis.strongRivals} rivales fuertes (pos. media &lt; 15)</div>
    </div>
    <div class="kpi" style="border-color:#86efac;background:#f0fdf4">
      <div class="l">🎯 Predictibilidad</div>
      <div class="v" style="color:${predColor}">${kpis.predictability}%</div>
      <div class="s">Fiab. media ${kpis.avgReliability}% · Cobertura ${kpis.coverage}%</div>
    </div>
    <div class="kpi" style="border-color:#c7d2fe;background:#eef2ff">
      <div class="l">🔍 Cobertura</div>
      <div class="v" style="color:#3730a3">${kpis.coverage}%</div>
      <div class="s">Inscritos con historial</div>
    </div>
  </div>

  <h2 class="section">🏆 Top 10 esperado (predicción IA — 60% forma reciente + 40% histórico)</h2>
  <table>
    <thead><tr>
      <th>#</th><th>Corredor</th><th>Club</th><th>Cat.</th>
      <th style="text-align:center">🤖 Pos. IA</th>
      <th style="text-align:center">🎯 Top10</th>
      <th style="text-align:center">🥇 Podio</th>
      <th style="text-align:center">🚨 Riesgo</th>
      <th style="text-align:center">Media</th>
      <th style="text-align:center">Fiab.</th>
    </tr></thead>
    <tbody>${topRows||'<tr><td colspan="10" style="text-align:center;color:#9ca3af">Sin datos suficientes</td></tr>'}</tbody>
  </table>

  ${(()=>{
    // Predicción Mi Equipo Montecarlo
    const mine = grid.filter(g=>g.isMyTeam && g.avgPos!=null);
    if(!mine.length || !myTeam) return '';
    const rowsHtml = mine.map(g=>{
      const mc = _simMonteCarlo(g, 1000);
      if(!mc) return '';
      return `<tr style="background:#eff6ff">
        <td><b>${esc(g.name)}</b><br><small style="color:#6b7280">${esc(g.cat||'')}${g.bib?' · #'+esc(g.bib):''}</small></td>
        <td style="text-align:center;font-size:14px;font-weight:900;color:#1d4ed8">${mc.predicted}º</td>
        <td style="text-align:center;color:#475569">${mc.lower}º – ${mc.upper}º</td>
        <td style="text-align:center;background:#fffbeb;font-weight:800">${mc.probTop3}%</td>
        <td style="text-align:center;background:#f0fdf4;font-weight:800">${mc.probTop5}%</td>
        <td style="text-align:center;background:#eef2ff;font-weight:800">${mc.probTop10}%</td>
        <td style="text-align:center;color:#475569">${g.raceCount||0}</td>
      </tr>`;
    }).join('');
    return `
      <h2 class="section">🔵 Predicción Mi Equipo · ${esc(myTeam)}</h2>
      <p style="font-size:10px;color:#475569;margin:0 0 2mm">Simulación Montecarlo 1000 iteraciones por corredor. Intervalo de confianza al 50%.</p>
      <table>
        <thead><tr><th>Corredor</th><th style="text-align:center">Puesto esperado</th><th style="text-align:center">Rango 50%</th><th style="text-align:center">P. Podio</th><th style="text-align:center">P. Top 5</th><th style="text-align:center">P. Top 10</th><th style="text-align:center">Carrs.</th></tr></thead>
        <tbody>${rowsHtml}</tbody>
      </table>`;
  })()}

  ${(()=>{
    // Análisis por tipo de circuito
    const circuitType = (race.circuitType||'').trim();
    if(!circuitType) return '';
    const histCirc = (_cachedHistory||[]).filter(h => h.id!==race.id && (h.circuitType||'').trim()===circuitType && (h.riders||[]).length>=3);
    if(!histCirc.length) return '';
    const circRows = grid.filter(g=>g.hasHistory).map(g=>{
      const nk = normalizeForMatching(g.name||'');
      const positions = [];
      histCirc.forEach(h=>{
        const r = (h.riders||[]).find(x=>normalizeForMatching(x.name)===nk);
        if(r && r.pos) positions.push(r.pos);
      });
      if(!positions.length) return null;
      const avgInType = positions.reduce((s,p)=>s+p,0)/positions.length;
      const dlt = avgInType - g.avgPos;
      const dltLbl = Math.abs(dlt)<1?'≈':(dlt<0?'▲ '+Math.abs(dlt).toFixed(1):'▼ '+dlt.toFixed(1));
      return {name:g.name,team:g.team,isMy:g.isMyTeam,avgInType,avgGlobal:g.avgPos,dlt,dltLbl,n:positions.length};
    }).filter(Boolean).sort((a,b)=>a.avgInType-b.avgInType).slice(0,20);
    if(!circRows.length) return '';
    return `
      <h2 class="section">🛣️ Análisis por tipo de circuito "${esc(circuitType)}"</h2>
      <p style="font-size:10px;color:#475569;margin:0 0 2mm">${histCirc.length} pruebas previas de este tipo. Top 20 inscritos con mejor media en este tipo.</p>
      <table>
        <thead><tr><th>#</th><th>Corredor</th><th>Equipo</th><th style="text-align:center">Media tipo</th><th style="text-align:center">Media global</th><th style="text-align:center">Δ</th><th style="text-align:center">Carrs.</th></tr></thead>
        <tbody>${circRows.map((r,i)=>`<tr ${r.isMy?'style="background:#dbeafe"':''}>
          <td style="text-align:center">${i+1}</td>
          <td>${r.isMy?'🔵 ':''}<b>${esc(r.name)}</b></td>
          <td>${esc(r.team||'')}</td>
          <td style="text-align:center;font-weight:800;color:#3730a3">${r.avgInType.toFixed(1)}º</td>
          <td style="text-align:center;color:#6b7280">${r.avgGlobal.toFixed(1)}º</td>
          <td style="text-align:center;font-weight:700;color:${r.dlt<0?'#166534':r.dlt>0?'#92400e':'#3730a3'}">${r.dltLbl}</td>
          <td style="text-align:center;color:#6b7280">${r.n}</td>
        </tr>`).join('')}</tbody>
      </table>`;
  })()}

  <h2 class="section">🚴 Parrilla completa analizada</h2>
  <table>
    <thead><tr>
      <th>#</th><th>Corredor</th><th>Club</th><th>Cat.</th>
      <th style="text-align:center">Hist.</th>
      <th style="text-align:center">🤖 Pos. IA</th>
      <th style="text-align:center">🎯 Top10</th>
      <th style="text-align:center">🥇 Podio</th>
      <th style="text-align:center">🚨 Riesgo</th>
      <th style="text-align:center">Media</th>
      <th style="text-align:center">Fiab.</th>
      <th style="text-align:center">C.</th>
    </tr></thead>
    <tbody>${gridRows}</tbody>
  </table>

  <div class="footer">
    <span><b>Generado:</b> ${esc(now)}</span>
    <span>🔮 Predicción IA · Uso interno del cuerpo técnico</span>
  </div>
</div>
</body></html>`;
  const w = window.open('','_blank','width=1100,height=850');
  if(!w){ alert('Permite ventanas emergentes para imprimir el PDF.'); return; }
  w.document.write(html);
  w.document.close();
}
